insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('sg',5,6,'crampon1923','Nous avons donc erré, loin du chemin de la vérité; la lumière de la justice n''a pas brillé sur nous, et sur nous ne s''est pas levé le soleil.'),
('sg',5,7,'crampon1923','Nous nous sommes rassasiés dans la voie de l''iniquité et de la perdition, nous avons marché dans des déserts sans chemin, et nous n''avons pas connu la voie du Seigneur.'),
('sg',5,8,'crampon1923','A quoi nous a servi l''orgueil, et que nous a rapporté la richesse avec la jactance?'),
('sg',5,9,'crampon1923','Toutes ces choses ont passé comme l''ombre, comme une rumeur qui s''enfuit;'),
('sg',5,10,'crampon1923','comme le navire qui fend l''onde agitée, sans qu''on puisse découvrir la trace de son passage, ni la marque de sa quille au milieu des flots;'),
('sg',5,11,'crampon1923','ou comme l''oiseau traversant les airs, sans qu''on relève aucun vestige de sa route; mais il bat à coups de plumes l''air léger, d''un puissant élan il le déchire, s''y fait un chemin en agitant ses ailes; puis, on n''y voit pas aucun indice de son passage;'),
('sg',5,12,'crampon1923','ou comme, lorsque la flèche a été lancée vers son but, l''air qu''elle a fendu revient aussitôt sur lui-même, et l''on ne sait plus par où elle a passé:'),
('sg',5,13,'crampon1923','Ainsi nous-mêmes, nous sommes nés et nous avons cessé d''être, et nous n''avons à montrer aucune trace de vertu; et dans notre iniquité, nous avons été retranchés. »'),
('sg',5,14,'crampon1923','En effet, l''espoir de l''impie est comme le duvet que le vent emporte, comme le givre léger que disperse l''ouragan, comme la fumée qu''un souffle dissipe, comme le souvenir de l''hôte d''un jour qui s''évanouit.'),
('sg',5,15,'crampon1923','Mais les justes vivent éternellement; leur récompense est auprès du Seigneur, et le Tout-Puissant a souci d''eux.'),
('sg',5,16,'crampon1923','C''est pourquoi ils recevront de la main du Seigneur le magnifique royaume et le splendide diadème; car il les protégera de sa droite, de son bras, il les couvrira comme d''un bouclier.'),
('sg',5,17,'crampon1923','Il saisira son zèle comme armure, et il armera la création pour se venger de ses ennemis.'),
('sg',5,18,'crampon1923','Il revêtira comme cuirasse la justice, et prendra pour casque un jugement sincère.'),
('sg',5,19,'crampon1923','Il prendra la sainteté comme un bouclier inexpugnable.'),
('sg',5,20,'crampon1923','De son inexorable colère il fera un glaive aigu, et l''univers combattra avec lui contre les insensés.'),
('sg',5,21,'crampon1923','Les traits de la foudre bien dirigés partiront, et, du sein des nuages, comme d''un arc bien tendu, voleront au but marqué.'),
('sg',5,22,'crampon1923','Sa colère, comme une baliste, lancera une masse de grêle; l''eau de la mer se soulèvera contre eux, et les fleuves se précipiteront avec furie.'),
('sg',5,23,'crampon1923','Le souffle de la puissance divine s''élèvera contre eux, et les dispersera comme un tourbillon: et ainsi l''iniquité fera de toute la terre un désert, et la malice renversera les trônes des puissants.'),
('sg',6,1,'crampon1923','Écoutez donc, ô rois, et comprenez; écoutez l''instruction, vous qui jugez les extrémités de la terre.'),
('sg',6,2,'crampon1923','Prêtez l''oreille, vous qui dominez sur la multitude, qui êtes fiers de commander à des foules de peuples.'),
('sg',6,3,'crampon1923','Sachez que la force vous a été donnée par le Seigneur, et la puissance par le Très-Haut, qui examinera vos œuvres et sondera vos pensées.'),
('sg',6,4,'crampon1923','Parce que, étant les ministres de sa royauté, vous n''avez pas jugé avec droiture, ni observé la loi, ni marché selon la volonté de Dieu;'),
('sg',6,5,'crampon1923','terrible et soudain, il fondra sur vous, car un jugement sévère s''exerce sur ceux qui commandent.'),
('sg',6,6,'crampon1923','Aux petits, on pardonne par pitié; mais les puissants sont puissamment châtiés.'),
('sg',6,7,'crampon1923','Le souverain de tous ne reculera devant personne, il ne s''arrêtera par respect devant aucune grandeur; car il a fait les grands et les petits, et il prend soin des uns comme des autres.'),
('sg',6,8,'crampon1923','Mais les puissants seront soumis à une épreuve plus rigoureuse.'),
('sg',6,9,'crampon1923','C''est donc à vous, ô rois, que s''adressent mes discours, afin que vous appreniez la sagesse et que vous ne tombiez point.'),
('sg',6,10,'crampon1923','Ceux qui observent saintement les saintes lois seront sanctifiés, et ceux qui les auront apprises auront de quoi répondre.'),
('sg',6,11,'crampon1923','Mettez donc vos complaisances dans mes paroles, désirez-les, et vous aurez l''instruction.'),
('sg',6,12,'crampon1923','La sagesse est brillante, et son éclat ne se ternit pas; facilement on l''aperçoit quand on l''aime, facilement on la trouve quand on la cherche.'),
('sg',6,13,'crampon1923','Elle prévient ceux qui la cherchent, et se montre à eux la première.'),
('sg',6,14,'crampon1923','Celui qui se lève matin pour la chercher n''a pas de peine: il la trouve assise à sa porte.'),
('sg',6,15,'crampon1923','Car penser à elle, c''est la perfection de la prudence, et celui qui veille à cause d''elle sera bientôt libre de soucis;'),
('sg',6,16,'crampon1923','elle-même va de tous côtés chercher ceux qui sont dignes d''elle, elle se montre amicalement à eux dans leurs voies, et les assiste dans tous leurs desseins.'),
('sg',6,17,'crampon1923','En effet, son commencement le plus assuré est le désir de l''instruction.'),
('sg',6,18,'crampon1923','Or le soin de l''instruction conduit à l''amour, l''amour fait qu''on obéit à ses lois, l''obéissance à ses lois assure l''immortalité,'),
('sg',6,19,'crampon1923','et l''immortalité donne une place près de Dieu.'),
('sg',6,20,'crampon1923','Ainsi le désir de la sagesse conduit à la royauté.'),
('sg',6,21,'crampon1923','Si donc, ô rois des peuples, vous mettez votre plaisir dans les trônes et le sceptre, honorez la sagesse, afin de régner éternellement.'),
('sg',6,22,'crampon1923','Mais ce qu''est la sagesse et son origine, je vais l''exposer, sans vous cacher les mystères de Dieu. Je remonterai jusqu''au début de la création, je mettrai au grand jour ce qui la concerne, et je ne m''écarterai pas de la vérité.'),
('sg',6,23,'crampon1923','Loin de moi de faire route avec l''envie dévorante! Elle n''a rien de commun avec la sagesse.'),
('sg',6,24,'crampon1923','Le grand nombre des sages fait le salut de la terre, et un roi sage la prospérité de son peuple.'),
('sg',6,25,'crampon1923','Recevez donc l''instruction par mes paroles, et vous vous en trouverez bien.'),
('sg',7,1,'crampon1923','Je suis moi-même un mortel, semblable à tous et descendant du premier qui fut formé de terre.'),
('sg',7,2,'crampon1923','J''ai été formé quant à la chair dans le sein de ma mère, pendant dix mois prenant consistance dans le sang, par la semence de l''homme, durant le repos du sommeil.'),
('sg',7,3,'crampon1923','Moi aussi, à ma naissance, j''ai respiré l''air commun à tous, je suis tombé sur la même terre, et, comme celui de tous, mon premier cri fut un gémissement.'),
('sg',7,4,'crampon1923','J''ai été élevé dans des langes et avec des soins infinis.'),
('sg',7,5,'crampon1923','Aucun roi n''a eu un autre commencement d''existence.'),
('sg',7,6,'crampon1923','Il n''y a pour tous qu''une seule manière d''entrer dans la vie et d''en sortir.'),
('sg',7,7,'crampon1923','C''est pourquoi j''ai prié, et la prudence m''a été donnée; j''ai invoqué, et l''esprit de sagesse est venu en moi.'),
('sg',7,8,'crampon1923','Je l''ai préférée aux sceptres et aux couronnes, et j''ai estimé de nul prix les richesses auprès d''elle.'),
('sg',7,9,'crampon1923','Je ne lui ai pas égalé les pierres les plus précieuses, car tout l''or du monde n''est auprès d''elle qu''un peu de sable, et l''argent, à côté d''elle, doit être estimé comme de la boue.'),
('sg',7,10,'crampon1923','Je l''ai aimée plus que la santé et la beauté; j''ai préféré la posséder plutôt que la lumière, car son flambeau ne s''éteint jamais.'),
('sg',7,11,'crampon1923','Avec elle me sont venus tous les biens, et des richesses innombrables sont dans ses mains.'),
('sg',7,12,'crampon1923','Et je me suis réjoui de tous ces biens, car la sagesse les amène avec elle; j''ignorais pourtant qu''elle en était la mère.'),
('sg',7,13,'crampon1923','Je l''ai apprise sans arrière-pensée, je la communique sans envie, et je ne cache point ses trésors.'),
('sg',7,14,'crampon1923','Car elle est pour les hommes un trésor inépuisable; ceux qui en usent ont part à l''amitié de Dieu, à qui les recommandent les dons acquis par l''instruction.'),
('sg',7,15,'crampon1923','Que Dieu me donne d''en parler comme je le voudrais, et de concevoir des pensées dignes des dons que j''ai reçus! Car c''est lui qui conduit la sagesse, et qui dirige les sages.'),
('sg',7,16,'crampon1923','Nous sommes dans sa main, nous et nos discours, et toute la prudence et le savoir-faire.'),
('sg',7,17,'crampon1923','C''est lui qui m''a donné la véritable science des êtres, pour me faire connaître la structure de l''univers, et les propriétés des éléments,'),
('sg',7,18,'crampon1923','le commencement, la fin et le milieu des temps, les retours périodiques du soleil, les vicissitudes des temps,'),
('sg',7,19,'crampon1923','les cycles des années et la position des étoiles,'),
('sg',7,20,'crampon1923','la nature des animaux et les instincts des bêtes, la puissance des esprits et les raisonnements des hommes, les différentes espèces des plantes et la vertu des racines.'),
('sg',7,21,'crampon1923','Tout ce qui est caché et à découvert, je l''ai appris;'),
('sg',7,22,'crampon1923','car la sagesse, ouvrière de toutes choses, me l''a enseigné. En elle, en effet, il y a un esprit intelligent, saint, unique, multiple, immatériel, actif, pénétrant, sans souillure, infaillible, impassible, aimant le bien, sagace, ne connaissant pas d''obstacle, bienfaisant,'),
('sg',7,23,'crampon1923','bon pour les hommes, immuable, assuré, tranquille, tout-puissant, surveillant tout, pénétrant tous les esprits, les intelligents, les purs et les plus subtils.'),
('sg',7,24,'crampon1923','Car la sagesse est plus agile que tout mouvement; elle pénètre et s''introduit partout, à cause de sa pureté.'),
('sg',7,25,'crampon1923','Elle est le souffle de la puissance de Dieu, une pure émanation de la gloire du Tout-puissant; aussi rien de souillé ne peut tomber sur elle.'),
('sg',7,26,'crampon1923','Elle est le resplendissement de la lumière éternelle, le miroir sans tache de l''activité de Dieu, et l''image de sa bonté.'),
('sg',7,27,'crampon1923','Etant unique, elle peut tout; restant la même, elle renouvelle tout; se répandant, à travers les âges, dans les âmes saintes, elle en fait des amis de Dieu et des prophètes.'),
('sg',7,28,'crampon1923','Dieu, en effet, n''aime que celui qui habite avec la sagesse.'),
('sg',7,29,'crampon1923','Car elle est plus belle que le soleil, et que l''arrangement harmonieux des étoiles. Comparée à la lumière, elle l''emporte sur elle;'),
('sg',7,30,'crampon1923','car la lumière fait place à la nuit, mais le mal ne prévaut pas contre la sagesse.'),
('sg',8,1,'crampon1923','La sagesse atteint avec force d''un bout du monde à l''autre, et dispose tout avec douceur.'),
('sg',8,2,'crampon1923','Je l''aimai et la recherchai dès ma jeunesse; je cherchai à l''avoir pour épouse, et j''étais épris de sa beauté.'),
('sg',8,3,'crampon1923','Elle fait voir la gloire de son origine en ce qu''elle habite avec Dieu, et le maître de toutes choses l''aime.'),
('sg',8,4,'crampon1923','Car c''est elle qui initie à la science de Dieu, et qui choisit parmi ses œuvres.'),
('sg',8,5,'crampon1923','Si la richesse est un bien désirable en cette vie, quoi de plus riche que la sagesse, qui opère toutes choses?'),
('sg',8,6,'crampon1923','Si la prudence préside au travail, qui mieux que la sagesse est l''ouvrière de tout ce qui existe?'),
('sg',8,7,'crampon1923','Aime-t-on la justice? Les labeurs de la sagesse produisent les vertus; elle enseigne la tempérance et la prudence, la justice et la force, ce qu''il y a de plus utile aux hommes pendant la vie.'),
('sg',8,8,'crampon1923','Désire-t-on une science étendue? Elle connaît le passé et conjecture l''avenir; elle pénètre les discours subtils et résout les énigmes; elle connaît à l''avance les signes et les prodiges; elle sait les événements des temps et des époques.'),
('sg',8,9,'crampon1923','Aussi ai-je résolu de la prendre pour compagne de ma vie, sachant qu''elle serait pour moi une conseillère de tout bien, et une consolation dans mes soucis et mes peines.'),
('sg',8,10,'crampon1923','Par elle, me disais-je, j''aurai de la gloire dans les assemblées, et, jeune encore, de l''honneur auprès des vieillards.'),
('sg',8,11,'crampon1923','On reconnaîtra ma pénétration dans les jugements, et devant moi les grands seront dans l''admiration.'),
('sg',8,12,'crampon1923','Si je me tais, ils attendront que je prenne la parole; si je parle, ils tiendront les yeux fixés sur moi; et si je prolonge mon discours, ils mettront la main sur leur bouche.'),
('sg',8,13,'crampon1923','Par elle, j''obtiendrai l''immortalité, et je laisserai à la postérité un souvenir éternel.'),
('sg',8,14,'crampon1923','Je gouvernerai des peuples, et les nations étrangères me seront soumises.'),
('sg',8,15,'crampon1923','En entendant parler de moi, des rois redoutables me craindront: je me montrerai bon au milieu du peuple, et vaillant à la guerre.'),
('sg',8,16,'crampon1923','A mon retour dans ma maison, je me reposerai auprès d''elle; car sa société ne cause aucune amertume, ni son commerce aucun ennui, mais le contentement et la joie.'),
('sg',8,17,'crampon1923','Méditant ces pensées en moi-même, et réfléchissant en mon cœur que l''immortalité est le fruit de l''union avec la sagesse,'),
('sg',8,18,'crampon1923','qu''il y a dans son amitié une noble jouissance, et dans les œuvres de ses mains des richesses inépuisables, qu''on acquiert la prudence dans un commerce assidu avec elle, et la gloire à prendre part à sa conversation: j''allai de tous côtés, cherchant le moyen de l''avoir avec moi.'),
('sg',8,19,'crampon1923','J''étais un enfant d''un bon naturel, et j''avais reçu en partage une bonne âme;'),
('sg',8,20,'crampon1923','ou plutôt, étant bon, je vins à un corps sans souillure.'),
('sg',8,21,'crampon1923','Mais, sachant que je ne pourrais obtenir la sagesse si Dieu ne me la donnait, — et c''était déjà de la prudence que de savoir de qui vient ce don, — je m''adressai au Seigneur, et je l''invoquai, et je lui dis du fond de mon cœur:'),
('sg',9,1,'crampon1923','« Dieu des pères, Seigneur de miséricorde, qui avez fait l''univers par votre parole,'),
('sg',9,2,'crampon1923','et qui, par votre sagesse, avez établi l''homme pour dominer sur toutes les créatures que vous avez faites,'),
('sg',9,3,'crampon1923','pour régir le monde dans la sainteté et la justice, et exercer l''empire dans la droiture du cœur,'),
('sg',9,4,'crampon1923','donnez-moi la Sagesse qui est assise près de votre trône, et ne me rejetez pas du nombre de vos enfants.'),
('sg',9,5,'crampon1923','Car je suis votre serviteur et le fils de votre servante, un homme faible, à la vie courte, et peu capable de comprendre le jugement et les lois.'),
('sg',9,6,'crampon1923','Quelqu''un serait-il parfait parmi les enfants des hommes, s''il manque de la sagesse qui vient de vous, il sera compté pour rien.'),
('sg',9,7,'crampon1923','Vous m''avez choisi pour régner sur votre peuple, et juger vos fils et vos filles.'),
('sg',9,8,'crampon1923','Et vous m''avez dit de bâtir un temple sur votre montagne sainte, et un autel dans la cité où vous demeurez, sur le modèle du saint tabernacle que vous avez préparé dès l''origine.'),
('sg',9,9,'crampon1923','Avec vous est la Sagesse qui connaît vos œuvres, qui était là quand vous faisiez l''univers, et qui sait ce qui est agréable à vos yeux, et ce qui est juste selon vos commandements.'),
('sg',9,10,'crampon1923','Envoyez-la de vos cieux très saints, envoyez-la du trône de votre gloire, afin qu''elle m''assiste dans mes labeurs, et que je connaisse ce qui vous est agréable.'),
('sg',9,11,'crampon1923','Car elle connaît et comprend toutes choses, et elle me conduira avec prudence dans mes œuvres, et me gardera par sa gloire.'),
('sg',9,12,'crampon1923','Et ainsi mes œuvres vous seront agréables, je gouvernerai votre peuple avec justice, et je serai digne du trône de mon père.'),
('sg',9,13,'crampon1923','Quel homme, en effet, peut connaître le conseil de Dieu, ou bien qui peut pénétrer ce que veut le Seigneur?'),
('sg',9,14,'crampon1923','Les pensées des hommes sont incertaines, et nos opinions sont hasardées.'),
('sg',9,15,'crampon1923','Car le corps, sujet à la corruption, appesantit l''âme, et sa demeure terrestre accable l''esprit aux pensées multiples.'),
('sg',9,16,'crampon1923','Nous avons peine à deviner ce qui est sur la terre, et nous trouvons avec difficulté ce qui est sous notre main: qui donc a pénétré ce qui est dans le ciel?'),
('sg',9,17,'crampon1923','Qui a connu votre volonté, si vous ne lui avez pas donné la Sagesse, et si vous n''avez pas envoyé d''en haut votre Esprit saint?'),
('sg',9,18,'crampon1923','Ainsi ont été rendues droites les voies de ceux qui sont sur la terre, et les hommes ont appris ce qui vous est agréable, et ils ont été sauvés par la Sagesse. »'),
('sg',9,19,'crampon1923',''),
('sg',10,1,'crampon1923','C''est la sagesse qui garda le premier homme formé par Dieu, pour être le père du genre humain, le seul créé;'),
('sg',10,2,'crampon1923','elle le tira de son péché, et lui donna le pouvoir de gouverner toutes les créatures.'),
('sg',10,3,'crampon1923','S''étant éloigné d''elle dans sa colère, l''injuste périt avec sa fureur fratricide.'),
('sg',10,4,'crampon1923','Quand, à cause de lui, la terre fut submergée, la sagesse la sauva, dirigeant le juste sur un bois sans valeur.'),
('sg',10,5,'crampon1923','Lorsque les nations étaient confondues dans leur commune iniquité, la sagesse connut le juste et le conserva sans reproche devant Dieu, et le garda invincible contre sa tendresse pour son fils.'),
('sg',10,6,'crampon1923','Ce fut elle qui, au milieu de la ruine des méchants, sauva le juste, qui s''enfuit loin du feu descendu sur les cinq villes.'),
('sg',10,7,'crampon1923','En témoignage de leur perversité, cette terre désolée continue de fumer, les arbres portent leurs fruits hors de saison; monument d''une âme incrédule, une colonne de sel reste là debout.'),
('sg',10,8,'crampon1923','Ayant négligé la sagesse, non seulement ils ont été privés de la connaissance du bien, mais ils ont laissé aux vivants un monument de leur folie, afin que leurs crimes ne puissent tomber dans l''oubli.'),
('sg',10,9,'crampon1923','Mais la sagesse a délivré du malheur ses fidèles.'),
('sg',10,10,'crampon1923','C''est elle qui conduisit par des voies droites le juste fuyant la colère de son frère, qui lui montra le royaume de Dieu, et lui donna la science des choses saintes; elle l''enrichit dans ses pénibles labeurs, et fit fructifier ses travaux.'),
('sg',10,11,'crampon1923','Elle l''assista contre d''avares oppresseurs, et lui fit acquérir des richesses.'),
('sg',10,12,'crampon1923','Elle le garda contre ses ennemis, et le protégea contre ceux qui lui dressaient des embûches; elle lui donna la victoire dans un rude combat, pour lui apprendre que la piété est plus puissante que tout.'),
('sg',10,13,'crampon1923','Elle n''abandonna pas le juste vendu, mais le préserva du péché;'),
('sg',10,14,'crampon1923','elle descendit avec lui dans la fosse, et ne le quitta pas dans les chaînes, jusqu''à ce qu''elle lui eut procuré le sceptre royal, et la puissance sur ses oppresseurs; elle convainquit de mensonge ceux qui l''avaient accusé, et lui donna une gloire éternelle.'),
('sg',10,15,'crampon1923','Elle délivra des nations qui l''opprimaient le peuple saint et la race sans reproche.'),
('sg',10,16,'crampon1923','Elle entra dans l''âme du serviteur de Dieu, et, par des signes et des prodiges, elle tint tête à des rois redoutables.'),
('sg',10,17,'crampon1923','Elle rendit aux saints le salaire de leurs travaux, elle les conduisit par une route semée de merveilles, et fut pour eux un ombrage pendant le jour, et comme la lumière des étoiles pendant la nuit.'),
('sg',10,18,'crampon1923','Elle leur fit traverser la mer Rouge, et les conduisit à travers les grandes eaux.'),
('sg',10,19,'crampon1923','Elle submergea leurs ennemis, puis des profondeurs de l''abîme elle les rejeta.'),
('sg',10,20,'crampon1923','C''est pourquoi les justes enlevèrent les dépouilles des impies, et chantèrent votre saint nom, Seigneur, et louèrent de concert votre main qui combattait pour eux.'),
('sg',10,21,'crampon1923','Car la sagesse ouvrit la bouche des muets et rendit éloquente la langue des enfants.'),
('sg',11,1,'crampon1923','Elle fit réussir leurs œuvres par la main d''un saint prophète.'),
('sg',11,2,'crampon1923','Ils firent route à travers un désert inhabité, et dressèrent leurs tentes dans des régions sans chemin.'),
('sg',11,3,'crampon1923','Ils résistèrent à leurs ennemis, et tirèrent vengeance de leurs adversaires.'),
('sg',11,4,'crampon1923','Ils éprouvèrent la soif et vous invoquèrent, et l''eau leur fut donnée d''un rocher escarpé, et d''une pierre, l''apaisement de leur soif.'),
('sg',11,5,'crampon1923','Ce qui avait fait le châtiment de leurs ennemis devint pour eux une bénédiction dans leur détresse.'),
('sg',11,6,'crampon1923','En effet, tandis que les eaux d''un fleuve intarissable étaient troublées par un sang impur,'),
('sg',11,7,'crampon1923','en punition du décret qui frappait de mort les enfants, vous donniez à vos fidèles, contre tout espoir, une eau abondante,'),
('sg',11,8,'crampon1923','leur montrant ainsi, par la soif qu''ils ressentirent alors, de quel châtiment vous frappiez vos adversaires.'),
('sg',11,9,'crampon1923','Après cette épreuve, quoique punis avec miséricorde, ils surent comment étaient tourmentés les impies jugés dans la colère.'),
('sg',11,10,'crampon1923','Vous avez éprouvé les uns comme un père qui avertit, et vous avez châtié les autres comme un roi sévère qui condamne.'),
('sg',11,11,'crampon1923','Absents ou présents, ils furent également tourmentés.'),
('sg',11,12,'crampon1923','Un double chagrin les saisit, et ils gémissaient au souvenir de ce qui était arrivé.'),
('sg',11,13,'crampon1923','Car en apprenant que leurs propres tourments tournaient à l''avantage des fugitifs, ils reconnurent la main du Seigneur.'),
('sg',11,14,'crampon1923','Celui qu''ils avaient autrefois exposé et rejeté avec mépris, ils l''admirèrent à la fin des événements, lorsqu''ils eurent souffert une soif bien différente de celle des justes.'),
('sg',11,15,'crampon1923','En punition des pensées extravagantes de leur perversité, qui les égaraient et leur faisaient adorer des reptiles sans raison et de vils animaux, vous leur envoyâtes en châtiment une multitude de bêtes stupides:'),
('sg',11,16,'crampon1923','pour leur apprendre que l''on est puni par où l''on a péché.'),
('sg',11,17,'crampon1923','Il n''était pas difficile à votre main toute-puissante, qui a fait le monde d''une matière informe, d''envoyer contre eux une multitude d''ours ou de lions féroces,'),
('sg',11,18,'crampon1923','ou des bêtes nouvellement créées, pleines de fureur et inconnues, respirant une vapeur enflammée, exhalant une fumée infecte, ou lançant par les yeux de terribles éclairs,'),
('sg',11,19,'crampon1923','capables, non seulement de donner la mort par une blessure, mais de foudroyer de peur par leur seul aspect.'),
('sg',11,20,'crampon1923','Et, sans cela même, ils pouvaient périr par un simple souffle, poursuivis par la justice, et dispersés par le souffle de votre puissance. Mais vous avez tout réglé avec mesure, avec nombre et avec poids.'),
('sg',11,21,'crampon1923','Car la souveraine puissance est toujours à vos ordres, et qui donc résisterait à la force de votre bras?'),
('sg',11,22,'crampon1923','Le monde entier est devant vous comme l''atome qui fait pencher la balance, comme la goutte de rosée matinale qui tombe sur la terre.'),
('sg',11,23,'crampon1923','Mais, parce que vous pouvez tout, vous avez pitié de tous, et vous fermez les yeux sur les péchés des hommes pour qu''ils se repentent.'),
('sg',11,24,'crampon1923','Car vous aimez toutes les créatures, et vous ne haïssez rien de ce que vous avez fait; si vous aviez haï une chose, vous ne l''auriez pas faite.'),
('sg',11,25,'crampon1923','Et comment un être subsisterait-il, si vous ne le vouliez, se conserverait-il, si vous ne l''aviez appelé à l''existence?'),
('sg',11,26,'crampon1923','Mais vous pardonnez à tous, parce que tout est à vous, Seigneur, qui aimez les âmes.'),
('sg',12,1,'crampon1923','Car votre esprit incorruptible est dans tous les êtres.'),
('sg',12,2,'crampon1923','C''est pourquoi vous châtiez avec modération ceux qui tombent, et, quand ils pèchent, vous les avertissez et vous les reprenez, afin que, renonçant à leur malice, ils croient en vous, Seigneur.'),
('sg',12,3,'crampon1923','Vous aviez en haine les anciens habitants de votre terre sainte,'),
('sg',12,4,'crampon1923','parce qu''ils se livraient à des œuvres détestables de magie, à des cérémonies impies,'),
('sg',12,5,'crampon1923','et à des meurtres cruels d''enfants, dévorant des chairs humaines et s''abreuvant de sang. Ces initiés à d''abominables mystères,'),
('sg',12,6,'crampon1923','ces parents meurtriers d''êtres sans défense, vous vouliez les détruire par la main de nos pères,'),
('sg',12,7,'crampon1923','afin que cette terre que vous honorez entre toutes reçût une digne colonie d''enfants de Dieu.'),
('sg',12,8,'crampon1923','Cependant, comme ils étaient hommes, vous avez usé de clémence, et vous avez envoyé, comme avant-coureurs de votre armée, des frelons pour les faire périr peu à peu.'),
('sg',12,9,'crampon1923','Non qu''il vous fût impossible de faire tomber ces impies, dans une bataille rangée, sous la main des justes, ou de les exterminer d''un seul coup par des bêtes féroces, ou par un ordre rigoureux;'),
('sg',12,10,'crampon1923','mais, en exerçant vos jugements par degré, vous leur donniez lieu de faire pénitence, quoique vous sussiez bien qu''ils étaient une race perverse, que leur malice était innée, et que leurs pensées ne changeraient jamais;'),
('sg',12,11,'crampon1923','car c''était une race maudite dès l''origine. Ce n''est pas non plus par crainte de personne que vous vous êtes montré indulgent pour leurs péchés.'),
('sg',12,12,'crampon1923','Qui en effet pourrait vous dire: « Qu''avez-vous fait? » Qui pourrait s''opposer à votre jugement? Qui vous accuserait de faire périr les nations que vous avez faites? Qui viendrait plaider contre vous la cause d''hommes impies?'),
('sg',12,13,'crampon1923','Car il n''y a pas d''autre Dieu que vous, qui prenez soin de toutes choses, afin de montrer que vous ne jugez pas injustement.'),
('sg',12,14,'crampon1923','Il n''y a ni roi ni tyran qui puisse se lever contre vous, pour la défense de ceux que vous avez châtiés.'),
('sg',12,15,'crampon1923','Mais, comme vous êtes juste, vous réglez tout avec justice, et vous regardez comme une chose contraire à votre puissance de condamner aussi celui qui ne mérite pas de châtiment.'),
('sg',12,16,'crampon1923','Car votre puissance est le fondement de la justice, et c''est parce que vous êtes le Seigneur de tous que vous usez d''indulgence envers tous.'),
('sg',12,17,'crampon1923','C''est à ceux qui ne croient pas à votre toute-puissance que vous montrez votre force, et vous confondez l''audace de ceux qui la connaissent.'),
('sg',12,18,'crampon1923','Maître de votre force, vous jugez avec douceur, et vous nous gouvernez avec une grande indulgence, car la puissance est avec vous quand vous le voulez.'),
('sg',12,19,'crampon1923','En agissant ainsi, vous avez appris à votre peuple que le juste doit être humain, et vous avez inspiré à vos enfants la joyeuse espérance que, s''ils pèchent, vous leur accordez le temps du repentir.'),
('sg',12,20,'crampon1923','Si, en effet, vous avez puni, avec tant de ménagement et d''indulgence, les ennemis de vos serviteurs, bien qu''ils fussent dignes de mort, leur donnant le temps et l''occasion de se convertir de leur malice,'),
('sg',12,21,'crampon1923','avec quelle circonspection jugez-vous vos enfants, dont les pères ont reçu de vous des serments et des alliances, jointes à de magnifiques promesses!'),
('sg',12,22,'crampon1923','Quand vous nous corrigez, vous flagellez nos ennemis mille fois plus fort, pour nous apprendre, quand nous jugeons, à songer à votre bonté, et, quand nous sommes jugés, à espérer en votre miséricorde.'),
('sg',12,23,'crampon1923','Voilà pourquoi vous avez tourmenté par leurs propres abominations, les injustes qui passaient leur vie dans la folie.'),
('sg',12,24,'crampon1923','Car ils s''étaient enfoncés si loin dans les voies de l''erreur, qu''ils regardaient comme des dieux les plus vils des animaux, s''étant laissé tromper comme des enfants sans raison.'),
('sg',12,25,'crampon1923','Aussi comme à des enfants sans raison, leur avez-vous envoyé d''abord un châtiment dérisoire.'),
('sg',12,26,'crampon1923','Mais ceux qu''une correction dérisoire n''a pas amendés, subiront un châtiment digne de Dieu.'),
('sg',12,27,'crampon1923','Châtiés par ceux qu''ils prenaient pour des dieux, ils furent exaspérés de leurs souffrances, et, voyant Celui qu''ils avaient autrefois refusé de connaître, ils le reconnurent pour le Dieu véritable; c''est pourquoi la suprême condamnation tomba sur eux.'),
('sg',13,1,'crampon1923','Insensés par nature tous les hommes qui ont ignoré Dieu, et qui n''ont pas su, par les biens visibles, voir Celui qui est, ni, par la considération de ses œuvres, reconnaître l''Ouvrier.'),
('sg',13,2,'crampon1923','Mais ils ont regardé le feu, le vent, l''air mobile, le cercle des étoiles, l''eau impétueuse, les flambeaux du ciel, comme des dieux gouvernant l''univers.'),
('sg',13,3,'crampon1923','Si, charmés de leur beauté, ils ont pris ces créatures pour des dieux, qu''ils sachent combien le Maître l''emporte sur elles; car c''est l''Auteur même de la beauté qui les a faites.'),
('sg',13,4,'crampon1923','Et s''ils en admiraient la puissance et les effets, qu''ils en concluent combien est plus puissant celui qui les a faites.'),
('sg',13,5,'crampon1923','Car la grandeur et la beauté des créatures font connaître par analogie Celui qui en est le Créateur.'),
('sg',13,6,'crampon1923','Ceux-ci pourtant encourent un moindre reproche; car ils s''égarent peut-être en cherchant Dieu et en voulant le trouver.'),
('sg',13,7,'crampon1923','Occupés de ses œuvres, ils en font l''objet de leurs recherches, et s''en rapportent à l''apparence, tant ce qu''ils voient est beau!'),
('sg',13,8,'crampon1923','D''autre part, ils ne sont pas non plus excusables;'),
('sg',13,9,'crampon1923','car, s''ils ont acquis assez de science pour arriver à connaître le monde, comment n''en ont-ils pas connu plus facilement le Maître?'),
('sg',13,10,'crampon1923','Mais ils sont bien malheureux, et ils mettent leur espérance en des objets sans vie, ceux qui ont appelé Dieu des ouvrages de la main des hommes, de l''or et de l''argent travaillés avec art, des figures d''animaux ou une pierre inutile, ouvrage d''une main antique.'),
('sg',13,11,'crampon1923','Voici qu''un artisan a coupé un arbre facile à travailler; il en ôte adroitement toute l''écorce, et, le façonnant avec habileté, il en fabrique un meuble utile pour l''usage de la vie.'),
('sg',13,12,'crampon1923','Son travail achevé, il emploie ce qui reste à faire cuire ses aliments, et satisfait sa faim.'),
('sg',13,13,'crampon1923','Quant aux derniers débris, qui ne sont plus d''aucun usage, au bois tordu et plein de nœuds, il le prend, le taille pour occuper ses loisirs, et, par un travail habile, lui donne une figure: il le fait ressembler à un homme.'),
('sg',13,14,'crampon1923','Ou bien il en fait l''image de quelque vil animal, le peint de vermillon, en recouvre la surface d''une couleur rouge, et fait disparaître sous un enduit toutes les taches.'),
('sg',13,15,'crampon1923','Puis, lui ayant disposé une habitation convenable, il le place contre la muraille et le fixe avec du fer.'),
('sg',13,16,'crampon1923','Il prend bien garde qu''il ne tombe, sachant que le dieu ne peut s''aider lui-même, car ce n''est qu''une statue qui a besoin d''appui.'),
('sg',13,17,'crampon1923','Cependant il le prie au sujet de ses biens, de ses mariages et de ses enfants, et il ne rougit pas de parler à ce qui n''a point d''âme. Il demande la santé à ce qui est sans force,'),
('sg',13,18,'crampon1923','la vie à ce qui est mort, le secours à ce qui ne peut rendre aucun service, un heureux voyage à ce qui ne peut se servir de ses pieds.'),
('sg',13,19,'crampon1923','Pour assurer ses profits, ses entreprises, le succès de son travail, il demande l''énergie à ce qui a les mains les plus débiles.'),
('sg',14,1,'crampon1923','En voici un autre qui pense à prendre la mer, et se dispose à voyager sur les flots en fureur: il invoque un bois plus fragile encore que le vaisseau qui le porte;'),
('sg',14,2,'crampon1923','car, ce vaisseau, c''est la passion du lucre qui l''a inventé, et c''est l''habileté de l''ouvrier qui l''a construit.'),
('sg',14,3,'crampon1923','Mais, ô Père, c''est votre providence qui le gouverne, vous qui avez même ouvert un chemin dans la mer, et une route sûre au milieu des flots,'),
('sg',14,4,'crampon1923','montrant par là que vous pouvez délivrer de tout péril, afin que, même sans la science de la navigation, on puisse se mettre en mer. Vous ne voulez pas que les œuvres de votre sagesse restent inutiles; c''est pourquoi les hommes, confiant leur vie à un bois fragile,'),
('sg',14,5,'crampon1923','traversent les vagues sur un radeau, et échappent à la mort.'),
('sg',14,6,'crampon1923','Et jadis, alors que les géants orgueilleux périssaient, l''espérance de l''univers échappa sur une barque, et, gouvernée par votre main, laissa au monde la semence d''une postérité.'),
('sg',14,7,'crampon1923','Car béni est le bois qui sert à un juste usage.'),
('sg',14,8,'crampon1923','Mais l''idole, œuvre de la main des hommes, est maudite, elle et son auteur: celui-ci parce qu''il l''a faite, celle-là parce qu''étant périssable, elle est appelée dieu;'),
('sg',14,9,'crampon1923','car Dieu hait également l''impie et son impiété,'),
('sg',14,10,'crampon1923','et l''œuvre et l''ouvrier seront pareillement châtiés.'),
('sg',14,11,'crampon1923','C''est pourquoi les idoles des nations seront visitées, parce que, créatures de Dieu, elles sont devenues une abomination, un scandale pour les âmes des hommes, un piège pour les pieds des insensés.'),
('sg',14,12,'crampon1923','L''idée de faire des idoles fut le principe de la fornication, et leur invention a amené la perte de la vie.'),
('sg',14,13,'crampon1923','Il n''y en avait pas à l''origine et il n''y en aura pas toujours.'),
('sg',14,14,'crampon1923','C''est la vanité des hommes qui les a introduites dans le monde; aussi leur fin prochaine est-elle arrêtée dans la pensée divine.'),
('sg',14,15,'crampon1923','Un père accablé par une douleur prématurée a façonné l''image d''un fils qui lui a été trop tôt enlevé; et cet enfant qui était mort, il s''est mis à l''honorer comme un dieu, et il a institué parmi les gens de sa maison des rites pieux et des cérémonies.'),
('sg',14,16,'crampon1923','Puis, cette coutume impie, s''affermissant avec le temps, fut observée comme une loi, et, sur l''ordre des princes, on adora les statues.'),
('sg',14,17,'crampon1923','Quand on ne pouvait les honorer en face, parce qu''ils habitaient trop loin, on se représentait leur lointaine figure, et l''on façonnait une image visible du roi vénéré, afin de rendre à l''absent des hommages aussi empressés que s''il eût été présent.'),
('sg',14,18,'crampon1923','Et, pour le succès de la superstition, ceux qui ne le connaissaient pas y furent amenés par l''ambition de l''artiste.'),
('sg',14,19,'crampon1923','Celui-ci, en effet, désireux de plaire au maître puissant, épuisa tout son art à embellir le portrait.'),
('sg',14,20,'crampon1923','Et la foule des hommes, séduite par l''élégance de l''œuvre, regarda comme un dieu celui qui naguère était honoré comme un homme.'),
('sg',14,21,'crampon1923','Ce fut un piège pour les vivants que les hommes, sous l''influence de l''infortune ou de la tyrannie, eussent donné à la pierre ou au bois le nom incommunicable.'),
('sg',14,22,'crampon1923','Bientôt ce ne fut pas assez pour eux d''errer dans la notion de Dieu; vivant dans un état de lutte violente, par suite de leur ignorance, ils appelaient du nom de paix de tels maux.'),
('sg',14,23,'crampon1923','Célébrant des cérémonies homicides de leurs enfants ou des mystères clandestins, et se livrant aux débauches effrénées de rites étranges,'),
('sg',14,24,'crampon1923','ils n''ont plus gardé de pudeur ni dans leur vie, ni dans leurs mariages. L''un tue l''autre par la trahison, ou l''outrage par l''adultère.'),
('sg',14,25,'crampon1923','C''est partout un mélange de sang et de meurtre, de vol et de tromperie, de corruption et d''infidélité, de révolte et de parjure,'),
('sg',14,26,'crampon1923','de persécution des gens de bien, d''oubli des bienfaits, de souillure des âmes, de crimes contre nature, d''instabilité dans les unions, d''adultère et d''impudicité.'),
('sg',14,27,'crampon1923','Car le culte des idoles sans nom est le principe, la cause et la fin de tout mal.'),
('sg',14,28,'crampon1923','Leurs divertissements sont de folles joies, et leurs oracles, des mensonges; ils vivent dans l''injustice et se parjurent sans scrupule.'),
('sg',14,29,'crampon1923','Comme ils mettent leur confiance en des idoles sans vie, ils n''attendent aucun préjudice de leurs parjures.'),
('sg',14,30,'crampon1923','Mais un juste châtiment les frappera pour ce double crime: parce que, s''attachant aux idoles, ils ont eu sur Dieu des pensées perverses, et parce qu''ils ont fait par fourberie des serments contre la justice, au mépris des plus saintes lois.'),
('sg',14,31,'crampon1923','Ce n''est pas la puissance des idoles par lesquelles ils ont juré, c''est le châtiment dû aux pécheurs qui atteint toujours la prévarication des impies.'),
('sg',15,1,'crampon1923','Mais vous, ô notre Dieu, vous êtes bon, fidèle et patient, et vous gouvernez tout avec miséricorde.'),
('sg',15,2,'crampon1923','Lors même que nous péchons, nous sommes à vous, connaissant votre puissance; mais nous ne voulons pas pécher, car nous savons que nous sommes comptés parmi les vôtres.'),
('sg',15,3,'crampon1923','Vous connaître est la justice parfaite, et connaître votre puissance est la racine de l''immortalité.'),
('sg',15,4,'crampon1923','Nous n''avons pas été égarés par l''invention d''un art funeste, ni par une figure barbouillée de diverses couleurs, vain travail d''un peintre:'),
('sg',15,5,'crampon1923','objets dont l''aspect excite la passion de l''insensé, qui s''éprend pour la figure inanimée d''une image sans vie.'),
('sg',15,6,'crampon1923','Affectionnant le mal, ils sont dignes de telles espérances, aussi bien ceux qui les font que ceux qui les aiment ou les adorent.'),
('sg',15,7,'crampon1923','En effet, voici un potier qui pétrit laborieusement la terre molle; il façonne chaque vase pour notre usage, et de la même argile il fait des vases qui sont destinés à de nobles emplois, et d''autres à des emplois tout contraires, sans distinguer nullement à quel usage chacun d''eux devra servir: c''est le potier qui en est juge.'),
('sg',15,8,'crampon1923','Ensuite, par un travail impie, de la même argile, il façonne une vaine divinité, lui qui, naguère fait de terre, retournera bientôt au lieu d''où il a été tiré, quand on lui redemandera son âme qui lui avait été prêtée.'),
('sg',15,9,'crampon1923','Pourtant il ne s''inquiète pas de ce que ses forces s''épuisent, ni de ce que sa vie est courte; mais il rivalise avec ceux qui travaillent l''or et l''argent, il imite ceux qui travaillent l''airain, et met sa gloire à exécuter des figures trompeuses.'),
('sg',15,10,'crampon1923','Son cœur est comme de la cendre, son espérance est plus vile que la terre, et sa vie est de moindre valeur que l''argile.'),
('sg',15,11,'crampon1923','Car il méconnaît celui qui l''a fait, qui lui a inspiré une âme agissante, et a mis en lui un souffle de vie.'),
('sg',15,12,'crampon1923','Il regarde notre existence comme un amusement, la vie comme un marché où l''on se rassemble pour le gain; car, disent-ils, « il faut acquérir par tous les moyens, même par le crime. »'),
('sg',15,13,'crampon1923','Car celui-là sait bien qu''il est plus coupable que tous les autres, qui, de la même terre, façonne des vases fragiles et des idoles.'),
('sg',15,14,'crampon1923','Mais ils sont tous très insensés, et plus malheureux que l''âme d''un enfant, les ennemis de votre peuple qui le tiennent dans l''oppression!'),
('sg',15,15,'crampon1923','Car ils ont regardé comme des dieux toutes les idoles des nations, qui ne peuvent user de leurs yeux pour voir, ni de leurs narines pour respirer l''air, ni de leurs oreilles pour entendre, ni des doigts de leurs mains pour toucher, et dont les pieds sont incapables de marcher.'),
('sg',15,16,'crampon1923','C''est un homme qui les a faites, et c''est celui à qui on a prêté le souffle qui les a façonnées. Il n''est pas d''homme qui puisse faire un dieu semblable à lui,'),
('sg',15,17,'crampon1923','car, étant mortel, il ne fait de ses mains impies qu''une œuvre morte; il vaut mieux que les objets qu''il adore, car au moins il a la vie, et eux ne l''ont jamais eue.'),
('sg',15,18,'crampon1923','Ils rendent un culte aux animaux les plus odieux, lesquels, jugés d''après la stupidité, sont pires que les autres.'),
('sg',15,19,'crampon1923','Il n''y a rien de bon en eux qui fasse naître l''affection, comme à l''aspect d''autres animaux; ils échappent à la louange de Dieu et à sa bénédiction.'),
('sg',16,1,'crampon1923','C''est pourquoi ils ont été justement châtiés par des créatures semblables et tourmentés par une multitude de bêtes.'),
('sg',16,2,'crampon1923','A la place de ces fléaux, vous avez accordé des bienfaits à votre peuple, et, pour satisfaire son ardent désir, vous lui avez préparé un aliment merveilleux, des cailles en nourriture:'),
('sg',16,3,'crampon1923','de sorte que les uns, malgré leur désir de manger, à l''aspect répugnant des insectes envoyés contre eux, prirent en aversion même leur appétit naturel, tandis que les autres, après une légère privation, goûtèrent une nourriture nouvelle.'),
('sg',16,4,'crampon1923','Car il fallait qu''une disette inévitable affligeât les premiers, les oppresseurs, et qu''il fût seulement montré aux autres comment leurs ennemis étaient tourmentés.'),
('sg',16,5,'crampon1923','En effet, lorsque ceux-ci souffraient de la fureur de bêtes cruelles, et qu''ils périssaient sous la morsure de serpents tortueux, votre colère ne dura pas jusqu''à la fin;'),
('sg',16,6,'crampon1923','ils furent troublés un moment, en vue de leur correction, et ils eurent un signe de salut, pour leur rappeler les préceptes de votre loi.'),
('sg',16,7,'crampon1923','Car celui qui se tournait de son côté était guéri, non par l''objet qu''il avait sous les yeux, mais par vous, qui êtes le sauveur de tous.'),
('sg',16,8,'crampon1923','Mais par là, vous avez aussi appris à nos ennemis que c''est vous qui délivrez de tout mal.'),
('sg',16,9,'crampon1923','En effet, la morsure des sauterelles et des moucherons les fit périr, et il ne se trouva aucun moyen de sauver leur vie, parce qu''ils méritaient d''être châtiés de la sorte.'),
('sg',16,10,'crampon1923','Vos enfants ne furent pas vaincus par la dent des serpents venimeux, car votre miséricorde vint à leur secours et les guérit.'),
('sg',16,11,'crampon1923','C''est pour que vos paroles leur revinssent en mémoire qu''ils étaient blessés, et promptement guéris, de peur que, venant à les oublier entièrement, ils ne fussent exclus de vos bienfaits.'),
('sg',16,12,'crampon1923','Ce ne fut ni une herbe, ni un médicament qui les guérit, mais votre parole, Seigneur, qui guérit tout.'),
('sg',16,13,'crampon1923','Car vous avez puissance sur la vie et sur la mort; vous menez aux portes du séjour des morts et vous en ramenez.'),
('sg',16,14,'crampon1923','L''homme, dans sa méchanceté, peut bien donner la mort, mais non ramener l''esprit une fois sorti, ni délivrer l''âme que le schéol a reçue.'),
('sg',16,15,'crampon1923','Mais il est impossible d''échapper à votre main.'),
('sg',16,16,'crampon1923','Les impies qui prétendaient ne pas vous connaître ont été flagellés par la force de votre bras; des eaux extraordinaires, la grêle et des pluies inexorables les ont tourmentés, et le feu les a consumés.'),
('sg',16,17,'crampon1923','Ce qui était le plus étrange c''est que, dans l''eau qui éteint tout, le feu n''était que plus ardent, car l''univers combat pour les justes.'),
('sg',16,18,'crampon1923','Tantôt la flamme s''adoucissait, afin que les animaux envoyés contre les impies ne fussent pas consumés, et que ceux-ci, à cette vue, reconnussent qu''un jugement de Dieu les poursuivait.'),
('sg',16,19,'crampon1923','Tantôt elle brûlait au sein même de l''eau, avec plus de force que n''en comporte la nature du feu, afin de détruire tous les produits d''une nation impie.'),
('sg',16,20,'crampon1923','Au lieu de cela, vous avez rassasié votre peuple de la nourriture des anges, et vous leur avez donné du ciel, sans travail, un pain tout préparé, procurant toute jouissance et approprié à tous les goûts.'),
('sg',16,21,'crampon1923','Cette substance, envoyée par vous, montrait la douceur que vous avez envers vos enfants, et ce pain, s''accommodant au désir de celui qui le mangeait, se changeait en ce qu''il voulait.'),
('sg',16,22,'crampon1923','La neige et la glace soutenaient la violence du feu sans se fondre, afin qu''ils sussent que le feu, qui brûlait dans la grêle et étincelait dans la pluie, détruisait les récoltes de leurs ennemis,'),
('sg',16,23,'crampon1923','et qu''il oubliait ensuite sa vertu propre, pour l''entretien des justes.'),
('sg',16,24,'crampon1923','Car la créature, soumis à vous, son Créateur, déploie son énergie pour tourmenter les méchants, et se relâche pour procurer le bien de ceux qui se confient en vous.'),
('sg',16,25,'crampon1923','C''est pourquoi, se pliant alors à tous ces changements, elle était aux ordres de votre grâce, qui nourrit tout, selon la volonté de ceux qui étaient dans le besoin;'),
('sg',16,26,'crampon1923','afin que vos enfants que vous aimez, Seigneur, apprissent que ce ne sont pas les différentes espèces de fruits qui nourrissent les hommes, mais que c''est votre parole qui conserve ceux qui croient en vous.'),
('sg',16,27,'crampon1923','Car ce qui résistait à l''action destructive du feu se fondait aisément, échauffé par le moindre rayon de soleil:'),
('sg',16,28,'crampon1923','afin d''apprendre à tous qu''il faut devancer le soleil pour vous rendre grâces, et vous adorer dès le lever du jour.'),
('sg',16,29,'crampon1923','Quant à l''ingrat, son espérance fondra comme la glace d''hiver, et s''écoulera comme une eau inutile.'),
('sg',17,1,'crampon1923','Car vos jugements sont grands et difficiles à expliquer; aussi les âmes sans instruction se sont-elles égarées.'),
('sg',17,2,'crampon1923','Alors que les méchants s''étaient persuadés qu''ils pouvaient opprimer la nation sainte, enchaînés par les ténèbres et prisonniers d''une longue nuit, enfermés sous leur toit, ils gisaient là, fuyant eux-mêmes votre incessante providence.'),
('sg',17,3,'crampon1923','Alors qu''ils imaginaient rester cachés avec leurs péchés secrets, sous le voile épais de l''oubli, ils furent dispersés, saisis d''une horrible épouvante, et effrayés par des fantômes.'),
('sg',17,4,'crampon1923','Les réduits où ils se renfermaient ne les préservaient pas de la crainte: des bruits effrayants retentissaient autour d''eux, et des spectres leur apparaissaient avec des visages lugubres.'),
('sg',17,5,'crampon1923','Il n''y avait pas de feu capable de donner de la lumière, et les flammes brillantes des astres ne pouvaient éclairer cette horrible nuit.'),
('sg',17,6,'crampon1923','Parfois seulement, leur apparaissait une masse de feu, allumée d''elle-même, effrayante, et, épouvantés de cette vision dont ils n''apercevaient pas la cause, ils jugeaient ces apparitions plus terribles encore.'),
('sg',17,7,'crampon1923','L''art dérisoire des magiciens était à bout, et leur prétention à la sagesse honteusement convaincue de fausseté.'),
('sg',17,8,'crampon1923','Eux qui se faisaient forts de chasser des âmes malades la terreur et le trouble, ils étaient malades eux-mêmes d''une peur ridicule.'),
('sg',17,9,'crampon1923','Car, quoiqu''il n''y eût rien de terrible pour les effrayer, le passage des animaux et le sifflement des serpents les terrifiaient;'),
('sg',17,10,'crampon1923','et ils mouraient de frayeur, se refusant à voir cet air auquel nul ne peut échapper.'),
('sg',17,11,'crampon1923','— Car la perversité est craintive, condamnée qu''elle est par son propre témoignage; pressée par sa conscience, elle s''exagère toujours le mal.'),
('sg',17,12,'crampon1923','La crainte, en effet, n''est pas autre chose que l''abandon des secours qu''apporterait la réflexion.'),
('sg',17,13,'crampon1923','L''espérance étant moindre au fond du cœur, on s''effraie d''autant plus d''ignorer la cause de ses tourments. —'),
('sg',17,14,'crampon1923','Eux, pendant cette nuit d''impuissance, sortie des profondeurs du schéol impuissant, endormis du même sommeil,'),
('sg',17,15,'crampon1923','étaient tantôt agités par des spectres terrifiants, tantôt abattus par la défaillance de leur âme; car une épouvante subite et inattendue s''était répandue sur eux.'),
('sg',17,16,'crampon1923','De même tous les autres, quels qu''ils fussent, tombant là sans force, étaient retenus comme enfermés dans une prison sans verrous.'),
('sg',17,17,'crampon1923','Le laboureur, le berger, l''ouvrier occupé aux rudes travaux de la campagne, surpris par le fléau, étaient soumis à l''inévitable nécessité;'),
('sg',17,18,'crampon1923','car tous étaient liés par la même chaîne de ténèbres. Le vent qui sifflait, le chant mélodieux des oiseaux dans les rameaux épais, le bruit des eaux précipitant leur cours,'),
('sg',17,19,'crampon1923','le fracas des pierres qui roulaient, la course invisible des animaux bondissants, les hurlements des bêtes féroces, l''écho se répercutant dans les cavités des montagnes, tout les faisait pâmer d''effroi.'),
('sg',17,20,'crampon1923','Car tandis que tout l''univers était éclairé d''une lumière brillante, et se livrait sans obstacle à ses travaux,'),
('sg',17,21,'crampon1923','sur eux seuls s''étendait une nuit pesante, image des ténèbres qui devaient les recevoir; mais ils étaient encore plus à charge à eux-mêmes que les ténèbres.'),
('sg',18,1,'crampon1923','Cependant une grande lumière brillait pour vos saints; les Égyptiens entendaient leur voix sans voir leur visage, et, malgré leurs souffrances passées, les proclamaient heureux.'),
('sg',18,2,'crampon1923','Et parce que, après avoir été maltraités, ils ne se vengeaient pas, ils leur rendaient grâces, et leur demandaient pardon de les avoir traités en ennemis.'),
('sg',18,3,'crampon1923','A la place de ces ténèbres, vous avez donné à vos saints une colonne de feu, guide dans une route inconnue, soleil inoffensif pour leur glorieux pèlerinage.'),
('sg',18,4,'crampon1923','Ils méritaient bien d''être privés de lumière, et d''être emprisonnés dans les ténèbres, ceux qui tenaient enfermés vos enfants, par qui la lumière incorruptible de votre loi devait être donnée au monde.'),
('sg',18,5,'crampon1923','Ils avaient résolu de faire périr les enfants des saints, et, l''un de ces derniers ayant été exposé et délivré, vous leur avez, pour leur châtiment, enlevé la multitude de leurs fils, et vous les avez engloutis tous ensemble dans les flots impétueux.'),
('sg',18,6,'crampon1923','Cette nuit avait été connue d''avance par nos pères, afin que, sachant bien à quelles promesses ils avaient cru, ils eussent meilleur courage.'),
('sg',18,7,'crampon1923','Et ainsi votre peuple attendit la délivrance des justes et l''extermination de ses ennemis.'),
('sg',18,8,'crampon1923','De même que vous avez châtié nos adversaires, du même coup vous nous avez glorifiés en nous appelant à vous.'),
('sg',18,9,'crampon1923','En effet, les pieux enfants des saints offraient leur sacrifice en secret, et faisaient d''un commun accord ce pacte divin; que les saints participeraient aux mêmes biens et aux mêmes dangers; — chantant déjà d''avance les hymnes de leurs pères.'),
('sg',18,10,'crampon1923','Pour leur faire écho, retentissaient les cris discordants des ennemis, et l''on entendait des lamentations sur les enfants qu''on pleurait.'),
('sg',18,11,'crampon1923','L''esclave et le maître étaient punis de la même peine, et l''homme du peuple souffrait la même chose que le roi.'),
('sg',18,12,'crampon1923','Ils avaient tous pareillement, dans un seul genre de mort, des morts sans nombre, et les vivants ne suffisaient pas aux funérailles, car leurs plus nobles rejetons avaient été exterminés en un instant.'),
('sg',18,13,'crampon1923','Ils avaient refusé de croire à cause de leurs sortilèges; quand arriva l''extermination des premiers-nés, ils reconnurent que ce peuple était fils de Dieu.'),
('sg',18,14,'crampon1923','Pendant qu''un profond silence enveloppait tout le pays, et que la nuit était arrivée au milieu de sa course rapide,'),
('sg',18,15,'crampon1923','votre Parole toute-puissante s''élança du haut du ciel, de son trône royal, comme un guerrier impitoyable, au milieu d''une terre vouée à l''extermination,'),
('sg',18,16,'crampon1923','portant comme un glaive aigu votre irrévocable décret; elle était là, remplissant tout de mort; elle touchait au ciel et se tenait sur la terre.'),
('sg',18,17,'crampon1923','Aussitôt des visions de songes effrayants les troublèrent, et des terreurs inattendues tombèrent sur eux.'),
('sg',18,18,'crampon1923','Jetés par terre çà et là à demi-morts, ils révélaient la cause pour laquelle ils mouraient.'),
('sg',18,19,'crampon1923','Car les songes qui les troublaient la leur avaient révélée, afin qu''ils ne mourussent pas sans savoir pourquoi ils étaient si rudement frappés.'),
('sg',18,20,'crampon1923','L''épreuve de la mort atteignit aussi les justes, et il y eut dans le désert une destruction de la multitude; mais votre colère ne dura pas longtemps.'),
('sg',18,21,'crampon1923','Car un homme sans reproche se hâta de combattre pour les coupables; prenant les armes de son ministère, la prière et l''encens expiatoire, il résista à la colère divine et mit un terme au fléau, montrant qu''il était votre serviteur.'),
('sg',18,22,'crampon1923','Il vint à bout de cette sédition, non par la force corporelle, ni par la puissance des armes; mais il dompta par la parole celui qui les châtiait, en rappelant les serments faits aux pères et les alliances.'),
('sg',18,23,'crampon1923','Lorsque déjà les morts étaient tombés en tas les uns sur les autres, s''interposant, il arrêta la colère, et ferma à l''Exterminateur le chemin des survivants.'),
('sg',18,24,'crampon1923','Car sur la robe qui tombait jusqu''à terre était tout l''univers; les noms glorieux des pères étaient gravés sur les quatre rangées de pierres précieuses, et votre majesté sur le diadème de sa tête.'),
('sg',18,25,'crampon1923','Devant ces symboles, l''Exterminateur se retira, il en fut effrayé; car la seule expérience de votre colère était suffisante.'),
('sg',19,1,'crampon1923','Mais une colère sans miséricorde poursuit les impies jusqu''à la fin. Car Dieu savait d''avance quelle serait leur conduite:'),
('sg',19,2,'crampon1923','Qu''après avoir permis aux justes de s''en aller, et pressé leur départ avec grande instance, ils en auraient du regret et se mettraient à leur poursuite.'),
('sg',19,3,'crampon1923','En effet, ils n''avaient pas encore achevé leurs deuils, et ils se lamentaient encore aux tombeaux de leurs morts, qu''ils s''engagèrent dans un autre dessein de folie, et poursuivirent comme des fugitifs ceux qu''ils avaient conjurés de s''éloigner.'),
('sg',19,4,'crampon1923','Une juste nécessité les entraînait à cette fin, et leur faisait oublier ce qui venait de leur arriver, afin qu''ils subissent dans la pleine mesure le châtiment qui manquait encore à leurs précédents supplices,'),
('sg',19,5,'crampon1923','et que, tandis que votre peuple bénéficiait d''un glorieux passage, ils trouvassent une mort étrange.'),
('sg',19,6,'crampon1923','Car la création tout entière fut transformée dans sa nature, obéissant aux commandements particuliers qui lui étaient donnés, afin que vos enfants fussent conservés à l''abri de tout mal.'),
('sg',19,7,'crampon1923','Ainsi on vit une nuée couvrir le camp de son ombre; là où il y avait auparavant de l''eau, apparut la terre ferme; la mer Rouge ouvrit un libre passage, et les flots impétueux se changèrent en un champ de verdure.'),
('sg',19,8,'crampon1923','Ils y passèrent, — toute une nation, — protégés par ta main, ayant sous les yeux de merveilleux prodiges.'),
('sg',19,9,'crampon1923','Comme des chevaux en pâturage, comme des agneaux bondissants, ils vous glorifiaient, Seigneur, vous, leur libérateur.'),
('sg',19,10,'crampon1923','Car ils se rappelaient encore ce qui s''était passé en leur séjour au pays étranger: comment, à la place des autres animaux, la terre avait produit des moustiques, et le fleuve, au lieu de poissons, une multitude de grenouilles.'),
('sg',19,11,'crampon1923','Plus tard, ils virent encore une étrange production d''oiseaux, lorsque, poussés par la convoitise, ils demandèrent une nourriture délicate:'),
('sg',19,12,'crampon1923','pour les satisfaire, des cailles montèrent du côté de la mer.'),
('sg',19,13,'crampon1923','Mais le châtiment tomba sur les pécheurs, non sans être signalé d''avance par de violents éclairs. Il souffrirent justement pour leurs crimes,'),
('sg',19,14,'crampon1923','car ils avaient montré pour l''étranger la haine la plus odieuse. D''autres n''avaient pas voulu recevoir des gens qui ne les connaissaient pas; ceux-là avaient réduit en esclavage des étrangers qui leur avaient fait du bien.'),
('sg',19,15,'crampon1923','Il y a plus, — car voici une autre considération en faveur des premiers: C''est en ennemis qu''ils recevaient ces étrangers;'),
('sg',19,16,'crampon1923','ceux-là, au contraire, accueillirent votre peuple avec des fêtes; et, après l''avoir admis à la jouissance de leurs droits, l''accablèrent de cruelles souffrances.'),
('sg',19,17,'crampon1923','Aussi furent-ils frappés d''aveuglement, comme ceux qui assiégeaient la porte du juste, lorsque, enveloppés de ténèbres profondes, ils cherchaient chacun l''entrée de la porte.'),
('sg',19,18,'crampon1923','Car les éléments échangeaient leurs propriétés, comme dans le psaltérion les sons changent de rythme, tout en conservant le même ton. C''est ce qu''on peut voir clairement par les faits qui se sont passés.'),
('sg',19,19,'crampon1923','Les animaux terrestres devenaient aquatiques, et ceux qui nagent passaient sur la terre.'),
('sg',19,20,'crampon1923','Le feu dépassait dans l''eau sa vertu naturelle, et l''eau oubliait sa propriété d''éteindre.'),
('sg',19,21,'crampon1923','D''autre part, la flamme n''atteignait pas la chair des frêles animaux répandus tout autour, et ne fondait pas cet aliment céleste, semblable au givre et fusible comme lui.'),
('sg',19,22,'crampon1923','En toutes choses, Seigneur, vous avez glorifié votre peuple, vous l''avez honoré et vous ne l''avez pas méprisé; en tout temps et en tout lieu vous l''avez assisté.'),
('si',1,1,'crampon1923','Toute sagesse vient du Seigneur, elle est avec lui à jamais.'),
('si',1,2,'crampon1923','Qui peut compter le sable de la mer, les gouttes de la pluie et les jours du passé?'),
('si',1,3,'crampon1923','Qui peut atteindre les hauteurs du ciel, la largeur de la terre, la profondeur de l''abîme et la sagesse?'),
('si',1,4,'crampon1923','La sagesse a été créée avant toutes choses, et la lumière de l''intelligence dès l''éternité.'),
('si',1,5,'crampon1923','[La source de la sagesse, c''est la parole de Dieu au plus haut des cieux, ses voies sont les commandements éternels.]'),
('si',1,6,'crampon1923','A qui a été révélée la racine de la sagesse, et qui a connu ses desseins profonds?'),
('si',1,7,'crampon1923','[A qui la science de la sagesse a-t-elle été révélée et manifestée, et qui comprend la richesse de ses voies?]'),
('si',1,8,'crampon1923','Il n''y a qu''un sage grandement redoutable, assis sur son trône: c''est le Seigneur.'),
('si',1,9,'crampon1923','C''est lui qui l''a créée; il l''a vue et il l''a fait connaître.'),
('si',1,10,'crampon1923','Il l''a répandue sur toutes ses œuvres, ainsi que sur toute chair, selon la mesure de son don, il l''a donnée libéralement à ceux qui l''aiment.'),
('si',1,11,'crampon1923','La crainte du Seigneur est gloire et honneur, et joie, et couronne d''allégresse.'),
('si',1,12,'crampon1923','La crainte du Seigneur réjouit le cœur; elle donne gaieté, joie et longue vie.'),
('si',1,13,'crampon1923','Celui qui craint le Seigneur s''en trouvera bien à la fin, et il trouvera grâce au jour de sa mort. [L''amour de Dieu est une glorieuse sagesse; à ceux à qui il se montre, Dieu communique la sagesse, pour qu''ils le puissent contempler.]'),
('si',1,14,'crampon1923','Le commencement de la sagesse est de craindre Dieu; elle est formée avec les fidèles dans le sein de leur mère.'),
('si',1,15,'crampon1923','Elle s''est préparé chez les hommes une éternelle habitation; elle demeurera fidèlement avec leur race.'),
('si',1,16,'crampon1923','La plénitude de la sagesse est de craindre le Seigneur; elle rassasie de ses fruits ceux qui la possèdent.'),
('si',1,17,'crampon1923','Elle remplit toute sa maison de choses désirables, et ses greniers de ses produits.'),
('si',1,18,'crampon1923','La couronne de la sagesse, c''est la crainte du Seigneur; elle fait fleurir la paix et les fruits de salut.'),
('si',1,19,'crampon1923','Le Seigneur l''a vue et l''a manifestée; [et toutes deux sont des dons de Dieu.] Il fait pleuvoir à flots la science et la lumière de l''intelligence, il exalte la gloire de ceux qui la possèdent.'),
('si',1,20,'crampon1923','La racine de la sagesse, c''est de craindre le Seigneur, et ses rameaux sont une longue vie.'),
('si',1,21,'crampon1923','[La crainte du Seigneur bannit le péché, et celui qui s''y attache détourne la colère.]'),
('si',1,22,'crampon1923','L''homme injuste et emporté ne saurait être justifié, car la fougue de sa colère amène sa ruine.'),
('si',1,23,'crampon1923','L''homme patient attend jusqu''au temps voulu, et ensuite la joie lui est rendue.'),
('si',1,24,'crampon1923','Il cache jusqu''au temps voulu ses paroles, et les lèvres des fidèles raconteront sa prudence.'),
('si',1,25,'crampon1923','Les trésors de la sagesse renferment des maximes de prudence, mais la piété envers Dieu est en abomination au pécheur.'),
('si',1,26,'crampon1923','Désires-tu la sagesse? garde les commandements, et le Seigneur te l''accordera.'),
('si',1,27,'crampon1923','Car la sagesse et l''instruction, c''est la crainte du Seigneur, et ce qui lui plaît, c''est la fidélité et la mansuétude.'),
('si',1,28,'crampon1923','Ne te refuse pas à la crainte du Seigneur, et ne t''approche pas de lui avec un cœur double.'),
('si',1,29,'crampon1923','Ne sois pas hypocrite devant les hommes, et prends garde à tes lèvres.'),
('si',1,30,'crampon1923','Ne t''élève pas toi-même, de peur que tu ne tombes, et que tu n''attires sur toi la confusion. Car le Seigneur révélera ce que tu caches, et te précipitera au milieu de l''assemblée, parce que tu ne t''es pas adonné à la crainte du Seigneur, et que ton cœur est plein de fraude.'),
('si',2,1,'crampon1923','Mon fils, si tu entreprends de servir le Seigneur, prépare ton âme à l''épreuve.'),
('si',2,2,'crampon1923','Rends droit ton cœur et sois constant, et ne te précipite pas au temps du malheur.'),
('si',2,3,'crampon1923','Attache-toi à Dieu et ne t''en sépare pas, afin que tu grandisses à ta fin.'),
('si',2,4,'crampon1923','Tout ce qui vient sur toi, accepte-le, et, dans les vicissitudes de ton humiliation, sois patient.'),
('si',2,5,'crampon1923','Car l''or s''éprouve dans le feu, et les hommes agréables à Dieu dans le creuset de l''humiliation.'),
('si',2,6,'crampon1923','Aie foi en Dieu, et il te relèvera; rends tes voies droites, et espère en lui.'),
('si',2,7,'crampon1923','Vous qui craignez le Seigneur, attendez sa miséricorde, et ne vous détournez pas, de peur que vous ne tombiez.'),
('si',2,8,'crampon1923','Vous qui craignez le Seigneur, ayez foi en lui, et votre récompense ne se perdra pas.'),
('si',2,9,'crampon1923','Vous qui craignez le Seigneur, espérez le bonheur, la joie éternelle et la miséricorde.'),
('si',2,10,'crampon1923','Considérez les générations antiques, et voyez: qui jamais a espéré au Seigneur et a été confondu? Qui est resté fidèle à sa crainte et a été abandonné? Qui l''a invoqué et n''a reçu de lui que le mépris?'),
('si',2,11,'crampon1923','Car le Seigneur est compatissant et miséricordieux; il remet les péchés et délivre au jour de l''affliction.'),
('si',2,12,'crampon1923','Malheur aux cœurs timides, aux mains sans vigueur, au pécheur qui marche dans deux voies!'),
('si',2,13,'crampon1923','Malheur au cœur sans vigueur, parce qu''il n''a pas foi en Dieu! Aussi ne sera-t-il pas protégé.'),
('si',2,14,'crampon1923','Malheur à vous qui avez perdu la patience! Que ferez-vous au jour de la visite du Seigneur?'),
('si',2,15,'crampon1923','Ceux qui craignent le Seigneur ne sont pas indociles à ses paroles, et ceux qui l''aiment gardent fidèlement ses voies.'),
('si',2,16,'crampon1923','Ceux qui craignent le Seigneur cherchent son bon plaisir, et ceux qui l''aiment se rassasient de sa loi.'),
('si',2,17,'crampon1923','Ceux qui craignent le Seigneur préparent leurs cœurs, et tiennent leurs âmes humiliées devant lui,'),
('si',2,18,'crampon1923','en disant: Nous tomberons entre les mains du Seigneur, et non entre les mains des hommes; car autant il a de puissance, autant il a de miséricorde.'),
('si',3,1,'crampon1923','Mes enfants, écoutez-moi, moi qui suis votre père, et faites en sorte que vous obteniez le salut.'),
('si',3,2,'crampon1923','Car le Seigneur veut que le père soit honoré par ses enfants, et il a affermi sur les fils l''autorité de la mère.'),
('si',3,3,'crampon1923','Celui qui honore son père expie ses péchés,'),
('si',3,4,'crampon1923','et c''est amasser un trésor que d''honorer sa mère.'),
('si',3,5,'crampon1923','Celui qui honore son père sera réjoui par ses enfants, et il sera exaucé au jour de sa prière.'),
('si',3,6,'crampon1923','Celui qui honore son père aura de longs jours; celui qui obéit au Seigneur donnera consolation à sa mère.'),
('si',3,7,'crampon1923','[Celui qui craint le Seigneur honore ses parents;] et sert comme des maîtres ceux qui lui ont donné le jour.'),
('si',3,8,'crampon1923','En action et en parole honore ton père, afin que sa bénédiction vienne sur toi;'),
('si',3,9,'crampon1923','car la bénédiction du père affermit les maisons des enfants; mais la malédiction de la mère déracine les fondations.'),
('si',3,10,'crampon1923','Ne te glorifie pas de l''opprobre de ton père, car sa confusion ne saurait te faire honneur;'),
('si',3,11,'crampon1923','car la gloire d''un homme lui vient de l''honneur de son père, et une mère méprisée est la honte de ses enfants.'),
('si',3,12,'crampon1923','Mon fils, soutiens ton père dans sa vieillesse, et ne le contriste pas durant sa vie.'),
('si',3,13,'crampon1923','Son esprit viendrait-il à s''affaiblir, sois indulgent, et ne le méprise pas dans la plénitude de tes forces.'),
('si',3,14,'crampon1923','Car le bien fait à un père ne sera pas mis en oubli, et, à la place de tes péchés, ta maison deviendra prospère.'),
('si',3,15,'crampon1923','Au jour de la tribulation, le Seigneur se souviendra de toi; comme la glace se fond par un temps serein, ainsi se dissiperont tes péchés.'),
('si',3,16,'crampon1923','Il ressemble au blasphémateur celui qui délaisse son père; il est maudit du Seigneur celui qui irrite sa mère.'),
('si',3,17,'crampon1923','Mon fils, accomplis tes œuvres avec mansuétude, et tu seras aimé de l''homme agréable à Dieu.'),
('si',3,18,'crampon1923','Humilie-toi d''autant plus que tu es plus grand, et tu trouveras grâce devant le Seigneur;'),
('si',3,19,'crampon1923','car la puissance du Seigneur est grande, et il est glorifié par les humbles.'),
('si',3,20,'crampon1923','Ne cherche pas ce qui est trop difficile pour toi, et ne scrute pas ce qui dépasse tes forces.'),
('si',3,21,'crampon1923','Ce qui t''est commandé, voilà à quoi tu dois penser, car tu n''as que faire des choses cachées.'),
('si',3,22,'crampon1923','Ne t''applique point aux occupations superflues, car on t''en a déjà montré plus que l''esprit humain ne peut saisir.'),
('si',3,23,'crampon1923','Leur propre illusion en a égaré un grand nombre, et une présomption coupable a fait dévier leurs pensées.'),
('si',3,24,'crampon1923','Celui qui aime le danger y trouvera sa perte: et le cœur dur tombe à la fin dans le malheur.'),
('si',3,25,'crampon1923','Le cœur dur sera accablé d''afflictions, et le pécheur entasse péchés sur péchés.'),
('si',3,26,'crampon1923','Le malheur de l''orgueilleux est sans remède, car la plante du mal a jeté en lui ses racines.'),
('si',3,27,'crampon1923','Le cœur de l''homme intelligent médite la parabole; trouver une oreille attentive est le désir du sage.'),
('si',3,28,'crampon1923','L''eau éteint le feu le plus ardent, et l''aumône expie les péchés.'),
('si',3,29,'crampon1923','Celui qui paie de retour les bienfaits songe à l''avenir, et, au jour du malheur, il trouvera un appui.'),
('si',3,30,'crampon1923',''),
('si',3,31,'crampon1923',''),
('si',4,1,'crampon1923','Mon fils, ne prive pas le pauvre de sa subsistance, ne fais pas attendre les yeux de l''indigent.'),
('si',4,2,'crampon1923','N''afflige pas l''âme de celui qui a faim, et n''aigris pas l''homme indigent dans sa détresse.'),
('si',4,3,'crampon1923','N''irrite pas davantage un cœur exaspéré, et ne diffère pas de donner au nécessiteux.'),
('si',4,4,'crampon1923','Ne repousse pas le suppliant qui souffre, et ne détourne pas ton visage du pauvre.'),
('si',4,5,'crampon1923','Ne détourne pas ton regard du nécessiteux, et ne lui donne pas occasion de te maudire;'),
('si',4,6,'crampon1923','car s''il te maudit dans l''amertume de son âme, celui qui l''a fait écoutera sa prière.'),
('si',4,7,'crampon1923','Rends-toi agréable à la société, et devant un grand abaisse ton front.'),
('si',4,8,'crampon1923','Prête l''oreille au pauvre, et fais-lui avec douceur une réponse qui le réjouisse.'),
('si',4,9,'crampon1923','Tire l''opprimé des mains de l''oppresseur, et ne sois pas pusillanime quand tu rends la justice.'),
('si',4,10,'crampon1923','Sois comme un père pour les orphelins, comme son mari pour leur mère; et tu seras comme un fils du Très-Haut, qui t''aimera plus que ta mère.'),
('si',4,11,'crampon1923','La sagesse exalte ses enfants, et prend soin de ceux qui la cherchent.'),
('si',4,12,'crampon1923','Celui qui l''aime aime la vie, et ceux qui la cherchent avec empressement sont remplis de joie.'),
('si',4,13,'crampon1923','Celui qui la saisit aura la gloire en partage, et, partout où il entrera, le Seigneur le bénira.'),
('si',4,14,'crampon1923','Ceux qui la servent servent le Saint, et ceux qui l''aiment sont aimés du Seigneur.'),
('si',4,15,'crampon1923','Celui qui l''écoute jugera les nations, et celui qui vient à elle habitera en sécurité.'),
('si',4,16,'crampon1923','Celui qui met en elle sa confiance l''aura en partage, et sa postérité en gardera la possession.'),
('si',4,17,'crampon1923','Car, au début, elle s''engage avec lui dans une voie difficile; elle amène sur lui la crainte et la frayeur; elle le tourmente par sa dure discipline, jusqu''à ce qu''elle puisse se fier à lui, et qu''elle l''ait éprouvé par ses prescriptions.'),
('si',4,18,'crampon1923','Mais alors, elle revient à lui par le droit chemin; elle le réjouit et lui révèle ses secrets.'),
('si',4,19,'crampon1923','S''il s''égare, elle l''abandonne, et le livre à sa perte.'),
('si',4,20,'crampon1923','Observe le temps et garde-toi du mal, et n''aie pas à rougir de toi-même.'),
('si',4,21,'crampon1923','Il y a une honte qui amène le péché, et il y a une honte qui attire la gloire et la grâce.'),
('si',4,22,'crampon1923','N''aie égard à personne au préjudice de ton âme, et ne rougis pas pour ta perte.'),
('si',4,23,'crampon1923','Ne retiens pas une parole au temps de salut, [et ne cache pas ta sagesse par vaine gloire];'),
('si',4,24,'crampon1923','car c''est au langage qu''on reconnaît la sagesse, aux paroles de la langue que se montre la science.'),
('si',4,25,'crampon1923','Ne contredis pas la vérité, mais rougis de manquer d''instruction.'),
('si',4,26,'crampon1923','N''aie pas honte de confesser tes péchés, et ne lutte pas contre le cours du fleuve.'),
('si',4,27,'crampon1923','Ne te soumets pas à un homme insensé, et n''aie pas égard à la personne d''un puissant.'),
('si',4,28,'crampon1923','Jusqu''à la mort combats pour la vérité, et le Seigneur Dieu combattra pour toi.'),
('si',4,29,'crampon1923','Ne sois pas dur dans ton langage, paresseux et lâche dans tes actions.'),
('si',4,30,'crampon1923','Ne sois pas comme un lion dans ta maison, ni capricieux au milieu de tes serviteurs.'),
('si',4,31,'crampon1923','Que ta main ne soit pas étendue pour recevoir, et retirée en arrière pour donner.'),
('si',5,1,'crampon1923','Ne t''appuie pas sur tes richesses, et ne dis pas: « J''ai assez de bien! »'),
('si',5,2,'crampon1923','Ne suis pas ta convoitise et ta force, pour satisfaire les désirs de ton cœur;'),
('si',5,3,'crampon1923','et ne dis pas: « Qui sera mon maître? » Car certainement le Seigneur te punira.'),
('si',5,4,'crampon1923','Ne dis point: « J''ai péché, et que m''est-il arrivé? » Car le Seigneur est patient.'),
('si',5,5,'crampon1923','Ne sois pas sans crainte au sujet de l''expiation, pour ajouter péché à péché.'),
('si',5,6,'crampon1923','Ne dis point: « La miséricorde de Dieu est grande, il pardonnera la multitude de mes péchés. » Car en lui se trouvent la pitié et la colère, et son courroux tombe sur les pécheurs.'),
('si',5,7,'crampon1923','Ne tarde pas à te convertir au Seigneur, et ne diffère pas de jour en jour; car la colère du Seigneur éclatera tout à coup, et, au jour de la vengeance, tu périras.'),
('si',5,8,'crampon1923','Ne t''appuie pas sur des richesses injustes, car elles ne te serviront de rien au jour du malheur.'),
('si',5,9,'crampon1923','Ne vanne pas à tout vent, et ne marche pas dans toute voie; ainsi fait le pécheur à la langue double.'),
('si',5,10,'crampon1923','Sois ferme dans ton sentiment, et que ton langage soit un.'),
('si',5,11,'crampon1923','Sois prompt à écouter, et lent à donner une réponse.'),
('si',5,12,'crampon1923','Si tu as de l''intelligence, réponds à ton prochain; sinon, mets ta main sur ta bouche.'),
('si',5,13,'crampon1923','La gloire et la honte sont dans la parole, et la langue de l''homme cause sa perte.'),
('si',5,14,'crampon1923','Ne t''attire pas le nom de médisant, et ne tends pas des pièges avec ta langue; car la confusion tombe sur le voleur, et une condamnation sévère atteint la langue double.'),
('si',5,15,'crampon1923','Ne sois en faute ni beaucoup ni peu,'),
('si',5,16,'crampon1923',''),
('si',5,17,'crampon1923',''),
('si',6,1,'crampon1923','et d''ami ne deviens pas ennemi; car le méchant aura en partage le mauvais renom, la honte et l''opprobre: tel est le pécheur à la langue double.'),
('si',6,2,'crampon1923','Ne t''élève pas toi-même par la volonté de ton âme, de peur que ton âme ne soit pillée, comme par un taureau.'),
('si',6,3,'crampon1923','Tu dévoreras ton feuillage, tu feras périr tes fruits, et tu ne laisseras de toi qu''un bois aride.'),
('si',6,4,'crampon1923','L''âme perverse perd celui qui la possède; elle fait de lui la risée de ses ennemis.'),
('si',6,5,'crampon1923','Une parole douce fait beaucoup d''amis, et la langue aimable est riche d''amabilités.'),
('si',6,6,'crampon1923','Qu''ils soient nombreux ceux qui vivent en bons rapports avec toi, mais prends conseil d''un seul entre mille.'),
('si',6,7,'crampon1923','Si tu veux acquérir un ami, acquiers-le en l''éprouvant, et ne te confie pas à lui à la légère.'),
('si',6,8,'crampon1923','Car tel est ami à ses heures, qui ne le restera pas au jour de ton affliction;'),
('si',6,9,'crampon1923','tel est ami qui deviendra un ennemi, et qui révélera votre différend à ta confusion;'),
('si',6,10,'crampon1923','tel est ami quand il est assis à ta table, qui ne le restera pas au jour de ton malheur.'),
('si',6,11,'crampon1923','Durant ta prospérité, il sera comme un autre toi-même, et il parlera librement avec les gens de ta maison.'),
('si',6,12,'crampon1923','Si tu tombes dans l''humiliation, il sera contre toi, et il se cachera devant toi.'),
('si',6,13,'crampon1923','Eloigne-toi de tes ennemis, et sois sur tes gardes avec tes amis.'),
('si',6,14,'crampon1923','Un ami fidèle est une protection puissante; celui qui le trouve a trouvé un trésor.'),
('si',6,15,'crampon1923','Rien ne vaut un ami fidèle; aucun poids ne saurait en marquer le prix.'),
('si',6,16,'crampon1923','Un ami fidèle est un remède de vie; ceux qui craignent le Seigneur le trouvent.'),
('si',6,17,'crampon1923','Celui qui craint le Seigneur a une véritable amitié, car son ami lui est semblable.'),
('si',6,18,'crampon1923','Mon fils, dès ta jeunesse adonne-toi à l''instruction, et jusqu''à tes cheveux blancs tu trouveras la sagesse.'),
('si',6,19,'crampon1923','Approche-toi d''elle comme le laboureur et le semeur, et attends ses bons fruits. Pendant un peu de temps tu auras de la peine à la cultiver, et bientôt tu mangeras de ses fruits.'),
('si',6,20,'crampon1923','Combien elle est escarpée pour les ignorants! L''insensé ne lui restera pas attaché.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('si',6,21,'crampon1923','Comme une lourde pierre d''épreuve, elle pèse sur lui, et il ne tarde pas à la rejeter.'),
('si',6,22,'crampon1923','Car la sagesse justifie son nom: elle ne se découvre pas au grand nombre.'),
('si',6,23,'crampon1923','Ecoute, mon fils, et reçois ma pensée, et ne rejette pas mon conseil.'),
('si',6,24,'crampon1923','Engage ton pied dans ses entraves, et ton cou dans son collier.'),
('si',6,25,'crampon1923','Courbe ton épaule pour la porter, et ne t''irrite pas de ses liens.'),
('si',6,26,'crampon1923','Viens à elle de toute ton âme, et garde ses voies de toutes tes forces.'),
('si',6,27,'crampon1923','Suis ses traces et cherche-la, et elle se fera connaître à toi, et, quand tu l''auras saisie, ne la quitte pas.'),
('si',6,28,'crampon1923','Car à la fin tu trouveras son repos, et elle se changera pour toi en sujet de joie.'),
('si',6,29,'crampon1923','Ses entraves deviendront pour toi une protection puissante, et son collier un vêtement de gloire.'),
('si',6,30,'crampon1923','Car sur sa tête est un ornement d''or, et ses bandeaux sont un tissu d''hyacinthe.'),
('si',6,31,'crampon1923','Tu t''en revêtiras comme d''une robe de gloire, et tu la mettras sur ta tête comme une couronne de joie.'),
('si',6,32,'crampon1923','Mon fils, si tu le veux, tu acquerras l''instruction, et, si tu appliques ton âme, tu deviendras habile.'),
('si',6,33,'crampon1923','Si tu aimes à écouter, tu apprendras; si tu prêtes l''oreille, tu deviendras sage.'),
('si',6,34,'crampon1923','Tiens-toi dans la compagnie des vieillards; quelqu''un est-il sage? Attache-toi à lui.'),
('si',6,35,'crampon1923','Ecoute volontiers tout discours sur Dieu, et que les maximes de sagesse ne t''échappent pas.'),
('si',6,36,'crampon1923','Si tu vois un homme de sens, sois près de lui dès le matin, et que ton pied use le seuil de sa porte.'),
('si',6,37,'crampon1923','Médite sur les commandements du Seigneur, et réfléchis constamment à ses préceptes; lui-même affermira ton cœur, et la sagesse que tu désires te sera donnée.'),
('si',7,1,'crampon1923','Ne fais pas le mal, et le mal ne te saisira pas;'),
('si',7,2,'crampon1923','éloigne-toi de ce qui est injuste, et l''injuste s''éloignera de toi.'),
('si',7,3,'crampon1923','Mon fils, ne sème point dans les sillons de l''injustice, si tu ne veux pas récolter sept fois autant.'),
('si',7,4,'crampon1923','Ne demande pas au Seigneur le pouvoir, ni au roi un siège d''honneur.'),
('si',7,5,'crampon1923','N''essaie pas de paraître juste devant le Seigneur, et ne cherche pas à paraître sage devant le roi.'),
('si',7,6,'crampon1923','Ne cherche pas à devenir juge, de peur que tu n''aies pas la force d''extirper l''injustice, de peur que tu ne sois intimidé en présence d''un puissant, et que tu ne mettes en péril ton équité.'),
('si',7,7,'crampon1923','N''offense pas toute la population d''une ville, et ne te jette pas au milieu de la foule.'),
('si',7,8,'crampon1923','Ne lie pas deux fois le péché, car même pour un seul tu ne seras pas impuni.'),
('si',7,9,'crampon1923','Ne dis pas: « Dieu considérera la multitude de mes dons, et, quand je les offrirai au Dieu très haut, il les recevra. »'),
('si',7,10,'crampon1923','Ne sois pas pusillanime dans ta prière, et ne néglige pas de faire l''aumône.'),
('si',7,11,'crampon1923','Ne te moque pas de l''homme dont le cœur est affligé, car il y en a un qui abaisse et qui élève.'),
('si',7,12,'crampon1923','Ne forge point de mensonge contre ton frère; ne fais point pareille chose contre ton ami.'),
('si',7,13,'crampon1923','Garde-toi de dire aucun mensonge, car le mensonge continu ne tourne pas à bien.'),
('si',7,14,'crampon1923','Ne bavarde pas dans la compagnie des vieillards, et ne répète pas les paroles de ta prière.'),
('si',7,15,'crampon1923','Ne hais pas les labeurs pénibles, ni le travail des champs institué par le Très-Haut.'),
('si',7,16,'crampon1923','Ne te mets pas parmi le plus grand nombre des pécheurs; souviens-toi que la vengeance ne tardera pas.'),
('si',7,17,'crampon1923','Humilie profondément ton âme, car le feu et le ver sont le châtiment de l''impie.'),
('si',7,18,'crampon1923','N''échange pas un ami pour de l''argent, ni un frère pour l''or d''Ophir.'),
('si',7,19,'crampon1923','Ne te détourne pas d''une épouse intelligente et bonne; car son charme vaut mieux que l''or.'),
('si',7,20,'crampon1923','Ne maltraite pas l''esclave qui travaille fidèlement, ni le mercenaire qui se dévoue à ton service.'),
('si',7,21,'crampon1923','Aime l''esclave intelligent; ne le prive pas de la liberté.'),
('si',7,22,'crampon1923','As-tu des troupeaux, prends-en soin, et, s''ils te sont utiles, garde-les chez toi.'),
('si',7,23,'crampon1923','As-tu des fils, instruis-les, et plie-les au joug dès leur enfance.'),
('si',7,24,'crampon1923','As-tu des filles, veille à leur chasteté, et n''aie pas avec elle un visage jovial.'),
('si',7,25,'crampon1923','Marie ta fille, et tu auras fini une grosse affaire; et donne-la à un homme intelligent.'),
('si',7,26,'crampon1923','As-tu une femme selon ton cœur, ne la répudie pas; [mais ne te donne pas à une femme qui t''est contraire].'),
('si',7,27,'crampon1923','Honore ton père de tout ton cœur, et n''oublie pas les douleurs de ta mère.'),
('si',7,28,'crampon1923','Souviens-toi que c''est par eux que tu es venu au monde: et comment leur rendras-tu ce qu''ils t''ont donné?'),
('si',7,29,'crampon1923','Crains le Seigneur de toute ton âme, et tiens ses prêtres en grand honneur.'),
('si',7,30,'crampon1923','Aime de toutes tes forces Celui qui t''a fait, et ne délaisse pas ses ministres.'),
('si',7,31,'crampon1923','Crains le Seigneur et honore le prêtre; donne-lui sa part, comme il a été prescrit dès l''origine: la victime pour le délit avec le don des épaules, la sainte oblation et les prémices.'),
('si',7,32,'crampon1923','Tends aussi la main au pauvre, afin que ta bénédiction soit complète.'),
('si',7,33,'crampon1923','Donne gracieusement à tout vivant, et ne refuse pas ton bienfait au mort.'),
('si',7,34,'crampon1923','Ne fais pas défaut à ceux qui pleurent, et afflige-toi avec les affligés.'),
('si',7,35,'crampon1923','Ne néglige pas de prendre soin des malades; pour de tels actes de charité tu seras aimé de Dieu.'),
('si',7,36,'crampon1923','Dans toutes tes actions souviens-toi de ta fin, et tu ne pécheras jamais.'),
('si',8,1,'crampon1923','N''aie pas de dispute avec un homme puissant, de peur que tu ne tombes entre ses mains.'),
('si',8,2,'crampon1923','N''aie pas de querelle avec un homme riche, de peur qu''il ne t''oppose le poids de son or; car l''or a perdu beaucoup de gens, il a même fait dévier le cœur des rois.'),
('si',8,3,'crampon1923','N''aie pas de dispute avec un grand parleur, et n''entasse pas de bois dans son feu.'),
('si',8,4,'crampon1923','Ne plaisante pas avec un homme mal élevé, de peur que tes ancêtres ne soient déshonorés.'),
('si',8,5,'crampon1923','Ne raille pas l''homme qui se détourne du péché; souviens-toi que nous sommes tous dignes de châtiment.'),
('si',8,6,'crampon1923','Ne méprise pas un homme dans sa vieillesse, car quelques-uns d''entre nous vieillissent aussi.'),
('si',8,7,'crampon1923','Ne te réjouis pas quand un homme meurt; souviens-toi que nous mourrons tous.'),
('si',8,8,'crampon1923','Ne néglige pas les discours des sages, et entretiens-toi de leurs maximes; car tu apprendras d''eux l''instruction, et l''art de servir les grands.'),
('si',8,9,'crampon1923','Ne laisse pas échapper les discours des vieillards, car eux-mêmes ont appris de leurs pères. Tu apprendras d''eux la sagesse, et à bien répondre quand il en sera besoin.'),
('si',8,10,'crampon1923','N''allume pas les charbons du pécheur, de peur que tu ne sois dévoré par les ardeurs de sa flamme.'),
('si',8,11,'crampon1923','Ne tiens pas tête à l''insolent qui t''insulte, de peur qu''il ne se mette en embuscade pour épier tes paroles.'),
('si',8,12,'crampon1923','Ne prête pas à plus puissant que toi, et, si tu lui as prêté une chose, tiens-la pour perdue.'),
('si',8,13,'crampon1923','Ne te porte pas caution au delà de tes moyens, et, si tu as cautionné, inquiète-toi comme devant payer.'),
('si',8,14,'crampon1923','N''aie pas de litige avec un juge, car on décidera pour lui selon sa considération.'),
('si',8,15,'crampon1923','Ne fais point route avec un téméraire, de peur qu''il ne te devienne à charge; car il fait tout à sa fantaisie, et, par sa folie, tu périras avec lui.'),
('si',8,16,'crampon1923','N''aie pas de querelle avec un homme irascible, et ne traverse pas le désert avec lui; car le sang est comme rien à ses yeux, et là où il n''y aura pas de secours, il te terrassera.'),
('si',8,17,'crampon1923','Ne tiens pas conseil avec un fou, car il ne pourra rien taire.'),
('si',8,18,'crampon1923','Devant un étranger ne fais rien qui doive rester caché, car tu ne sais ce qu''il peut faire.'),
('si',8,19,'crampon1923','Ne découvre pas ton cœur à tout homme, si tu ne veux pas en être mal récompensé.'),
('si',9,1,'crampon1923','Ne sois point jaloux de la femme qui repose sur ton sein, et n''éveille pas dans son esprit, à ton détriment, une idée mauvaise.'),
('si',9,2,'crampon1923','Ne livre pas ton âme à ta femme, de telle sorte qu''elle s''élève contre ton autorité.'),
('si',9,3,'crampon1923','Ne va pas à la rencontre d''une femme courtisane, de peur de tomber dans ses filets.'),
('si',9,4,'crampon1923','Ne reste pas longtemps avec une chanteuse, de peur que tu ne sois pris par son art.'),
('si',9,5,'crampon1923','N''arrête pas ton regard sur une jeune fille, de peur d''avoir à subir des châtiments à cause d''elle.'),
('si',9,6,'crampon1923','Ne te livre pas aux courtisanes, de peur que tu ne perdes ton héritage.'),
('si',9,7,'crampon1923','Ne promène pas tes yeux dans les rues de la ville, et ne rôde pas dans ses endroits solitaires.'),
('si',9,8,'crampon1923','Détourne les yeux de la femme élégante, et ne regarde pas curieusement une beauté étrangère. Beaucoup sont séduits par la beauté de la femme, et la passion s''y allume comme un feu.'),
('si',9,9,'crampon1923','Ne t''assois jamais auprès d''une femme mariée, [ne t''accoude pas à table avec elle], et ne bois pas avec elle le vin dans des banquets, de peur que ton âme ne se tourne vers elle, et que la passion ne t''entraîne à ta perte.'),
('si',9,10,'crampon1923','N''abandonne pas un vieil ami, car le nouveau ne le vaudra pas. Vin nouveau, nouvel ami; qu''il vieillisse, et tu le boiras avec plaisir.'),
('si',9,11,'crampon1923','N''envie pas la gloire du pécheur, car tu ne sais pas ce que sera sa ruine.'),
('si',9,12,'crampon1923','Ne prends pas plaisir au plaisir des impies; souviens-toi qu''ils ne resteront pas impunis jusqu''au schéol.'),
('si',9,13,'crampon1923','Tiens-toi loin de l''homme qui a le pouvoir de faire mourir, et tu n''auras pas la crainte de la mort. Et si tu l''approches, garde-toi de toute faute, de peur qu''il ne t''ôte la vie. Sache que tu marches au milieu de pièges, et que tu te promènes sur les créneaux de la ville.'),
('si',9,14,'crampon1923','Observe autant que possible ton prochain, et prends conseil des sages.'),
('si',9,15,'crampon1923','Converse avec les hommes intelligents, et que tous tes entretiens soient sur la loi du Très-Haut.'),
('si',9,16,'crampon1923','Que les hommes justes soient tes commensaux, et mets ta gloire dans la crainte de Dieu.'),
('si',9,17,'crampon1923','C''est la main de l''artiste qui vaut à une œuvre la louange, c''est sa parole qui fait paraître sage le chef du peuple.'),
('si',9,18,'crampon1923','Le grand parleur est redouté dans sa ville, et l''inconsidéré s''attire la haine par ses discours.'),
('si',10,1,'crampon1923','Le prince sage tient son peuple dans la discipline, et le gouvernement de l''homme sensé est bien réglé.'),
('si',10,2,'crampon1923','Tel le chef du peuple, tels ses ministres; et tel le gouvernement de la ville, tels tous ses habitants.'),
('si',10,3,'crampon1923','Un roi ignorant perd son peuple, mais une ville prospère par l''intelligence des chefs.'),
('si',10,4,'crampon1923','La souveraineté du pays est entre les mains du Seigneur, et il lui suscite en son temps le prince habile.'),
('si',10,5,'crampon1923','Le succès d''un homme est dans la main du Seigneur; c''est lui qui met sur le front du chef son autorité.'),
('si',10,6,'crampon1923','Pour aucune injustice ne garde rancune à ton prochain, et ne fais rien au milieu des actes de violence.'),
('si',10,7,'crampon1923','L''orgueil est odieux à Dieu et aux hommes; et pour les deux, l''injustice est une iniquité.'),
('si',10,8,'crampon1923','La domination passe d''un peuple à un autre, à cause de l''injustice, des injures et de la convoitise des richesses.'),
('si',10,9,'crampon1923','Pourquoi s''enorgueillit ce qui est terre et poussière? Car pendant sa vie je mets le trouble dans ses membres;'),
('si',10,10,'crampon1923','la maladie est longue; le médecin se rit; et le roi d''aujourd''hui mourra demain!'),
('si',10,11,'crampon1923','Et quand l''homme est mort, il a en partage les larves, les bêtes et les vers.'),
('si',10,12,'crampon1923','L''orgueil commence quand l''homme se sépare du Seigneur, et quand le cœur s''éloigne de Celui qui l''a fait.'),
('si',10,13,'crampon1923','Car le commencement de l''orgueil, c''est le péché, et celui qui s''y attache répand l''abomination comme la pluie. C''est pourquoi le Seigneur envoie des châtiments prodigieux, et frappe les méchants d''une ruine complète.'),
('si',10,14,'crampon1923','Le Seigneur renverse le trône des princes, et fait asseoir à leur place les hommes doux.'),
('si',10,15,'crampon1923','Le Seigneur arrache les racines des nations, et plante les humbles à leur place.'),
('si',10,16,'crampon1923','Le Seigneur bouleverse les contrées des nations, et en poursuit la destruction jusqu''aux fondements de la terre.'),
('si',10,17,'crampon1923','Il en dessèche plusieurs et en extermine les habitants; il efface leur mémoire de la terre.'),
('si',10,18,'crampon1923','L''orgueil n''est pas fait pour l''homme, ni la colère insolente pour ceux qui naissent de la femme.'),
('si',10,19,'crampon1923','Quelle race est honorée? La race de l''homme. Quelle race est honorée? Ceux qui craignent le Seigneur. Quelle race est méprisée? La race de l''homme. Quelle race est méprisée? Ceux qui transgressent les commandements.'),
('si',10,20,'crampon1923','Au milieu de ses frères, leur chef est en honneur; ceux qui craignent le Seigneur le sont de même à ses yeux.'),
('si',10,21,'crampon1923','Riche, noble et pauvre, leur gloire est la crainte du Seigneur.'),
('si',10,22,'crampon1923','Il n''est pas juste de mépriser un pauvre intelligent; il ne convient pas d''honorer un pécheur.'),
('si',10,23,'crampon1923','Le grand, le juge et le puissant sont en honneur, mais aucun d''eux n''est plus grand que celui qui craint le Seigneur.'),
('si',10,24,'crampon1923','Les hommes libres sont les serviteurs de l''esclave prudent, et l''homme intelligent ne murmurera pas.'),
('si',10,25,'crampon1923','Ne raisonne pas pour faire ton ouvrage, et ne te vante pas au temps de ta détresse.'),
('si',10,26,'crampon1923','Mieux vaut l''homme qui travaille en toutes choses, que celui qui se promène, qui se vante et manque de pain.'),
('si',10,27,'crampon1923','Mon fils, honore ton âme dans la douceur, et donne-lui le respect qu''elle mérite.'),
('si',10,28,'crampon1923','L''homme qui pèche contre son âme, qui le regardera comme juste? Qui honorera celui qui déshonore sa vie?'),
('si',10,29,'crampon1923','Le pauvre est honoré pour sa science, et le riche est honoré pour sa richesse.'),
('si',10,30,'crampon1923','Mais celui qui est honoré dans la pauvreté, combien le serait-il davantage dans la richesse? Et celui qui est sans honneur dans la richesse, combien plus le serait-il dans la pauvreté?'),
('si',10,31,'crampon1923',''),
('si',11,1,'crampon1923','La sagesse de l''homme humble relèvera sa tête, et le fera asseoir au milieu des grands.'),
('si',11,2,'crampon1923','Ne loue pas un homme pour sa beauté, et ne prends pas un homme en dégoût sur sa mine.'),
('si',11,3,'crampon1923','L''abeille est petite parmi les volatiles, et son produit est au premier rang parmi les choses douces.'),
('si',11,4,'crampon1923','Ne te glorifie pas des habits qui te couvrent, et ne t''élève pas au jour de la gloire. Car les œuvres du Seigneur sont étonnantes, et son action parmi les hommes est cachée.'),
('si',11,5,'crampon1923','Beaucoup de princes se sont assis sur le pavé, et celui à qui on ne pensait pas a porté la couronne.'),
('si',11,6,'crampon1923','Beaucoup de puissants ont été accablés d''opprobre, et des hommes illustres livrés aux mains des autres.'),
('si',11,7,'crampon1923','Avant de t''informer, ne jette pas le blâme; examine d''abord, et alors tu pourras reprendre.'),
('si',11,8,'crampon1923','Ne réponds rien avant d''avoir écouté, et ne jette pas tes paroles au milieu des discours des autres.'),
('si',11,9,'crampon1923','Ne conteste pas pour une chose qui n''est pas à toi, et ne t''assois pas avec les pécheurs pour juger.'),
('si',11,10,'crampon1923','Mon fils, n''applique pas ton activité à une multitude de choses: si tu embrasses beaucoup, tu ne seras exempt de faute. Si tu poursuis trop de choses, tu ne les atteindras pas, et tu ne t''échapperas pas en fuyant.'),
('si',11,11,'crampon1923','Tel travaille, se fatigue et se hâte, et il n''en devient que plus pauvre.'),
('si',11,12,'crampon1923','Tel est sans énergie, appelant le secours, pauvre de forces et riche de besoins; mais les yeux du Seigneur le regardent favorablement, il le tire de son humble condition,'),
('si',11,13,'crampon1923','il relève sa tête, et beaucoup sont dans l''admiration à son sujet.'),
('si',11,14,'crampon1923','Les biens et les maux, la mort et la vie, la pauvreté et la richesse viennent du Seigneur.'),
('si',11,15,'crampon1923','Les dons de Dieu demeurent aux justes, et sa faveur assure la prospérité pour toujours.'),
('si',11,16,'crampon1923','Tel est riche à force de soin et de parcimonie, et voici la part qui lui échoit en récompense:'),
('si',11,17,'crampon1923','Il peut dire: « J''ai trouvé le repos, et maintenant je vais manger de mon bien. » Mais il ne sait pas quel temps s''écoulera; il va laisser ses biens à d''autres et mourir.'),
('si',11,18,'crampon1923','Sois fidèle à ton alliance avec Dieu, et vis dans cette pensée, et vieillis dans ton œuvre.'),
('si',11,19,'crampon1923','Ne t''étonne pas des affaires du pécheur; confie-toi dans le Seigneur et persévère dans ton travail. Car c''est chose facile aux yeux du Seigneur d''enrichir promptement et d''un seul coup celui qui est pauvre.'),
('si',11,20,'crampon1923','La bénédiction du Seigneur est la récompense de l''homme pieux; dans une heure rapide, il fait fleurir sa bénédiction.'),
('si',11,21,'crampon1923','Ne dis pas: « De quoi ai-je besoin, et quel peut être désormais mon bonheur? »'),
('si',11,22,'crampon1923','Ne dis pas non plus: « J''ai ce qu''il me faut, et quel mal pourrais-je avoir à souffrir? »'),
('si',11,23,'crampon1923','Au jour du bonheur, on oublie le malheur, et, au jour du malheur, on ne se souvient plus du bonheur.'),
('si',11,24,'crampon1923','Car c''est chose facile devant le Seigneur, au jour de la mort, de rendre à l''homme selon ses voies.'),
('si',11,25,'crampon1923','Un moment d''affliction fait oublier le bien-être passé, et, à la fin de l''homme, ses œuvres seront dévoilés.'),
('si',11,26,'crampon1923','N''estime personne heureux avant sa mort: c''est dans ses enfants qu''on reconnaît un homme.'),
('si',11,27,'crampon1923','N''introduis pas tout le monde dans ta maison, car les embûches de l''homme trompeur sont nombreuses.'),
('si',11,28,'crampon1923','Comme la perdrix de chasse dans sa cage, ainsi est le cœur de l''orgueilleux; et, comme l''espion, il guette la ruine.'),
('si',11,29,'crampon1923','Changeant le bien en mal, il dresse des pièges, et il imprime une tache à ce qu''il y a de plus pur.'),
('si',11,30,'crampon1923','Une étincelle produit beaucoup de charbon; ainsi le pécheur cherche insidieusement à répandre le sang.'),
('si',11,31,'crampon1923','Prends garde au méchant, — car il ourdit le mal, — de peur qu''il ne t''imprime une flétrissure ineffaçable.'),
('si',11,32,'crampon1923','Donne entrée chez toi à l''étranger, et il te renversera en excitant des troubles, et il t''aliénera les gens de ta maison.'),
('si',11,33,'crampon1923',''),
('si',11,34,'crampon1923',''),
('si',12,1,'crampon1923','Si tu fais du bien, sache à qui tu le fais, et l''on te saura gré de tes bienfaits.'),
('si',12,2,'crampon1923','Fais du bien à l''homme pieux, et tu en trouveras la récompense, sinon de lui, du moins du Seigneur.'),
('si',12,3,'crampon1923','Les bienfaits ne sont pas pour celui qui persévère dans le mal, ni pour celui qui ne pratique pas la bienfaisance.'),
('si',12,4,'crampon1923','Donne à l''homme pieux, et n''assiste pas le pécheur.'),
('si',12,5,'crampon1923','Fais du bien à celui qui est humilié, et ne donne pas à l''impie; refuse-lui du pain, et ne lui en donne pas, de peur qu''il ne devienne par là plus fort que toi; car tu recueilleras un double mal de tout le bien que tu lui auras fait.'),
('si',12,6,'crampon1923','Le Très-Haut aussi hait les pécheurs, et il tirera vengeance des impies.'),
('si',12,7,'crampon1923','Donne à l''homme vertueux, et n''assiste pas le pécheur.'),
('si',12,8,'crampon1923','Ce n''est point dans la prospérité qu''un ami s''attire le châtiment, ni dans l''adversité qu''un ennemi se dissimule.'),
('si',12,9,'crampon1923','Quand un homme est heureux, ses ennemis sont dans le deuil; quand il est malheureux, son ami même se sépare de lui.'),
('si',12,10,'crampon1923','Ne te fie jamais à ton ennemi, car sa malice est comme l''airain que couvre la rouille;'),
('si',12,11,'crampon1923','alors même qu''il se montre humble et marche courbé, veille sur toi-même et garde-toi de lui; et tu seras pour lui comme celui qui polit un miroir, et tu connaîtras qu''il n''a pas de rouille jusqu''à la fin.'),
('si',12,12,'crampon1923','Ne le mets pas à côté de toi, de peur qu''il ne te renverse et ne prenne ta place. Ne le fais pas asseoir à ta droite, de peur qu''il ne cherche à occuper ton siège, et qu''à la fin, reconnaissant la vérité de mes discours, tu n''aies du chagrin au souvenir de mes paroles.'),
('si',12,13,'crampon1923','Qui aura pitié de l''enchanteur mordu par un serpent, et de tous ceux qui approchent les bêtes féroces?'),
('si',12,14,'crampon1923','Il en est de même de celui qui lie société avec un pécheur, et qui se mêle à ses péchés.'),
('si',12,15,'crampon1923','Il reste une heure avec toi; mais, si tu te détournes, il ne tiendra pas plus longtemps.'),
('si',12,16,'crampon1923','L''ennemi a la douceur sur les lèvres, et, dans son cœur, il médite le moyen de te jeter dans la fosse. L''ennemi a des larmes dans les yeux, et, s''il trouve l''occasion, il sera insatiable de ton sang.'),
('si',12,17,'crampon1923','Si le malheur t''atteint, tu le trouveras là avant toi, et, sous prétexte de te secourir, il te donnera un croc-en-jambe.'),
('si',12,18,'crampon1923','Alors il branlera la tête, il battra des mains, il ne cessera de chuchoter et prendra un autre visage.'),
('si',13,1,'crampon1923','Qui touche à la poix se souille, et qui se lie avec l''orgueilleux lui devient semblable.'),
('si',13,2,'crampon1923','Ne mets pas sur tes épaules un lourd fardeau, et ne te lie pas avec un homme plus fort et plus riche que toi. Quelle association peut-il y avoir entre le pot de terre et le chaudron? Le chaudron heurtera le pot, et celui-ci sera brisé.'),
('si',13,3,'crampon1923','Le riche commet une injustice, et il frémit d''indignation; le pauvre est maltraité, et il demande excuse.'),
('si',13,4,'crampon1923','Tant que tu pourras lui être utile, il se servira de toi, et quand tu n''auras plus rien, il te délaissera.'),
('si',13,5,'crampon1923','Si tu as du bien, il vivra avec toi, il te dépouillera, et n''aura nul souci.'),
('si',13,6,'crampon1923','Lui es-tu nécessaire? il t''enjôlera, il te sourira et te donnera des espérances, il te dira de belles paroles et te dira: « De quoi as-tu besoin? »'),
('si',13,7,'crampon1923','Il te rendra confus par ses festins, jusqu''à ce qu''il t''ait dépouillé deux ou trois fois, et, à la fin, il se rira de toi; après quoi, il te verra et te délaissera, et secouera la tête devant toi.'),
('si',13,8,'crampon1923','Prends garde de te laisser séduire, et, au sein de la prospérité, de tomber dans l''humiliation.'),
('si',13,9,'crampon1923','Si un puissant t''appelle, retire-toi en arrière; il ne fera que t''inviter avec plus d''instances.'),
('si',13,10,'crampon1923','Ne tombe pas sur lui à l''improviste, de peur d''être repoussé, et ne te tiens pas trop loin de lui, de peur d''être oublié.'),
('si',13,11,'crampon1923','Ne t''imagine pas de causer avec lui d''égal à égal, et ne te fie pas à ses nombreux discours.'),
('si',13,12,'crampon1923','Car par son flux de paroles il te tentera, et il t''interrogera comme en souriant. Homme sans pitié, il ne gardera pas pour lui tes paroles, et il ne t''épargnera ni les coups ni les chaînes.'),
('si',13,13,'crampon1923','Prends garde et fais bien attention, car tu marches avec ta ruine.'),
('si',13,14,'crampon1923','Toute créature vivante aime son semblable, et tout homme son prochain.'),
('si',13,15,'crampon1923','Toute chair s''unit selon son espèce, et tout homme s''associe à son semblable.'),
('si',13,16,'crampon1923','Quelle union peut-il y avoir entre le loup et l''agneau? Il en est de même entre le pécheur et l''homme pieux.'),
('si',13,17,'crampon1923','Quelle paix peut avoir l''hyène avec le chien? Quelle paix le riche avec le pauvre?'),
('si',13,18,'crampon1923','Les onagres sont la proie des lions dans le désert; ainsi les pauvres sont la proie des riches.'),
('si',13,19,'crampon1923','L''orgueilleux a en horreur l''humiliation: ainsi le riche a en horreur le pauvre.'),
('si',13,20,'crampon1923','Le riche vient-il à chanceler, ses amis le soutiennent; mais quand l''humble tombe, il est encore repoussé par ses amis.'),
('si',13,21,'crampon1923','Quand le riche fait une chute, beaucoup lui viennent en aide; il tient des discours insensés, et on l''approuve. Quand l''humble fait une chute, il a encore des reproches.'),
('si',13,22,'crampon1923','Le riche parle, et tout le monde se tait; et on élève son discours jusqu''aux nues. Le pauvre parle, et l''on dit: « Quel est celui-là? » et, s''il heurte, on le culbute.'),
('si',13,23,'crampon1923','La richesse est bonne quand elle n''est pas unie au péché, et la pauvreté est mauvaise dans la bouche de l''impie.'),
('si',13,24,'crampon1923','Le cœur de l''homme change son visage, soit en bien, soit en mal.'),
('si',13,25,'crampon1923','Le signe d''un cœur content est un visage joyeux; pour trouver de sages maximes, il faut le labeur de la réflexion.'),
('si',13,26,'crampon1923',''),
('si',14,1,'crampon1923','Heureux l''homme qui n''a pas péché par les paroles de sa bouche, qui n''a pas été meurtri par le remords du péché!'),
('si',14,2,'crampon1923','Heureux celui que son âme ne condamne pas, et qui n''a pas perdu son espérance au Seigneur!'),
('si',14,3,'crampon1923','A l''homme sordide la richesse est inutile; et que servent les trésors à l''homme envieux?'),
('si',14,4,'crampon1923','Celui qui amasse en se privant lui-même amasse pour d''autres; avec ses biens d''autres vivront dans les délices.'),
('si',14,5,'crampon1923','Celui qui est mauvais à lui-même, pour qui sera-t-il bon? Il ne jouira pas de ses propres trésors.'),
('si',14,6,'crampon1923','Il n''y a pas pire que celui qui se refuse tout, et c''est là le juste salaire de sa malice.'),
('si',14,7,'crampon1923','S''il fait quelque bien, c''est par oubli, et il finit par laisser voir sa malice.'),
('si',14,8,'crampon1923','C''est un méchant que celui qui regarde d''un œil d''envie, qui détourne son visage et méprise les âmes.'),
('si',14,9,'crampon1923','L''œil de l''avare n''est pas rassasié par une portion, et une funeste convoitise dessèche l''âme.'),
('si',14,10,'crampon1923','L''œil mauvais se refuse le pain, et il a faim à sa propre table.'),
('si',14,11,'crampon1923','Mon fils, selon ce que tu possèdes, fais-toi du bien, et présente au Seigneur de dignes offrandes.'),
('si',14,12,'crampon1923','Rappelle-toi que la mort ne tarde pas, et que le pacte du schéol ne t''a pas été révélé.'),
('si',14,13,'crampon1923','Avant de mourir, fais du bien à ton ami; et, selon tes moyens, étends la main et donne-lui.'),
('si',14,14,'crampon1923','Ne te prive pas d''un jour de fête, et ne laisse échapper aucune partie d''un bon désir.'),
('si',14,15,'crampon1923','Est-ce que tu ne laisseras pas à d''autres le fruit de ton labeur, et le fruit de tes peines à la décision du sort?'),
('si',14,16,'crampon1923','Donne et prends, et réjouis ton âme, car il n''y a pas à chercher des délices dans le schéol.'),
('si',14,17,'crampon1923','Toute chair vieillit comme un vêtement, car c''est une loi portée dès l''origine; tu mourras certainement.'),
('si',14,18,'crampon1923','Comme la feuille verdoyante sur un arbre touffu; — il laisse tomber les unes, et fait pousser les autres; — ainsi en est-il des générations de chair et de sang: les unes meurent, d''autres viennent à la vie.'),
('si',14,19,'crampon1923','Toute œuvre corruptible finit par périr, et son ouvrier s''en ira avec elle.'),
('si',14,20,'crampon1923','Heureux l''homme qui médite sur la sagesse, et qui parle avec son bon sens;'),
('si',14,21,'crampon1923','qui réfléchit dans son cœur sur ses voies, et qui étudie ses secrets;'),
('si',14,22,'crampon1923','qui la poursuit, comme un chasseur, et guette ses entrées.'),
('si',14,23,'crampon1923','Il se baisse pour regarder par ses fenêtres, et il écoute à sa porte.'),
('si',14,24,'crampon1923','Il s''établit tout près de sa demeure, et fixe ses pieux dans ses parois'),
('si',14,25,'crampon1923','Il dresse sa tente auprès d''elle, et il habite dans la maison où se trouve le bonheur.'),
('si',14,26,'crampon1923','Il met ses enfants sous sa protection, et s''abrite sous ses rameaux.'),
('si',14,27,'crampon1923','A son ombre, il sera garanti contre la chaleur, et il se reposera dans sa gloire.'),
('si',15,1,'crampon1923','Voilà ce que fait celui qui craint le Seigneur, et celui qui s''attache à la loi obtiendra la sagesse.'),
('si',15,2,'crampon1923','Elle viendra au-devant de lui comme une mère, et elle l''accueillera comme une épouse vierge.'),
('si',15,3,'crampon1923','Elle le nourrira du pain de l''intelligence, et lui donnera à boire l''eau de la sagesse.'),
('si',15,4,'crampon1923','Il s''appuiera sur elle et ne fléchira pas, il s''attachera à elle et ne sera pas confondu.'),
('si',15,5,'crampon1923','Elle l''élèvera devant ses compagnons, et lui ouvrira la bouche au milieu de l''assemblée.'),
('si',15,6,'crampon1923','La joie, une couronne d''allégresse, et un nom éternel seront son partage.'),
('si',15,7,'crampon1923','Les insensés ne la posséderont pas, et les pécheurs ne la verront même pas.'),
('si',15,8,'crampon1923','Elle se tient loin des hommes d''orgueil, et les hommes de mensonge ne songent pas à elle.'),
('si',15,9,'crampon1923','La louange de Dieu n''est pas agréable dans la bouche du pécheur, parce qu''elle n''est pas envoyée par le Seigneur.'),
('si',15,10,'crampon1923','Car c''est par la sagesse qu''est dictée la louange, et le Seigneur l''aura pour agréable.'),
('si',15,11,'crampon1923','Ne dis pas: « Le Seigneur est cause que je me sois écarté, » car ce qu''il hait, tu ne dois pas le faire.'),
('si',15,12,'crampon1923','Ne dis pas: « C''est lui qui m''a égaré; » car il n''a pas besoin du pécheur.'),
('si',15,13,'crampon1923','Le Seigneur hait toute abomination, et elle ne doit pas être aimée de ceux qui le craignent.'),
('si',15,14,'crampon1923','Au commencement il a créé l''homme, et il l''a laissé dans la main de son conseil:'),
('si',15,15,'crampon1923','« Si tu le veux, tu garderas les commandements; être fidèle dépend de ton bon plaisir.'),
('si',15,16,'crampon1923','Il a mis devant toi le feu et l''eau, du côté que tu voudras tu peux étendre la main. »'),
('si',15,17,'crampon1923','Devant les hommes sont la vie et la mort; ce qu''il aura choisi lui sera donné.'),
('si',15,18,'crampon1923','Car la sagesse du Seigneur est grande; il est fort et puissant, et il voit toutes choses.'),
('si',15,19,'crampon1923','Ses yeux sont sur ceux qui le craignent, et il connaît lui-même toutes les œuvres de l''homme.'),
('si',15,20,'crampon1923','Il n''a commandé à personne d''être impie, à personne il n''a donné la permission de pécher.'),
('si',16,1,'crampon1923','Ne désire pas un grand nombre d''enfants inutiles, et ne mets pas ta joie dans des fils impies.'),
('si',16,2,'crampon1923','S''ils se multiplient, ne t''en réjouis pas, si la crainte du Seigneur n''est pas avec eux.'),
('si',16,3,'crampon1923','N''espère pas pour eux une longue vie, et ne fais aucun fond sur leur prospérité. Un seul vaut mieux que mille; et mieux vaut mourir sans enfants que d''avoir des fils impies.'),
('si',16,4,'crampon1923','Car un seul homme intelligent peuplera un pays, mais la race des méchants sera détruite.'),
('si',16,5,'crampon1923','J''en ai vu de mes yeux beaucoup d''exemples, et mes oreilles en on entendu de plus graves encore.'),
('si',16,6,'crampon1923','Le feu s''allume sur l''assemblée des pécheurs, et la colère de Dieu s''enflamme sur un peuple rebelle.'),
('si',16,7,'crampon1923','Le Seigneur n''a point pardonné aux antiques géants, lesquels, confiants dans leur force, s''étaient révoltés.'),
('si',16,8,'crampon1923','Il n''a pas épargné ceux qui habitaient avec Lot, il les eut en horreur à cause de leur orgueil insolent.'),
('si',16,9,'crampon1923','Il n''a pas eu pitié du peuple voué à la perdition, lequel fut exterminé avec ses péchés.'),
('si',16,10,'crampon1923','De même il extermina six cent mille hommes de pied qui s''étaient rassemblés dans l''endurcissement de leurs cœurs.'),
('si',16,11,'crampon1923','Un seul raidit-il le cou, ce serait merveille s''il restait impuni. Car du Seigneur viennent la miséricorde et la colère; puissant en pardon, il déchaîne aussi sa colère.'),
('si',16,12,'crampon1923','Autant est grande sa miséricorde, autant le sont ses châtiments; il jugera l''homme selon ses œuvres.'),
('si',16,13,'crampon1923','Le pécheur n''échappera pas avec ses rapines, et il ne retardera pas l''attente de l''homme pieux.'),
('si',16,14,'crampon1923','Il donnera carrière à toute sa miséricorde, et chacun recevra selon ses œuvres.'),
('si',16,15,'crampon1923','Ne dis pas: « Je me déroberai au regard du Seigneur, et de là-haut qui donc pensera à moi? Au milieu de la foule je serai oublié, et que suis-je au sein de l''immense création? »'),
('si',16,16,'crampon1923','Vois: le ciel et le ciel des cieux de Dieu, l''abîme et la terre sont ébranlés quand il les visite;'),
('si',16,17,'crampon1923','ensemble les montagnes et les fondements de la terre sont saisis de tremblement quand il les regarde.'),
('si',16,18,'crampon1923','Mais le cœur de l''homme ne réfléchit pas à cela, et quel est celui qui étudie ses voies?'),
('si',16,19,'crampon1923','La tempête échappe à l''œil de l''homme: et la plupart des œuvres de Dieu sont cachées.'),
('si',16,20,'crampon1923','« Qui nous dira les œuvres de sa justice et qui les attendra? Elle est si loin l''alliance du châtiment! »'),
('si',16,21,'crampon1923','Ainsi pense l''homme sans intelligence; l''insensé qui s''égare n''imagine que folies.'),
('si',16,22,'crampon1923','Ecoute-moi, mon fils, et apprends la sagesse; et rends ton cœur attentif à mes paroles.'),
('si',16,23,'crampon1923','Je te découvrirai une doctrine pesée dans la balance, et je te ferai connaître une science exacte.'),
('si',16,24,'crampon1923','Les œuvres du Seigneur subsistent depuis l''origine comme il les a disposées, et dès leur création il en a séparé les parties.'),
('si',16,25,'crampon1923','Il a orné pour toujours ses ouvrages, et les plus beaux pour briller d''âge en âge. Ils n''éprouvent ni la faim ni la fatigue, et ils n''interrompent pas leur tâche.'),
('si',16,26,'crampon1923','Aucun d''eux ne heurte son voisin, et à jamais ils obéissent au divin commandement.'),
('si',16,27,'crampon1923','Après cela, le Seigneur regarda sur la terre et il l''a remplit de ses biens.'),
('si',16,28,'crampon1923','D''animaux de toutes sortes il en a couvert la surface, et c''est dans son sein qu''ils doivent retourner.'),
('si',16,29,'crampon1923',''),
('si',16,30,'crampon1923',''),
('si',17,1,'crampon1923','Le Seigneur a formé l''homme de terre, et il le fait retourner dans la terre.'),
('si',17,2,'crampon1923','Il lui a assigné un nombre de jours et un temps déterminé, et il lui a donné pouvoir sur tout ce qui est sur la terre.'),
('si',17,3,'crampon1923','Selon sa nature, il l''a revêtu de force, et il l''a fait à son image.'),
('si',17,4,'crampon1923','Il a inspiré sa crainte à toute chair, et lui a donné l''empire sur les bêtes et sur les oiseaux.'),
('si',17,5,'crampon1923','Il lui a donné le discernement, une langue, des yeux, des oreilles, et un cœur pour penser.'),
('si',17,6,'crampon1923','Il l''a rempli de science et d''intelligence, et il lui a fait connaître le bien et le mal.'),
('si',17,7,'crampon1923','Il a mis son œil dans leurs cœurs, pour leur montrer la grandeur de ses œuvres.'),
('si',17,8,'crampon1923','Et ainsi ils loueront son saint nom, en publiant les merveilles de ses œuvres.'),
('si',17,9,'crampon1923','Il leur a encore donné la science, et les a mis en possession de la loi de vie.'),
('si',17,10,'crampon1923','Il a contracté avec eux une alliance éternelle, et il leur a révélé ses commandements.'),
('si',17,11,'crampon1923','Leurs yeux ont contemplé les splendeurs de sa majesté, et leurs oreilles ont entendu les magnifiques accents de sa voix.'),
('si',17,12,'crampon1923','Et il leur a dit: « Gardez-vous de toute iniquité! » et il leur a donné à chacun des prescriptions à l''égard du prochain.'),
('si',17,13,'crampon1923','Leurs voies sont constamment devant lui; rien ne peut les dérober à son regard.'),
('si',17,14,'crampon1923','A chaque peuple il assigne un chef, mais Israël est la portion du Seigneur.'),
('si',17,15,'crampon1923','Toutes leurs œuvres sont devant lui, comme le soleil, et ses yeux sont toujours tournés sur leurs voies.'),
('si',17,16,'crampon1923','Leurs injustices ne lui sont pas cachées, et tous leurs péchés sont devant le Seigneur.'),
('si',17,17,'crampon1923','L''œuvre charitable d''un homme est pour lui comme un sceau, et il conserve le bienfait de l''homme comme la prunelle de l''œil.'),
('si',17,18,'crampon1923','Ensuite il se lèvera et leur rendra selon leurs actions, et il fera retomber sur leur tête ce qui leur est dû.'),
('si',17,19,'crampon1923','Cependant, à ceux qui se repentent, il accorde le retour, et il console ceux qui ont perdu confiance.'),
('si',17,20,'crampon1923','Tourne-toi vers le Seigneur et quitte tes péchés; prie devant sa face et diminue tes offenses.'),
('si',17,21,'crampon1923','Reviens au Très-Haut, détourne-toi de l''injustice, et déteste fortement ce qui est abominable.'),
('si',17,22,'crampon1923','Qui louera le Très-Haut dans le schéol, à la place des vivants et de ceux qui lui rendent leurs hommages?'),
('si',17,23,'crampon1923','A l''homme mort, comme s''il n''était plus rien, la louange est impossible; celui qui a la vie et la santé loue le Seigneur.'),
('si',17,24,'crampon1923','Qu''elle est grande la miséricorde du Seigneur, et sa compassion envers ceux qui se convertissent à lui!'),
('si',17,25,'crampon1923','Car tout ne peut pas se trouver dans les hommes, le fils de l''homme n''étant pas immortel.'),
('si',17,26,'crampon1923','Quoi de plus brillant que le soleil? Et pourtant il s''obscurcit: ainsi le méchant pense à la chair et au sang.'),
('si',17,27,'crampon1923','Le soleil visite l''armée des astres dans les hauteurs des cieux, mais tous les hommes sont terre et cendre.'),
('si',17,28,'crampon1923',''),
('si',17,29,'crampon1923',''),
('si',17,30,'crampon1923',''),
('si',17,31,'crampon1923',''),
('si',17,32,'crampon1923',''),
('si',18,1,'crampon1923','Celui qui vit éternellement a tout créé sans exception;'),
('si',18,2,'crampon1923','le Seigneur seul est juste.'),
('si',18,3,'crampon1923','Il n''a donné à personne de raconter ses œuvres; et qui pourra découvrir ses grandeurs?'),
('si',18,4,'crampon1923','Qui exprimera la toute-puissance de sa majesté, et qui encore redira ses miséricordes?'),
('si',18,5,'crampon1923','Rien à diminuer, rien à ajouter; impossible de pénétrer les merveilles du Seigneur.'),
('si',18,6,'crampon1923','Quand l''homme a fini de chercher, il n''est qu''au commencement, et, quand il s''arrête, il ne sait que penser.'),
('si',18,7,'crampon1923','Qu''est-ce que l''homme et à quoi est-il bon? Quel est son bonheur et quel est son malheur?'),
('si',18,8,'crampon1923','Le nombre des jours de l''homme est au plus de cent ans.'),
('si',18,9,'crampon1923','Comme une goutte d''eau prise dans la mer et comme un grain de sable, ainsi ses quelques années au jour de l''éternité.'),
('si',18,10,'crampon1923','C''est pourquoi le Seigneur est patient à l''égard des hommes et il répand sur eux sa miséricorde.'),
('si',18,11,'crampon1923','Il voit et il reconnaît que leur fin est déplorable; c''est pourquoi il est libéral à pardonner.'),
('si',18,12,'crampon1923','La miséricorde de l''homme s''exerce envers son prochain, mais la miséricorde de Dieu s''étend à toute chair. Il reprend, il corrige, il instruit, et ramène au bercail, comme le berger son troupeau.'),
('si',18,13,'crampon1923','Il a pitié de ceux qui reçoivent la correction, et de ceux qui s''empressent d''accomplir ses préceptes.'),
('si',18,14,'crampon1923','Mon fils, à tes bienfaits n''ajoute pas l''injure, ni à tous tes dons les paroles qui excitent la tristesse.'),
('si',18,15,'crampon1923','La rosée ne rafraîchit-elle pas les ardeurs du vent? De même une parole vaut mieux qu''un don.'),
('si',18,16,'crampon1923','Ne vois-tu pas que la parole est meilleure que le don? L''homme gracieux unit les deux ensemble.'),
('si',18,17,'crampon1923','L''insensé fait d''aigres reproches, et le don de l''envieux dessèche les yeux.'),
('si',18,18,'crampon1923','Avant de parler, instruis-toi; avant la maladie, soigne-toi.'),
('si',18,19,'crampon1923','Avant le jugement, examine-toi, et, à l''heure de l''enquête, tu trouveras grâce.'),
('si',18,20,'crampon1923','Avant d''être malade, humilie-toi, et, quand tu es dans le péché, reviens à Dieu.'),
('si',18,21,'crampon1923','Que rien ne t''empêche d''accomplir ton vœu dans le temps voulu, et n''attend pas jusqu''à la mort pour t''acquitter.'),
('si',18,22,'crampon1923','Avant de faire un vœu, prépare-toi, et ne sois pas comme un homme qui tente le Seigneur.'),
('si',18,23,'crampon1923','Songe à la colère du dernier jour, au temps de la vengeance, où Dieu détournera son visage.'),
('si',18,24,'crampon1923','Au temps de l''abondance, pense au temps de la faim; aux jours de la richesse, pense à la pauvreté et à la disette.'),
('si',18,25,'crampon1923','Du matin au soir le temps change: ainsi tout changement est rapide devant le Seigneur.'),
('si',18,26,'crampon1923','L''homme sage est en toute chose sur ses gardes; aux jours de péché, il se préserve de la faute.'),
('si',18,27,'crampon1923','Tout homme sensé connaît la sagesse, et rend hommage à celui qui l''a trouvée.'),
('si',18,28,'crampon1923','Ceux qui saisissent les discours des sages sont eux-mêmes des sages, et ils font pleuvoir les maximes parfaites.'),
('si',18,29,'crampon1923','Ne te laisse pas aller à tes convoitises, et garde-toi de tes désirs.'),
('si',18,30,'crampon1923','Si tu accordes à ton âme la satisfaction de ses convoitises, elle fera de toi la risée de tes ennemis.'),
('si',18,31,'crampon1923','Ne mets pas ta joie dans l''abondance de la bonne chère, et ne lie pas société avec elle.'),
('si',18,32,'crampon1923','Ne t''appauvris pas en donnant des banquets avec de l''argent emprunté, et quand tu n''as rien dans ta bourse.'),
('si',18,33,'crampon1923',''),
('si',19,1,'crampon1923','L''ouvrier adonné au vin ne s''enrichira pas; celui qui ne soigne pas le peu qu''il a tombera bientôt dans la ruine.'),
('si',19,2,'crampon1923','Le vin et les femmes égarent les hommes intelligents, et celui qui s''attache aux courtisanes est un imprudent.'),
('si',19,3,'crampon1923','Les larves et les vers en feront leur proie, et l''âme criminelle sera retranchée.'),
('si',19,4,'crampon1923','Celui qui croit trop vite est un cœur léger, et celui qui tombe dans cette faute pèche contre son âme.'),
('si',19,5,'crampon1923','Celui qui prend plaisir à de sots discours sera condamné,'),
('si',19,6,'crampon1923','et celui qui hait le bavardage se préserve du mal.'),
('si',19,7,'crampon1923','Ne répète jamais une parole, et tu n''encourras aucun dommage.'),
('si',19,8,'crampon1923','Ne la redis ni à un ami ni à un ennemi, et, à moins qu''il n''y ait faute pour toi, ne la révèle pas.'),
('si',19,9,'crampon1923','Car, s''il t''entend, il se gardera de toi, et, le moment venu, il se montrera ton ennemi.'),
('si',19,10,'crampon1923','As-tu entendu quelque grave propos? Qu''il meure avec toi! Sois sans inquiétude, il ne te fera pas éclater.'),
('si',19,11,'crampon1923','Pour une parole à garder, l''insensé est dans les douleurs, comme la femme en travail d''enfant.'),
('si',19,12,'crampon1923','Comme une flèche enfoncée dans la chair de la cuisse, ainsi est une parole dans le cœur de l''insensé.'),
('si',19,13,'crampon1923','Questionne ton ami; peut-être n''a-t-il pas fait la chose; et, s''il l''a faite, afin qu''il ne la fasse plus.'),
('si',19,14,'crampon1923','Questionne ton ami; peut-être n''a-t-il pas dit la chose; et, s''il l''a dite, afin qu''il ne recommence pas.'),
('si',19,15,'crampon1923','Questionne ton ami, car souvent il y a calomnie, et ne crois pas tout ce qu''on dit.'),
('si',19,16,'crampon1923','Il en est qui manquent, mais sans que le cœur y soit; et qui est-ce qui n''a pas péché par sa langue?'),
('si',19,17,'crampon1923','Questionne ton ami avant d''en venir aux menaces, et attache-toi à observer la loi du Très-Haut.'),
('si',19,18,'crampon1923','Toute sagesse consiste dans la crainte du Seigneur, et dans toute sagesse est l''accomplissement de la loi.'),
('si',19,19,'crampon1923','La sagesse n''est pas l''habileté à faire le mal, et la prudence ne se trouve pas dans le conseil des pécheurs.'),
('si',19,20,'crampon1923','Il y a une habileté qui est exécrable, et il y a une folie qui n''est qu''un manque de sagesse.'),
('si',19,21,'crampon1923','Mieux vaut celui qui a peu d''intelligence et qui craint Dieu, que l''homme qui a beaucoup de sens et qui transgresse la loi.'),
('si',19,22,'crampon1923','Il y a une habileté véritable, mais qui viole la justice, et il est tel qui fausse la cause pour faire rendre la sentence qu''il désire.'),
('si',19,23,'crampon1923','Il est tel méchant qui marche courbé par le chagrin, et son cœur est rempli de fraude.'),
('si',19,24,'crampon1923','Il baisse la tête, il est sourd d''un côté, et, dès qu''il n''est pas remarqué, il prend sur toi les devants.'),
('si',19,25,'crampon1923','Et si, par sa faiblesse, il est empêché de pécher, il fera le mal quand il en trouvera l''occasion.'),
('si',19,26,'crampon1923','A son air on connaît un homme, et au visage qu''il présente on connaît le sage.'),
('si',19,27,'crampon1923','Le vêtement d''un homme, le rire de ses lèvres, et la démarche d''un homme révèlent ce qu''il est.'),
('si',19,28,'crampon1923',''),
('si',19,29,'crampon1923',''),
('si',19,30,'crampon1923',''),
('si',20,1,'crampon1923','Il y a une réprimande qui n''est pas opportune, et tel se tait qui fait preuve de prudence.'),
('si',20,2,'crampon1923','Mieux vaut reprendre que de brûler d''une colère contenue; et celui qui avoue sera préservé de dommage.'),
('si',20,3,'crampon1923','Comme l''eunuque qui désire déflorer une jeune fille, ainsi est celui qui rend la justice avec violence. [Qu''il est beau, quand on est repris, de témoigner du repentir! C''est ainsi que tu échapperas au péché volontaire.]'),
('si',20,4,'crampon1923','Tel en se taisant se montre sage, et tel se rend odieux par son intempérance de langage.'),
('si',20,5,'crampon1923','Tel se tait parce qu''il n''a rien à répondre; tel autre se tait parce qu''il connaît le temps propice.'),
('si',20,6,'crampon1923','Le sage se tait jusqu''au moment favorable, mais le fanfaron et l''inconsidéré passent par-dessus.'),
('si',20,7,'crampon1923','Celui qui multiplie les paroles sera détesté, et celui qui se donne pleine licence se rendra odieux.'),
('si',20,8,'crampon1923','Tel homme trouve dans le malheur quelque chose d''heureux, et un bonheur inespéré tourne à sa perte.'),
('si',20,9,'crampon1923','Il est tel don qui ne te rapporte rien, et il est tel don qui est rendu au double.'),
('si',20,10,'crampon1923','D''une situation brillante résulte souvent un dommage, et tel relève la tête après une humiliation.'),
('si',20,11,'crampon1923','Tel achète beaucoup de choses à vil prix, qui les paie sept fois leur valeur.'),
('si',20,12,'crampon1923','Celui qui est sage dans ses discours se fait aimer, mais les paroles aimables de l''insensé sont en pure perte.'),
('si',20,13,'crampon1923','Le don de l''insensé ne te servira de rien; car ses yeux, au lieu d''un seul, sont nombreux.'),
('si',20,14,'crampon1923','Il donne peu, et reproche beaucoup, et il ouvre la bouche comme un crieur public. Il prête aujourd''hui, et il redemandera demain: un tel homme est odieux.'),
('si',20,15,'crampon1923','L''insensé dit: « Je n''ai point d''ami, et l''on ne me sait pas gré de mes bienfaits; ceux qui mangent mon pain ont des langues perverses. » —'),
('si',20,16,'crampon1923','Combien de fois et de combien de gens ne sera-t-il pas la risée?'),
('si',20,17,'crampon1923','Mieux vaut une chute sur le pavé qu''une chute de langue; c''est ainsi que la ruine des méchants arrive promptement.'),
('si',20,18,'crampon1923','Un homme désagréable est comme un conte hors de saison; l''homme mal appris l''a constamment à la bouche.'),
('si',20,19,'crampon1923','On n''accepte pas une maxime des lèvres d''un sot; car il ne la dit pas dans le temps qui lui convient.'),
('si',20,20,'crampon1923','Il est tel qui ne peut pécher, à cause de son indigence; et, dans son repos, il n''a pas de remords.'),
('si',20,21,'crampon1923','Tel se perd par une fausse honte, et tombe dans la ruine à cause du regard d''un insensé.'),
('si',20,22,'crampon1923','Tel par fausse honte promet beaucoup à son ami, et il s''en fait gratuitement un ennemi.'),
('si',20,23,'crampon1923','Le mensonge chez l''homme est une tache honteuse; il est toujours sur les lèvres des gens mal élevés.'),
('si',20,24,'crampon1923','Mieux vaut un voleur que l''homme qui fait métier de mentir: tous deux auront la ruine en partage.'),
('si',20,25,'crampon1923','La coutume du menteur est déshonorante, et la honte du menteur est constamment avec lui.'),
('si',20,26,'crampon1923','Celui qui est sage dans ses discours s''élève en considération, et l''homme prudent plaît aux grands.'),
('si',20,27,'crampon1923','Celui qui cultive sa terre élèvera son tas de blé, et celui qui plaît aux grands se fait pardonner ses injustices.'),
('si',20,28,'crampon1923','Les présents et les dons aveuglent les yeux des sages, et, comme une muselière à la bouche d''un animal, ils arrêtent le blâme.'),
('si',20,29,'crampon1923','Sagesse cachée, trésor invisible: à quoi servent l''un et l''autre?'),
('si',20,30,'crampon1923','Mieux vaut l''homme qui cache sa sottise que celui qui cache sa sagesse.'),
('si',20,31,'crampon1923',''),
('si',20,32,'crampon1923',''),
('si',21,1,'crampon1923','Mon fils, as-tu péché? ne le fais plus, mais prie pour tes fautes passées.'),
('si',21,2,'crampon1923','Fuis devant le péché comme devant un serpent; car, si tu en approches, il te mordra. Ses dents sont des dents de lion; elles donnent la mort aux hommes.'),
('si',21,3,'crampon1923','Toute transgression est comme une épée à deux tranchants; la plaie qu''elle fait est incurable.'),
('si',21,4,'crampon1923','La menace et l''injure détruisent la richesse; c''est ainsi que la maison de l''orgueilleux est détruite.'),
('si',21,5,'crampon1923','La prière du pauvre monte de ses lèvres à l''oreille du riche; mais sur l''orgueilleux viendra bientôt son jugement.'),
('si',21,6,'crampon1923','Celui qui hait la réprimande marche sur la trace du pécheur, mais celui qui craint Dieu se tourne vers lui d''un cœur sincère.'),
('si',21,7,'crampon1923','L''homme puissant par la langue se fait connaître de loin; mais l''homme de sens sait quand il faillit.'),
('si',21,8,'crampon1923','L''homme qui bâtit sa maison avec de l''argent qui n''est pas à lui est comme celui qui ramasse ses pierres pour l''hiver.'),
('si',21,9,'crampon1923','La troupe des ennemis est un amas d''étoupes; elle finira par être la proie du feu.'),
('si',21,10,'crampon1923','La voie des pécheurs est pavée de pierres, mais à son extrémité est le gouffre du schéol.'),
('si',21,11,'crampon1923','Celui qui observe la loi maîtrise ses pensées, et le résultat final de la crainte du Seigneur est la sagesse.'),
('si',21,12,'crampon1923','Celui qui manque d''habileté ne sera pas instruit; mais il y a une habileté qui produit beaucoup d''amertume.'),
('si',21,13,'crampon1923','La science du sage abonde comme une eau qui déborde, et son conseil est une source de vie.'),
('si',21,14,'crampon1923','L''intérieur de l''insensé est comme un vase fêlé; il ne retiendra aucune connaissance.'),
('si',21,15,'crampon1923','Que l''homme intelligent entende une sage parole, il en fait l''éloge et y ajoute quelque chose. Que le voluptueux l''entende, elle lui déplaît, et il la jette derrière lui.'),
('si',21,16,'crampon1923','Le discours de l''insensé est comme un fardeau en voyage, mais sur les lèvres de l''homme intelligent se trouve la grâce.'),
('si',21,17,'crampon1923','On recherche dans l''assemblée la bouche de l''homme prudent, et on médite ses paroles dans son cœur.'),
('si',21,18,'crampon1923','La sagesse est pour le sot comme une maison en ruines, et la science de l''insensé n''est que paroles incohérentes.'),
('si',21,19,'crampon1923','L''instruction est pour les insensés comme des chaînes aux pieds, et des menottes à la main droite.'),
('si',21,20,'crampon1923','Le sot, quand il rit, fait éclater sa voix, mais l''homme habile sourit à peine tout bas.'),
('si',21,21,'crampon1923','L''instruction est pour l''homme sensé comme une parure d''or, et comme un bracelet au bras droit.'),
('si',21,22,'crampon1923','L''insensé entre d''un pas rapide dans la maison, mais l''homme d''expérience s''arrête timidement à l''entrée.'),
('si',21,23,'crampon1923','L''insensé se courbe dès la porte pour voir dans la maison, mais l''homme bien élevé se tient dehors.'),
('si',21,24,'crampon1923','C''est une grossièreté pour un homme d''écouter à la porte; l''homme sensé s''indigne d''une action si honteuse.'),
('si',21,25,'crampon1923','Les lèvres des insensés ne profèrent que sottises, mais les paroles des hommes prudents sont pesées à la balance.'),
('si',21,26,'crampon1923','Dans la bouche des sots est leur cœur, mais le cœur des sages est leur bouche.'),
('si',21,27,'crampon1923','Quand l''impie maudit son adversaire, c''est lui-même qu''il maudit.'),
('si',21,28,'crampon1923','Le rapporteur se souille lui-même, et il est détesté de tous ceux qui l''approchent.'),
('si',22,1,'crampon1923','Le paresseux ressemble à une pierre remplie d''ordure, et chacun siffle son infamie.'),
('si',22,2,'crampon1923','Le paresseux ressemble à une boule de fiente: celui qui la ramasse secoue sa main.'),
('si',22,3,'crampon1923','Un fils mal élevé est la honte du père qui lui a donné le jour; une fille semblable est venue au monde pour son détriment.'),
('si',22,4,'crampon1923','Une fille prudente trouvera son mari, mais celle dont on a honte fait le chagrin de son père.'),
('si',22,5,'crampon1923','L''effrontée fait honte à son père et à son mari; tous deux la mépriseront.'),
('si',22,6,'crampon1923','Telle une musique dans le deuil, tel un sermon à contre-temps; mais le fouet et la correction sont en tout temps de la sagesse.'),
('si',22,7,'crampon1923','Instruire un sot, c''est recoller un pot cassé; [raconter une chose à qui n''écoute pas], c''est réveiller un homme endormi d''un profond sommeil.'),
('si',22,8,'crampon1923','C''est parler à un homme qui dort que d''entretenir un sot; à la fin de ton discours, il dira: « Qu''est-ce? »'),
('si',22,9,'crampon1923','Pleure sur un mort, car il est privé de lumière; pleure sur un sot, car il est privé de bon sens. Pleure doucement sur le mort, car il a trouvé le repos, mais la vie du sot est pire que la mort.'),
('si',22,10,'crampon1923','Le deuil pour un mort dure sept jours; pour le sot et pour l''impie, il dure tous les jours de leur vie.'),
('si',22,11,'crampon1923','Avec l''insensé n''aie pas de longs entretiens, et ne va pas avec l''homme dénué de sens. Garde-toi de lui, si tu ne veux pas avoir d''ennui, et tu ne seras pas souillé de son contact. Détourne-toi de lui et tu trouveras le repos, et tu n''auras pas à t''attrister en voyant sa sottise.'),
('si',22,12,'crampon1923','Qu''est-ce qui est plus lourd que le plomb, et quel autre nom lui donner que celui de sot?'),
('si',22,13,'crampon1923','Le sable, le sel, une masse de fer sont plus faciles à porter qu''un homme sans intelligence.'),
('si',22,14,'crampon1923','Un assemblage de charpente bien lié pour un édifice ne sera pas disjoint par un tremblement de terre: ainsi le cœur fixé dans un dessein mûrement réfléchi sera sans crainte au moment critique.'),
('si',22,15,'crampon1923','Le cœur qui s''appuie sur une pensée de sagesse est comme l''enduit mêlé de sable sur un mur poli.'),
('si',22,16,'crampon1923','Une palissade sur une hauteur ne tient pas contre le vent: ainsi un cœur timide avec ses folles résolutions ne résistera pas à la crainte.'),
('si',22,17,'crampon1923','Celui qui froisse un œil fait couler des larmes; celui qui froisse un cœur excite le sentiment de la douleur.'),
('si',22,18,'crampon1923','Celui qui jette une pierre contre des oiseaux les met en fuite, et celui qui reproche un bienfait à son ami dissout l''amitié.'),
('si',22,19,'crampon1923','As-tu tiré l''épée contre ton ami? Ne désespère pas; un retour est possible.'),
('si',22,20,'crampon1923','As-tu ouvert la bouche contre ton ami? Sois sans crainte; la réconciliation est possible. Mais le reproche d''un bienfait, l''arrogance, la révélation d''un secret, un coup de langue perfide: cela met en fuite tous les amis.'),
('si',22,21,'crampon1923','Reste fidèle à ton prochain dans sa pauvreté, afin que tu jouisses avec lui de sa prospérité. Reste avec lui aux jours de son épreuve, afin que tu aies part aux biens qui lui surviendront.'),
('si',22,22,'crampon1923','Avant le feu s''élèvent la vapeur de la fournaise et la fumée; de même avant l''effusion du sang retentissent les injures.'),
('si',22,23,'crampon1923','Je ne rougirai pas de défendre mon ami, et je ne me cacherai pas devant lui;'),
('si',22,24,'crampon1923','et, si quelque mal m''arrive par son fait, quiconque l''apprendra se mettra en garde contre lui.'),
('si',22,25,'crampon1923','Qui mettra une garde à ma bouche, et sur mes lèvres un sceau prudent, afin que je ne tombe pas à cause d''elles, et que ma langue ne me perde pas!'),
('si',22,26,'crampon1923',''),
('si',22,27,'crampon1923',''),
('si',23,1,'crampon1923','Seigneur, Père et souverain Maître de ma vie, ne m''abandonnez pas au conseil de mes lèvres, et ne permettez pas que j''y trouve une occasion de chute.'),
('si',23,2,'crampon1923','Qui fera sentir le fouet à mes pensées, et la discipline de la sagesse à mon cœur, pour ne pas m''épargner dans mes folies, et ne pas laisser un libre cours à mes péchés:'),
('si',23,3,'crampon1923','de peur que mes folies ne s''accroissent, que mes péchés ne se multiplient, que je ne tombe en présence de mes adversaires, et que mon ennemi ne se réjouisse à mon sujet?'),
('si',23,4,'crampon1923','Seigneur, Père et Dieu de ma vie, ne me donnez point la licence des yeux,'),
('si',23,5,'crampon1923','et détournez de moi les désirs mauvais.'),
('si',23,6,'crampon1923','Que les désirs de la chair et la volupté ne s''emparent pas de moi, et ne me livrez pas à une âme sans pudeur.'),
('si',23,7,'crampon1923','Mes enfants, écoutez la discipline de la bouche; celui qui l''observera ne sera pas pris.'),
('si',23,8,'crampon1923','Par ses lèvres le pécheur sera pris; le médisant et l''insolent y trouveront une occasion de chute.'),
('si',23,9,'crampon1923','N''accoutume pas ta bouche à faire des serments, et ne prends pas l''habitude de prononcer le nom du Saint.'),
('si',23,10,'crampon1923','Car, comme un esclave mis souvent à la torture ne saurait être exempt de meurtrissures, ainsi celui qui fait serment et prononce sans cesse le nom du Saint, ne sera pas pur du péché.'),
('si',23,11,'crampon1923','L''homme qui fait beaucoup de serments multiplie l''iniquité, et le fouet ne s''éloignera pas de sa maison. S''il s''est rendu coupable, son péché est sur lui; s''il n''y fait pas attention, son péché est double. S''il a fait un faux serment, il ne sera pas absous, car sa maison sera remplie de châtiments.'),
('si',23,12,'crampon1923','Il y a des paroles qui appellent la mort: qu''elles ne se rencontrent pas dans l''héritage de Jacob! Tout cela est éloigné des hommes pieux; ils ne s''engagent pas dans ces péchés.'),
('si',23,13,'crampon1923','N''accoutume pas ta bouche à une vile grossièreté, car elle inspire des paroles coupables.'),
('si',23,14,'crampon1923','Souviens-toi de ton père et de ta mère, quand tu sièges au milieu des grands, de peur que, les oubliant en leur présence, tu ne fasses des sottises par l''effet de l''habitude, et que tu n''en viennes à souhaiter de n''être pas né, et à maudire le jour de ta naissance.'),
('si',23,15,'crampon1923','Un homme qui s''habitue à un langage grossier ne parviendra jamais à la sagesse.'),
('si',23,16,'crampon1923','Deux sortes d''hommes multiplient les péchés, et la troisième attire la colère. L''homme que brûle la passion, comme un feu ardent, ne s''éteindra pas jusqu''à ce qu''il soit consumé. L''homme impudique en sa propre chair ne cessera pas jusqu''à ce que le feu soit allumé.'),
('si',23,17,'crampon1923','Au voluptueux tout pain est doux; il ne s''arrêtera pas qu''il ne soit mort.'),
('si',23,18,'crampon1923','L''homme qui quitte la couche conjugale dit dans son cœur: « Qui me voit? Les ténèbres m''environnent, les murailles me cachent, et personne ne m''aperçoit: que craindrais-je? Le Très-Haut ne se souviendra pas de mes péchés ». —'),
('si',23,19,'crampon1923','Les yeux des hommes sont sa crainte, et il ne sait pas que les yeux du Seigneur sont mille fois plus brillants que le soleil; qu''ils regardent toutes les voies de l''homme, et pénètrent jusque dans les lieux cachés!'),
('si',23,20,'crampon1923','Avant d''être créées, toutes choses sont connues du Seigneur, elles le sont encore après leur achèvement.'),
('si',23,21,'crampon1923','L''adultère sera puni dans les rues de la ville, et, là où il ne s''y attendait pas, il sera pris.'),
('si',23,22,'crampon1923','Il en est de même de la femme qui a abandonné son mari, et donné un hériter d''une union étrangère.'),
('si',23,23,'crampon1923','Car d''abord elle a désobéi à la loi du Très-Haut: en deuxième lieu, elle a péché envers son mari, et en troisième lieu, elle a commis un adultère, et donné des enfants d''un sang étranger.'),
('si',23,24,'crampon1923','Elle sera amenée devant l''assemblée, et le châtiment visitera ses enfants.'),
('si',23,25,'crampon1923','Ses enfants ne pousseront point de racines, et ses branches ne porteront pas de fruits.'),
('si',23,26,'crampon1923','Elle laissera une mémoire vouée à la malédiction, et son infamie ne s''effacera jamais.'),
('si',23,27,'crampon1923','Et les survivants sauront qu''il n''y a rien de meilleur que la crainte du Seigneur, rien de plus doux que d''observer ses commandements. [C''est une grande gloire que de suivre le Seigneur; s''attacher à lui, c''est la longueur des jours].'),
('si',23,28,'crampon1923',''),
('si',24,1,'crampon1923','La sagesse se loue elle-même, et se glorifie au milieu de son peuple.'),
('si',24,2,'crampon1923','Elle ouvre la bouche dans l''assemblée du Très-Haut, et se glorifie en présence de sa Majesté:'),
('si',24,3,'crampon1923','Je suis sortie de la bouche du Très-Haut, et, comme une nuée, je couvris la terre.'),
('si',24,4,'crampon1923','J''habitai dans les hauteurs, et mon trône était sur une colonne de nuée.'),
('si',24,5,'crampon1923','Seule, j''ai parcouru le cercle du ciel, et je me suis promenée dans les profondeurs de l''abîme.'),
('si',24,6,'crampon1923','Dans les flots de la mer et sur toute la terre, dans tout peuple et toute nation j''ai exercé l''empire.'),
('si',24,7,'crampon1923','Parmi eux tous j''ai cherché un lieu de repos, et dans quel domaine je devais habiter.'),
('si',24,8,'crampon1923','Alors le Créateur de toutes choses me donna ses ordres, et celui qui m''a créée fit reposer ma tente; et il me dit: « Habite en Jacob, aie ton héritage en Israël. »'),
('si',24,9,'crampon1923','Avant tous les siècles, dès le commencement il m''a créée, et jusqu''à l''éternité je ne cesserai pas d''être.'),
('si',24,10,'crampon1923','J''ai exercé le ministère devant lui dans le saint tabernacle, et ainsi j''ai eu une demeure fixe en Sion.'),
('si',24,11,'crampon1923','De même, il m''a fait reposer dans la cité bien-aimée, et dans Jérusalem est le siège de mon empire.'),
('si',24,12,'crampon1923','J''ai poussé mes racines dans le peuple glorifié, dans la portion du Seigneur, dans son héritage.'),
('si',24,13,'crampon1923','Je me suis élevée comme le cèdre sur le Liban, et comme le cyprès sur la montagne d''Hermon.'),
('si',24,14,'crampon1923','Je me suis élevée comme le palmier sur les rivages, et comme les rosiers à Jéricho; comme un bel olivier dans la plaine, et je me suis élevée comme un platane.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('si',24,15,'crampon1923','J''ai donné du parfum comme la canelle et comme le baume odorant, et comme une myrrhe choisie j''ai répandu une odeur suave, comme le galbanum, l''onyx et le stacte, et comme la vapeur de l''encens dans le tabernacle.'),
('si',24,16,'crampon1923','J''ai étendu mes branches comme le térébinthe, et mes rameaux sont des rameaux de gloire et de grâce.'),
('si',24,17,'crampon1923','Comme la vigne, j''ai produit des pousses charmantes, et mes fleurs ont donné des fruits de gloire et de richesse. [Je suis la mère du pur amour, de la crainte de Dieu, de la science et de la sainte espérance].'),
('si',24,18,'crampon1923','Venez à moi, vous tous qui me désirez, et rassasiez-vous de mes fruits.'),
('si',24,19,'crampon1923','Car mon souvenir est plus doux que le miel, et ma possession plus douce que le rayon de miel.'),
('si',24,20,'crampon1923','Ceux qui me mangent auront encore faim, et ceux qui me boivent auront encore soif.'),
('si',24,21,'crampon1923','Celui qui m''écoute n''aura jamais de confusion, et ceux qui agissent par moi ne pécheront point.'),
('si',24,22,'crampon1923','Tout cela, c''est le livre de l''alliance du Dieu très haut, c''est la loi que Moïse a donnée, pour être l''héritage des assemblées de Jacob.'),
('si',24,23,'crampon1923','Cette loi fait déborder la Sagesse, comme le Phison, et comme le Tigre au temps des fruits nouveaux.'),
('si',24,24,'crampon1923','Elle répand à flots l''intelligence, comme l''Euphrate, comme le Jourdain au temps de la moisson.'),
('si',24,25,'crampon1923','Elle fait jaillir la science, comme le Fleuve, comme le Géhon au temps de la vendange.'),
('si',24,26,'crampon1923','Le premier qui l''a étudiée n''a pas achevé de la connaître, et de même, le dernier ne l''a pas pénétrée.'),
('si',24,27,'crampon1923','Car son intelligence est plus vaste que la mer, et son conseil plus profond que le grand abîme.'),
('si',24,28,'crampon1923','Et moi, j''ai coulé comme un canal dérivé d''un fleuve, comme un aqueduc arrosant un jardin de plaisance.'),
('si',24,29,'crampon1923','J''ai dit: « J''arroserai mon jardin, j''abreuverai mon parterre. » Et voilà que mon canal est devenu un fleuve, que mon fleuve est devenu une mer.'),
('si',24,30,'crampon1923','Je veux donc faire briller encore l''instruction comme l''aurore, faire connaître au loin ses maximes;'),
('si',24,31,'crampon1923','je veux encore répandre la doctrine comme une prophétie, et la laisser en héritage aux générations lointaines.'),
('si',24,32,'crampon1923','Reconnaissez que je n''ai pas travaillé pour moi seul, mais pour tous ceux qui cherchent la Sagesse.'),
('si',24,33,'crampon1923',''),
('si',24,34,'crampon1923',''),
('si',25,1,'crampon1923','Trois choses me plaisent, et elles sont belles devant le Seigneur et les hommes: la concorde entre les frères, l''amitié entre les proches, et le bon accord entre le mari et la femme.'),
('si',25,2,'crampon1923','Mais il y a trois sortes de gens que je déteste, et dont la vie m''est tout à fait odieuse: le pauvre orgueilleux, le riche qui use de fraude, et le vieillard voluptueux, dénué de sens.'),
('si',25,3,'crampon1923','Tu n''as pas amassé dans ta jeunesse: comment posséderais-tu dans ta vieillesse?'),
('si',25,4,'crampon1923','Qu''il est beau pour les cheveux blancs de bien juger, pour la vieillesse de connaître le bon conseil!'),
('si',25,5,'crampon1923','Que la sagesse sied bien aux vieillards, la prudence et le conseil à ceux qu''on honore!'),
('si',25,6,'crampon1923','La couronne des vieillards, c''est une riche expérience; leur gloire, c''est la crainte du Seigneur.'),
('si',25,7,'crampon1923','Il y a neuf choses qu''en mon cœur j''estime heureuses, et une dixième que ma langue proclame: L''homme qui a de la joie dans ses enfants, celui qui vit assez pour voir la ruine de ses ennemis.'),
('si',25,8,'crampon1923','Heureux qui habite avec une femme sensée, et celui qui ne pèche point par la langue! [Heureux qui a trouvé un ami fidèle], et celui qui ne sert pas des maîtres indignes de lui!'),
('si',25,9,'crampon1923','Heureux qui a trouvé la prudence, et celui qui l''enseigne à une oreille attentive!'),
('si',25,10,'crampon1923','Qu''il est grand l''homme qui a trouvé la sagesse! Pourtant il n''est pas au-dessus de celui qui craint le Seigneur.'),
('si',25,11,'crampon1923','La crainte du Seigneur surpasse tout; celui qui la possède, à qui le comparer? [La crainte du Seigneur est le commencement de son amour, et la foi est le commencement de l''attachement à Dieu].'),
('si',25,12,'crampon1923','Toutes les souffrances, mais non la souffrance du cœur; toutes les méchancetés, mais non la méchanceté de la femme.'),
('si',25,13,'crampon1923','Tous les maux, mais non le mal causé par des adversaires, toutes les vengeances, mais non la vengeance des ennemis.'),
('si',25,14,'crampon1923','Il n''y a pas de venin plus mauvais que le venin du serpent, et il n''y a pas de colère plus grande que la colère d''une femme.'),
('si',25,15,'crampon1923','J''aimerais mieux habiter avec un lion et un dragon, que de demeurer avec une femme méchante.'),
('si',25,16,'crampon1923','La méchanceté de la femme change sa figure; elle rend sons visage aussi noir qu''un sac.'),
('si',25,17,'crampon1923','Son mari va s''asseoir au milieu de ses amis, et, en les entendant, il soupire amèrement.'),
('si',25,18,'crampon1923','Toute méchanceté est légère, comparée à la méchanceté de la femme: que le sort des pécheurs tombe sur elle!'),
('si',25,19,'crampon1923','Comme une montée sablonneuse pour les pieds d''un vieillard, ainsi est une femme bavarde pour un mari paisible.'),
('si',25,20,'crampon1923','Ne te laisse pas séduire par la beauté d''une femme, et qu''aucune femme n''excite ta convoitise.'),
('si',25,21,'crampon1923','C''est un sujet d''indignation, un opprobre et une grande honte, que la femme fournisse l''entretien de son mari.'),
('si',25,22,'crampon1923','Abattement du cœur, tristesse du visage, souffrance de l''âme: voilà ce que produit une méchante femme. Des mains languissantes, et des genoux qui fléchissent: voilà ce que produit une femme qui ne rend pas heureux son mari.'),
('si',25,23,'crampon1923','C''est par une femme que le péché a commencé; c''est à cause d''elle que nous mourons tous.'),
('si',25,24,'crampon1923','Ne laisse à l''eau aucune issue, ni à la femme méchante aucune autorité.'),
('si',25,25,'crampon1923','Si elle ne marche pas comme ta main la conduit, retranche-la de ta chair.'),
('si',25,26,'crampon1923',''),
('si',26,1,'crampon1923','Heureux est le mari d''une femme vertueuse, et le nombre de ses jours sera doublé.'),
('si',26,2,'crampon1923','La femme forte est la joie de son mari, et il passe ses années dans la paix.'),
('si',26,3,'crampon1923','La femme vertueuse est une bonne part; elle sera donnée en partage à ceux qui craignent le Seigneur.'),
('si',26,4,'crampon1923','Riche ou pauvre, son mari a le cœur joyeux, en tout temps son visage est gai.'),
('si',26,5,'crampon1923','Il y a trois choses que redoute mon cœur, et au sujet de la quatrième, je prie devant le Seigneur: les méchants propos de toute une ville, la malédiction de la foule et la calomnie: toutes ces choses me sont plus odieuses que la mort;'),
('si',26,6,'crampon1923','mais la douleur du cœur et l''affliction, c''est une femme jalouse d''une autre, et le fouet d''une langue qui raconte à tous ses griefs.'),
('si',26,7,'crampon1923','Une méchante épouse, c''est une paire de bœufs en désaccord; celui qui la tient est pareil à celui qui a saisi un scorpion.'),
('si',26,8,'crampon1923','C''est un grand sujet de colère qu''une femme adonnée au vin; elle ne voilera pas même sa honte.'),
('si',26,9,'crampon1923','A l''effronterie de son regard, au clignotement de ses paupières, on reconnaît l''impudicité d''une femme.'),
('si',26,10,'crampon1923','Fais bonne garde auprès d''une fille indocile, de peur que, voyant ta négligence, elle ne se livre à la débauche.'),
('si',26,11,'crampon1923','Garde-toi de suivre un œil impudent; autrement ne t''étonne pas qu''il t''entraîne au péché.'),
('si',26,12,'crampon1923','Comme le voyageur altéré ouvre sa bouche, et boit de toute eau qu''il rencontre, l''impudique s''assied devant chaque poteau, et devant la flèche ouvre son carquois.'),
('si',26,13,'crampon1923','La grâce d''une femme fait la joie de son mari, et son intelligence répand la vigueur en ses os.'),
('si',26,14,'crampon1923','C''est un don de Dieu qu''une femme silencieuse, et rien n''est comparable à une femme bien élevée.'),
('si',26,15,'crampon1923','C''est une grâce au-dessus de toute grâce qu''une femme pudique, et aucun trésor ne vaut une femme chaste.'),
('si',26,16,'crampon1923','Le soleil se lève dans les hauteurs du Seigneur: ainsi la beauté d''une femme brille dans sa maison bien ornée.'),
('si',26,17,'crampon1923','Comme le flambeau qui luit sur le chandelier sacré, ainsi est la beauté du visage sur une noble stature.'),
('si',26,18,'crampon1923','Comme des colonnes d''or sur des bases d''argent, tels sont des pieds élégants sur des talons solides.'),
('si',26,19,'crampon1923','Deux choses attristent mon cœur, et la troisième excite mon indignation: l''homme de guerre qui souffre de la pauvreté, les hommes intelligents qui sont l''objet du mépris; celui qui passe de la justice au péché, le Seigneur le prépare pour l''épée.'),
('si',26,20,'crampon1923','Difficilement l''homme du négoce évitera la faute, et le marchand de vin ne sera pas exempt de péché.'),
('si',26,21,'crampon1923',''),
('si',26,22,'crampon1923',''),
('si',26,23,'crampon1923',''),
('si',26,24,'crampon1923',''),
('si',26,25,'crampon1923',''),
('si',26,26,'crampon1923',''),
('si',26,27,'crampon1923',''),
('si',26,28,'crampon1923',''),
('si',26,29,'crampon1923',''),
('si',27,1,'crampon1923','Beaucoup pèchent pour de l''argent, et celui qui cherche à s''enrichir détourne les yeux.'),
('si',27,2,'crampon1923','La cheville s''enfonce entre les jointures des pierres: ainsi le péché pénètre entre la vente et l''achat.'),
('si',27,3,'crampon1923','Si tu ne t''attaches pas fortement à la crainte de Dieu, ta maison sera bientôt détruite.'),
('si',27,4,'crampon1923','Quand on agite le crible, il reste un tas de rebuts: de même les défauts d''un homme apparaissent dans ses discours.'),
('si',27,5,'crampon1923','La fournaise éprouve les vases du potier, et l''épreuve de l''homme est dans sa conversation.'),
('si',27,6,'crampon1923','Le fruit d''un arbre fait connaître le champ qui le porte: ainsi la parole manifeste les sentiments du cœur de l''homme.'),
('si',27,7,'crampon1923','Ne loue personne avant qu''il n''ait parlé, car la parole est l''épreuve des hommes.'),
('si',27,8,'crampon1923','Si tu poursuis la justice, tu l''atteindras, et tu t''en revêtiras comme d''une robe d''honneur.'),
('si',27,9,'crampon1923','Les oiseaux se réunissent à leurs semblables: de même la vérité retourne à ceux qui la pratiquent.'),
('si',27,10,'crampon1923','Le lion guette sa proie: ainsi le péché guette ceux qui commettent l''injustice.'),
('si',27,11,'crampon1923','Le discours de l''homme pieux est toujours sagesse, mais l''insensé est changeant comme la lune.'),
('si',27,12,'crampon1923','Pour aller au milieu des insensés, observe le temps; mais sois continuellement au milieu de ceux qui réfléchissent.'),
('si',27,13,'crampon1923','La conversation des insensés est détestable; leur rire éclate dans la joie du péché.'),
('si',27,14,'crampon1923','Le langage de celui qui prodigue les serments fait dresser les cheveux; quand il dispute, on se bouche les oreilles.'),
('si',27,15,'crampon1923','Les disputes des orgueilleux font couler le sang, et leurs invectives font peine à entendre.'),
('si',27,16,'crampon1923','Celui qui révèle les secrets perd la confiance, et il ne trouvera plus d''ami à son gré.'),
('si',27,17,'crampon1923','Aime ton ami et sois-lui fidèle; mais, si tu dévoiles ses secrets, ne cours pas après lui.'),
('si',27,18,'crampon1923','Car, comme un homme donne la mort à son ennemi, ainsi tu as tué l''affection de ton ami.'),
('si',27,19,'crampon1923','Et comme lorsque tu as laissé échapper un oiseau de ta main, ainsi tu as éloigné ton ami, et tu ne le rattraperas plus.'),
('si',27,20,'crampon1923','Ne le poursuis pas, car il est loin; il s''est enfui comme une gazelle échappée du filet.'),
('si',27,21,'crampon1923','On bande une blessure, après une injure on se réconcilie; mais celui qui a révélé des secrets n''a plus d''espérance.'),
('si',27,22,'crampon1923','Celui qui cligne de l''œil fabrique l''iniquité, et personne ne peut s''en défaire.'),
('si',27,23,'crampon1923','En ta présence, il n''aura que douceur sur les lèvres, il admirera tes paroles; mais ensuite il changera de langage, et donnera un tour fâcheux à tes discours,'),
('si',27,24,'crampon1923','Je hais bien des choses, mais rien tant que lui; le Seigneur aussi l''a en aversion.'),
('si',27,25,'crampon1923','Celui qui jette une pierre en l''air la jette sur sa propre tête: ainsi un coup perfide fait des blessures au perfide.'),
('si',27,26,'crampon1923','Qui creuse une fosse y tombera, et qui tend un filet y sera pris.'),
('si',27,27,'crampon1923','Celui qui fait le mal le verra rouler sur lui, et il ne saura pas d''où cela lui vient.'),
('si',27,28,'crampon1923','Le sarcasme et l''outrage sont dans la bouche des orgueilleux, mais la vengeance les guette comme un lion.'),
('si',27,29,'crampon1923','Ils seront pris au piège ceux que réjouit le malheur des hommes pieux, et la douleur les consumera avant leur mort.'),
('si',27,30,'crampon1923','Le ressentiment et la colère, eux aussi, sont détestables, et le pécheur les possède.'),
('si',28,1,'crampon1923','Celui qui se venge trouvera la vengeance auprès du Seigneur, qui conservera soigneusement ses péchés.'),
('si',28,2,'crampon1923','Pardonne au prochain son injustice, et alors à ta prière tes péchés seront remis.'),
('si',28,3,'crampon1923','L''homme conserve de la colère contre un autre homme, et il demande à Dieu sa guérison!…'),
('si',28,4,'crampon1923','Il n''a pas pitié d''un homme, son semblable, et il supplie pour ses propres fautes!…'),
('si',28,5,'crampon1923','Lui, qui n''est que chair, garde rancune; qui donc lui obtiendra le pardon de ses péchés?'),
('si',28,6,'crampon1923','Souviens-toi de ta fin, et cesse de haïr; de la corruption et de la mort, et observe les commandements.'),
('si',28,7,'crampon1923','Souviens-toi des commandements, et n''aie pas de rancune contre ton prochain; de l''alliance du Très-Haut, et passe par-dessus l''offense.'),
('si',28,8,'crampon1923','Tiens-toi éloigné de la dispute, et tu pécheras moins; car l''homme irascible échauffe la querelle,'),
('si',28,9,'crampon1923','et le pécheur met le trouble parmi les amis, et jette la calomnie parmi ceux qui vivent en paix.'),
('si',28,10,'crampon1923','Le feu s''embrase en proportion de la matière qui l''alimente: ainsi la colère d''un homme s''allume en proportion de sa puissance. Selon sa richesse, il fait monter sa fureur; elle s''enflamme selon la violence de la dispute.'),
('si',28,11,'crampon1923','Une querelle précipitée allume le feu, et une dispute irréfléchie fait couler le sang.'),
('si',28,12,'crampon1923','Si tu souffles sur une étincelle, elle s''embrase; si tu craches dessus, elle s''éteint: les deux choses sortent de ta bouche.'),
('si',28,13,'crampon1923','Maudis le rapporteur et l''homme à double langue, car ils en ont perdu beaucoup qui vivaient en paix.'),
('si',28,14,'crampon1923','La langue calomniatrice en a précipité un grand nombre, et les a chassés d''un peuple chez un autre; elle a renversé des villes fortes, et jeté par terre les palais des grands.'),
('si',28,15,'crampon1923','La langue calomniatrice a fait chasser des femmes vaillantes, et les a dépouillées du fruit de leurs travaux.'),
('si',28,16,'crampon1923','Qui lui prête l''oreille ne trouvera plus le repos, et il n''aura plus de paix dans sa demeure.'),
('si',28,17,'crampon1923','Le coup de verge fait des meurtrissures, le coup de langue brise les os.'),
('si',28,18,'crampon1923','Beaucoup ont péri par le tranchant de l''épée; mais pas autant que ceux qui ont péri par la langue.'),
('si',28,19,'crampon1923','Heureux celui qui en est à l''abri, qui n''est pas livré à sa fureur, qui n''a pas traîné son joug, et qui n''a pas été lié de ses chaînes!'),
('si',28,20,'crampon1923','Car son joug est un joug de fer, et ses chaînes sont des chaînes d''airain.'),
('si',28,21,'crampon1923','La mort qu''elle donne est une mort affreuse, et le schéol vaut mieux qu''elle.'),
('si',28,22,'crampon1923','Elle n''aura pas d''empire sur les hommes pieux, et ils ne seront pas brûlés par sa flamme.'),
('si',28,23,'crampon1923','Ceux qui abandonnent le Seigneur y tomberont; et elle les consumera sans s''éteindre.'),
('si',28,24,'crampon1923','Vois, entoure ton domaine d''une haie d''épines, lie dans ton sac ton or et ton argent;'),
('si',28,25,'crampon1923','et fais une balance et des poids pour tes discours, et fais une porte et un verrou pour ta bouche.'),
('si',28,26,'crampon1923','Prends garde à ne pas faillir par la langue, de peur que tu ne tombes devant celui qui te guette.'),
('si',29,1,'crampon1923','Celui qui pratique la miséricorde prête à son prochain, et celui qui le soutient de sa main observe les commandements.'),
('si',29,2,'crampon1923','Prête à ton prochain quand il est dans le besoin, et, à ton tour, rends au prochain, le temps venu, ce qu''il t''a prêté.'),
('si',29,3,'crampon1923','Tiens ta parole, et agis loyalement avec lui, et tu trouveras en tout temps ce qui t''est nécessaire.'),
('si',29,4,'crampon1923','Beaucoup regardent comme une trouvaille ce qu''on leur a prêté, et causent de l''ennui à ceux qui leur sont venus en aide.'),
('si',29,5,'crampon1923','Jusqu''à ce qu''on ait reçu, on baise la main du prochain, d''une voix humble on vante ses richesses; mais quand vient le moment de rendre, on prend des délais, on ne rend que des paroles de plainte, et on accuse la dureté des temps.'),
('si',29,6,'crampon1923','Si l''on a des moyens, le prêteur recevra la moitié à peine, et croira faire une trouvaille. Si on n''en a pas, on le frustre de son argent, et celui-ci sans le vouloir se fait de son obligé un ennemi, qui le paie en malédictions et en injures, et qui, au lieu de l''honneur, ne lui rend que l''outrage.'),
('si',29,7,'crampon1923','Beaucoup se refusent à prêter à cause de la malice des hommes; ils craignent d''être frustrés inutilement de leur argent.'),
('si',29,8,'crampon1923','Pourtant sois indulgent à l''égard du malheureux, et ne lui fais pas attendre ton aumône.'),
('si',29,9,'crampon1923','Assiste le pauvre à cause du commandement divin, et, à cause de sa détresse, ne le renvoie pas les mains vides.'),
('si',29,10,'crampon1923','Consens à perdre ton argent en faveur de ton frère et de ton ami, et qu''il ne se rouille pas sans profit sous une pierre.'),
('si',29,11,'crampon1923','Emploie ton trésor selon les préceptes du Très-Haut, et plus que l''or il te profitera.'),
('si',29,12,'crampon1923','Enferme ton aumône dans tes appartements, et elle te délivrera de tout malheur.'),
('si',29,13,'crampon1923','Mieux qu''un fort bouclier, mieux qu''une lance puissante, elle combattra pour toi en face de l''ennemi.'),
('si',29,14,'crampon1923','L''homme bon se porte caution pour son prochain, et celui-là seul l''abandonne, qui a perdu toute honte.'),
('si',29,15,'crampon1923','N''oublie pas les bontés de celui qui a répondu, car il s''est engagé pour toi.'),
('si',29,16,'crampon1923','Le pécheur fait perdre ses biens à son répondant, et l''ingrat abandonne son sauveur.'),
('si',29,17,'crampon1923','Une caution a entraîné la perte de beaucoup d''heureux, et les a ballottés comme les vagues de la mer;'),
('si',29,18,'crampon1923','elle a fait bannir des hommes puissants, et ils ont dû errer parmi les nations étrangères.'),
('si',29,19,'crampon1923','Le pécheur est prompt à se rendre caution, et celui qui poursuit le gain éprouvera la rigueur des jugements.'),
('si',29,20,'crampon1923','Assiste ton prochain selon ton pouvoir, et prends garde de tomber toi-même dans le malheur.'),
('si',29,21,'crampon1923','La première chose pour vivre, c''est l''eau et le pain, le vêtement et la maison pour couvrir la nudité.'),
('si',29,22,'crampon1923','Mieux vaut la vie du pauvre sous un toit de planches, que des mets somptueux dans une maison étrangère.'),
('si',29,23,'crampon1923','Que tu aies peu ou beaucoup, sois content, [et tu ne t''entendras pas reprocher d''être un étranger.]'),
('si',29,24,'crampon1923','C''est une triste vie que d''aller de maison en maison; là où l''on est reçu comme étranger, on n''ose pas ouvrir la bouche.'),
('si',29,25,'crampon1923','Tu donneras à ton hôte à manger et à boire sans qu''on t''en sache gré, et tu entendras encore par-dessus des paroles amères:'),
('si',29,26,'crampon1923','« Arrive, étranger, prépare la table, et, si tu as quelque chose, donne-moi à manger.'),
('si',29,27,'crampon1923','Va-t''en, étranger, loin de cette magnificence; j''ai mon frère à recevoir, j''ai besoin de ma maison. »'),
('si',29,28,'crampon1923','Il est dur, pour quelqu''un qui a du sens, de s''entendre reprocher l''hospitalité et d''être injurié par son débiteur.'),
('si',30,1,'crampon1923','Celui qui aime son fils lui fait souvent sentir le fouet, afin d''en avoir ensuite de la joie.'),
('si',30,2,'crampon1923','Celui qui élève bien son fils retirera de lui des avantages, et il se glorifiera de lui devant ses connaissances.'),
('si',30,3,'crampon1923','Celui qui instruit son fils rendra son ennemi jaloux, et il se réjouira de lui devant ses amis.'),
('si',30,4,'crampon1923','Son père vient-il à mourir? C''est comme s''il n''était pas mort, car il laisse après lui quelqu''un qui lui ressemble.'),
('si',30,5,'crampon1923','Pendant sa vie, il le voit et se réjouit, et, à sa mort, il n''est point affligé.'),
('si',30,6,'crampon1923','Il laisse quelqu''un qui le vengera de ses ennemis, et témoignera de la reconnaissance à ses amis.'),
('si',30,7,'crampon1923','Celui qui gâte son fils bandera ses blessures, et, à chacun de ses cris, ses entrailles seront émues.'),
('si',30,8,'crampon1923','Le cheval indompté devient intraitable: ainsi le fils abandonné à lui-même devient inconsidéré.'),
('si',30,9,'crampon1923','Caresse ton enfant, et il te fera trembler, joue avec lui, et il te contristera.'),
('si',30,10,'crampon1923','Ne ris pas avec lui, de peur que tu n''aies à t''affliger avec lui, et qu''à la fin tu ne grinces des dents.'),
('si',30,11,'crampon1923','Ne lui donne pas toute liberté dans sa jeunesse, et ne ferme pas les yeux sur ses folies.'),
('si',30,12,'crampon1923','[Fais plier sa tête pendant sa jeunesse,] et meurtris-lui les flancs pendant qu''il est enfant, de peur qu''il ne devienne opiniâtre et ne t''obéisse plus, [et que tu n''aies la douleur au cœur.]'),
('si',30,13,'crampon1923','Corrige ton fils, et fais-le travailler, de peur qu''il ne trébuche par ta honteuse faiblesse.'),
('si',30,14,'crampon1923','Mieux vaut un pauvre sain et vigoureux, qu''un riche flagellé dans son corps par la maladie.'),
('si',30,15,'crampon1923','La santé et la bonne complexion valent mieux que tout l''or, et un corps vigoureux est préférable à une immense fortune.'),
('si',30,16,'crampon1923','Il n''y a pas de richesse préférable à la santé du corps, et il n''y a pas de joie meilleure que la joie du cœur.'),
('si',30,17,'crampon1923','Mieux vaut la mort qu''une vie d''amertume, et l''éternel repos qu''une souffrance continuelle.'),
('si',30,18,'crampon1923','Des biens répandus sur une bouche fermée sont comme les offrandes d''aliments placés sur une tombe.'),
('si',30,19,'crampon1923','Que sert l''offrande à une idole? Elle ne la mangera pas et n''en sentira pas l''odeur:'),
('si',30,20,'crampon1923','ainsi en est-il de l''homme que Dieu poursuit par la maladie: Il voit de ses yeux, et il soupire, comme soupire un eunuque qui tient une vierge dans ses bras.'),
('si',30,21,'crampon1923','N''abandonne pas ton âme à la tristesse, et ne te tourmente pas par tes réflexions.'),
('si',30,22,'crampon1923','La joie au cœur est la vie de l''homme, et l''allégresse de l''homme est pour lui longueur de jours.'),
('si',30,23,'crampon1923','Aime ton âme et console ton cœur, et chasse loin de toi la tristesse; le chagrin en a tué beaucoup, et il n''y a pas en lui de profit.'),
('si',30,24,'crampon1923','L''emportement et la colère abrègent les jours, et les soucis amènent la vieillesse avant le temps.'),
('si',30,25,'crampon1923','Le cœur généreux et bon prend soin des mets qui forment sa nourriture.'),
('si',31,1,'crampon1923','Les veilles du riche consument les chairs, et les soucis lui enlèvent le sommeil.'),
('si',31,2,'crampon1923','Un souci perpétuel empêche le sommeil, comme une maladie grave le bannit.'),
('si',31,3,'crampon1923','Le riche travaille pour amasser des richesses, et, quand il se repose, il se rassasie de plaisirs.'),
('si',31,4,'crampon1923','Le pauvre travaille, faute d''avoir de quoi vivre, et, quand il se repose, il manque de tout.'),
('si',31,5,'crampon1923','Celui qui aime l''or ne sera pas sans péché, et celui qui poursuit la corruption sera rassasié.'),
('si',31,6,'crampon1923','Beaucoup ont été livrés à la ruine à cause de l''or, et leur perte était devant eux.'),
('si',31,7,'crampon1923','L''or est un bois de scandale pour ceux qui lui sacrifient; tout insensé y sera pris.'),
('si',31,8,'crampon1923','Heureux le riche qui sera trouvé sans tache, et qui n''est pas allé après l''or!'),
('si',31,9,'crampon1923','Qui est-il, pour que nous le proclamions heureux? Car il a fait une chose merveilleuse parmi son peuple.'),
('si',31,10,'crampon1923','Quel est celui qui a été éprouvé à ce sujet et trouvé sans reproche? Que cette épreuve lui soit un sujet de gloire! Qui a pu violer la loi et ne l''a pas violée, faire le mal et ne l''a pas fait?'),
('si',31,11,'crampon1923','Sa fortune sera affermie, et l''assemblée publiera ses bienfaits.'),
('si',31,12,'crampon1923','As-tu pris place à une table bien servie, n''ouvre pas la bouche devant elle, et ne dis pas: « Il y a sur elle bien des mets. »'),
('si',31,13,'crampon1923','Souviens-toi que l''œil envieux est chose mauvaise; rien a-t-il été créé de plus mauvais que l''œil envieux? Aussi pleure-t-il de tout visage.'),
('si',31,14,'crampon1923','Où il regarde, n''étends pas la main, et ne te heurte pas avec lui dans le plat.'),
('si',31,15,'crampon1923','Juge des désirs du prochain d''après toi-même, et agis en toutes choses avec réflexion.'),
('si',31,16,'crampon1923','Mange, comme il convient à un homme, de ce qui est devant toi, et ne mâche pas avec bruit, de peur d''inspirer du dégoût.'),
('si',31,17,'crampon1923','Cesse le premier par bonne éducation, et ne te montre pas insatiable, de peur de scandaliser.'),
('si',31,18,'crampon1923','Si tu es assis en nombreuse compagnie, n''étends pas la main avant les autres.'),
('si',31,19,'crampon1923','Qu''il suffit de peu à un homme bien élevé! Aussi, sur sa couche, il respire librement.'),
('si',31,20,'crampon1923','Le sommeil salutaire est pour l''estomac sobre; on se lève matin et on a l''esprit à soi. Les douleurs de l''insomnie, les vomissements et la colique sont pour l''homme intempérant.'),
('si',31,21,'crampon1923','Si tu as été amené à trop manger, lève-toi, promène-toi au large, et tu seras soulagé.'),
('si',31,22,'crampon1923','Ecoute-moi, mon fils, et ne me méprise pas, et à la fin tu éprouveras la vérité de mes paroles: Dans toutes tes actions, sois diligent, et aucune maladie ne te surviendra.'),
('si',31,23,'crampon1923','Les lèvres bénissent celui qui est libéral en ses repas, et le témoignage rendu à sa générosité est vrai.'),
('si',31,24,'crampon1923','La ville murmure contre celui qui est avare en ses repas, et le témoignage rendu à son avarice est exact.'),
('si',31,25,'crampon1923','Ne fais pas le brave avec le vin, car le vin en a fait périr beaucoup.'),
('si',31,26,'crampon1923','La fournaise éprouve l''acier quand on le trempe; de même le vin éprouve les cœurs quand les orgueilleux se querellent.'),
('si',31,27,'crampon1923','Le vin est comme la vie pour l''homme, si tu le bois dans sa juste mesure. Quelle vie a celui qui manque de vin? Et certes le vin a été fait pour réjouir les hommes.'),
('si',31,28,'crampon1923','Allégresse du cœur et joie de l''âme, tel est le vin pris à temps, dans une juste mesure.'),
('si',31,29,'crampon1923','Amertume de l''âme est le vin bu en abondance, alors qu''on est excité et qu''on se dispute.'),
('si',31,30,'crampon1923','L''ivresse échauffe la fureur de l''insensé et le fait tomber; elle diminue les forces et amène des blessures.'),
('si',31,31,'crampon1923','Dans un festin, ne fais pas de reproches au prochain, et ne le traite avec mépris pendant qu''il est dans la joie; ne lui adresse pas de paroles injurieuses, et ne le presse pas, en lui redemandant quelque chose.'),
('si',32,1,'crampon1923','On t''a établi roi du festin? Ne t''élève pas; sois au milieu des convives comme l''un d''eux. Prends soin d''eux, et ensuite assieds-toi.'),
('si',32,2,'crampon1923','Quand tu auras rempli tous tes devoirs, prends place, afin de te réjouir à cause d''eux, et, pour la belle ordonnance du banquet, recevoir la couronne.'),
('si',32,3,'crampon1923','Parle, vieillard, car cela te convient, mais avec justesse et doctrine, et sans empêcher la musique.'),
('si',32,4,'crampon1923','Lorsqu''on écoute la musique, ne prodigue pas les paroles, et n''étale pas ta sagesse à contre-temps.'),
('si',32,5,'crampon1923','Un sceau d''escarboucle enchâssé dans l''or, tel un concert harmonieux dans un banquet.'),
('si',32,6,'crampon1923','Un sceau d''émeraude dans une garniture d''or, telle une douce mélodie avec un vin agréable.'),
('si',32,7,'crampon1923','Parle, jeune homme, s''il y a utilité pour toi; à peine deux fois, si l''on t''interroge.'),
('si',32,8,'crampon1923','Abrège ton discours, beaucoup de choses en peu de mots; sois comme un homme qui a la science et qui sait se taire.'),
('si',32,9,'crampon1923','Au milieu des grands, ne te fais pas leur égal, et où il y a des vieillards, sois sobre de paroles.'),
('si',32,10,'crampon1923','Avant le tonnerre l''éclair brille: ainsi devant le jeune homme modeste marche la grâce.'),
('si',32,11,'crampon1923','L''heure venue, lève-toi de table sans tarder; cours à ta maison, et ne sois pas insouciant.'),
('si',32,12,'crampon1923','Là divertis-toi, fais tes fantaisies, toutefois sans pécher par des discours insolents.'),
('si',32,13,'crampon1923','Et pour tout cela, bénis Celui qui t''a créé, et qui t''enivre de tous ses biens.'),
('si',32,14,'crampon1923','Celui qui craint le Seigneur reçoit l''instruction, et ceux qui le cherchent avec empressement trouveront sa faveur.'),
('si',32,15,'crampon1923','Celui qui cherche la loi y trouvera son rassasiement; mais pour l''hypocrite, elle sera une occasion de chute.'),
('si',32,16,'crampon1923','Ceux qui craignent le Seigneur trouveront le jugement vrai, et ils feront briller, comme un flambeau, de justes sentences.'),
('si',32,17,'crampon1923','Le pécheur décline la correction, et il trouve des excuses à son gré.'),
('si',32,18,'crampon1923','L''homme intelligent ne méprise aucun avis, mais l''étranger et l''orgueilleux ne sont arrêtés par aucune crainte, et, après avoir agi, ils sont sans réflexion, [et ainsi ils sont convaincus de folie.]'),
('si',32,19,'crampon1923','Ne fais rien sans réflexion, et, après l''action, tu n''auras pas à te repentir.'),
('si',32,20,'crampon1923','Ne va pas sur un chemin dégradé, et tu ne te heurteras pas aux pierres.'),
('si',32,21,'crampon1923','Ne te fie pas à un chemin uni, et sois sur tes gardes vis-à-vis de tes enfants.'),
('si',32,22,'crampon1923','Dans tout ce que tu fais, aie confiance en ton âme, car cela aussi est observation des commandements.'),
('si',32,23,'crampon1923','Celui qui a confiance en la loi est attentif à ses préceptes, et celui qui se confie au Seigneur ne souffrira aucun dommage.'),
('si',32,24,'crampon1923',''),
('si',33,1,'crampon1923','A celui qui craint le Seigneur le malheur ne surviendra pas; mais, s''il est éprouvé, il sera délivré.'),
('si',33,2,'crampon1923','L''homme sage ne hait pas la loi, mais qui est hypocrite envers elle est comme un vaisseau dans la tempête.'),
('si',33,3,'crampon1923','L''homme intelligent a confiance dans la loi, et pour lui la loi est digne de foi comme l''oracle de l''Urim.'),
('si',33,4,'crampon1923','Prépare ton discours, et ainsi tu seras écouté; rassemble ton savoir, et réponds.'),
('si',33,5,'crampon1923','L''intérieur de l''insensé est comme une roue de chariot, et sa pensée comme un essieu qui tourne.'),
('si',33,6,'crampon1923','L''étalon est l''image de l''ami moqueur: il hennit sous tout cavalier.'),
('si',33,7,'crampon1923','Pourquoi un jour l''emporte-t-il sur un autre jour, puisque la lumière de tous les jours de l''année vient du soleil?'),
('si',33,8,'crampon1923','C''est la sagesse du Seigneur qui a établi entre eux des distinctions, il a institué des temps divers et des fêtes.'),
('si',33,9,'crampon1923','Parmi les jours, il y en a qu''il a élevés et sanctifiés, et il y en a qu''il a mis au nombre des jours ordinaires.'),
('si',33,10,'crampon1923','Ainsi tous les hommes viennent de la poussière, de la terre dont Adam a été formé.'),
('si',33,11,'crampon1923','Mais avec une grande sagesse le Seigneur les a distingués, et les a fait marcher dans des voies différentes.'),
('si',33,12,'crampon1923','Il a béni les uns et les a élevés; il a sanctifié les autres et les a approchés de lui. D''autres, il les a maudits et abaissés, et les a précipités de leurs places'),
('si',33,13,'crampon1923','Comme l''argile est dans la main du potier, et qu''il en dispose selon son bon plaisir, ainsi les hommes sont dans la main de Celui qui les a faits, et il leur donne selon son jugement.'),
('si',33,14,'crampon1923','En face du mal est le bien, en face de la mort, la vie: ainsi en face du juste est le pécheur.'),
('si',33,15,'crampon1923','Considère de même toutes les œuvres du Très-Haut: elles sont deux à deux, l''une opposée à l''autre.'),
('si',33,16,'crampon1923','Pour moi, venu le dernier, j''ai consacré mes veilles à la sagesse, semblable à celui qui grappille les raisins après la vendange; par la bénédiction du Seigneur, j''ai pris les devants, et, comme le vendangeur, j''ai rempli le pressoir.'),
('si',33,17,'crampon1923','Reconnaissez que je n''ai pas travaillé pour moi seul, mais pour tous ceux qui recherchent la sagesse.'),
('si',33,18,'crampon1923','Ecoutez-moi donc, chefs du peuple; présidents de l''assemblée, prêtez-moi l''oreille.'),
('si',33,19,'crampon1923','Ni à ton fils ni à ton épouse, ni à ton frère ni à ton ami, ne donne pouvoir sur toi durant ta vie, et ne donne pas tes biens à un autre, de peur que, plein de regret, tu ne doives leur adresser des supplications.'),
('si',33,20,'crampon1923','Tant que tu vis et qu''il te reste un souffle, ne t''aliène toi-même à aucune chair.'),
('si',33,21,'crampon1923','Car il vaut mieux que tes enfants te demandent, que d''avoir toi-même à regarder vers les mains de tes enfants.'),
('si',33,22,'crampon1923','Dans tout ce que tu fais reste le maître, et n''imprime aucune tache à ta renommée.'),
('si',33,23,'crampon1923','Quand viendra la fin des jours de ta vie, et le moment de mourir, distribue ton héritage.'),
('si',33,24,'crampon1923','A l''âne le fourrage, le bâton et la charge; à l''esclave le pain, la correction et le travail.'),
('si',33,25,'crampon1923','Fais travailler ton esclave, et tu seras en repos; laisse-lui les mains libres, et il cherchera la liberté.'),
('si',33,26,'crampon1923','Le joug et la lanière font plier le cou; à l''esclave méchant la torture et la douleur.'),
('si',33,27,'crampon1923','Envoie-le au travail, afin qu''il ne reste pas oisif, car l''oisiveté enseigne beaucoup de mal.'),
('si',33,28,'crampon1923','Mets-le à l''ouvrage, c''est ce qui lui convient; et, s''il n''obéit pas, serre-lui les entraves; mais ne dépasse la mesure envers personne, et ne fais rien de contraire à la justice.'),
('si',33,29,'crampon1923','Si tu as un esclave, qu''il soit comme toi-même, car tu l''as acquis avec du sang.'),
('si',33,30,'crampon1923','Si tu as un esclave, traite-le comme toi-même, et ainsi tu l''attacheras à ton âme.'),
('si',33,31,'crampon1923','Si tu le maltraites et qu''il prenne la fuite, sur quel chemin iras-tu le chercher?'),
('si',33,32,'crampon1923',''),
('si',33,33,'crampon1923',''),
('si',34,1,'crampon1923','L''insensé se livre à des espérances vaines et trompeuses, et les songes donnent des ailes aux sots.'),
('si',34,2,'crampon1923','C''est vouloir saisir une ombre et atteindre le vent, que de s''arrêter à des songes.'),
('si',34,3,'crampon1923','Une chose d''après une autre, voilà ce qu''on voit en songe; c''est comme l''image d''un visage en face d''un visage.'),
('si',34,4,'crampon1923','De l''impureté, que peut-il sortir de pur? Du mensonge, que peut-il sortir de vrai?'),
('si',34,5,'crampon1923','La divination, les augures et les songes sont choses vaines, pareilles aux imaginations du cœur d''une femme enceinte.'),
('si',34,6,'crampon1923','A moins qu''ils ne soient envoyés par le Très-Haut, dans une visite, ne leur abandonne pas ton cœur.'),
('si',34,7,'crampon1923','Car les songes en ont égaré beaucoup, et ceux qui appuyaient sur eux leurs espérances sont tombés.'),
('si',34,8,'crampon1923','Mais la loi s''accomplit sans mensonge, comme se réalise toute sage parole sortie d''une bouche fidèle.'),
('si',34,9,'crampon1923','L''homme instruit sait beaucoup de choses, et l''homme de grande expérience parle sagement.'),
('si',34,10,'crampon1923','Celui qui n''a pas été éprouvé sait peu de choses, et celui qui a voyagé possède une grande prudence.'),
('si',34,11,'crampon1923','J''ai vu beaucoup de choses dans mes voyages, et ma science est plus grande que mes paroles.'),
('si',34,12,'crampon1923','Souvent j''ai été en danger de mort, et j''ai été sauvé grâce à cette expérience.'),
('si',34,13,'crampon1923','L''esprit de ceux qui craignent le Seigneur vivra, car leur espérance est en celui qui les sauve.'),
('si',34,14,'crampon1923','Celui qui craint le Seigneur n''a peur de rien; il ne tremble pas, car Dieu est son espérance.'),
('si',34,15,'crampon1923','Heureuse l''âme de celui qui craint le Seigneur! Sur qui s''appuie-t-elle, et qui est son soutien?'),
('si',34,16,'crampon1923','Les yeux du Seigneur sont sur ceux qui l''aiment; il est un protecteur puissant, un appui plein de force, un abri contre le vent d''Orient, un abri contre les feux du midi, une garde contre l''achoppement, un secours contre la chute;'),
('si',34,17,'crampon1923','il élève l''âme, il illumine les yeux, il donne santé, vie et bénédiction.'),
('si',34,18,'crampon1923','Immoler un bien mal acquis, c''est faire une offrande dérisoire; et les dérisions des pécheurs ne sauraient être agréables à Dieu.'),
('si',34,19,'crampon1923','Le Très-Haut n''agrée pas les offrandes des impies, et ce n''est pas pour les nombreuses victimes qu''il pardonne les péchés.'),
('si',34,20,'crampon1923','Il immole un fils sous les yeux de son père, celui qui offre un sacrifice pris sur le bien des pauvres.'),
('si',34,21,'crampon1923','Le pain des malheureux est la vie des pauvres; celui qui les en prive est un meurtrier.'),
('si',34,22,'crampon1923','Il donne la mort à son prochain, celui qui lui ôte sa subsistance; il verse le sang, celui qui prive le mercenaire de son salaire.'),
('si',34,23,'crampon1923','L''un bâtit et l''autre détruit: qu''en retirent-ils, sinon de la peine?'),
('si',34,24,'crampon1923','L''un prie et l''autre maudit: duquel le Maître écoutera-t-il la voix?'),
('si',34,25,'crampon1923','Celui qui se lave après le contact d''un mort et qui le touche encore, que gagne-t-il à s''être lavé?'),
('si',34,26,'crampon1923','Ainsi en est-il de l''homme qui jeûne pour ses péchés, s''il va les commettre encore: qui entendra sa prière, et que lui servira son humiliation.'),
('si',34,27,'crampon1923',''),
('si',34,28,'crampon1923',''),
('si',34,29,'crampon1923',''),
('si',34,30,'crampon1923',''),
('si',34,31,'crampon1923',''),
('si',35,1,'crampon1923','Qui observe la loi fait de nombreuses offrandes;'),
('si',35,2,'crampon1923','qui s''attache aux préceptes offre un sacrifice pacifique.'),
('si',35,3,'crampon1923','Qui rend grâces fait une offrande de fleur de farine;'),
('si',35,4,'crampon1923','qui pratique la miséricorde offre un sacrifice de louange.'),
('si',35,5,'crampon1923','Ce qui plaît au Seigneur, c''est qu''on s''éloigne du mal; ce qui obtient son pardon, c''est la fuite de l''injustice.'),
('si',35,6,'crampon1923','Pourtant ne te présente pas devant le Seigneur les mains vides,'),
('si',35,7,'crampon1923','car toutes ces offrandes doivent être faites à cause du précepte.'),
('si',35,8,'crampon1923','L''offrande du juste engraisse l''autel, et sa suave odeur s''élève devant le Seigneur.'),
('si',35,9,'crampon1923','Le sacrifice de l''homme juste est agréable, et son souvenir ne sera pas oublié'),
('si',35,10,'crampon1923','Glorifie le Seigneur d''un cœur libéral, et ne retranche rien aux prémices de tes mains.'),
('si',35,11,'crampon1923','Dans toutes tes offrandes, aie le visage joyeux, et consacre ta dîme avec allégresse.'),
('si',35,12,'crampon1923','Donne au Très-Haut selon ce qu''il t''a donné, d''un cœur libéral, selon ce que tes mains ont acquis.'),
('si',35,13,'crampon1923','Car le Seigneur paie de retour, et il te rendra sept fois autant.'),
('si',35,14,'crampon1923','Ne cherche pas à le corrompre par des dons, car il ne les recevrait pas'),
('si',35,15,'crampon1923','et ne t''appuie pas sur une offrande injuste. Car le Seigneur est un juge, et il n''a point égard au rang des personnes.'),
('si',35,16,'crampon1923','Il ne fait acception de personne au détriment du pauvre, et il écoute la prière de l''opprimé.'),
('si',35,17,'crampon1923','Il ne dédaigne pas l''orphelin qui supplie, ni la veuve qui répand sa plainte.'),
('si',35,18,'crampon1923','Les larmes de la veuve ne coulent-elles pas sur ses joues,'),
('si',35,19,'crampon1923','et son cri n''éclate-t-il pas sur celui qui les fait verser?'),
('si',35,20,'crampon1923','Celui qui honore Dieu de la manière qui lui plaît sera bien accueilli, et sa prière monte jusqu''aux nues.'),
('si',35,21,'crampon1923','La prière de l''humble pénétrera les nues; il ne sera pas consolé qu''elle ne soit arrivée jusqu''à Dieu; il ne cessera pas que le Très-Haut ne l''ait regardé, et le Seigneur jugera selon l''équité et rendra justice.'),
('si',35,22,'crampon1923','Le Seigneur ne fera pas attendre, il n''aura plus de patience à l''égard des oppresseurs; jusqu''à ce qu''il ait brisé les reins de ces hommes sans pitié,'),
('si',35,23,'crampon1923','et qu''il ait tiré vengeance des nations; jusqu''à ce qu''il ait anéanti la foule des blasphémateurs, et mis en pièces les sceptres des impies;'),
('si',35,24,'crampon1923','jusqu''à ce qu''il ait rendu à l''homme selon ses actes, et rémunéré les œuvres des hommes selon leurs pensées;'),
('si',35,25,'crampon1923','jusqu''à ce qu''il ait pris en main la cause de son peuple, et qu''il l''ait réjoui par sa miséricorde.'),
('si',35,26,'crampon1923','La miséricorde est belle au temps de l''oppression d''Israël, comme les nuées chargées de pluie au temps de la sécheresse.'),
('si',36,1,'crampon1923','Ayez pitié de nous, Maître, Dieu de l''univers et regardez;'),
('si',36,2,'crampon1923','et répandez votre terreur sur toutes les nations.'),
('si',36,3,'crampon1923','Levez votre main contre les peuples étrangers, et qu''ils sentent votre puissance!'),
('si',36,4,'crampon1923','De même que vous avez montré devant eux votre sainteté en nous punissant, ainsi montrez votre grandeur devant nous en les châtiant;'),
('si',36,5,'crampon1923','et qu''ils apprennent, comme nous l''avons appris nous-mêmes, qu''il n''y a pas d''autre Dieu que vous, Seigneur!'),
('si',36,6,'crampon1923','Renouvelez les prodiges, et reproduisez les merveilles;'),
('si',36,7,'crampon1923','glorifiez votre main et votre bras droit.'),
('si',36,8,'crampon1923','Réveillez votre courroux et répandez votre colère;'),
('si',36,9,'crampon1923','détruisez l''adversaire et anéantissez l''ennemi.'),
('si',36,10,'crampon1923','Hâtez le temps et souvenez-vous du serment; et qu''on célèbre vos hauts faits!'),
('si',36,11,'crampon1923','Que par un feu ardent soit dévoré celui qui serait échappé, et que ceux qui maltraitent votre peuple trouvent leur perte.'),
('si',36,12,'crampon1923','Brisez les têtes des chefs des ennemis, qui disent: « Il n''y a que nous! »'),
('si',36,13,'crampon1923','Rassemblez toutes les tribus de Jacob, et rendez-leur l''héritage tel qu''au commencement.'),
('si',36,14,'crampon1923','Seigneur, ayez pitié de votre peuple, qui est appelé de votre nom, et d''Israël, que vous avez fait semblable à un premier-né.'),
('si',36,15,'crampon1923','Prenez compassion de la ville de votre sanctuaire, de Jérusalem, le lieu de votre repos.'),
('si',36,16,'crampon1923','Remplissez Sion de vos oracles, et votre peuple de votre gloire.'),
('si',36,17,'crampon1923','Rendez témoignage à ceux qui sont vos créatures dès le commencement, et accomplissez les promesses faites en votre nom.'),
('si',36,18,'crampon1923','Récompensez ceux qui espèrent en vous, et que vos prophètes soient trouvés véridiques. Exaucez, Seigneur, la prière de ceux qui vous implorent,'),
('si',36,19,'crampon1923','selon la bénédiction d''Aaron sur votre peuple; et que tous les habitants de la terre reconnaissent que vous êtes le Seigneur, le Dieu des siècles!'),
('si',36,20,'crampon1923','L''estomac reçoit toute espèce de nourriture, mais tel aliment est meilleur qu''un autre.'),
('si',36,21,'crampon1923','Le palais discerne au goût la viande sauvage: ainsi le cœur sensé reconnaît la parole mensongère.'),
('si',36,22,'crampon1923','Le cœur pervers cause du chagrin, mais l''homme d''expérience se met en garde contre lui.'),
('si',36,23,'crampon1923','La femme reçoit toute espèce de mari, mais telle fille est meilleure qu''une autre.'),
('si',36,24,'crampon1923','La beauté de la femme réjouit le visage, et surpasse tout désir de l''homme.'),
('si',36,25,'crampon1923','Si la bonté et la douceur sont sur sa langue, son mari n''est plus un simple enfant des hommes.'),
('si',36,26,'crampon1923','Celui qui acquiert une femme a le principe de sa fortune, une aide semblable à lui et une colonne d''appui.'),
('si',36,27,'crampon1923','Là où il n''y a pas de haie, le domaine est au pillage; là où il n''y a pas de femme, l''homme errant gémit.'),
('si',36,28,'crampon1923','Qui se fie au brigand agile, qui court de ville en ville? Ainsi en est-il de l''homme qui n''a pas de demeure, et qui prend son gîte où la nuit le surprend.'),
('si',36,29,'crampon1923',''),
('si',36,30,'crampon1923',''),
('si',36,31,'crampon1923',''),
('si',37,1,'crampon1923','Tout ami dit: « Moi aussi je suis ton ami; » mais tel ami ne l''est que de nom.'),
('si',37,2,'crampon1923','N''est-ce pas un chagrin jusqu''à la mort, quand un compagnon et un ami se changent en ennemis?'),
('si',37,3,'crampon1923','O pensée perverse, d''où es-tu sortie, pour couvrir la terre de tromperie?'),
('si',37,4,'crampon1923','Le compagnon d''un ami se réjouit de ses joies, et, au jour de l''adversité, il se tourne contre lui!'),
('si',37,5,'crampon1923','Un compagnon partage la peine de son ami dans l''intérêt de son ventre, et, en face du combat, il prend son bouclier!'),
('si',37,6,'crampon1923','N''oublie pas ton ami dans ton cœur, et, au sein de l''opulence, ne perds pas son souvenir.'),
('si',37,7,'crampon1923','Tout conseiller donne des conseils, mais il en est qui conseillent dans leur propre intérêt.'),
('si',37,8,'crampon1923','Vis-à-vis d''un conseiller, tiens-toi sur tes gardes, et cherche d''abord à savoir quel est son intérêt, — car c''est pour lui-même qu''il conseillera, — afin qu''il ne jette pas le sort sur toi,'),
('si',37,9,'crampon1923','et qu''il ne dise pas: « Ta voie est bonne »; puis il se tiendra de l''autre côté pour voir ce qui t''arrivera.'),
('si',37,10,'crampon1923','Ne consulte pas un homme qui te regarde en-dessous, et cache ta résolution à celui qui te jalouse.'),
('si',37,11,'crampon1923','Ne consulte pas une femme sur sa rivale, un lâche sur la guerre, un marchand sur un échange, un acheteur sur une vente, un envieux sur la reconnaissance, un homme sans compassion sur un acte charitable, un paresseux sur un travail quelconque, un mercenaire de la maison sur l''achèvement d''un travail, un esclave paresseux sur une grosse besogne: ne fais fonds sur ces gens pour aucun conseil.'),
('si',37,12,'crampon1923','Mais sois assidu près d''un homme pieux, que tu connais comme observateur des commandements, dont le cœur est selon ton cœur, et qui, si tu tombes, souffrira avec toi.'),
('si',37,13,'crampon1923','Ensuite tiens-toi à ce que ton cœur te conseille, car personne ne t''est plus fidèle que lui.'),
('si',37,14,'crampon1923','Car l''âme de l''homme annonce parfois plus de choses que sept sentinelles postées sur une hauteur pour observer.'),
('si',37,15,'crampon1923','Et avec tout cela prie le Très-Haut, afin qu''il dirige sûrement ta voie.'),
('si',37,16,'crampon1923','Avant toute œuvre est la parole: avant toute entreprise, la réflexion.'),
('si',37,17,'crampon1923','Comme trace du changement du cœur apparaissent quatre choses:'),
('si',37,18,'crampon1923','le bien et le mal, la vie et la mort; et la langue est toujours leur maîtresse.'),
('si',37,19,'crampon1923','Tel homme est prudent et le docteur d''un grand nombre, mais il est inutile à lui-même.'),
('si',37,20,'crampon1923','Celui qui affecte la sagesse dans ses paroles est odieux; il finira par manquer de toute nourriture.'),
('si',37,21,'crampon1923','Car le Seigneur ne lui a pas donné sa faveur, parce qu''il est dépourvu de toute sagesse.'),
('si',37,22,'crampon1923','Tel sage est sage pour lui-même, et les fruits de son savoir sont assurés sur ses lèvres.'),
('si',37,23,'crampon1923','L''homme sage instruit son peuple, et les fruits de son savoir sont assurés.'),
('si',37,24,'crampon1923','L''homme sage est comblé de bénédictions, et tous ceux qui le voient le proclament heureux.'),
('si',37,25,'crampon1923','La vie de l''homme est d''un nombre restreint de jours, mais les jours d''Israël sont sans nombre.'),
('si',37,26,'crampon1923','Le sage obtient la confiance au milieu de son peuple, et son nom vivra à jamais.'),
('si',37,27,'crampon1923','Mon fils, pour ta manière de vivre, consulte ton âme; vois ce qui lui est nuisible et ne le lui donne pas.'),
('si',37,28,'crampon1923','Car tout n''est pas bon pour tous, et chacun ne trouve pas son bien-être en tout.'),
('si',37,29,'crampon1923','Ne sois pas insatiable devant toute friandise, et ne te jette pas avidement sur les mets;'),
('si',37,30,'crampon1923','car l''excès de la nourriture amène des incommodités, et l''intempérance conduit jusqu''à la colique.'),
('si',37,31,'crampon1923','A cause de l''intempérance beaucoup sont morts, mais celui qui s''abstient prolonge sa vie.'),
('si',38,1,'crampon1923','Rends au médecin pour tes besoins les honneurs qui lui sont dus; car, lui aussi, c''est le Seigneur qui l''a créé.'),
('si',38,2,'crampon1923','C''est du Très-Haut, en effet, que vient la guérison, et du roi lui-même il reçoit des présents.'),
('si',38,3,'crampon1923','La science du médecin élève sa tête, et il est admiré en présence des grands.'),
('si',38,4,'crampon1923','Le Seigneur fait produire à la terre ses médicaments, et l''homme sensé ne les dédaigne pas.'),
('si',38,5,'crampon1923','Un bois n''a-t-il pas adouci l''eau amère, afin que sa vertu fût connue de tous?'),
('si',38,6,'crampon1923','Il a donné aux hommes la science, pour se glorifier par ses dons merveilleux.'),
('si',38,7,'crampon1923','Par eux l''homme procure la guérison, et enlève la douleur.'),
('si',38,8,'crampon1923','Le pharmacien en fait des mixtions, et son œuvre est à peine achevée que par lui le bien-être se répand sur la face de la terre.'),
('si',38,9,'crampon1923','Mon fils, si tu es malade, ne néglige pas mon conseil, mais prie le Seigneur, et il te guérira.'),
('si',38,10,'crampon1923','Eloigne la transgression, redresse tes mains, et purifie ton cœur de tout péché.'),
('si',38,11,'crampon1923','Offre l''encens et l''oblation de farine, et immole de grasses victimes, comme si c''en était fait de toi.'),
('si',38,12,'crampon1923','Puis donne accès au médecin, car, lui aussi, le Seigneur l''a créé, et qu''il ne s''éloigne pas de toi, car tu as besoin de lui.'),
('si',38,13,'crampon1923','Il arrive que leurs mains ont du succès,'),
('si',38,14,'crampon1923','car eux aussi prieront le Seigneur, afin qu''il leur accorde de procurer le repos et la guérison, pour prolonger la vie du malade.'),
('si',38,15,'crampon1923','Que celui qui pèche devant son Créateur tombe entre les mains du médecin!'),
('si',38,16,'crampon1923','Mon fils, répands des pleurs sur un mort, et, comme si tu souffrais cruellement, commence la lamentation. Puis donne à son corps les soins qui lui sont dus, et ne néglige pas sa sépulture.'),
('si',38,17,'crampon1923','Verse des larmes amères, exhale des soupirs brûlants, et fais le deuil, selon qu''il en est digne, un jour ou deux, pour éviter les mauvais propos. Ensuite console-toi, pour éloigner la tristesse;'),
('si',38,18,'crampon1923','car de la tristesse peut venir la mort, et le chagrin du cœur abat toute vigueur.'),
('si',38,19,'crampon1923','Quand on emmène un mort, le chagrin doit passer avec lui, comme la vie du pauvre est contre son cœur.'),
('si',38,20,'crampon1923','N''abandonne pas ton cœur à la tristesse; chasse-la, te souvenant de ta fin.'),
('si',38,21,'crampon1923','Ne l''oublie pas: il n''y a point de retour; tu ne seras pas utile au mort, et tu feras du mal à toi-même.'),
('si',38,22,'crampon1923','Souviens-toi qu''à l''arrêt porté sur lui, le tien sera pareil: « Pour moi hier, pour toi aujourd''hui. »'),
('si',38,23,'crampon1923','Quand le mort repose, laisse reposer sa mémoire, et console-toi à son sujet, au départ de son esprit.'),
('si',38,24,'crampon1923','La sagesse du scribe s''acquiert à la faveur du loisir, et celui qui n''a pas à s''occuper d''affaires deviendra sage.'),
('si',38,25,'crampon1923','Comment deviendrait-il sage celui qui gouverne la charrue, dont l''ambition est de manier, en guise de lance, l''aiguillon; qui pousse ses bœufs et se mêle à leurs travaux, et ne sait discourir que des petits des taureaux?'),
('si',38,26,'crampon1923','Il met tout son cœur à tracer des sillons, un soin vigilant à procurer le fourrage à ses génisses.'),
('si',38,27,'crampon1923','Il en est de même de tout charpentier et constructeur, qui poursuivent leurs occupations la nuit comme le jour; de celui qui grave les empreintes des cachets: son application est de varier les figures; il met son cœur à reproduire le dessin, un soin vigilant à parfaire son ouvrage.'),
('si',38,28,'crampon1923','Tel est le forgeron assis près de son enclume, et considérant le fer encore brut; la vapeur du feu fait fondre ses chairs, et il tient bon contre la chaleur de la fournaise; le bruit du marteau assourdit son oreille, et son œil est fixé sur le modèle de l''ustensile. Il met son cœur à parfaire son œuvre, un soin vigilant à la polir dans la perfection.'),
('si',38,29,'crampon1923','Tel encore le potier assis à son ouvrage, et tournant la roue avec ses pieds: constamment il est en souci de son travail, et tous ses efforts tendent à fournir un certain nombre de vases.'),
('si',38,30,'crampon1923','Avec son bras il façonne l''argile, et devant ses pieds il la rend flexible; il met son cœur à parfaire le vernis, un soin vigilant à nettoyer son four.'),
('si',38,31,'crampon1923','Ces sortes de gens attendent tout de leurs mains, et chacun d''eux est intelligent dans son métier.'),
('si',38,32,'crampon1923','Sans eux on ne bâtirait aucune ville, on n''irait pas à l''étranger, on ne voyagerait pas.'),
('si',38,33,'crampon1923','Mais ils ne seront pas recherchés dans le conseil du peuple, et ils ne se distingueront pas dans l''assemblée; ils n''auront pas la science de l''alliance du droit; ils ne prendront point place sur le siège du juge; ils n''interpréteront pas la justice et le droit, et on ne les trouvera pas pour énoncer des sentences.'),
('si',38,34,'crampon1923','Cependant ils soutiennent les choses du temps, et leur prière se rapporte aux travaux de leur métier.'),
('si',39,1,'crampon1923','Il en est autrement de celui qui applique son esprit, et qui médite sur la loi du Très-Haut! Il cherche la sagesse de tous les anciens, et il consacre ses loisirs aux prophéties.'),
('si',39,2,'crampon1923','Il garde dans sa mémoire les récits des hommes célèbres, et il pénètre dans les détours des sentences.'),
('si',39,3,'crampon1923','Il cherche le sens caché des proverbes, et il s''occupe des sentences énigmatiques.'),
('si',39,4,'crampon1923','Il sert au milieu des grands, et il paraît devant le prince. Il voyage dans le pays des peuples étrangers, car il veut connaître le bien et le mal parmi les hommes.'),
('si',39,5,'crampon1923','Il met son cœur à aller dès le matin auprès du Seigneur qui l''a fait: il prie en présence du Très-Haut, il ouvre sa bouche pour la prière et il demande pardon pour ses péchés.'),
('si',39,6,'crampon1923','Si c''est la volonté du Seigneur, qui est grand, il sera rempli de l''esprit d''intelligence; alors il répandra à flots les paroles de la sagesse, et, dans sa prière, il rendra grâces au Seigneur.'),
('si',39,7,'crampon1923','Il saura diriger sa prudence et son savoir, et il étudiera les mystères divins.'),
('si',39,8,'crampon1923','Il publiera la doctrine de son enseignement, et il se glorifiera de la loi de l''alliance du Seigneur.'),
('si',39,9,'crampon1923','Beaucoup loueront son intelligence, et il ne sera jamais oublié; sa mémoire ne passera pas, et son nom vivra d''âge en âge.'),
('si',39,10,'crampon1923','Les peuples raconteront sa sagesse, et l''assemblée célébrera ses louanges.'),
('si',39,11,'crampon1923','Tant qu''il est en vie, son nom reste plus illustre que mille autres; et, quand il se reposera, sa gloire grandira encore.'),
('si',39,12,'crampon1923','Je veux encore publier le fruit de mes réflexions, car je suis rempli, comme la lune dans son plein.'),
('si',39,13,'crampon1923','Ecoutez-moi, fils pieux, et croissez, comme la rose sur le bord d''une eau courante:'),
('si',39,14,'crampon1923','répandez, comme l''encens, votre suave odeur; faites éclore votre fleur, comme le lis; exhalez votre parfum et chantez un cantique, célébrez le Seigneur pour toutes ses œuvres.'),
('si',39,15,'crampon1923','Rendez gloire à son nom, proclamez sa louange, dans les chants de vos lèvres et sur vos harpes, et, en le célébrant, vous direz:'),
('si',39,16,'crampon1923','Toutes les œuvres du Seigneur sont très bonnes, et tout ce qu''il a ordonné s''accomplira en son temps.'),
('si',39,17,'crampon1923','On ne doit pas dire: « Qu''est-ce que cela? A quoi sert-il? » car toute chose sera recherchée en son temps. A sa parole, l''eau se rassembla comme un monceau, et, sur une parole de sa bouche, il y eut des réservoirs d''eau.'),
('si',39,18,'crampon1923','Par son commandement, ce qui lui plaît arrive, et nul ne peut arrêter le salut qu''il envoie.'),
('si',39,19,'crampon1923','Les œuvres de toute chair sont devant lui, et l''on ne peut se cacher à ses yeux.'),
('si',39,20,'crampon1923','Son regard atteint de l''éternité à l''éternité, et il n''y a rien d''étonnant devant lui.'),
('si',39,21,'crampon1923','On ne doit pas dire: « Qu''est-ce que cela? A quoi sert-il? » car toute chose a été créée pour son usage.'),
('si',39,22,'crampon1923','La bénédiction du Seigneur déborde comme un fleuve, et, comme un déluge, elle arrose la terre.'),
('si',39,23,'crampon1923','De même il donne sa colère en partage aux nations, comme il a changé un pays bien arrosé en une contrée de sel.'),
('si',39,24,'crampon1923','Ses voies sont droites pour les hommes saints, et de même elles sont pour les impies des occasions de chute.'),
('si',39,25,'crampon1923','Les biens ont été créés pour les bons dès l''origine, et, de même, les maux pour les méchants.'),
('si',39,26,'crampon1923','Ce qui est de première nécessité pour la vie de l''homme, c''est l''eau, le feu, le fer et le sel, la farine de froment, le miel et le lait, le sang de la grappe, l''huile et le vêtement.'),
('si',39,27,'crampon1923','Toutes ces choses sont des biens pour les hommes pieux, mais se changent en maux pour les pécheurs.'),
('si',39,28,'crampon1923','Il y a des vents qui ont été créés pour la vengeance, et, dans leur fureur, ils déchaînent leurs fléaux. Au jour de la destruction, ils déploieront leur puissance, et apaiseront le courroux de Celui qui les a faits.'),
('si',39,29,'crampon1923','Feu et grêle, famine et peste, toutes ces choses ont été créées pour le châtiment;'),
('si',39,30,'crampon1923','ainsi que la dent des bêtes féroces, les scorpions et les vipères, et le glaive exterminateur funeste aux impies.'),
('si',39,31,'crampon1923','Ces créatures se réjouissent du commandement du Seigneur, elles se tiennent prêtes sur la terre pour le besoin, et, aux temps marqués, elles ne désobéissent pas à ses ordres.'),
('si',39,32,'crampon1923','C''est pourquoi j''ai été dès le début ferme dans mes pensées, et, après avoir médité, je les ai mises par écrit:'),
('si',39,33,'crampon1923','Toutes les œuvres du Seigneur sont bonnes, et il pourvoit à tout besoin en son temps.'),
('si',39,34,'crampon1923','Il n''y a pas lieu de dire: « Ceci est plus mauvais que cela, » car toute chose en son temps sera reconnue bonne.'),
('si',39,35,'crampon1923','Et maintenant chantez de tout cœur et de bouche, et bénissez le nom du Seigneur.'),
('si',40,1,'crampon1923','A tout homme a été imposée une grande misère, et un joug pesant est sur les enfants des hommes, depuis le jour où ils sortent du sein de leur mère, jusqu''au jour de leur sépulture dans le sein de la mère commune.'),
('si',40,2,'crampon1923','Ce qui trouble leurs pensées et fait craindre leurs cœurs, c''est la pensée de leur attente, c''est la crainte de la mort.'),
('si',40,3,'crampon1923','Depuis l''homme qui siège sur un trône, dans la gloire, jusqu''au malheureux assis par terre et sur la cendre;'),
('si',40,4,'crampon1923','depuis celui qui porte la pourpre et la couronne, jusqu''au misérable, couvert d''une toile grossière,'),
('si',40,5,'crampon1923','la colère, l''envie, le trouble, l''agitation, la crainte de la mort, l''aigreur et les querelles sont le partage de tous; et, dans le temps où chacun repose sur sa couche, le sommeil de la nuit bouleverse ses idées.'),
('si',40,6,'crampon1923','Il repose un instant, si peu que rien, et aussitôt des rêves l''agitent; il lui semble être en sentinelle pendant le jour, il est effrayé par la vision de son esprit, comme un homme qui fuit devant le combat.'),
('si',40,7,'crampon1923','Au moment de la délivrance, il s''éveille, et s''étonne de sa vaine frayeur.'),
('si',40,8,'crampon1923','Ainsi en est-il de toute chair, depuis l''homme jusqu''à la bête, et pour les pécheurs, sept fois plus encore.'),
('si',40,9,'crampon1923','La peste, le meurtre, la discorde, l''épée, [les calamités, la famine, la destruction et les autres fléaux]:'),
('si',40,10,'crampon1923','tout cela a été créé contre les pécheurs, comme c''est à cause d''eux que le déluge est arrivé.'),
('si',40,11,'crampon1923','Tout ce qui vient de la terre retourne à la terre, comme ce qui vient des eaux descend à la mer.'),
('si',40,12,'crampon1923','Tout présent et tout bien injustement acquis périront, mais la bonne foi subsistera à jamais.'),
('si',40,13,'crampon1923','Les richesses des injustes tariront comme un torrent, et comme un fort tonnerre retentit pendant l''ondée.'),
('si',40,14,'crampon1923','L''homme qui sait ouvrir la main se réjouira, mais les prévaricateurs subiront une ruine totale.'),
('si',40,15,'crampon1923','La postérité des impies ne pousse pas de nombreux rameaux, et les racines impures sont sur le rocher escarpé.'),
('si',40,16,'crampon1923','Le roseau qui croît près des eaux et sur le bord d''un fleuve est arraché avant toute autre herbe.'),
('si',40,17,'crampon1923','La bienveillance est comme un jardin béni, et la bienfaisance demeure à jamais.'),
('si',40,18,'crampon1923','Douce est la vie de l''homme qui se suffit et de l''ouvrier; plus que les deux, la vie de celui qui trouve un trésor:'),
('si',40,19,'crampon1923','Des enfants et la fondation d''une ville perpétuent un nom: plus que les deux, on estime une femme irréprochable.'),
('si',40,20,'crampon1923','Le vin et la musique réjouissent le cœur: plus que l''un et l''autre, l''amour de la sagesse.'),
('si',40,21,'crampon1923','La flûte et la harpe font entendre de doux sons: plus que les deux, une langue bienveillante.'),
('si',40,22,'crampon1923','La grâce et la beauté font le plaisir de tes yeux: plus que les deux, la verdure des champs.'),
('si',40,23,'crampon1923','L''ami et le compagnon se rencontrent à certaines heures: plus que les deux, la femme avec son mari.'),
('si',40,24,'crampon1923','Les frères et les secours sont pour le temps de l''affliction: plus que les deux, la bienfaisance délivre.'),
('si',40,25,'crampon1923','L''or et l''argent affermissent les pieds: plus que les deux, est estimée la prudence.'),
('si',40,26,'crampon1923','La richesse et la force élèvent le cœur: plus que les deux, la crainte du Seigneur. Avec la crainte du Seigneur, on ne manque de rien; avec elle, il n''y a pas à implorer du secours.'),
('si',40,27,'crampon1923','La crainte du Seigneur est comme un jardin béni, et le Seigneur la revêt d''une gloire sans égale.'),
('si',40,28,'crampon1923','Mon fils, puisses-tu ne pas mener une vie de mendicité; mieux vaut mourir que de mendier.'),
('si',40,29,'crampon1923','Quand un homme en est réduit à regarder vers la table d''un autre, sa vie ne saurait compter pour une vie. Car il souille son âme par des mets étrangers, ce dont se gardera l''homme instruit et bien élevé.'),
('si',40,30,'crampon1923','Dans la bouche de l''homme sans pudeur la mendicité est douce; mais, dans ses entrailles, elle brûle comme un feu.'),
('si',41,1,'crampon1923','O mort, que ton souvenir est amer à l''homme qui vit en paix au sein de ses richesses, à l''homme exempt de soucis et qui prospère en tout, et qui est encore en état de goûter le plaisir de la table!'),
('si',41,2,'crampon1923','O mort, ton arrêt est agréable, à l''indigent, à celui dont les forces sont épuisées, au vieillard accablé d''années et travaillé de mille soins, à celui qui ne se soumet pas à son sort et qui a perdu l''espérance.'),
('si',41,3,'crampon1923','Ne redoute point l''arrêt de la mort: souviens-toi de ceux qui t''ont précédé et de ceux qui viendront plus tard.'),
('si',41,4,'crampon1923','C''est l''arrêt porté par le Seigneur sur toute chair; et pourquoi te révolter contre le bon plaisir du Très-Haut? Que tu aies vécu dix ans, cent, mille: dans le schéol on n''est plus en peine de la durée de la vie.'),
('si',41,5,'crampon1923','Ce sont des fils abominables que les fils des pécheurs, eux qui fréquentent les demeures des impies.'),
('si',41,6,'crampon1923','L''héritage des enfants des pécheurs va à la ruine, et l''opprobre s''attache à leur postérité.'),
('si',41,7,'crampon1923','Les enfants d''un père impie lui jettent l''outrage, parce que c''est à cause de lui qu''ils sont dans l''opprobre.'),
('si',41,8,'crampon1923','Malheur à vous, hommes impies, qui avez abandonné la loi du Dieu très haut!'),
('si',41,9,'crampon1923','Si vous naissez, vous naissez pour la malédiction, et si vous mourez, la malédiction sera votre partage.'),
('si',41,10,'crampon1923','Tout ce qui est de la terre retourne à la terre: ainsi les impies vont de la malédiction à la ruine.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('si',41,11,'crampon1923','Les hommes s''attristent pour leur corps, mais le nom odieux des pécheurs sera anéanti.'),
('si',41,12,'crampon1923','Prends soin de ton nom car il te demeurera, plus longtemps que mille grands trésors d''or.'),
('si',41,13,'crampon1923','On compte les jours d''une bonne vie, mais un beau nom demeure à jamais.'),
('si',41,14,'crampon1923','Mes enfants, observez en paix mes instructions: Sagesse cachée et trésor invisible, à quoi servent-ils l''un et l''autre?'),
('si',41,15,'crampon1923','Mieux vaut l''homme qui cache sa sottise, que l''homme qui cache sa sagesse.'),
('si',41,16,'crampon1923','Donc ayez honte des choses que je vais vous dire. Car toute honte n''est pas bonne à garder, et toutes choses ne sont pas jugées par tous selon la vérité.'),
('si',41,17,'crampon1923','Ayez honte de la fornication, devant votre père et votre mère, et du mensonge, devant le prince et le puissant;'),
('si',41,18,'crampon1923','du délit, devant le juge et le magistrat, de la transgression de la loi, devant l''assemblée et le peuple; de l''injustice, devant le compagnon et l''ami,'),
('si',41,19,'crampon1923','du vol, devant les gens du voisinage. Au nom de la vérité de Dieu et de son alliance, aie honte d''appuyer ton coude sur les pains; de t''attirer le mépris en prenant et en donnant,'),
('si',41,20,'crampon1923','et de garder le silence devant ceux qui te saluent; de regarder une femme débauchée,'),
('si',41,21,'crampon1923','et de détourner le visage d''un parent; de lui prendre sa part et son don, et d''observer une femme mariée;'),
('si',41,22,'crampon1923','d''avoir des familiarités avec ta servante, et ne te tiens pas près de son lit; aie honte des paroles offensantes devant tes amis, et ne reproche pas après avoir donné.'),
('si',41,23,'crampon1923',''),
('si',41,24,'crampon1923',''),
('si',41,25,'crampon1923',''),
('si',41,26,'crampon1923',''),
('si',41,27,'crampon1923',''),
('si',42,1,'crampon1923','Aie honte de répéter ce que tu as entendu, et de révéler des choses secrètes. Ainsi tu auras la vraie honte, et tu trouveras faveur devant tous les hommes. Ne rougis pas de ces choses-ci, et n''aie pas égard aux personnes pour commettre le péché:'),
('si',42,2,'crampon1923','de la loi du Très-Haut et de son alliance, de la sentence qui justifie l''impie,'),
('si',42,3,'crampon1923','de t''entretenir avec des compagnons et des passants, de donner quelque bien à tes amis,'),
('si',42,4,'crampon1923','d''user de balances justes et de justes poids, d''acquérir beaucoup ou peu,'),
('si',42,5,'crampon1923','de ne pas faire de différence dans la vente et avec les marchands, de corriger sévèrement tes enfants, et de frapper jusqu''au sang le dos d''un méchant esclave.'),
('si',42,6,'crampon1923','Avec une méchante femme, le sceau est bon; et là où il y a beaucoup de mains, mets sous clef.'),
('si',42,7,'crampon1923','Ce que tu livres à tes gens, compte-le et pèse-le, et mets par écrit ce que tu donnes et ce que tu reçois.'),
('si',42,8,'crampon1923','Ne rougis pas de réprimander l''insensé et le sot, et le vieillard qui dispute avec des jeunes gens. Et ainsi tu seras véritablement instruit, et approuvé de tout le monde.'),
('si',42,9,'crampon1923','Une fille est pour son père un secret souci; l''inquiétude qu''elle lui donne lui ôte le sommeil: jeune fille, elle passera peut-être la fleur de l''âge; unie à un mari, elle lui deviendra peut-être odieuse;'),
('si',42,10,'crampon1923','vierge, elle pourrait se laisser séduire, et devenir enceinte dans la maison paternelle; avec un mari, peut-être sera-t-elle infidèle, et, habitant avec lui, peut-être restera-t-elle stérile.'),
('si',42,11,'crampon1923','A l''égard d''une fille opiniâtre, exerce une sévère vigilance de peur qu''elle ne fasse de toi la risée de tes ennemis, la fable de la ville et l''objet des propos publics, et ne te déshonore au milieu de tout le peuple.'),
('si',42,12,'crampon1923','Ne regarde pas à la beauté de tout homme, et ne t''assieds pas au milieu des femmes;'),
('si',42,13,'crampon1923','car des vêtements sort la teigne, et de la femme la malice féminine.'),
('si',42,14,'crampon1923','Un homme méchant vaut mieux qu''une femme caressante, car la femme couvre d''opprobre et de honte.'),
('si',42,15,'crampon1923','Je vais rappeler les œuvres du Seigneur, et publier ce que j''ai vu. C''est par la parole du Seigneur que ses œuvres ont été faites.'),
('si',42,16,'crampon1923','Le soleil qui les éclaire les contemple toutes; ouvrage du Seigneur, il est rempli de sa gloire.'),
('si',42,17,'crampon1923','Le Seigneur n''a pas rendu ses saints capables d''annoncer toutes ses merveilles, que le Seigneur tout-puissant a solidement établies, pour que tout l''univers soit affermi par sa gloire.'),
('si',42,18,'crampon1923','Il sonde les profondeurs de l''océan et le cœur des hommes, et il connaît leurs desseins les plus subtils. Car le Seigneur possède toute science, et il voit les signes du temps.'),
('si',42,19,'crampon1923','Il annonce le passé et l''avenir, et il dévoile les traces des choses cachées.'),
('si',42,20,'crampon1923','Aucune pensée ne lui échappe, aucune parole n''est cachée pour lui.'),
('si',42,21,'crampon1923','Il a orné les grandes œuvres de sa sagesse; il est avant tous les siècles, et il subsistera à jamais; rien n''a été ajouté à son être, et il n''en a été rien ôté; et il n''a eu besoin d''aucun conseiller.'),
('si',42,22,'crampon1923','Comme toutes ses œuvres sont belles! Et ce qu''on en contemple n''est qu''une étincelle.'),
('si',42,23,'crampon1923','Tout est vivant et demeure à jamais, pour tous les usages, et tout obéit au Créateur.'),
('si',42,24,'crampon1923','Tout est par couple, un individu en face d''un autre, et il n''a rien fait qui aille à la ruine.'),
('si',42,25,'crampon1923','L''un assure le bonheur de l''autre: qui pourra se rassasier de voir la gloire du Seigneur?'),
('si',43,1,'crampon1923','L''orgueil des hauteurs, c''est le firmament dans son pur éclat; et l''aspect du ciel est une vision de gloire.'),
('si',43,2,'crampon1923','Le soleil, quand il se montre, glorifie le Seigneur, à son lever; c''est une merveilleuse créature, l''œuvre du Très-Haut.'),
('si',43,3,'crampon1923','A son midi, il dessèche la terre; qui peut tenir devant ses ardeurs?'),
('si',43,4,'crampon1923','Pour ses travaux, l''artisan active le feu de la fournaise: trois fois plus le soleil échauffe les montagnes. Il embrase les vapeurs de l''air, et, quand il fait resplendir ses rayons, il éblouit les yeux.'),
('si',43,5,'crampon1923','Grand est le Seigneur qui l''a fait, et, sur son ordre, il précipite sa course.'),
('si',43,6,'crampon1923','La lune aussi est toujours fidèle, à l''heure qui lui est assignée; elle indique les temps de l''année, et annonce l''avenir.'),
('si',43,7,'crampon1923','De la lune vient le signal des fêtes; sa lumière diminue quand elle est arrivée à son plein.'),
('si',43,8,'crampon1923','C''est d''elle que le mois prend son nom; elle croît merveilleusement dans ses diverses phases. C''est la tente d''un camp dans les hauteurs des cieux; elle brille au firmament du ciel.'),
('si',43,9,'crampon1923','La beauté du ciel, c''est l''éclat des étoiles, parure éclatante dans les hauteurs du Seigneur.'),
('si',43,10,'crampon1923','Selon l''ordre du Saint, elles se tiennent à la place assignée, et ne se fatiguent pas dans leurs veilles.'),
('si',43,11,'crampon1923','Vois l''arc-en-ciel et bénis Celui qui l''a fait; il est bien beau dans sa splendeur!'),
('si',43,12,'crampon1923','Il embrasse le ciel dans son cercle radieux; ce sont les mains du Très-Haut qui le tendent.'),
('si',43,13,'crampon1923','Par son ordre, la neige se précipite, et les éclairs se pressent, exécuteurs de ses jugements.'),
('si',43,14,'crampon1923','C''est pourquoi ses trésors s''ouvrent, et les nuées volent comme des oiseaux.'),
('si',43,15,'crampon1923','Par sa puissance, il donne la force aux nuées, et la grêle tombe comme des éclats de pierre.'),
('si',43,16,'crampon1923','La voix de son tonnerre fait trembler la terre, et, quand il se montre, les montagnes chancellent.'),
('si',43,17,'crampon1923','A sa volonté, le vent du midi souffle, l''aquilon se déchaîne et le tourbillon fait rage. Il répand la neige comme des oiseaux qui s''abattent; elle descend comme la sauterelle qui fait halte.'),
('si',43,18,'crampon1923','L''œil admire la beauté de sa blancheur, et le cœur est émerveillé de sa chute.'),
('si',43,19,'crampon1923','Il verse le givre sur la terre comme du sel, et la gelée le durcit en pointes d''épines.'),
('si',43,20,'crampon1923','Le vent froid du nord se met à souffler, et l''eau se durcit en glace; cette glace s''étend immobile sur tout amas d''eau, et revêt l''eau comme d''une cuirasse.'),
('si',43,21,'crampon1923','Le Seigneur dévore les montagnes et embrase le désert, il brûle la verdure comme le feu.'),
('si',43,22,'crampon1923','De tous ces maux le remède est un nuage qui arrive rapidement; une rosée qui survient console de la chaleur brûlante.'),
('si',43,23,'crampon1923','Selon son dessein, il a dompté l''abîme, et il y a planté des îles.'),
('si',43,24,'crampon1923','Ceux qui naviguent sur la mer en racontent les périls, et, en entendant leurs récits, nous sommes étonnés.'),
('si',43,25,'crampon1923','Là sont des créatures étranges et merveilleuses, des animaux de toutes sortes et la race des monstres marins.'),
('si',43,26,'crampon1923','Par le Seigneur, toute chose marche heureusement à sa fin, et tout subsiste par sa parole.'),
('si',43,27,'crampon1923','Nous pourrions dire beaucoup, et nous ne l''atteindrions pas; Le résumé de notre discours: Il est le tout.'),
('si',43,28,'crampon1923','Voulant le louer, où en trouverions-nous la force? Il est le Tout-Puissant, supérieur à toutes ses œuvres.'),
('si',43,29,'crampon1923','Le Seigneur est terrible et souverainement grand, et merveilleuse est sa puissance.'),
('si',43,30,'crampon1923','En louant le Seigneur, exaltez-le tant que vous pourrez, car il sera toujours plus haut encore. Pour l''exalter, rassemblez toutes vos forces; ne vous lassez pas, car vous ne pourrez l''atteindre.'),
('si',43,31,'crampon1923','Qui l''a vu et pourrait en discourir? Qui est capable de le louer tel qu''il est?'),
('si',43,32,'crampon1923','Beaucoup de merveilles cachées sont plus grandes encore, car nous ne voyons qu''un petit nombre de ses œuvres.'),
('si',43,33,'crampon1923','Le Seigneur a tout fait, et il donne la sagesse aux hommes pieux.'),
('si',43,34,'crampon1923',''),
('si',43,35,'crampon1923',''),
('si',44,1,'crampon1923','Faisons donc l''éloge des hommes illustres, et des pères de notre race.'),
('si',44,2,'crampon1923','En eux le Seigneur a opéré de glorieuses merveilles, il a manifesté sa grandeur dès l''origine.'),
('si',44,3,'crampon1923','C''étaient des souverains dans leurs royaumes, des hommes renommés par leur puissance, des conseillers remplis de sagesse, annonçant la volonté divine par leurs prophéties,'),
('si',44,4,'crampon1923','des guides du peuple par leurs conseils et leur prudence, des docteurs du peuple, qui l''instruisaient par de sages discours;'),
('si',44,5,'crampon1923','des hommes cultivant l''art des saintes mélodies, et qui ont mis par écrit de poétiques récits;'),
('si',44,6,'crampon1923','des riches ayant des biens en abondance, vivant en paix dans leurs demeures: tous ces hommes furent honorés par leurs contemporains,'),
('si',44,7,'crampon1923','tous ont été la gloire de leur temps.'),
('si',44,8,'crampon1923','Il en est parmi eux qui ont laissé un nom, pour qu''on puisse raconter leurs louanges.'),
('si',44,9,'crampon1923','Il en est dont il n''y a plus de souvenir, ils ont péri comme s''ils n''avaient jamais existé; ils sont devenus comme s''ils n''étaient jamais nés, et, de même, leurs enfants après eux.'),
('si',44,10,'crampon1923','Les premiers étaient des hommes pieux, dont les vertus n''ont pas été oubliées.'),
('si',44,11,'crampon1923','Le bonheur reste attaché à leur race, et un héritage est assuré à leurs enfants.'),
('si',44,12,'crampon1923','Leur race se maintient fidèle aux alliances, et leurs enfants à cause d''eux.'),
('si',44,13,'crampon1923','Leur race demeure éternellement, et leur gloire ne sera jamais effacée.'),
('si',44,14,'crampon1923','Leur corps a été enseveli en paix, et leur nom vit d''âge en âge.'),
('si',44,15,'crampon1923','Les peuples célèbrent leur sagesse, et l''assemblée publie leurs louanges.'),
('si',44,16,'crampon1923','Hénoch fut agréable au Seigneur, et il a été transporté, exemple de pénitence pour les générations.'),
('si',44,17,'crampon1923','Noé a été trouvé parfait et juste; au temps de la colère, il fut la rançon de l''humanité. C''est pourquoi un reste fut laissé à la terre, lorsque le déluge arriva.'),
('si',44,18,'crampon1923','Une alliance éternelle a été faite avec lui, afin que toute chair ne fût plus détruite par un déluge.'),
('si',44,19,'crampon1923','Abraham est l''illustre père d''une multitude de nations, et il ne s''est trouvé personne qui l''égalât en gloire.'),
('si',44,20,'crampon1923','Il a gardé la loi du Très-Haut, et il est entré en alliance avec lui. Il a institué cette alliance dans sa chair, et, dans l''épreuve, il s''est montré fidèle.'),
('si',44,21,'crampon1923','Aussi Dieu lui assura par serment que les nations seraient bénies dans sa race; il lui promit de le multiplier comme la poussière de la terre, d''élever sa postérité comme les étoiles, de leur donner en héritage depuis la mer jusqu''à l''autre mer, depuis le fleuve jusqu''aux extrémités de la terre.'),
('si',44,22,'crampon1923','De la même manière il confirma en Isaac, à cause de son père Abraham, la bénédiction de tous les peuples et l''alliance.'),
('si',44,23,'crampon1923','Et il la fit reposer ensuite sur la tête de Jacob; il eut égard à lui dans ses bénédictions; il lui donna le pays en héritage; il en fit diverses portions, et les partagea entre les douze tribus.'),
('si',45,1,'crampon1923','Il a fait sortir de Jacob un homme pieux, qui trouva grâce auprès de toute chair, un homme aimé de Dieu et des hommes, Moïse: que sa mémoire soit en bénédiction!'),
('si',45,2,'crampon1923','Il lui a donné une gloire égale à celle des saints, il l''a rendu grand par les terreurs qu''il inspira aux ennemis.'),
('si',45,3,'crampon1923','Par sa parole, il a fait cesser les prodiges; il l''a glorifié devant les rois; il lui a donné des commandements pour son peuple, et il lui a fait voir un rayon de sa gloire.'),
('si',45,4,'crampon1923','A cause de sa foi et de sa mansuétude, il l''a consacré, il l''a choisi d''entre tous les mortels.'),
('si',45,5,'crampon1923','Il lui a fait entendre sa voix, et l''a introduit dans la nuée; il lui a donné face à face des commandements, la loi de la vie et de la science, pour qu''il enseignât à Jacob son alliance, et ses décrets à Israël.'),
('si',45,6,'crampon1923','Il a élevé Aaron, un saint semblable à lui, son frère, de la tribu de Lévi.'),
('si',45,7,'crampon1923','Il conclut avec lui une alliance éternelle, et lui donna le sacerdoce de son peuple. Il l''orna d''une splendide parure, et le ceignit de la robe de gloire.'),
('si',45,8,'crampon1923','Il le revêtit d''une souveraine magnificence, et lui assigna des vêtements d''honneur: les caleçons, la longue tunique et l''éphod.'),
('si',45,9,'crampon1923','Il l''entoura de grenades, avec de nombreuses clochettes d''or à l''entour, qui devaient retentir quand il marchait, et faire entendre leur son dans le temple; c''était un mémorial pour les fils de son peuple.'),
('si',45,10,'crampon1923','Il l''entoura du vêtement sacré, tissé d''or, d''hyacinthe et de pourpre, ouvrage du brodeur; du rational du jugement, avec l''Urim et le Thummim, fait de fils d''écarlate, œuvre d''un artiste;'),
('si',45,11,'crampon1923','avec des pierres précieuses, gravées comme les cachets, et enchâssées dans l''or, travail d''un lapidaire, pour être un mémorial, des noms étant écrits, selon le nombre des tribus d''Israël.'),
('si',45,12,'crampon1923','Il lui mit sur la tiare la couronne d''or, portant ces mots gravés: Saint du Seigneur, insigne d''honneur, ouvrage parfait, délices des yeux, parure magnifique.'),
('si',45,13,'crampon1923','Rien de pareil n''a été avant lui et ne sera jamais; aucun étranger ne s''en est revêtu, mais seulement ses fils, et ses descendants dans toute la suite des âges.'),
('si',45,14,'crampon1923','Ses holocaustes seront offerts, deux fois chaque jour, sans interruption.'),
('si',45,15,'crampon1923','Moïse lui remplit les mains, et l''oignit de l''huile sainte. Ce fut pour lui une alliance éternelle, et pour sa race, tant que dureront les jours du ciel, de servir le Seigneur et de remplir les fonctions du sacerdoce, et de bénir son peuple en son nom.'),
('si',45,16,'crampon1923','Le Seigneur le choisit parmi tous les vivants, pour lui présenter l''offrande, le parfum et la suave odeur en souvenir, et pour faire l''expiation des péchés de son peuple.'),
('si',45,17,'crampon1923','Il lui donna, dans ses commandements, autorité sur les saintes ordonnances, pour apprendre à Jacob ses préceptes, et enseigner sa loi à Israël.'),
('si',45,18,'crampon1923','Des étrangers conspirèrent contre lui, et furent jaloux de lui dans le désert: les hommes du parti de Dathan et d''Abiron, et la bande de Coré, ardente et furieuse.'),
('si',45,19,'crampon1923','Le Seigneur le vit et n''y eut pas plaisir, et ils furent exterminés dans l''ardeur de sa colère; il fit contre eux des prodiges, et les consuma par la flamme de son feu.'),
('si',45,20,'crampon1923','Et il augmenta la gloire d''Aaron, et lui assigna un héritage: il lui donna en partage les prémices des fruits de la terre; avant tout il prépara le pain pour les rassasier.'),
('si',45,21,'crampon1923','Ils se nourrissent des sacrifices du Seigneur, qu''il donna à Aaron et à ses descendants.'),
('si',45,22,'crampon1923','Seulement il n''a pas d''héritage dans la terre du peuple, et il n''a pas de part au sein de la nation, car, dit le Seigneur, « je serai ta part et ton héritage. »'),
('si',45,23,'crampon1923','Phinéès, fils d''Eléazar, est le troisième en gloire, en ce qu''il montra du zèle dans la crainte du Seigneur, et que, dans la défection du peuple, il demeura ferme, dans le noble courage de son âme, et fit l''expiation pour Israël.'),
('si',45,24,'crampon1923','C''est pourquoi fut conclue avec lui une alliance de paix, qui le fit chef des prêtres et de son peuple, afin qu''à lui et à ses descendants appartînt à jamais l''auguste dignité du sacerdoce.'),
('si',45,25,'crampon1923','Il y eut aussi une alliance avec David, fils de Jessé, de la tribu de Juda; l''héritage du roi passe seulement de fils en fils, tandis que l''héritage d''Aaron appartient à tous ses descendants.'),
('si',45,26,'crampon1923','Que le Seigneur vous donne, ô grands prêtres, la sagesse dans votre cœur, pour juger son peuple dans la justice, afin que sa prospérité ne disparaisse pas, ni sa gloire dans les âges futurs!'),
('si',46,1,'crampon1923','Il fut vaillant à la guerre, Josué fils de Nun, qui succéda à Moïse dans la dignité de prophète, et qui, vérifiant son nom, se montra grand dans la délivrance des élus du Seigneur, en châtiant les ennemis soulevés, afin de mettre Israël en possession du pays.'),
('si',46,2,'crampon1923','De quelle gloire il se couvrit lorsqu''il leva ses mains, et étendit son épée contre les villes!'),
('si',46,3,'crampon1923','Qui jamais avant lui soutint tant de combats, quand le Seigneur lui-même amenait les ennemis?'),
('si',46,4,'crampon1923','Le soleil, au geste de sa main, n''a-t-il pas rétrogradé, et un seul jour ne fut-il pas pareil à deux jours?'),
('si',46,5,'crampon1923','Il invoqua le très haut Souverain pendant qu''il pressait les ennemis de tous côtés; et le Seigneur tout-puissant l''entendit, avec des pierres de grêle d''une grande force.'),
('si',46,6,'crampon1923','Le Seigneur fondit sur la nation hostile, et fit périr les adversaires dans le défilé, afin que les nations connussent toutes les armes de Josué, et apprissent que la guerre qu''il soutenait était devant le Seigneur; car il suivait le Tout-Puissant.'),
('si',46,7,'crampon1923','Déjà, aux jours de Moïse, il avait montré sa piété, lui et Caleb, fils de Jéphoné, en tenant ferme contre l''ennemi, en empêchant le peuple de pécher, et en faisant taire le murmure des méchants.'),
('si',46,8,'crampon1923','Aussi ces deux hommes furent-ils seuls conservés, de six cent mille hommes de pied, pour être introduits dans l''héritage, dans la terre où coulent le lait et le miel.'),
('si',46,9,'crampon1923','Et le Seigneur donna la vigueur à Caleb, — et elle lui resta jusqu''à la vieillesse, — de sorte qu''il put monter sur les sommets de la région, et que sa postérité conserva cet héritage:'),
('si',46,10,'crampon1923','afin que tous les enfants d''Israël reconnussent qu''il est bon de suivre le Seigneur.'),
('si',46,11,'crampon1923','Et les Juges, chacun selon son nom, tous ceux dont le cœur ne s''est pas adonné à la fornication, tous ceux qui ne se sont pas détournés du Seigneur, que leur mémoire soit en bénédiction!'),
('si',46,12,'crampon1923','Que leurs os refleurissent du sein de leur tombeau, que leur nom se renouvelle dans les enfants de ces hommes illustres!'),
('si',46,13,'crampon1923','Samuel fut aimé du Seigneur son Dieu; prophète du Seigneur, il a établi la royauté, et il a oint des princes pour commander à son peuple.'),
('si',46,14,'crampon1923','Il a jugé l''assemblée selon la loi du Seigneur, et le Seigneur abaissa ses regards sur Jacob.'),
('si',46,15,'crampon1923','Par sa véracité il se montra prophète; à sa véracité on reconnut un voyant digne de foi.'),
('si',46,16,'crampon1923','Il invoqua le Seigneur souverain, lorsque ses ennemis le pressaient de toutes parts, et il offrit un agneau encore à la mamelle.'),
('si',46,17,'crampon1923','Et le Seigneur tonna du haut du ciel, et, avec grand éclat, il fit entendre sa voix;'),
('si',46,18,'crampon1923','et il écrasa les chefs des Tyriens, et tous les princes des Philistins.'),
('si',46,19,'crampon1923','Avant le temps de l''éternel sommeil, Samuel prit à témoin le Seigneur et son Oint: « De personne je n''ai reçu aucun don, pas même des sandales; » et aucun homme ne se leva pour l''accuser.'),
('si',46,20,'crampon1923','Et lorsqu''il se fut endormi, il prophétisa, et, il annonça au roi sa fin prochaine. Du sein de la terre, il éleva sa voix en prophétisant, afin d''effacer l''iniquité du peuple.'),
('si',47,1,'crampon1923','Ensuite parut Nathan, pour prophétiser dans les jours de David.'),
('si',47,2,'crampon1923','Comme la graisse est séparée de la victime d''action de grâces, ainsi David a été mis à part parmi les enfants d''Israël.'),
('si',47,3,'crampon1923','Il joua avec les lions comme avec des chevreaux, avec les ours comme avec de jeunes agneaux.'),
('si',47,4,'crampon1923','Dans sa jeunesse, n''a-t-il pas tué le géant, et ôté l''opprobre du peuple, lorsqu''il leva la main avec la pierre de sa fronde, et abattit l''insolence de Goliath?'),
('si',47,5,'crampon1923','Car il invoqua le Seigneur, le Très-Haut, et le Seigneur donna la force à sa droite, pour mettre à mort le puissant guerrier, pour élever la corne de son peuple.'),
('si',47,6,'crampon1923','Aussi on le célébra à cause des dix mille, on le loua à cause des bénédictions du Seigneur, et on lui offrit la couronne de gloire.'),
('si',47,7,'crampon1923','Car il écrasa les ennemis de tous côtés, il foula aux pieds les Philistins, les adversaires; il brisa leur puissance jusqu''à ce jour.'),
('si',47,8,'crampon1923','Dans toutes ses entreprises, il rendit hommage, au Saint, au Très-Haut, dans des paroles de louange, de tout son cœur, il chanta des hymnes, et il aima Celui qui l''avait fait.'),
('si',47,9,'crampon1923','Il établit des chantres devant l''autel, et, par leur voix, il fit entendre de douces mélodies.'),
('si',47,10,'crampon1923','Il donna de l''éclat aux fêtes, et une splendeur souveraine aux solennités, pendant que les chantres célèbrent le saint nom du Seigneur, et que, dès le matin, ils font résonner le sanctuaire.'),
('si',47,11,'crampon1923','Le Seigneur lui pardonna ses fautes, et il éleva pour toujours sa puissance; il lui assura une descendance de rois, et le trône de gloire en Israël.'),
('si',47,12,'crampon1923','Après lui s''éleva un fils plein de sagesse; à cause de son père, il vécut dans la prospérité.'),
('si',47,13,'crampon1923','Salomon régna en des jours de paix, Dieu lui ayant procuré le repos tout autour, afin qu''il bâtit un temple à son nom, et préparât un sanctuaire éternel.'),
('si',47,14,'crampon1923','Comme tu étais sage dans ta jeunesse, et débordant d''intelligence, comme un fleuve!'),
('si',47,15,'crampon1923','Ton esprit a couvert la terre, et tu l''as remplie de sentences au sens caché.'),
('si',47,16,'crampon1923','Ton nom est arrivé jusqu''aux îles lointaines, et tu fus aimé dans ta paix.'),
('si',47,17,'crampon1923','Pour tes cantiques, tes proverbes, tes paraboles et tes réponses, le monde t''a admiré.'),
('si',47,18,'crampon1923','Au nom du Seigneur Dieu, qui est appelé le Dieu d''Israël, tu as amassé l''or comme l''étain, et amoncelé l''argent comme le plomb.'),
('si',47,19,'crampon1923','Tu t''es livré aux femmes et tu as donné puissance sur ton corps;'),
('si',47,20,'crampon1923','tu as imprimé une tache à ta gloire, et tu as profané ta race, et ainsi tu as attiré la colère sur tes enfants. Je sens une cruelle douleur pour ta folie;'),
('si',47,21,'crampon1923','elle a été cause que l''empire fut partagé en deux, et que d''Ephraïm s''éleva le chef d''un royaume rebelle.'),
('si',47,22,'crampon1923','Mais le Seigneur n''abandonnera pas sa miséricorde, et aucune de ses œuvres ne périra. Il ne détruira pas la postérité de son élu, et ne fera pas disparaître la race de celui qui l''aimait. Il a laissé à Jacob un reste, et à David un rejeton de sa race.'),
('si',47,23,'crampon1923','Salomon reposa avec ses pères, et il laissa après lui, de sa race, un fils, insensé aux yeux du peuple, dépourvu de prudence, Roboam, qui amena le peuple à s''écarter de ses conseils, et Jéroboam, fils de Nabat, qui fit pécher Israël, et ouvrit à Ephraïm la voie de la prévarication.'),
('si',47,24,'crampon1923','Et les péchés des Israélites se multiplièrent à l''excès, en sorte qu''on les emmena loin de leur pays.'),
('si',47,25,'crampon1923','Ils poursuivirent toutes sortes d''iniquités, jusqu''à ce que la vengeance vint fondre sur eux.'),
('si',48,1,'crampon1923','Ensuite se leva Elie, prophète semblable au feu, et sa parole était enflammée comme un flambeau.'),
('si',48,2,'crampon1923','Il fit venir la famine sur Israël, et, par son zèle, il le réduisit à un petit nombre.'),
('si',48,3,'crampon1923','Par la parole du Seigneur, il ferma le ciel; de même, il en fit trois fois tomber le feu.'),
('si',48,4,'crampon1923','Combien tu t''es rendu glorieux, ô Elie, par tes prodiges, et qui pourrait se vanter d''être semblable à toi?'),
('si',48,5,'crampon1923','Toi qui as fait lever un cadavre du sein de la mort, et du schéol, par la parole du Très-Haut;'),
('si',48,6,'crampon1923','toi qui as précipité des rois dans la ruine, et d''illustres personnages de leur couche dans la mort;'),
('si',48,7,'crampon1923','toi qui as entendu sur le Sinaï des remontrances, et sur l''Horeb des arrêts de vengeance;'),
('si',48,8,'crampon1923','toi qui as sacré des rois pour exercer la vengeance, et des prophètes pour te succéder;'),
('si',48,9,'crampon1923','toi qui fus enlevé dans un tourbillon de flamme, et dans un char aux chevaux de feu;'),
('si',48,10,'crampon1923','toi qui as été désigné dans de sévères écrits pour des temps à venir, comme devant apaiser la colère avant qu''elle s''enflamme, ramener le cœur du père vers l''enfant, et rétablir les tribus d''Israël.'),
('si',48,11,'crampon1923','Heureux ceux qui te verront, et qui seront parés de l''amour de Dieu! Car, nous aussi, nous serons certainement en vie.'),
('si',48,12,'crampon1923','Lorsque Elie eu été enveloppé dans le tourbillon, Elisée fut rempli de son esprit. Durant ses jours, il ne fut ébranlé par aucun prince, et personne ne le domina.'),
('si',48,13,'crampon1923','Rien ne lui fut impossible, et son corps, couché dans le tombeau, fit des miracles.'),
('si',48,14,'crampon1923','Pendant sa vie, il fit des prodiges, et, dans sa mort, il opéra des merveilles.'),
('si',48,15,'crampon1923','Malgré tout cela, le peuple ne se repentit point, et ne s''éloigna pas du péché, jusqu''à ce qu''il fût emmené loin de son pays, et dispersé par toute la terre. Il ne resta qu''un petit peuple, avec un chef de la maison de David.'),
('si',48,16,'crampon1923','Parmi ceux-ci, quelques-uns firent ce qui est agréable à Dieu, et d''autres multiplièrent les transgressions.'),
('si',48,17,'crampon1923','Ezéchias fortifia sa ville, et amena dans son enceinte le Gihon; avec le fer, il creusa le rocher, et construisit des réservoirs pour les eaux.'),
('si',48,18,'crampon1923','De son temps Sennachérib monta, et envoya Rabsacès; celui-ci partit, et leva la main contre Sion, et se vanta dans sa jactance.'),
('si',48,19,'crampon1923','Alors leurs cœurs et leurs mains tremblèrent, et ils furent dans la douleur comme les femmes qui enfantent.'),
('si',48,20,'crampon1923','Ils invoquèrent le Seigneur miséricordieux, étendant leurs mains vers lui, et le Saint les entendit aussitôt du ciel, et les délivra par le ministère d''Isaïe.'),
('si',48,21,'crampon1923','Il frappa l''armée des Assyriens, et son ange les extermina.'),
('si',48,22,'crampon1923','Car Ezéchias fit ce qui est agréable au Seigneur, et se tint ferme dans les voies de David, son père, que lui recommanda Isaïe le prophète, grand et véridique dans ses visions.'),
('si',48,23,'crampon1923','Pendant ses jours, le soleil rétrograda, et Isaïe prolongea la vie du roi.'),
('si',48,24,'crampon1923','Sous une puissante inspiration, il vit les temps à venir, et consola les affligés dans Sion. Il annonça ce qui doit arriver jusqu''à la fin des temps, et les choses cachées avant leur accomplissement.'),
('si',48,25,'crampon1923',''),
('si',49,1,'crampon1923','La mémoire de Josias est un parfum composé de suaves odeurs, préparé par l''art du parfumeur; dans toute bouche, son souvenir est doux comme le miel, et comme une musique dans un festin.'),
('si',49,2,'crampon1923','Il réussit à amener la nation au repentir, et il fit disparaître les abominations de l''impiété.'),
('si',49,3,'crampon1923','Il tourna fidèlement son cœur vers le Seigneur, et, dans les jours des impies, il affermit la piété.'),
('si',49,4,'crampon1923','A l''exception de David, d''Ezéchias et de Josias, tous les autres ont commis l''iniquité; car, ayant abandonné la loi du Très-Haut, les rois de Juda sont allés à leur perte.'),
('si',49,5,'crampon1923','En effet, ils ont laissé à d''autres leur puissance, et leur gloire à une nation étrangère.'),
('si',49,6,'crampon1923','Ils ont brûlé la ville choisie du sanctuaire, et ont rendu ses places désertes,'),
('si',49,7,'crampon1923','à cause de Jérémie, car ils l''ont maltraité, lui, consacré prophète dès le sein de sa mère, pour renverser, détruire et faire périr, en même temps que pour édifier et planter.'),
('si',49,8,'crampon1923','Ezéchiel contempla la vision de gloire, que le Seigneur lui montra sur le char des Chérubins;'),
('si',49,9,'crampon1923','car il songea aux ennemis dans la menace d''une pluie d''orage, et il fit du bien à ceux qui suivaient la voie droite.'),
('si',49,10,'crampon1923','Quant aux douze prophètes, que leurs ossements refleurissent du sein de leurs tombeaux! Car ils ont consolé Jacob, et l''ont sauvé par une espérance certaine.'),
('si',49,11,'crampon1923','Comment célébrer Zorobabel? Car il est comme un anneau de cachet à la main droite.'),
('si',49,12,'crampon1923','Il en est de même de Jésus, fils de Josédec! Tous deux, en leurs jours, ont rebâti la maison de Dieu, et relevé le temple, consacré au Seigneur, destiné à une gloire éternelle.'),
('si',49,13,'crampon1923','De Néhémie aussi le souvenir est grand, lui qui a relevé nos murs en ruines, qui a rétabli nos portes avec leurs barres, et reconstruit nos maisons.'),
('si',49,14,'crampon1923','Pas un homme n''a existé ici-bas semblable à Hénoch, car, lui aussi, il a été enlevé de cette terre.'),
('si',49,15,'crampon1923','Nul homme ne fut non plus comme Joseph, le prince de ses frères, le soutien de sa nation; et ses ossements ont été gardés avec soin.'),
('si',49,16,'crampon1923','Sem et Seth ont été glorifiés parmi les hommes, mais au-dessus de tout être dans la création est Adam.'),
('si',50,1,'crampon1923','Simon, fils d''Onias, est le grand prêtre qui, pendant sa vie, répara la maison du Seigneur, et, durant ses jours, affermit le temple.'),
('si',50,2,'crampon1923','Par lui furent posées les fondations pour porter au double le mur élevé qui soutient l''enceinte du temple.'),
('si',50,3,'crampon1923','De son temps fut fabriqué le réservoir des eaux; l''airain dont il était formé avait le périmètre de la mer.'),
('si',50,4,'crampon1923','Il prit soin de son peuple pour le préserver de la ruine, et fortifia la ville contre un siège.'),
('si',50,5,'crampon1923','Qu''il était majestueux au milieu du peuple rassemblé tout autour, lorsqu''il sortait de la maison du voile!'),
('si',50,6,'crampon1923','Il était comme l''étoile du matin qui étincelle à travers le nuage, comme la lune aux jours de son plein,'),
('si',50,7,'crampon1923','comme le soleil qui resplendit sur le temple du Très-Haut, et comme l''arc-en-ciel qui brille au milieu des nuées lumineuses;'),
('si',50,8,'crampon1923','comme la fleur des roses aux jours du printemps, comme les lys sur le bord des eaux, comme le rameau de l''arbre odoriférant aux jours de l''été,'),
('si',50,9,'crampon1923','comme le parfum sur le feu de l''encensoir, comme un vase d''or massif, orné de toutes sortes de pierres précieuses,'),
('si',50,10,'crampon1923','comme l''olivier qui pousse ses fruits, et comme le cyprès qui s''élève dans les nuages.'),
('si',50,11,'crampon1923','Quand il avait pris la robe d''honneur, et revêtu tous ses ornements, et qu''il montait à l''autel saint, il faisait resplendir les abords du sanctuaire.'),
('si',50,12,'crampon1923','Mais quand il recevait les parties des victimes des mains des prêtres, et se tenait debout près du foyer de l''autel, ses frères formant une couronne autour de lui, alors il paraissait comme un cèdre majestueux sur le Liban, et les prêtres l''entouraient comme des troncs de palmiers.'),
('si',50,13,'crampon1923','Tous les fils d''Aaron étaient revêtus de leurs magnifiques ornements, et ils tenaient dans leurs mains l''offrande pour le Seigneur, devant toute l''assemblée d''Israël.'),
('si',50,14,'crampon1923','Et lorsqu''il avait achevé le service sur les autels, afin d''embellir l''offrande du Très-Haut tout-puissant, il étendait la main sur la coupe aux libations, et répandait le sang de la grappe.'),
('si',50,15,'crampon1923','Il le versait sur la base de l''autel, parfum d''agréable odeur au Très-Haut, au grand Roi.'),
('si',50,16,'crampon1923','Alors les fils d''Aaron poussaient des cris, ils sonnaient de leurs trompettes de métal battu, et faisaient entendre d''éclatantes clameurs, en souvenir devant le Très-Haut.'),
('si',50,17,'crampon1923','Et tout le peuple à la fois s''empressait, et tombait la face contre terre, pour adorer leur Seigneur, le Dieu tout-puissant, le Très-Haut.'),
('si',50,18,'crampon1923','Et les chantres, en déployant leur voix, le louaient; le vaste temple retentissait de doux accords.'),
('si',50,19,'crampon1923','Et le peuple suppliait le Seigneur très haut, se tenant en prière devant le Miséricordieux, jusqu''à ce que la cérémonie du Seigneur fût achevée, et que les prêtres eussent accompli les fonctions sacrées.'),
('si',50,20,'crampon1923','Alors le grand prêtre descendait et élevait sa main sur toute l''assemblée des enfants d''Israël, pour donner de ses lèvres la bénédiction du Seigneur, et se glorifier en son nom.'),
('si',50,21,'crampon1923','Et le peuple se prosternait de nouveau pour recevoir la bénédiction de la part du Très-Haut.'),
('si',50,22,'crampon1923','Et maintenant, bénissez le Seigneur de l''univers, qui fait partout de grandes choses, qui a exalté nos jours depuis l''origine, et nous a traités selon sa miséricorde.'),
('si',50,23,'crampon1923','Qu''il nous donne la joie du cœur, et que la paix soit de nos jours en Israël comme aux jours du passé!'),
('si',50,24,'crampon1923','Que sa miséricorde demeure perpétuellement avec nous, et qu''il nous délivre quand son jour sera venu!'),
('si',50,25,'crampon1923','Il y a deux nations que déteste mon âme, et la troisième n''est pas même une nation:'),
('si',50,26,'crampon1923','ceux qui demeurent dans la montagne de Séir, les Philistins, et le peuple insensé qui habite Sichem.'),
('si',50,27,'crampon1923','J''ai consigné dans ce livre un enseignement d''intelligence et de science, moi, Jésus, fils de Sirach, de Jérusalem, qui ai fait couler à flots la sagesse de mon cœur.'),
('si',50,28,'crampon1923','Heureux celui qui s''adonnera à ces enseignements! Celui qui les recueille dans son cœur deviendra sage;'),
('si',50,29,'crampon1923','car s''il les met en pratique, il triomphera de tout, parce que la lumière du Seigneur est son sentier. <DEUX APPENDICES >'),
('si',51,1,'crampon1923','Je veux vous célébrer, Seigneur, Roi; je veux vous louer, ô Dieu Sauveur, je célèbre votre nom.'),
('si',51,2,'crampon1923','Car vous avez été pour moi un protecteur et un secours; vous avez sauvé mon corps de la ruine, du filet de la langue calomnieuse, des lèvres de ceux qui pratiquent le mensonge; et, en face de mes adversaires,'),
('si',51,3,'crampon1923','vous avez été mon soutien et vous m''avez délivré, selon la grandeur de votre miséricorde et de votre nom, de ceux qui grinçaient des dents, prêts à me dévorer; de la main de ceux qui en voulaient à ma vie, de toutes les tribulations dont j''étais assiégé;'),
('si',51,4,'crampon1923','de la suffocation du feu qui m''entourait, du milieu d''un feu que je n''avais pas allumé;'),
('si',51,5,'crampon1923','de l''abîme profond du schéol, de la langue impure et de la parole mensongère adressée au roi, de la calomnie d''une langue injuste.'),
('si',51,6,'crampon1923','Mon âme s''approchait de la mort, et ma vie touchait au schéol en bas.'),
('si',51,7,'crampon1923','Ils m''entouraient de toutes parts, et il n''y avait personne pour me secourir; je regardais après le secours des hommes, et il n''y en avait aucun.'),
('si',51,8,'crampon1923','Alors je me suis souvenu de votre miséricorde, Seigneur, et de vos œuvres dans les temps antiques; je me suis souvenu que vous sauviez ceux qui espéraient en vous, et que vous les délivriez des mains des nations idolâtres.'),
('si',51,9,'crampon1923','Et, prosterné contre terre, j''ai fait monter ma prière, et je vous ai conjuré de me sauver de la mort.'),
('si',51,10,'crampon1923','J''invoquai le Seigneur, père de mon Seigneur, pour qu''il ne m''abandonnât point aux jours de ma détresse, au temps des orgueilleux, où il n''y avait pas de secours:'),
('si',51,11,'crampon1923','« Je louerai sans cesse votre nom, et je le chanterai dans ma reconnaissance. » Et ma prière a été exaucée,'),
('si',51,12,'crampon1923','car vous m''avez sauvé de la ruine, et vous m''avez délivré au temps du malheur. C''est pourquoi je vous célébrerai et je vous louerai, et je bénirai le nom du Seigneur. — Zèle pour l''acquisition de la sagesse —'),
('si',51,13,'crampon1923','Quand j''étais encore jeune, avant d''avoir erré, j''ai recherché ouvertement la sagesse dans ma prière.'),
('si',51,14,'crampon1923','Je l''ai demandé devant le temple, et je la rechercherai jusqu''à la fin.'),
('si',51,15,'crampon1923','En voyant sa fleur, comme à la vue de la grappe qui se colore, mon cœur se réjouissait en elle. Avec elle, mon pied a marché dans le droit chemin; dès ma jeunesse, j''ai suivi sa trace.'),
('si',51,16,'crampon1923','Je lui ai prêté l''oreille un peu de temps et je l''ai recueillie, et j''ai trouvé pour moi une grande instruction.'),
('si',51,17,'crampon1923','Grâce à elle, j''ai retiré un grand profit: à celui qui m''a donné la sagesse je veux rendre gloire!'),
('si',51,18,'crampon1923','Car je me suis résolu à la mettre en pratique, je me suis appliqué au bien, et je ne serai pas confondu.'),
('si',51,19,'crampon1923','Pour elle mon âme a lutté, et j''ai apporté un grand soin à mes actions. J''ai levé mes mains en haut, et j''ai déploré de l''avoir ignorée.'),
('si',51,20,'crampon1923','Vers elle j''ai dirigé mon âme, et, dans la pureté de la vie, je l''ai trouvée. Avec elle, dès le commencement, j''ai acquis l''intelligence; c''est pourquoi je ne serai jamais abandonné.'),
('si',51,21,'crampon1923','Mes entrailles se sont émues à sa recherche; aussi ai-je acquis un bien précieux.'),
('si',51,22,'crampon1923','Le Seigneur m''a donné en récompense le don de la parole, et j''en userai pour le louer.'),
('si',51,23,'crampon1923','Approchez-vous de moi, ignorants, et établissez votre demeure dans la maison de l''instruction,'),
('si',51,24,'crampon1923','puisque vous manquez de sagesse, et que vos âmes ont grandement soif.'),
('si',51,25,'crampon1923','J''ouvre ma bouche et je parle: Procurez-vous-la sans argent;'),
('si',51,26,'crampon1923','pliez votre cou sous le joug, et que votre âme reçoive l''instruction; il n''y a pas à aller loin pour la trouver.'),
('si',51,27,'crampon1923','Voyez de vos yeux que j''ai peu travaillé, et que j''ai trouvé un grand repos.'),
('si',51,28,'crampon1923','Prenez part à l''instruction à grand prix d''argent, et avec elle vous aurez acquis de l''or en abondance.'),
('si',51,29,'crampon1923','Que votre âme se réjouisse de la miséricorde du Seigneur, et ne rougissez pas de sa louange.'),
('si',51,30,'crampon1923','Accomplissez votre œuvre avant le temps, et, en son temps, il vous donnera la récompense.'),
('is',1,1,'crampon1923','Vision d''Isaïe, fils d''Amos, qu''il a vue touchant Juda et Jérusalem, aux jours d''Osias, de Joatham, d''Achaz et d''Ezéchias, rois de Juda.'),
('is',1,2,'crampon1923','Cieux, écoutez, et toi, terre, prête l''oreille, car Yahweh parle: J''ai nourri des enfants et je les ai élevés, et eux se sont révoltés contre moi.'),
('is',1,3,'crampon1923','Le bœuf connaît son possesseur et l''âne la crèche de son maître; mais Israël n''a point de connaissance, mon peuple n''a point d''intelligence.'),
('is',1,4,'crampon1923','Ah! nation pécheresse, peuple chargé d''iniquité, race de méchants, fils criminels. Ils ont abandonné Yahweh, ils ont outragé le Saint d''Israël, ils se sont retirés en arrière.'),
('is',1,5,'crampon1923','Où vous frapper encore, si vous continuez vos révoltes? Toute la tête est malade, et tout le cœur est languissant.'),
('is',1,6,'crampon1923','De la plante des pieds au sommet de la tête, il n''y a en lui rien de sain: ce n''est que blessures, meurtrissures, plaies vives, qui n''ont pas été pansées, ni bandées, ni adoucies avec de l''huile.'),
('is',1,7,'crampon1923','Votre pays est un désert; vos villes sont consumées par le feu; votre sol, des étrangers le dévorent sous vos yeux; la dévastation est comme le ravage fait par des étrangers.'),
('is',1,8,'crampon1923','Et la fille de Sion est restée comme une cabane dans une vigne, comme une hutte dans un champ de concombres, comme une tour de garde.'),
('is',1,9,'crampon1923','Si Yahweh des armées ne nous eût pas laissé un faible reste, nous serions comme Sodome, nous ressemblerions à Gomorrhe.'),
('is',1,10,'crampon1923','Ecoutez la parole de Yahweh, juges de Sodome; prêtez l''oreille à la loi de notre Dieu, peuple de Gomorrhe.'),
('is',1,11,'crampon1923','Que m''importe la multitude de vos sacrifices? dit Yahweh. Je suis rassasié des holocaustes de béliers, et de la graisse des veaux; je ne prends point plaisir au sang des taureaux, des brebis et des boucs.'),
('is',1,12,'crampon1923','Quand vous venez vous présenter devant ma face, qui vous a demandé de fouler mes parvis?'),
('is',1,13,'crampon1923','Ne continuez pas de m''apporter de vaines oblations; l''encens m''est en abomination; quant aux nouvelles lunes, aux sabbats et aux convocations, je ne puis voir ensemble le crime et l''assemblée solennelle.'),
('is',1,14,'crampon1923','Mon âme hait vos nouvelles lunes et vos fêtes; elles me sont à charge, je suis las de les supporter.'),
('is',1,15,'crampon1923','Quand vous étendez vos mains, je voile mes yeux devant vous; quand vous multipliez les prières, je n''écoute pas: Vos mains sont pleines de sang.'),
('is',1,16,'crampon1923','Lavez-vous, purifiez-vous; ôtez la malice de vos actions de devant mes yeux; cessez de mal faire,'),
('is',1,17,'crampon1923','apprenez à bien faire; recherchez la justice, redressez l''oppresseur, faites droit à l''orphelin, défendez la veuve.'),
('is',1,18,'crampon1923','Venez et discutons ensemble: Si vos péchés sont comme l''écarlate, ils deviendront blancs comme la neige; s''ils sont rouges comme la pourpre, ils deviendront comme la laine.'),
('is',1,19,'crampon1923','Si vous obéissez de bon cœur, vous mangerez les biens de votre pays;'),
('is',1,20,'crampon1923','mais si vous résistez, et si vous êtes rebelles, vous serez mangés par l''épée; car la bouche de Yahweh a parlé.'),
('is',1,21,'crampon1923','Comment est-elle devenue une prostituée, la cité fidèle, elle, pleine d''équité, dans laquelle la justice habitait, et maintenant... des meurtriers!'),
('is',1,22,'crampon1923','Ton argent s''est changé en scories, ton vin a été coupé d''eau.'),
('is',1,23,'crampon1923','Tes princes sont des rebelles, et des compagnons de voleurs; tous aiment les présents, et courent après les récompenses; ils ne font pas droit à l''orphelin, et la cause de la veuve ne vient pas devant eux.'),
('is',1,24,'crampon1923','C''est pourquoi — oracle du Seigneur, Yahweh des armées, le Fort d''Israël: Ah! je tirerai satisfaction de mes adversaires, et je me vengerai de mes ennemis.'),
('is',1,25,'crampon1923','J''étendrai ma main sur toi, et je fondrai tes scories comme avec de la potasse, et j''ôterai toutes tes parcelles de plomb.'),
('is',1,26,'crampon1923','Je te rendrai des juges comme ceux d''autrefois, et des conseillers comme aux premiers temps. Après cela on t''appellera la ville de justice, la cité fidèle.'),
('is',1,27,'crampon1923','Sion sera rachetée par la droiture, et ses convertis, par la justice.'),
('is',1,28,'crampon1923','Mais les rebelles et les pécheurs seront brisés ensemble, et ceux qui abandonnent Yahweh périront.'),
('is',1,29,'crampon1923','Car ils auront honte des térébinthes que vous avez aimés, et vous rougirez des jardins dont vous faites vos délices.'),
('is',1,30,'crampon1923','Car vous serez comme un térébinthe au feuillage flétri, et comme un jardin sans eau.'),
('is',1,31,'crampon1923','Et l''homme fort sera l''étoupe, et ses œuvres, l''étincelle; ils brûleront tous deux ensemble, et personne n''éteindra.'),
('is',2,1,'crampon1923','La parole qu''Isaïe, fils d''Amos, a vue touchant Juda et Jérusalem.'),
('is',2,2,'crampon1923','Il arrivera, à la fin des jours, que la Montagne de la maison de Yahweh sera établie au sommet des montagnes et élevée au-dessus des collines. Et vers elle toutes les nations afflueront,'),
('is',2,3,'crampon1923','et des nations nombreuses viendront et diront: " Venez et montons à la montagne de Yahweh, à la maison du Dieu de Jacob; il nous instruira de ses voies, et nous marcherons dans ses sentiers. " Car de Sion sortira la loi, et de Jérusalem la parole de Yahweh.'),
('is',2,4,'crampon1923','Il sera l''arbitre des peuples et le juge de nations nombreuses. Ils forgeront leurs épées en socs de charrue; et leurs lances en faucilles. Une nation ne lèvera plus l''épée contre l''autre, et l''on n''apprendra plus la guerre.'),
('is',2,5,'crampon1923','Maison de Jacob, venez, et marchons à la lumière de Yahweh.'),
('is',2,6,'crampon1923','Car vous avez abandonné votre peuple, la maison de Jacob, parce qu''ils ont comblé la mesure depuis longtemps, qu''ils pratiquent la magie comme les Philistins, et qu''ils donnent la main aux fils de l''étranger.'),
('is',2,7,'crampon1923','Leur pays est rempli d''argent et d''or, et leurs trésors sont sans fin; leur pays est rempli de chevaux, et leurs chars sont sans nombre.'),
('is',2,8,'crampon1923','Leur pays est rempli d''idoles; ils se prosternent devant l''ouvrage de leurs mains, devant ce que leurs doigts ont fabriqué.'),
('is',2,9,'crampon1923','C''est pourquoi le mortel sera humilié et l''homme sera abaissé: non, vous ne leur pardonnerez point!'),
('is',2,10,'crampon1923','Entre dans le rocher, cache-toi dans la poussière, devant la terreur de Yahweh et l''éclat de sa majesté.'),
('is',2,11,'crampon1923','Les yeux hautains du mortel seront abaissés, et l''orgueil de l''homme sera humilié, et Yahweh sera exalté, lui seul, en ce jour-là.'),
('is',2,12,'crampon1923','Car Yahweh des armées aura un jour contre tout orgueil et toute hauteur, et contre tout ce qui s''élève, pour l''abaisser;'),
('is',2,13,'crampon1923','contre tous les cèdres du Liban, hauts et élevés, et contre tous les chênes de Basan;'),
('is',2,14,'crampon1923','contre toutes les hautes montagnes, et contre toutes les collines élevées;'),
('is',2,15,'crampon1923','contre toute tour superbe, et contre toute forte muraille;'),
('is',2,16,'crampon1923','contre tous les vaisseaux de Tarsis, et contre tout ce qui charme les yeux.'),
('is',2,17,'crampon1923','L''arrogance du mortel sera humiliée, et l''orgueil de l''homme sera abaissé, et Yahweh sera élevé, lui seul, en ce jour-là.'),
('is',2,18,'crampon1923','Et toutes les idoles disparaîtront.'),
('is',2,19,'crampon1923','Et ils entreront dans les cavernes des rochers, et dans les antres de la terre, devant la terreur de Yahweh, et l''éclat de sa majesté, quand il se lèvera pour épouvanter la terre.'),
('is',2,20,'crampon1923','En ce jour-là l''homme jettera ses idoles d''argent et ses idoles d''or, qu''il s''était faites pour les adorer, aux rats et aux chauves-souris,'),
('is',2,21,'crampon1923','pour s''enfuir dans les trous de la pierre et dans les fentes des rochers, devant la terreur de Yahweh, et l''éclat de sa majesté, quand il se lèvera pour épouvanter la terre.'),
('is',2,22,'crampon1923','Cessez donc de vous confier en l''homme, dans les narines duquel il n''y a qu''un souffle; car quelle estime en avoir?'),
('is',3,1,'crampon1923','Car voici que le Seigneur, Yahweh des armées, va retirer de Jérusalem et de Juda toute ressource et tout appui, toute ressource de pain et toute ressource d''eau,'),
('is',3,2,'crampon1923','héros et homme de guerre, juge, prophète et devin, ancien,'),
('is',3,3,'crampon1923','capitaine et notable, conseiller, ouvrier expert en son art et habile enchanteur.'),
('is',3,4,'crampon1923','Et je leur donnerai des jeunes gens pour princes, et des enfants domineront sur eux.'),
('is',3,5,'crampon1923','Et le peuple se ruera homme contre homme, chacun contre son voisin; ils se précipiteront, le jeune homme contre le vieillard, et l''homme de rien contre le plus illustre.'),
('is',3,6,'crampon1923','Lorsqu''un homme prendra son frère dans la maison de son père, en disant: " Tu as un manteau, sois notre chef, et que cette ruine soit sous ta garde! "'),
('is',3,7,'crampon1923','Il se récriera en ce jour-là: " Je ne veux pas être le médecin: je n''ai dans ma maison ni pain ni manteau; ne me faites pas chef du peuple. "'),
('is',3,8,'crampon1923','Car Jérusalem chancelle et Juda s''écroule, parce que leurs paroles et leurs œuvres sont contre Yahweh, pour braver le regard de sa majesté.'),
('is',3,9,'crampon1923','L''air de leur visage dépose contre eux; comme Sodome, ils publient leur péché et ne s''en cachent point. Malheur à eux! car ils sont eux-mêmes les auteurs de leur perte.'),
('is',3,10,'crampon1923','Dites au juste qu''il est heureux, car il mangera le fruit de ses œuvres.'),
('is',3,11,'crampon1923','Malheur au méchant! mal lui arrivera, car ce que ses mains ont fait lui sera rendu.'),
('is',3,12,'crampon1923','Mon peuple est opprimé par des enfants, et des femmes le gouvernent. Mon peuple, ceux qui te dirigent t''égarent, et ils ruinent le chemin où tu dois passer.'),
('is',3,13,'crampon1923','Yahweh s''est levé pour rendre la justice, et il est debout pour juger les peuples.'),
('is',3,14,'crampon1923','Yahweh entre en jugement avec les anciens et les princes de son peuple: " Vous avez brouté la vigne; la dépouille du pauvre est dans vos maisons.'),
('is',3,15,'crampon1923','De quel droit foulez-vous mon peuple, et écrasez-vous la face des malheureux? " — oracle du Seigneur Yahweh des armées.'),
('is',3,16,'crampon1923','Yahweh a dit: Parce que les filles de Sion sont devenues orgueilleuses, qu''elles s''avancent la tête haute, lançant des regards, qu''elles vont à petits pas, et font sonner les anneaux de leurs pieds,'),
('is',3,17,'crampon1923','le Seigneur rendra chauve le crâne des filles de Sion, et Yahweh découvrira leur nudité.'),
('is',3,18,'crampon1923','En ce jour-là, le Seigneur enlèvera le luxe des anneaux, les soleils et les croissants;'),
('is',3,19,'crampon1923','les pendants d''oreille, les bracelets et les voiles;'),
('is',3,20,'crampon1923','les diadèmes, les chaînettes des pieds et les ceintures;'),
('is',3,21,'crampon1923','les boîtes à parfum et les amulettes, les bagues et les anneaux du nez;'),
('is',3,22,'crampon1923','les robes de fête et les larges tuniques, les manteaux et les bourses;'),
('is',3,23,'crampon1923','les miroirs et les mousselines, les turbans et les mantilles.'),
('is',3,24,'crampon1923','Et, au lieu de parfum, il y aura la pourriture; au lieu de ceinture, une corde; au lieu de cheveux bouclés, une tête chauve; au lieu d''une ample robe, un sac; au lieu de beauté, la marque imprimée par le feu.'),
('is',3,25,'crampon1923','Tes guerriers tomberont par l''épée, et tes héros dans la bataille.'),
('is',3,26,'crampon1923','Les portes de Sion gémiront et seront dans le deuil, et, désolée, elle sera assise dans la poussière.'),
('is',4,1,'crampon1923','Sept femmes saisiront un seul homme en ce jour, et diront: " Nous mangerons notre pain, et nous nous vêtirons de nos habits; permets seulement que nous portions ton nom; ôte notre opprobre. "'),
('is',4,2,'crampon1923','En ce jour-là, le germe de Yahweh fera l''ornement et la gloire, et le fruit de la terre, fera l''orgueil et la parure des réchappés d''Israël.'),
('is',4,3,'crampon1923','Et ceux qui seront restés dans Sion, et ceux qui auront été épargnés dans Jérusalem seront appelés saints, tous ceux qui sont inscrits pour la vie dans Jérusalem.'),
('is',4,4,'crampon1923','Quand Yahweh aura lavé les souillures des filles de Sion, et purifié Jérusalem du sang qui est au milieu d''elle, par l''esprit de jugement et par l''esprit d''extermination,'),
('is',4,5,'crampon1923','alors Yahweh créera sur toute l''étendue de la montagne de Sion, et sur ses assemblées, une nuée durant le jour et une fumée, et l''éclat d''une flamme ardente pendant la nuit. Car sur toute sa gloire il y aura un dais;'),
('is',4,6,'crampon1923','et il y aura une tente pour donner de l''ombrage contre les ardeurs du jour, et pour servir de refuge et d''abri contre l''orage et la pluie.'),
('is',5,1,'crampon1923','Je vais chanter pour mon bien-aimé le chant de mon bien-aimé au sujet de sa vigne. Mon bien-aimé avait une vigne, sur un coteau fertile.'),
('is',5,2,'crampon1923','Il en remua le sol, il en ôta les pierres, il la planta de ceps exquis. Il bâtit une tour au milieu, et il y creusa aussi un pressoir. Il attendait qu''elle donnât des raisins, mais elle donna du verjus. —'),
('is',5,3,'crampon1923','" Et maintenant, habitants de Jérusalem et hommes de Juda, jugez, je vous prie, entre moi et entre ma vigne!'),
('is',5,4,'crampon1923','Qu''y avait-il à faire de plus à ma vigne, que je n''aie pas fait pour elle? Pourquoi, ai-je attendu qu''elle donnât des raisins, et n''a-t-elle donné que du verjus?'),
('is',5,5,'crampon1923','" Et maintenant, je vous ferai connaître ce que je vais faire à ma vigne: j''arracherai sa haie, et elle sera broutée; j''abattrai sa clôture, et elle sera foulée aux pieds.'),
('is',5,6,'crampon1923','J''en ferai un désert; et elle ne sera plus taillée, ni cultivée; les ronces et les épines y croîtront, et je commanderai aux nuées de ne plus laisser tomber la pluie sur elle. " —'),
('is',5,7,'crampon1923','Car la vigne de Yahweh des armées, c''est la maison d''Israël, et les hommes de Juda sont le plant qu''il chérissait; il en attendait la droiture, voici du sang versé; la justice, et voici le cri de détresse.'),
('is',5,8,'crampon1923','Malheur à ceux qui ajoutent maison à maison, qui joignent champ à champ, jusqu''à ce qu''il n''y ait plus d''espace, et qu''ils habitent seuls au milieu du pays!'),
('is',5,9,'crampon1923','Yahweh des armées a dit cette parole à mes oreilles: Oui, ces nombreuses maisons seront désertes; grandes et belles, elles n''auront plus d''habitants.'),
('is',5,10,'crampon1923','Car dix arpents de vignes ne produiront qu''un bath, un homer de semence ne produira qu''un épha.'),
('is',5,11,'crampon1923','Malheur à ceux qui courent dès le matin après les boissons enivrantes, et qui, le soir, prolongent leur orgie, échauffés par le vin!'),
('is',5,12,'crampon1923','La harpe et le luth, le tambourin, la flûte et le vin, voilà leurs festins; mais ils ne prennent point garde à l''œuvre de Yahweh, et ils ne voient point l''ouvrage de ses mains.'),
('is',5,13,'crampon1923','C''est pourquoi mon peuple s''en ira en exil sans s''en douter; sa noblesse deviendra une troupe affamée, et sa multitude séchera de soif.'),
('is',5,14,'crampon1923','C''est pourquoi le schéol se dilate, et ouvre sa bouche sans mesure; elle y descend, la magnificence de Sion, avec sa multitude bruyante et joyeuse.'),
('is',5,15,'crampon1923','Le mortel sera humilié, l''homme sera abaissé, et les yeux des superbes seront abattus.'),
('is',5,16,'crampon1923','Et Yahweh des armées apparaîtra grand dans le jugement, et le Dieu saint apparaîtra saint dans la justice.'),
('is',5,17,'crampon1923','Des brebis paîtront comme sur leur pâturage, et des étrangers dévoreront les champs dévastés des riches.'),
('is',5,18,'crampon1923','Malheur à ceux qui tirent l''iniquité avec des cordes de mensonge, et le péché comme avec les traits d''un chariot!'),
('is',5,19,'crampon1923','Qui disent: " Qu''il se dépêche, qu''il hâte son œuvre, afin que nous la voyions! Qu''il s''approche et s''exécute, le décret du Saint d''Israël, et que nous sachions!... "'),
('is',5,20,'crampon1923','Malheur à ceux qui appellent le mal bien, et le bien mal, qui font des ténèbres la lumière, et de la lumière les ténèbres, qui font ce qui est doux amer, et ce qui est amer doux!'),
('is',5,21,'crampon1923','Malheur à ceux qui sont sages à leurs propres yeux, et intelligents à leur propre sens!'),
('is',5,22,'crampon1923','Malheur à ceux qui sont des héros pour boire le vin, et des vaillants pour mêler les liqueurs fortes!'),
('is',5,23,'crampon1923','A ceux qui justifient le méchant pour un présent, et qui privent les justes de leur droit!'),
('is',5,24,'crampon1923','C''est pourquoi, comme la langue du feu dévore le chaume, et comme l''herbe sèche s''abîme dans la flamme, leur racine sera semblable à la pourriture, et leur fleur sera emportée comme la poussière; car ils ont rejeté la loi de Yahweh des armées, et méprisé la parole du Saint d''Israël.'),
('is',5,25,'crampon1923','C''est pourquoi la colère de Yahweh s''est embrasée contre son peuple; il a étendu la main contre lui, et il l''a frappé; les montagnes sont ébranlées; leurs cadavres gisent au milieu des chemins, comme de l''ordure. Avec tout cela, sa colère ne s''est pas détournée, et sa main reste étendue.'),
('is',5,26,'crampon1923','Il dresse une bannière pour les nations éloignées; il les siffle des extrémités de la terre. Et voici qu''ils arrivent, prompts et légers.'),
('is',5,27,'crampon1923','Il n''y en a pas un qui soit las et qui chancelle, pas un qui sommeille ou qui dorme; à aucun la ceinture de ses reins ne se détache, ni la courroie de ses sandales ne se rompt.'),
('is',5,28,'crampon1923','Leurs flèches sont aiguisées, leurs arcs sont tous tendus; les sabots de leurs chevaux sont durs comme le caillou, les roues de leurs chars pareilles à l''ouragan.'),
('is',5,29,'crampon1923','Leur rugissement est celui du lion; ils rugissent comme le lionceau: il gronde et saisit sa proie; il l''emporte et personne ne la lui arrache.'),
('is',5,30,'crampon1923','En ce temps-là, il y aura sur le peuple un grondement, semblable au grondement de la mer. On regardera le pays, et voilà les ténèbres! Angoisse et lumière! Puis la nuit s''étend sur le ciel du pays.'),
('is',6,1,'crampon1923','L''année de la mort du roi Ozias, je vis le Seigneur assis sur un trône haut et élevé, et les pans de sa robe remplissaient le temple.'),
('is',6,2,'crampon1923','Des Séraphins se tenaient devant lui; ils avaient chacun six ailes: de deux ils se couvraient la face, de deux ils se couvraient les pieds, et de deux ils volaient.'),
('is',6,3,'crampon1923','Et ils criaient l''un à l''autre et disaient: " Saint, saint, saint est Yahweh des armées! toute la terre est pleine de sa gloire. "'),
('is',6,4,'crampon1923','Les fondements des portes étaient ébranlés par la voix de celui qui criait, et la maison se remplit de fumée.'),
('is',6,5,'crampon1923','Alors je dis: " Malheur à moi! je suis perdu! car je suis un homme aux lèvres souillées, et j''habite au milieu d''un peuple aux lèvres souillées, et mes yeux ont vu le Roi, Yahweh des armées! "'),
('is',6,6,'crampon1923','Mais l''un des Séraphins vola vers moi, tenant à la main un charbon ardent, qu''il avait pris sur l''autel avec des pincettes.'),
('is',6,7,'crampon1923','Il en toucha ma bouche et dit: " Vois, ceci a touché tes lèvres; ton iniquité est enlevée et ton péché expié. "'),
('is',6,8,'crampon1923','Et j''entendis la voix du Seigneur qui disait: " Qui enverrai-je, et qui ira pour nous? " Et je dis: " Me voici, envoyez-moi. "'),
('is',6,9,'crampon1923','Il dit: " Va, et dis à ce peuple: Entendez, et ne comprenez point; voyez, et n''ayez point l''intelligence.'),
('is',6,10,'crampon1923','Appesantis le cœur de ce peuple, et rends dures ses oreilles, et bouche-lui les yeux, en sorte qu''il ne voie point de ses yeux et n''entende point de ses oreilles, et qu''il ne se convertisse point et ne soit point guéri. "'),
('is',6,11,'crampon1923','Et je dis: " jusques à quand, Seigneur? " Il répondit: " Jusqu''à ce que les villes soient dévastées et sans habitants, que les maisons soient sans hommes, et que la terre soit ravagée et déserte;'),
('is',6,12,'crampon1923','jusqu''à ce que Yahweh ait éloigné les hommes, et que la solitude soit grande dans le pays.'),
('is',6,13,'crampon1923','Et s''il y reste encore un dixième de ses habitants, il sera anéanti à son tour. Mais, comme le térébinthe et le chêne, quand ils sont abattus, conservent leur souche, le tronc d''Israël sera une semence sainte. "'),
('is',7,1,'crampon1923','Il arriva du temps d''Achaz, fils de Joatham, fils d''Ozias, roi de Juda, que Rasin, roi de Syrie, avec Phacée, fils de Romélie, roi d''Israël, monta contre Jérusalem pour l''attaquer; mais il ne put s''en emparer.'),
('is',7,2,'crampon1923','On annonça à la maison de David cette nouvelle: " La Syrie est campée en Ephraïm. " Alors le cœur du roi et le cœur de son peuple furent agités comme les arbres de la forêt sont agités par le vent.'),
('is',7,3,'crampon1923','Et Yahweh dit à Isaïe: " Sors à la rencontre d''Achaz, toi et Schéar-Jasub, ton fils, vers l''extrémité du canal de l''étang supérieur, sur le chemin du champ du foulon.'),
('is',7,4,'crampon1923','Et tu lui diras: Prends garde, tiens-toi tranquille, ne crains point, et que ton cœur ne défaille point devant ces deux bouts de tisons fumants, à cause de la fureur de Rasin et de la Syrie, et du fils de Romélie.'),
('is',7,5,'crampon1923','Parce que la Syrie a médité le mal contre toi ainsi qu''Ephraïm et le fils de Romélie, en disant:'),
('is',7,6,'crampon1923','" Montons contre Juda, jetons-le dans l''épouvante, envahissons-le, et établissons-y pour roi le fils de Tabéel;'),
('is',7,7,'crampon1923','ainsi parle le Seigneur Yahweh: Cela n''aura pas d''effet, cela ne sera pas!'),
('is',7,8,'crampon1923','Car la tête de la Syrie, c''est Damas, et la tête de Damas, c''est Rasin; et encore soixante-cinq ans, et Ephraïm aura cessé d''être un peuple.'),
('is',7,9,'crampon1923','Et la tête d''Ephraïm, c''est Samarie, et la tête de Samarie, c''est le fils de Romélie. Si vous ne croyez pas, vous ne subsisterez pas! "'),
('is',7,10,'crampon1923','Yahweh parla encore à Achaz, en disant:'),
('is',7,11,'crampon1923','" Demande un signe à Yahweh, ton Dieu, demande-le dans les profondeurs du schéol ou dans les hauteurs du ciel. "'),
('is',7,12,'crampon1923','Mais Achaz dit: " Je ne le demanderai pas, je ne tenterai pas Yahweh. "'),
('is',7,13,'crampon1923','Et Isaïe dit: " Ecoutez, maison de David: Est-ce trop peu pour vous de fatiguer les hommes, que vous fatiguiez aussi mon Dieu?'),
('is',7,14,'crampon1923','C''est pourquoi le Seigneur lui-même vous donnera un signe: Voici que la Vierge a conçu, et elle enfante un fils, et elle lui donne le nom d''Emmanuel.'),
('is',7,15,'crampon1923','Il mangera de la crème et du miel, jusqu''à ce qu''il sache rejeter le mal et choisir le bien.'),
('is',7,16,'crampon1923','Car avant que l''enfant sache rejeter le mal et choisir le bien, le pays dont tu redoutes les deux rois sera dévasté.'),
('is',7,17,'crampon1923','Yahweh fera venir sur toi et sur ton peuple, et sur la maison de ton père, des jours tels qu''il n''en est pas venu depuis le jour où Ephraïm s''est séparé de Juda, — le roi d''Assyrie. "'),
('is',7,18,'crampon1923','En ce jour-là, Yahweh sifflera la mouche qui est à l''extrémité des fleuves d''Egypte, et l''abeille qui est au pays d''Assyrie.'),
('is',7,19,'crampon1923','Elles viendront et se poseront toutes dans les vallées escarpées et dans les fentes des rochers, sur tous les buissons et sur tous les pâturages.'),
('is',7,20,'crampon1923','En ce jour-là, le Seigneur rasera avec un rasoir qu''il aura loué au delà du Fleuve — avec le roi d''Assyrie, — la tête et le poil des pieds, et il enlèvera aussi la barbe.'),
('is',7,21,'crampon1923','En ce jour-là, un homme nourrira une vache et deux brebis,'),
('is',7,22,'crampon1923','et, à cause de l''abondance du lait qu''elles donneront, on ne mangera plus que de la crème; car c''est de la crème et du miel que mangeront tous ceux qui seront restés dans le pays.'),
('is',7,23,'crampon1923','En ce jour-là, tout endroit où il y avait mille ceps de vigne, valant mille pièces d''argent, sera couvert de ronces et d''épines.'),
('is',7,24,'crampon1923','On y entrera avec des flèches et avec l''arc, car tout le pays ne sera que ronces et épines.'),
('is',7,25,'crampon1923','Et sur toutes les montagnes que l''on cultivait avec le sarcloir, tu n''iras plus, par crainte des ronces et des épines, elles seront un pâturage de bœufs, et une terre foulée par les brebis.'),
('is',8,1,'crampon1923','Et Yahweh me dit: " Prends une grande tablette, et écris-y en caractères lisibles à tous: Hâtez le pillage! Butinez vite! "'),
('is',8,2,'crampon1923','Et je pris avec moi des témoins dignes de foi, le prêtre Urie et Zacharie, fils de Jébarachie.'),
('is',8,3,'crampon1923','Et je m''approchai de la prophétesse, et elle conçut et enfanta un fils. Et Yahweh me dit: " Appelle-le Maher-Schalal-Chasch-Baz.'),
('is',8,4,'crampon1923','Car avant que l''enfant sache crier: Mon père, ma mère! on portera les richesses de Damas et les dépouilles de Samarie devant le roi d''Assyrie. "'),
('is',8,5,'crampon1923','Yahweh me parla encore, en ces termes:'),
('is',8,6,'crampon1923','" Parce que ce peuple a méprisé les eaux de Siloé qui coulent doucement, et qu''il se réjouit au sujet de Rasin et du fils de Romélie,'),
('is',8,7,'crampon1923','à cause de cela, voici que le Seigneur va faire venir sur eux les eaux du fleuve, fortes et profondes, le roi d''Assyrie et toute sa puissance. Il s''élèvera partout au-dessus de son lit, et se répandra par-dessus toutes ses rives;'),
('is',8,8,'crampon1923','il pénétrera en Juda, il débordera, il inondera, il montera jusqu''au cou; et le déploiement de ses ailes couvrira toute l''étendue de ton pays, ô Emmanuel. "'),
('is',8,9,'crampon1923','Poussez des cris de guerre, peuples, et vous serez défaits! prêtez l''oreille, vous toutes, extrémités de la terre! Equipez-vous, et vous serez défaits! Equipez-vous, et vous serez défaits!'),
('is',8,10,'crampon1923','Formez des projets, et ils seront anéantis; donnez des ordres, et ils resteront sans effet; car Dieu est avec nous!'),
('is',8,11,'crampon1923','Car ainsi m''a parlé Yahweh, quand sa main me saisit et qu''il m''avertit de ne pas suivre la voie de ce peuple, en disant:'),
('is',8,12,'crampon1923','" N''appelez pas conjuration tout ce que ce peuple appelle conjuration; ne craignez point ce qu''il craint, et ne vous effrayez pas.'),
('is',8,13,'crampon1923','Yahweh des armées, c''est lui que vous sanctifierez, lui qui sera votre crainte et votre frayeur.'),
('is',8,14,'crampon1923','Et il sera un sanctuaire; mais aussi une pierre d''achoppement et un rocher de scandale pour les deux maisons d''Israël, un filet et un piège pour les habitants de Jérusalem.'),
('is',8,15,'crampon1923','Beaucoup d''entre eux trébucheront, ils tomberont et se briseront; ils seront enlacés et pris.'),
('is',8,16,'crampon1923','Lie le témoignage, scelle l''enseignement dans le cœur de mes disciples. "'),
('is',8,17,'crampon1923','J''espère en Yahweh qui cache sa face à la maison de Jacob, et je me confie en lui.'),
('is',8,18,'crampon1923','Voici que moi et mes enfants que Dieu m''a donnés, nous sommes des signes et des présages en Israël, de la part de Yahweh des armées, qui habite sur la montagne de Sion.'),
('is',8,19,'crampon1923','Quand ils vous diront: " Consultez ceux qui évoquent les morts, et les devins qui murmurent et chuchotent, " répondez: " Un peuple ne doit-il pas consulter son Dieu? Consultera-t-il les morts pour les vivants?'),
('is',8,20,'crampon1923','A l''enseignement et au témoignage! " Si le peuple tient un autre langage, il n''y a point pour lui d''aurore.'),
('is',8,21,'crampon1923','Il errera dans le pays, accablé de misère et affamé, et, quand il aura faim, il maudira, dans sa fureur, son roi et son Dieu.'),
('is',8,22,'crampon1923','Il élèvera ses regards en haut, et les abaissera vers la terre: et voici la détresse, l''obscurité, une sombre angoisse; il sera rejeté dans les ténèbres.'),
('is',8,23,'crampon1923','Mais il n''y a plus de ténèbres pour la terre qui a été dans l''angoisse. Comme le premier temps a couvert d''opprobre le pays de Zabulon et le pays de Nephtali, le dernier temps remplira de gloire le chemin de la mer, le pays d''au delà du Jourdain et le district des nations.'),
('is',8,24,'crampon1923',''),
('is',9,1,'crampon1923','Le peuple qui marchait dans les ténèbres a vu une grande lumière, et sur ceux qui habitaient le pays de l''ombre de la mort, la lumière a resplendi.'),
('is',9,2,'crampon1923','Vous avez multiplié votre peuple vous avez rendu grande la joie; il se réjouit devant vous comme on se réjouit à la moisson, comme on pousse des cris au partage du butin.'),
('is',9,3,'crampon1923','Car le, joug qui pesait sur lui, la verge qui frappait son épaule, le bâton de son exacteur, vous les avez brisés comme au jour de Madian!'),
('is',9,4,'crampon1923','Car toute sandale du guerrier dans la mêlée, et tout manteau roulé dans le sang sont livrés à l''incendie; le feu les dévore.'),
('is',9,5,'crampon1923','Car un enfant nous est né, un fils nous a été donné; l''empire a été posé sur ses épaules, et on lui donne pour nom: Conseiller admirable, Dieu fort, Père éternel, Prince de la paix:'),
('is',9,6,'crampon1923','Pour étendre l''empire et pour donner une paix sans fin au trône de David et à sa royauté, pour l''établir et l''affermir dans le droit et dans la justice, dès maintenant et à toujours. Le zèle de Yahweh des armées fera cela.'),
('is',9,7,'crampon1923','Le Seigneur a envoyé une parole à Jacob, et elle est tombée en Israël;'),
('is',9,8,'crampon1923','tout le peuple en aura connaissance, Ephraïm et les habitants de Samarie; eux qui disent dans leur orgueil, et dans la fierté de leur cœur:'),
('is',9,9,'crampon1923','" Les briques sont tombées, bâtissons en pierres de taille; les sycomores sont coupés, remplaçons-les par des Cèdres. "'),
('is',9,10,'crampon1923','Yahweh fait lever contre eux les adversaires de Rasin, et il aiguillonne leurs ennemis,'),
('is',9,11,'crampon1923','la Syrie à l''Orient, les Philistins à l''Occident, et ils dévoreront Israël à pleine bouche. Avec tout cela, sa colère ne s''est point détournée, et sa main reste étendue.'),
('is',9,12,'crampon1923','Car le peuple n''est pas revenu à Celui qui le frappait, et ils n''ont pas recherché Yahweh des armées.'),
('is',9,13,'crampon1923','Et Yahweh retranchera d''Israël la tête et la queue, la palme et le jonc, en un seul jour.'),
('is',9,14,'crampon1923','L''ancien et le noble, c''est la tête, et le prophète qui enseigne le mensonge, c''est la queue.'),
('is',9,15,'crampon1923','Ceux qui guident ce peuple l''égarent, et ceux qui s''ont guidés se perdent.'),
('is',9,16,'crampon1923','C''est pourquoi le Seigneur ne prendra pas plaisir en ses jeunes gens, et il n''aura pas compassion de ses orphelins et de ses veuves; car tous sont des impies et des pervers, et toute bouche profère l''impiété. Avec tout cela, sa colère ne s''est point détournée, et sa main reste étendue.'),
('is',9,17,'crampon1923','Car la malice s''est allumée comme un feu; elle dévore les ronces et les épines; elle embrase les halliers de la forêt, et la fumée s''élève en tourbillons.'),
('is',9,18,'crampon1923','Par le courroux de Yahweh des armées, le pays est embrasé, et le peuple est devenu la proie des flammes. Nul n''épargne son frère.'),
('is',9,19,'crampon1923','On coupe à droite, et l''on a faim; on dévore à gauche, et l''on n''est point rassasié; chacun dévore la chair de son bras; Manassé contre Ephraïm, Ephraïm contre Manassé, tous deux ensemble contre Juda.'),
('is',9,20,'crampon1923','Avec tout cela, sa colère ne s''est point détournée, et sa main reste étendue.'),
('is',9,21,'crampon1923',''),
('is',10,1,'crampon1923','Malheur à ceux qui rendent des arrêts iniques, et aux scribes qui écrivent des sentences injustes,'),
('is',10,2,'crampon1923','écartant du tribunal les faibles, et dépouillant de leur droit les affligés de mon peuple, faisant des veuves leur proie, et pillant les orphelins!'),
('is',10,3,'crampon1923','Que ferez-vous au jour de la visite, et dans la catastrophe qui viendra de loin? Vers qui fuirez-vous pour avoir du secours, et où déposerez-vous vos trésors?'),
('is',10,4,'crampon1923','Il ne reste qu''à se courber parmi les captifs, ou à tomber parmi les tués. Avec tout cela, sa colère ne s''est point détournée, et sa main reste étendue.'),
('is',10,5,'crampon1923','Malheur à Assur, verge de ma colère! Le bâton qui est dans sa main est l''instrument de ma fureur;'),
('is',10,6,'crampon1923','je l''envoie contre une nation impie, je lui donne mes ordres contre le peuple de mon courroux, pour le mettre au pillage et faire du butin, et le fouler au pied comme la boue des rues.'),
('is',10,7,'crampon1923','Mais lui, ce n''est pas ainsi qu''il l''entend, et telle n''est pas la pensée de son cœur; car il ne songe qu''à détruire, et à exterminer des nations, non en petit nombre.'),
('is',10,8,'crampon1923','Il dit: " Mes princes ne sont-ils pas tous des rois?'),
('is',10,9,'crampon1923','N''en a-t-il pas été de Calno comme de Carchémis, et de Hamath comme d''Arphad, et de Samarie comme de Damas?'),
('is',10,10,'crampon1923','Comme ma main a atteint les royaumes des divinités impuissantes, dont les idoles l''emportaient sur celles de Jérusalem et de Samarie; comme j''ai fait à Samarie et à ses dieux,'),
('is',10,11,'crampon1923','ne ferai-je pas de même à Jérusalem et à ses images? "'),
('is',10,12,'crampon1923','Mais il arrivera: Quand le Seigneur aura accompli toute son œuvre, sur la montagne de Sion et à Jérusalem: " Je visiterai le fruit du cœur hautain du roi d''Assyrie, et l''arrogance de ses regards altiers. "'),
('is',10,13,'crampon1923','Car il a dit: " Par la force de ma main j''ai fait cela, et par ma sagesse, car je suis intelligent! J''ai déplacé les bornes des peuples, j''ai pillé leurs trésors, et, comme un héros, j''ai renversé du trône ceux qui y étaient assis.'),
('is',10,14,'crampon1923','Ma main a saisi, comme un nid, les richesses des peuples, et, comme on ramasse des œufs abandonnés, j''ai ramassé toute la terre, sans que nul ait remué l''aile, ouvert le bec ou poussé un cri! " —'),
('is',10,15,'crampon1923','La hache se glorifie-t-elle contre la main qui la brandit, la scie s''élève-t''elle contre celui qui la meut? Comme si la verge faisait mouvoir celui qui la lève, comme si le bâton soulevait ce qui n''est pas du bois!'),
('is',10,16,'crampon1923','C''est pourquoi le Seigneur Yahweh des armées, enverra le dépérissement sur ses robustes guerriers, et sous sa magnificence s''embrasera un feu, comme le feu d''un incendie.'),
('is',10,17,'crampon1923','La lumière d''Israël sera un feu, et son Saint, une flamme, qui consumera et dévorera ses épines et ses ronces, en un seul jour.'),
('is',10,18,'crampon1923','Et la gloire de sa forêt et de son verger, il l''anéantira de l''âme au corps; ce sera comme un malade qui meurt de consomption.'),
('is',10,19,'crampon1923','Le reste des arbres de sa forêt pourra être compté; un enfant les inscrirait.'),
('is',10,20,'crampon1923','Et il arrivera en ce jour-là: Le reste d''Israël et les réchappés de la maison de Jacob ne continueront pas de s''appuyer sur celui qui les frappait, mais ils s''appuieront sur Yahweh, le Saint d''Israël, avec fidélité.'),
('is',10,21,'crampon1923','Un reste reviendra, un reste de Jacob, vers le Dieu fort.'),
('is',10,22,'crampon1923','Car, quand ton peuple, ô Israël, serait comme le sable de la mer, c''est un reste qui reviendra; la destruction est résolue, elle fera déborder la justice.'),
('is',10,23,'crampon1923','Car la destruction qu''il a décrétée, le Seigneur Yahweh des armées l''accomplira dans tout le pays.'),
('is',10,24,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh des armées: " Ne crains rien d''Assur, ô mon peuple, qui habite Sion, quand il te frappera de la verge, et qu''il lèvera sur toi le bâton, comme autrefois l''Egypte.'),
('is',10,25,'crampon1923','Car, encore bien peu de temps, et mon courroux cessera, et ma colère se tournera contre eux pour les détruire.'),
('is',10,26,'crampon1923','Et Yahweh des armées lèvera contre eux le fouet, comme il frappa Madian au rocher d''Oreb, et comme son bâton fut sur la mer; et il le lèvera, comme autrefois en Egypte.'),
('is',10,27,'crampon1923','Et il arrivera en ce jour-là: Le fardeau d''Assur sera ôté de ton épaule, et son joug de dessus ton cou, et ta vigueur fera éclater le joug.'),
('is',10,28,'crampon1923','Il est venu à Ajath, il a passé à Magron, il laisse son bagage à Machmas.'),
('is',10,29,'crampon1923','Ils ont passé le défilé; ils ont campé la nuit à Gaba; Rama est dans l''épouvante; Gabaa de Saül prend la fuite.'),
('is',10,30,'crampon1923','Pousse des cris de détresse, fille de Gallim! Prête l''oreille, Laïs! Pauvre Anathoth!'),
('is',10,31,'crampon1923','Medména se disperse, les habitants de Gabim sont en fuite.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('is',10,32,'crampon1923','Encore un jour et il sera à Nobé; il lèvera sa main contre la montagne de la fille de Sion, contre la colline de Jérusalem!...'),
('is',10,33,'crampon1923','Voici que le Seigneur, Yahweh des armées, abat avec fracas la ramure des arbres; les plus hauts sont coupés, les plus élevés sont jetés par terre.'),
('is',10,34,'crampon1923','Les fourrés de la forêt sont taillés avec le fer, et le Liban tombe sous les coups d''un Puissant.'),
('is',11,1,'crampon1923','Un rameau sortira du tronc de Jessé, et de ses racines croîtra un rejeton.'),
('is',11,2,'crampon1923','Sur lui reposera l''Esprit de Yahweh, esprit de sagesse et d''intelligence, esprit de conseil et de force, esprit de connaissance et de crainte de Yahweh;'),
('is',11,3,'crampon1923','Il mettra ses délices dans la crainte de Yahweh. Il ne jugera point sur ce qui paraîtra à ses yeux, et il ne prononcera point sur ce qui frappera ses oreilles.'),
('is',11,4,'crampon1923','Il jugera les petits avec justice, et prononcera selon le droit pour les humbles de la terre. Il frappera la terre de la verge de sa bouche, et par le souffle de ses lèvres il fera mourir le méchant.'),
('is',11,5,'crampon1923','La justice ceindra ses flancs, et la fidélité sera la ceinture de ses reins.'),
('is',11,6,'crampon1923','Le loup habitera avec l''agneau, la panthère reposera avec le chevreau; le veau, le lion et le bœuf gras vivront ensemble, et un jeune enfant les conduira.'),
('is',11,7,'crampon1923','La vache et l''ourse iront au même pâturage, leurs petits auront un même gîte; et le lion mangera du fourrage comme le bœuf.'),
('is',11,8,'crampon1923','Le nourrisson s''ébattra sur le trou de la vipère, et dans le repaire du basilic l''enfant à peine sevré mettra sa main.'),
('is',11,9,'crampon1923','On ne fera point de mal et on ne détruira plus sur toute ma montagne sainte; car le pays sera rempli de la connaissance de Yahweh, comme le fond des mers par les eaux qui le couvrent.'),
('is',11,10,'crampon1923','Et il arrivera en ce jour-là: La racine de Jessé, élevée comme un étendard pour les peuples, sera recherchée par les nations, et son séjour sera glorieux.'),
('is',11,11,'crampon1923','Et il arrivera en ce jour-là: le Seigneur étendra une seconde fois sa main pour racheter le reste de son peuple, ce qui subsistera aux pays d''Assyrie et d''Egypte, de Patros, d''Ethiopie, d''Elam, de Sennaar, de Hamath et des îles de la mer.'),
('is',11,12,'crampon1923','Il élèvera un étendard pour les nations, et il rassemblera les bannis d''Israël; il recueillera les dispersés de Juda, des quatre bouts de la terre.'),
('is',11,13,'crampon1923','La jalousie d''Ephraïm disparaîtra et les inimitiés de Juda cesseront; Ephraïm ne sera plus jaloux de Juda, et Juda ne sera plus l''ennemi d''Ephraïm.'),
('is',11,14,'crampon1923','Ils voleront sur l''épaule des Philistins à l''Occident; ils pilleront de concert les fils de l''Orient; ils mettront la main sur Edom et Moab, et les fils d''Ammon leur seront soumis.'),
('is',11,15,'crampon1923','Yahweh frappera d''anathème la langue de la mer d''Egypte; et il lèvera la main contre le Fleuve, dans la vigueur de son souffle; et, le frappant, il le partagera en sept ruisseaux, et fera qu''on y marche en sandales.'),
('is',11,16,'crampon1923','Et ainsi il y aura une route pour le reste de son peuple, ce qui en subsistera au pays d''Assyrie, comme il y en eut une pour Israël au jour où il monta du pays d''Egypte.'),
('is',12,1,'crampon1923','Et tu diras en ce jour-là: Je te loue, Yahweh, car tu étais irrité, mais ta colère s''est détournée et tu me consoles.'),
('is',12,2,'crampon1923','Voici le Dieu de ma délivrance; j''ai confiance et je ne crains pas; car ma force et ma louange c''est Yahweh, Yahweh; il a été pour moi le salut. —'),
('is',12,3,'crampon1923','Vous puiserez des eaux avec joie aux sources du salut,'),
('is',12,4,'crampon1923','et vous direz en ce jour-là: Louez Yahweh, invoquez son nom, publiez parmi les peuples ses grandes œuvres, proclamez que son nom est élevé.'),
('is',12,5,'crampon1923','Chantez Yahweh, car il a fait des choses magnifiques; qu''on le sache dans toute la terre!'),
('is',12,6,'crampon1923','Pousse des cris, tressaille d''allégresse, habitante de Sion, car le Saint d''Israël est grand au milieu de toi!'),
('is',13,1,'crampon1923','Oracle sur Babylone, révélé à Isaïe, fils d''Amots.'),
('is',13,2,'crampon1923','Sur une montagne nue levez un étendard; appelez-les à haute voix, faites des signes de la main, et qu''ils franchissent les portes des princes.'),
('is',13,3,'crampon1923','Moi, j''ai donné ordre à mes consacrés; j''ai appelé mes héros pour servir ma colère, ceux qui acclament avec joie ma majesté.'),
('is',13,4,'crampon1923','On entend sur les montagnes une rumeur: on dirait le bruit d''un peuple nombreux; on entend un tumulte de royaumes, de nations rassemblées: C''est Yahweh des armées qui passe en revue ses troupes de guerre.'),
('is',13,5,'crampon1923','Ils viennent d''un pays lointain, de l''extrémité du ciel, Yahweh et les instruments de son courroux, pour ravager toute la terre.'),
('is',13,6,'crampon1923','Poussez des hurlements, car le jour de Yahweh est proche: il vient comme une dévastation du Tout-puissant.'),
('is',13,7,'crampon1923','C''est pourquoi toute main sera défaillante, et tout cœur d''homme se fondra.'),
('is',13,8,'crampon1923','Ils trembleront, les transes et les douleurs les saisiront; ils se tordront comme une femme qui enfante; ils se regarderont les uns les autres avec stupeur; leurs visages seront comme la flamme.'),
('is',13,9,'crampon1923','Voici que le jour de Yahweh est venu, jour cruel, de fureur et d''ardente colère, pour réduire la terre en désert, et en exterminer les pécheurs.'),
('is',13,10,'crampon1923','Car les étoiles du ciel et leurs constellations ne font point briller leur lumière; le soleil s''est obscurci à son lever, et la lune ne répand plus sa clarté.'),
('is',13,11,'crampon1923','Je punirai le monde pour sa malice, et les méchants pour leur iniquité; je ferai cesser l''arrogance des superbes, et j''abaisserai l''orgueil des tyrans.'),
('is',13,12,'crampon1923','Je rendrai les hommes plus rares que l''or fin, plus rares que l''or d''Ophir.'),
('is',13,13,'crampon1923','C''est pourquoi je ferai trembler les cieux, et la terre sera ébranlée de sa place, par la fureur de Yahweh des armées, au jour où s''allumera sa colère.'),
('is',13,14,'crampon1923','Alors, comme une gazelle que l''on poursuit, comme un troupeau que personne ne rassemble, chacun se tournera vers son peuple, et s''enfuira dans son pays.'),
('is',13,15,'crampon1923','Tous ceux qu''on trouvera seront transpercés, tous ceux qu''on saisira tomberont par l''épée.'),
('is',13,16,'crampon1923','Leurs petits enfants seront écrasés sous leurs yeux, leurs maisons pillées et leurs femmes violées.'),
('is',13,17,'crampon1923','Voici que je fais lever contre eux les Mèdes, qui ne font point cas de l''argent, et ne convoitent pas l''or.'),
('is',13,18,'crampon1923','Leurs arcs écraseront les jeunes gens; ils ne feront point grâce au fruit des entrailles; leur œil n''aura pas pitié des enfants.'),
('is',13,19,'crampon1923','Et Babylone, l''ornement des royaumes, la parure des fiers Chaldéens, sera comme Sodome et Gomorrhe que Dieu a détruites.'),
('is',13,20,'crampon1923','Elle ne sera jamais plus peuplée, elle ne sera plus habitée dans le cours des âges; l''Arabe n''y dressera pas sa tente, et le berger n''y parquera pas ses troupeaux.'),
('is',13,21,'crampon1923','Les animaux du désert y feront leur gîte; les hiboux rempliront ses maisons; là habiteront les autruches, et le satyre y bondira.'),
('is',13,22,'crampon1923','Les chacals hurleront dans ses palais déserts, et les chiens sauvages dans ses maisons de plaisir. Son temps est proche, et ses jours ne seront pas prolongés.'),
('is',14,1,'crampon1923','Car Yahweh aura pitié de Jacob, et il choisira encore Israël; il les rétablira dans leur pays; les étrangers s''adjoindront à eux, et s''attacheront à la maison de Jacob.'),
('is',14,2,'crampon1923','Les peuples les prendront et les ramèneront chez eux, et la maison d''Israël se les appropriera, sur la terre de Yahweh, comme serviteurs et comme servantes; ils feront captifs ceux qui les avaient faits captifs; et ils domineront sur leurs oppresseurs.'),
('is',14,3,'crampon1923','Et au jour où Yahweh te fera reposer de ton labeur, de tes anxiétés, et de la dure servitude qu''on t''avait imposée,'),
('is',14,4,'crampon1923','tu entonneras cette satire contre le roi de Babylone, et tu diras: Comment a fini le tyran, a cessé l''oppression?'),
('is',14,5,'crampon1923','Yahweh a brisé le talon des méchants, le sceptre des dominateurs!'),
('is',14,6,'crampon1923','Il frappait avec fureur les peuples, de coups sans relâche; dans sa colère, il tenait les nations sous le joug par une persécution sans répit.'),
('is',14,7,'crampon1923','Toute la terre est en repos, elle est tranquille, elle éclate en cris d''allégresse.'),
('is',14,8,'crampon1923','Les Cyprès mêmes se réjouissent de ta chute, avec les cèdres du Liban: " Depuis que tu es couché là, personne ne monte plus pour nous abattre! "'),
('is',14,9,'crampon1923','Le schéol dans ses profondeurs s''émeut à ton sujet, pour venir à ta rencontre; il réveille pour toi les ombres, tous les monarques de la terre; il fait lever de leurs trônes tous les rois des nations.'),
('is',14,10,'crampon1923','Tous, ils prennent la parole pour te dire: " Toi aussi, tu es déchu comme nous, et te voilà semblable à nous! "'),
('is',14,11,'crampon1923','Ton faste est descendu au schéol, avec le son de tes harpes; sous toi sont répandus les vers, et la vermine est ta couverture!'),
('is',14,12,'crampon1923','Comment es-tu tombé du ciel, astre brillant, fils de l''aurore? Comment es-tu renversé par terre, toi, le destructeur des nations?'),
('is',14,13,'crampon1923','Toi qui disais en ton cœur: " Je monterai dans les cieux; au-dessus des étoiles de Dieu, j''élèverai mon trône; je m''assiérai sur la montagne de l''assemblée, dans les profondeurs du septentrion;'),
('is',14,14,'crampon1923','je monterai sur les sommets des nues, je serai semblable au Très-Haut!... "'),
('is',14,15,'crampon1923','Et te voilà descendu au schéol, dans les profondeurs de l''abîme!'),
('is',14,16,'crampon1923','Ceux qui te voient fixent sur toi leurs regards, ils te considèrent avec attention: " Est-ce là l''homme qui troublait la terre, qui ébranlait les royaumes,'),
('is',14,17,'crampon1923','qui faisait du monde un désert, détruisait les villes, et ne laissait pas ses captifs revenir chez eux?'),
('is',14,18,'crampon1923','Tous les rois des nations, tous, reposent avec honneur, chacun dans sa maison;'),
('is',14,19,'crampon1923','mais toi, on t''a jeté loin de ton sépulcre, comme un rameau qu''on méprise, couvert de morts, égorgés par l''épée, et précipités dans les flancs rocheux de l''abîme; comme un cadavre qu''on foule aux pieds.'),
('is',14,20,'crampon1923','Tu ne seras pas avec eux dans la tombe car tu as ruiné ton pays, tu as fait périr ton peuple! On ne nommera plus jamais la race des méchants.'),
('is',14,21,'crampon1923','Préparez à ses fils un massacre, pour le crime de leurs pères. Qu''ils ne se relèvent pas pour conquérir la terre, qu''ils ne couvrent pas de villes la face du monde!'),
('is',14,22,'crampon1923','Je me lèverai contre eux, — oracle de Yahweh des armées, — et j''anéantirai de Babylone le nom et le reste, la race et le rejeton, — oracle de Yahweh.'),
('is',14,23,'crampon1923','Et j''en ferai un nid de hérissons, et un étang d''eaux, et je la balaierai avec le balai de la destruction, — oracle de Yahweh des armées.'),
('is',14,24,'crampon1923','Yahweh des armées a juré en disant: " Oui, le dessein qui est arrêté s''accomplira, et ce que j''ai décidé se réalisera.'),
('is',14,25,'crampon1923','Je briserai Assur dans ma terre, et je le foulerai sur mes montagnes. Alors son joug sera ôté de dessus eux, et son fardeau sera enlevé de leurs épaules.'),
('is',14,26,'crampon1923','C''est là le dessein qui est arrêté contre toute la terre, et c''est là la main qui est étendue contre toutes les nations!'),
('is',14,27,'crampon1923','Car Yahweh des armées a décidé, et qui l''empêcherait? Sa main est étendue, et qui la détournerait? "'),
('is',14,28,'crampon1923','L''année de la mort du roi Achaz, cet oracle fut prononcé:'),
('is',14,29,'crampon1923','Ne te livre pas à la joie, Philistie tout entière, de ce que la verge qui te frappait a été brisée; car de la race du serpent sortira un basilic, et son fruit sera un dragon volant.'),
('is',14,30,'crampon1923','Alors les plus pauvres trouveront leur pâture, et les malheureux reposeront en sécurité; mais je ferai périr ta race par la faim, et ce qui restera de toi sera exterminé. —'),
('is',14,31,'crampon1923','Hurle, ô porte! Pousse des cris, ô ville! Pâme-toi de frayeur, Philistie tout entière! Car du septentrion vient une fumée, et nul ne se débande dans ses bataillons.'),
('is',14,32,'crampon1923','Que répondra-t-on aux envoyés de la nation? Que Yahweh a fondé Sion, et que les affligés de son peuple y trouvent un refuge.'),
('is',15,1,'crampon1923','Oracle sur Moab. Oui, dans la nuit où elle a été saccagée, Ar-Moab a été ruinée! Dans la nuit où elle a été saccagée, Kir-Moab a été ruinée!'),
('is',15,2,'crampon1923','On monte au temple de Chamos et à Dibon, aux hauts-lieux, pour pleurer; sur Nebo et Médéba, Moab se lamente, Toute tête est rasée, toute barbe est coupée.'),
('is',15,3,'crampon1923','Dans ses rues, ils se revêtent de sacs; sur ses toits et sur ses places publiques; tous poussent des hurlements, fondent en larmes.'),
('is',15,4,'crampon1923','Hésebon et Eléalé jettent des cris; on entend leur voix jusqu''à Jahas. C''est pourquoi les guerriers de Moab se lamentent, et son âme est tremblante.'),
('is',15,5,'crampon1923','Mon cœur gémit sur Moab; ses défenseurs sont déjà à Ségor, à Eglath-Schelischiah. Oui, la montée de Luhith, on la gravit en pleurant; et sur le chemin de Horonaïm, on pousse des cris de détresse.'),
('is',15,6,'crampon1923','Car les eaux de Nimrim sont taries, l''herbe est desséchée, le gazon est détruit, il n''y a plus de verdure.'),
('is',15,7,'crampon1923','Ce qu''ils ont pu sauver et leurs provisions, ils les transportent au delà du torrent des Saules.'),
('is',15,8,'crampon1923','Car les cris ont fait le tour du territoire de Moab; ses hurlements retentissent jusqu''à Eglaïm, ses hurlements jusqu''à Béer-Elim;'),
('is',15,9,'crampon1923','car les eaux de Dimon sont pleines de sang. Car je ferai venir sur Dimon un surcroît de malheur, un lion aux réchappés de Moab, à ce qui sera resté dans le pays.'),
('is',16,1,'crampon1923','" Envoyez l''agneau du dominateur du pays, de Pétra, à travers le désert, à la montagne de la fille de Sion. "'),
('is',16,2,'crampon1923','Comme des oiseaux fugitifs, comme une nichée que l''on disperse, telles sont les filles de Moab, aux passages de l''Arnon:'),
('is',16,3,'crampon1923','" Conseille-nous, sois notre arbitre; donne-nous l''ombre, comme dans la nuit, au milieu du jour; cache ceux que l''on poursuit, ne trahis point les fugitifs.'),
('is',16,4,'crampon1923','" Que les fugitifs de Moab demeurent chez toi; sois-leur une retraite contre le dévastateur; car l''invasion a cessé, la dévastation a pris fin, les oppresseurs ont disparu du pays.'),
('is',16,5,'crampon1923','Le trône est affermi par la miséricorde, et sur ce trône s''assiéra selon la vérité, dans la tente de David, un juge poursuivant le droit, et zélé pour la justice. " —'),
('is',16,6,'crampon1923','" Nous connaissons l''orgueil de Moab, le très orgueilleux, sa fierté et son orgueil, son arrogance et ses discours mensongers. "'),
('is',16,7,'crampon1923','Que Moab se lamente donc sur Moab; que tous se lamentent! Sur les gâteaux de raisins de Kir-Haréseth gémissez, tout consternés!'),
('is',16,8,'crampon1923','Car les champs de Hésebon sont désolés; de la vigne de Sabama, les maîtres des nations ont détruit les treilles elles qui s''étendaient jusqu''à Jazer, allaient se perdre dans le désert, poussaient au loin leurs rejetons, passaient par delà la mer.'),
('is',16,9,'crampon1923','C''est pourquoi je pleure, comme pleure Jazer, sur la vigne de Sabama; je vous arrose de mes larmes, Hésebon, Eléalé, car sur vos fruits et sur votre moisson; est venu fondre le cri du pressureur.'),
('is',16,10,'crampon1923','La joie et l''allégresse ont disparu des vergers; dans les vignes, plus de chants, plus de cris de joie; le vendangeur ne foule plus le vin dans les cuves; j''ai fait cesser le cri joyeux du pressureur.'),
('is',16,11,'crampon1923','Aussi mes entrailles, au sujet de Moab, frémissent comme une harpe, ainsi que mon cœur au sujet de Kir-Harès.'),
('is',16,12,'crampon1923','Et l''on verra Moab se fatiguer sur ses hauts-lieux; il entrera dans son sanctuaire pour prier, et il n''obtiendra rien.'),
('is',16,13,'crampon1923','Tel est l''oracle que Yahweh a prononcé sur Moab depuis un long temps.'),
('is',16,14,'crampon1923','Et maintenant Yahweh parle et dit: " Dans trois ans, comptés comme les années d''un mercenaire, la gloire de Moab avec sa grande multitude sera avilie, et ce qui en restera sera peu de chose, petit et faible ".'),
('is',17,1,'crampon1923','Oracle sur Damas. Voici Damas retirée du nombre des villes; elle ne sera plus qu''un monceau de ruines!'),
('is',17,2,'crampon1923','Les villes d''Aroër sont abandonnées, elles sont livrées aux troupeaux, ils s''y reposent, et personne ne les chasse.'),
('is',17,3,'crampon1923','La forteresse sera ôtée à Ephraïm, et la royauté à Damas; il en sera du reste de la Syrie comme de la gloire des enfants d''Israël, — oracle de Yahweh des armées.'),
('is',17,4,'crampon1923','Et il arrivera en ce jour-là: La gloire de Jacob sera flétrie, et la graisse de son corps sera amaigrie.'),
('is',17,5,'crampon1923','Il en sera comme lorsque le moissonneur rassemble les gerbes, et que son bras coupe les épis; il en sera comme lorsqu''on ramasse les épis, dans la vallée de Raphaïm.'),
('is',17,6,'crampon1923','Il restera un grappillage, comme lorsqu''on secoue l''olivier, deux, trois olives au haut de la cime, quatre, cinq aux branches de l''arbre, — oracle de Yahweh, le Dieu d''Israël.'),
('is',17,7,'crampon1923','En ce jour-là, l''homme regardera vers celui qui l''a fait, et ses yeux contempleront le Saint d''Israël.'),
('is',17,8,'crampon1923','Il ne regardera plus vers les autels, œuvre de ses mains; il ne contemplera plus ce que ses doigts ont façonné, les aschérahs et les piliers du Soleil.'),
('is',17,9,'crampon1923','En ce jour-là, ses villes fortes seront comme les villes abandonnées dans les bois et les montagnes, qui furent abandonnées devant les enfants d''Israël; ce sera un désert.'),
('is',17,10,'crampon1923','Car tu as oublié le Dieu de ton salut, tu ne t''es pas souvenu du Rocher de ta force. C''est pourquoi tu plantes des plantations agréables, et tu y mets des ceps de l''étranger.'),
('is',17,11,'crampon1923','Le jour ou tu les plantes, tu les entoures d''une clôture, et, le lendemain matin, tu fais fleurir tes semences; et la moisson t''échappe au jour de la maladie et de la douleur mortelle!'),
('is',17,12,'crampon1923','Oh! Rumeur de peuples nombreux! Ils mugissent comme mugissent les mers! Grondement des nations! Elles grondent comme grondent les eaux puissantes.'),
('is',17,13,'crampon1923','Les nations grondent comme grondent les grandes eaux. Mais il les menace: elles fuient au loin; elles sont dispersées, comme la paille des hauteurs au souffle du vent, comme un tourbillon de poussière devant l''ouragan.'),
('is',17,14,'crampon1923','Au temps du soir, voici la consternation; avant le matin, ils ne sont plus. Voilà le partage de ceux qui nous pillent, et le sort de ceux qui nous dépouillent.'),
('is',18,1,'crampon1923','Oh! Terre ou résonne le bruissement des ailes, au delà des fleuves de Cusch!'),
('is',18,2,'crampon1923','Toi qui envoies des messagers sur la mer, dans des nacelles de jonc, sur la face des eaux! Allez, messagers rapides, vers la nation à la haute stature, à la peau rasée, vers le peuple redouté au loin; nation impérieuse et qui écrase, et dont la terre est sillonnée de fleuves.'),
('is',18,3,'crampon1923','Vous tous, habitants du monde, habitants de la terre, quand l''étendard sera levé sur les montagnes, regardez; quand la trompette sonnera, écoutez.'),
('is',18,4,'crampon1923','Car ainsi m''a parlé Yahweh: " Je me tiendrai en repos et je regarderai, assis dans ma demeure, comme une chaleur sereine par un brillant soleil, comme un nuage de rosée dans la chaleur de la moisson. "'),
('is',18,5,'crampon1923','Car avant la moisson, quand la floraison sera passée, et que la fleur sera devenue une grappe bientôt mûre, alors il coupera les pampres à coups de serpe, il enlèvera les sarments, il les détachera.'),
('is',18,6,'crampon1923','Ils seront livrés tous ensemble aux vautours des montagnes et aux bêtes de la terre; les vautours en feront leur proie pendant l''été, et les bêtes de la terre pendant l''hiver.'),
('is',18,7,'crampon1923','En ce temps-là, une offrande sera apportée à Yahweh des armées, de la part du peuple à la haute stature, à la peau rasée, de la part du peuple redouté au loin, nation impérieuse et qui écrase, et dont la terre est sillonnée de fleuves, au séjour du nom de Yahweh des armées, à la montagne de Sion.'),
('is',19,1,'crampon1923','Oracle sur l''Egypte. Voici que Yahweh, porté sur une nuée légère, entre en Egypte; les idoles de l''Egypte tremblent en sa présence, et le cœur de l''Egypte se fond au dedans d''elle.'),
('is',19,2,'crampon1923','Je pousserai l''Egypte contre l''Egypte, et ils se battront frère contre frère, ami contre ami, ville contre ville, royaume contre royaume.'),
('is',19,3,'crampon1923','L''esprit de l''Egypte s''évanouira en elle, et j''anéantirai son conseil; ils interrogeront les idoles et les enchanteurs, les nécromanciens et les devins.'),
('is',19,4,'crampon1923','Je livrerai l''Egypte entre les mains d''un maître dur, et un roi redoutable dominera sur eux, — oracle du Seigneur, Yahweh des armées.'),
('is',19,5,'crampon1923','Les eaux de la mer tariront, le fleuve s''épuisera et se desséchera.'),
('is',19,6,'crampon1923','Les rivières deviendront infectes; les canaux d''Egypte baisseront et se dessécheront; les joncs et les roseaux se flétriront.'),
('is',19,7,'crampon1923','Les prairies le long du Nil, sur les bords du Nil, tous les champs ensemencés le long du Nil, sécheront, s''évanouiront, et il n''y en aura plus.'),
('is',19,8,'crampon1923','Les pêcheurs gémiront et se lamenteront, tous ceux qui jettent l''hameçon dans le fleuve; ceux qui tendent le filet sur la face des eaux seront désolés.'),
('is',19,9,'crampon1923','Ceux qui travaillent le lin peigné, et ceux qui tissent le coton seront consternés.'),
('is',19,10,'crampon1923','Les colonnes de l''Egypte seront brisées, tous les artisans seront dans l''abattement.'),
('is',19,11,'crampon1923','Les princes de Tanis ne sont que des insensés; des sages conseillers de Pharaon les conseils sont stupides. Comment osez-vous dire à Pharaon: " Je suis fils des sages, fils des rois antiques? "'),
('is',19,12,'crampon1923','Où sont-ils, tes sages? Qu''ils t''annoncent donc, qu''ils devinent ce que Yahweh des armées a décrété contre l''Egypte!'),
('is',19,13,'crampon1923','Les princes de Tanis ont perdu le sens, les princes de Memphis sont dans l''illusion; ils égarent l''Egypte, eux, la pierre angulaire de ses castes.'),
('is',19,14,'crampon1923','Yahweh a répandu au milieu d''elle un esprit de vertige, et ils font errer l''Egypte dans tout ce qu''elle fait, comme erre un homme ivre dans son vomissement.'),
('is',19,15,'crampon1923','Et il n''y aura aucune œuvre qui profite à l''Egypte, de tout ce que pourra faire la tête ou la queue, la palme ou le jonc.'),
('is',19,16,'crampon1923','En ce jour-là, l''Egypte sera comme les femmes: elle tremblera et s''épouvantera en voyant se lever la main de Yahweh des armées; qu''il lève contre elle.'),
('is',19,17,'crampon1923','Et le pays de Juda sera pour l''Egypte un sujet de terreur; chaque fois qu''on le lui rappellera, elle tremblera, à cause de l''arrêt de Yahweh des armées, qu''il a porté contre elle.'),
('is',19,18,'crampon1923','En ce jour-là, il y aura cinq villes sur la terre d''Egypte, qui parleront la langue de Chanan, et qui prêteront serment à Yahweh des armées; l''une d''elles s''appellera Ville du Soleil.'),
('is',19,19,'crampon1923','En ce jour-là, il y aura un autel pour Yahweh au milieu du pays d''Egypte, et près de la frontière une stèle pour Yahweh.'),
('is',19,20,'crampon1923','Et ce sera pour Yahweh des armées un signal, et un témoignage sur la terre d''Egypte; quand ils crieront vers Yahweh, à cause des oppresseurs, il leur enverra un sauveur et un champion pour les délivrer.'),
('is',19,21,'crampon1923','Yahweh se fera connaître de l''Egypte, et l''Egypte connaîtra Yahweh, en ce jour-là; ils feront des sacrifices et des offrandes; ils feront des vœux à Yahweh et les accompliront.'),
('is',19,22,'crampon1923','Yahweh frappera l''Egypte, frappant et guérissant. Ils se convertiront à Yahweh, et il se laissera fléchir par eux et les guérira.'),
('is',19,23,'crampon1923','En ce jour-là, il y aura une route d''Egypte en Assyrie; l''Assyrien viendra en Egypte, et l''Egyptien ira en Assyrie, et l''Egypte servira Yahweh avec Assur.'),
('is',19,24,'crampon1923','En ce jour-là, Israël s''unira, lui troisième, à l''Egypte et à l''Assyrie, pour être une bénédiction au milieu de la terre.'),
('is',19,25,'crampon1923','Yahweh des armées les bénira en disant: " Bénis soient l''Egypte, mon peuple, et Assur, l''ouvrage de mes mains, et Israël, mon héritage! "'),
('is',20,1,'crampon1923','L''année où Thartan vint à Azoth, envoyé par Sargon, roi d''Assyrie, assiégea Azoth et la prit,'),
('is',20,2,'crampon1923','en ce temps-là, Yahweh parla par le ministère d''Isaïe, fils d''Amos, en disant: " Va, détache le sac qui couvre tes reins, et ôte les sandales de tes pieds. " Et il fit ainsi, marchant nu et déchaussé.'),
('is',20,3,'crampon1923','Et Yahweh dit: " De même que mon serviteur Isaïe a marché nu et déchaussé; étant pendant trois ans un signe et un présage, pour l''Egypte et pour l''Ethiopie;'),
('is',20,4,'crampon1923','ainsi le roi d''Assyrie emmènera les captifs de l''Egypte, et les déportés de l''Ethiopie, jeunes gens et vieillards, nus et déchaussés, et les reins découverts, à la honte de l''Egypte.'),
('is',20,5,'crampon1923','Alors ils seront consternés et confus, à cause de l''Ethiopie, qui était leur espoir, et de l''Egypte qui était leur sujet de gloire.'),
('is',20,6,'crampon1923','Et l''habitant de ce rivage dira en ce jour-là: Voilà ce qu''est devenu celui en qui nous espérions; celui auprès de qui nous voulions fuir pour chercher du secours, pour être délivrés, des mains du roi d''Assyrie! Et nous, comment échapperons-nous? "'),
('is',21,1,'crampon1923','Oracle sur le désert de la mer. Comme les ouragans passent dans le midi, cela vient du désert, d''une terre redoutable.'),
('is',21,2,'crampon1923','Une vision terrible m''a été montrée: le pillard pille et le ravageur ravage! Monte, Elam! Assiège, Mède! Je fais cesser tous les gémissements.'),
('is',21,3,'crampon1923','C''est pourquoi mes reins sont remplis d''angoisses; des douleurs me saisissent, comme les douleurs d''une femme qui enfante. Je me tords à entendre, je m''épouvante à voir;'),
('is',21,4,'crampon1923','mon cœur s''égare, l''effroi me saisit; de la nuit que je désirais on a fait pour moi un temps de terreurs.'),
('is',21,5,'crampon1923','On dresse la table, la sentinelle fait le guet, on mange, on boit. — " Debout, capitaines! Oignez le bouclier! "'),
('is',21,6,'crampon1923','Car ainsi m''a parlé le Seigneur: " Va, établis une sentinelle; qu''elle annonce ce qu''elle verra.'),
('is',21,7,'crampon1923','Et elle verra des cavaliers, deux à deux, sur des chevaux, des cavaliers sur des ânes, des cavaliers sur des chameaux. Et elle regardera avec attention, avec grande attention. "'),
('is',21,8,'crampon1923','Et elle a crié comme un lion: " Sur la tour du guet, Seigneur, je me tiens, sans cesse tout le jour, et à mon poste je suis debout toutes les nuits.'),
('is',21,9,'crampon1923','Voici qu''arrive de la cavalerie; des cavaliers deux à deux. " Et elle a repris et dit: " Elle est tombée, elle est tombée, Babylone, et toutes les statues de ses dieux, il les a brisées contre terre! "'),
('is',21,10,'crampon1923','O mon froment qu''on foule, grain de mon aire, ce que j''ai entendu de Yahweh des armées, du Dieu d''Israël, je vous l''annonce.'),
('is',21,11,'crampon1923','Oracle sur Duma. On me crie de Séir: " Sentinelle, où en est la nuit? Sentinelle, où en est la nuit? "'),
('is',21,12,'crampon1923','La sentinelle répond: " Le matin vient et la nuit aussi. Si vous voulez m''interroger, interrogez; revenez une autre fois! "'),
('is',21,13,'crampon1923','Oracle en Arabie. Vous passerez la nuit dans les steppes en Arabie, caravanes de Dédan. —'),
('is',21,14,'crampon1923','A la rencontre de celui qui a soif, apportez de l''eau! Les habitant du pays de Théma offrent du pain aux fugitifs.'),
('is',21,15,'crampon1923','Car ils ont fui devant l''épée, devant l''épée nue, devant l''arc bandé, devant la terrible bataille.'),
('is',21,16,'crampon1923','Car ainsi m''a parlé le Seigneur: Encore une année, comptée comme les années du mercenaire, et c''en est fait de toute la gloire de Cédar;'),
('is',21,17,'crampon1923','et des arcs nombreux des vaillants fils de Cédar il ne restera que peu de chose; car Yahweh, le Dieu d''Israël, a parlé.'),
('is',22,1,'crampon1923','Oracle sur la Vallée de vision. Qu''as-tu donc que tu sois montée tout entière sur les toits,'),
('is',22,2,'crampon1923','cité bruyante, pleine de tumulte, ville joyeuse? Tes morts n''ont pas péri par l''épée, et ne sont pas tombés dans le combat.'),
('is',22,3,'crampon1923','Tes chefs ont fui tous ensemble, ils ont été pris sans qu''on ait tiré de l''arc; tous tes citoyens ont été pris ensemble, comme ils fuyaient au loin.'),
('is',22,4,'crampon1923','C''est pourquoi j''ai dit: " Détournez de moi vos regards Que je pleure amèrement! Ne vous empressez pas à me consoler sur la ruine de la fille de mon peuple. "'),
('is',22,5,'crampon1923','Car c''est un jour de confusion, d''écrasement, de perplexité, envoyé par le Seigneur Yahweh des années, dans la vallée des visions; on démolit la muraille, on entend des cris vers la montagne.'),
('is',22,6,'crampon1923','Elam a pris le carquois, il vient avec des chars et des cavaliers, et Kir a tiré le bouclier de son enveloppe.'),
('is',22,7,'crampon1923','Tes plus belles vallées sont remplies de chars, et les cavaliers sont postés devant tes portes; on ôte à Juda son voile.'),
('is',22,8,'crampon1923','Et en ce jour-là tu regardes vers l''arsenal du palais de la forêt;'),
('is',22,9,'crampon1923','et les brèches de la cité de David, vous voyez qu''elles sont nombreuses. Et vous avez recueilli les eaux de l''étang inférieur;'),
('is',22,10,'crampon1923','vous avez compté les maisons de Jérusalem, et vous avez démoli les maisons pour réparer les murailles.'),
('is',22,11,'crampon1923','Vous avez fait un réservoir entre les deux murs, pour les eaux du vieil étang. Mais vous n''avez pas regardé vers Celui qui a fait cela, et vous n''avez pas vu Celui qui l''a préparé de loin.'),
('is',22,12,'crampon1923','Le Seigneur Yahweh des armées vous appelait, en ce jour-là, à pleurer et à vous lamenter, à raser votre tête et à ceindre le sac.'),
('is',22,13,'crampon1923','Et voici la fête, la réjouissance; on égorge les bœufs, on tue des brebis, on se gorge de viandes et on boit du vin, " Mangeons, et buvons, car demain nous mourrons! "'),
('is',22,14,'crampon1923','Yahweh des armées l''a révélé à mes oreilles: Ce péché ne vous sera pas remis jusqu''à ce que vous mourriez, dit le Seigneur, Yahweh des armées.'),
('is',22,15,'crampon1923','Ainsi a parlé le Seigneur Yahweh des armées: Va trouver cet intendant, Sobna, le préfet du palais, et dis-lui:'),
('is',22,16,'crampon1923','" Qu''as-tu à faire ici, et qui es-tu ici, que tu te creuses ici un sépulcre, toi qui te creuses un sépulcre sur un lieu élevé, qui te tailles dans le roc une demeure?'),
('is',22,17,'crampon1923','Voici que Yahweh va te lancer d''un bras viril;'),
('is',22,18,'crampon1923','il va te faire tourner, il te fera rouler avec force, rouler comme une boule, sur une vaste plaine. Là tu mourras, là seront tes chars magnifiques, ô l''opprobre de la maison de ton maître.'),
('is',22,19,'crampon1923','Je te chasserai de ton poste, Yahweh t''arrachera de ta place. "'),
('is',22,20,'crampon1923','Et il arrivera en ce jour-là: J''appellerai mon serviteur Eliacim, fils d''Helcias,'),
('is',22,21,'crampon1923','je le revêtirai de ta tunique, et je le ceindrai de ton écharpe; je mettrai ton autorité entre ses mains; et il sera un père pour les habitants de Jérusalem, et pour la maison de Juda.'),
('is',22,22,'crampon1923','Je mettrai sur son épaule la clef de la maison de David, il ouvrira, et personne ne fermera; il fermera, et personne n''ouvrira.'),
('is',22,23,'crampon1923','Je le planterai comme un clou en un lieu solide, et il deviendra un trône de gloire pour la maison de son père.'),
('is',22,24,'crampon1923','A lui sera suspendue toute la gloire de la maison de son père, les fils et les petits-fils, tous les plus petits vases, depuis la coupe jusqu''aux jarres.'),
('is',22,25,'crampon1923','En ce jour-là, — oracle de Yahweh des armées, le clou planté en un lieu solide sera ôté; il sera arraché et tombera, et le fardeau qu''il portait sera détruit; car Yahweh a parlé.'),
('is',23,1,'crampon1923','Oracle sur Tyr. Hurlez, navires de Tarsis, car elle est détruite! Plus de maisons, plus d''entrée! C''est du pays de Céthim qu''ils en reçoivent la nouvelle.'),
('is',23,2,'crampon1923','Soyez dans la stupeur, habitants de la côte, que remplissaient les marchands de Sidon, parcourant la mer.'),
('is',23,3,'crampon1923','A travers les grandes eaux, le blé du Nil, les moissons du fleuve étaient son revenu; elle était le marché des nations!'),
('is',23,4,'crampon1923','Rougis de honte, Sidon, car la mer a parlé, la citadelle de la mer, en disant: " Je n''ai pas été en travail, je n''ai pas enfanté, je n''ai point nourri de jeunes gens, et je n''ai point élevé de vierges.'),
('is',23,5,'crampon1923','Quand l''Egypte en apprendra la nouvelle, elle sera saisie d''effroi à la nouvelle de la chute de Tyr.'),
('is',23,6,'crampon1923','Passez à Tarsis et hurlez, habitants de la côte!'),
('is',23,7,'crampon1923','Est-ce là votre cité joyeuse, dont l''origine remontait aux jours anciens, et que ses pieds portaient au loin pour y séjourner?'),
('is',23,8,'crampon1923','Qui a décidé cela contre Tyr, qui donnait des couronnes, dont les marchands étaient des princes, et les trafiquants des grands de la terre?'),
('is',23,9,'crampon1923','C''est Yahweh des armées qui l''a décidé, pour flétrir l''orgueil de tout ce qui brille, pour humilier tous les grands de la terre.'),
('is',23,10,'crampon1923','Répands-toi dans ton pays, comme le Nil, fille de Tarsis, car tu n''as plus de ceinture.'),
('is',23,11,'crampon1923','Yahweh a étendu sa main sur la mer, il a fait trembler les royaumes; il a décrété contre Chanaan la ruine de ses forteresses.'),
('is',23,12,'crampon1923','Et il a dit: " Tu ne te livreras plus à la joie, vierge déshonorée, fille de Sidon! Lève-toi, passe à Céthim; là même, plus de repos pour toi.'),
('is',23,13,'crampon1923','Vois le pays des Chaldéens, de ce peuple qui n''était pas, et qui a livré Assur aux bêtes du désert; ils ont élevé leurs tours, détruit ses palais, ils en ont fait un monceau de ruines. "'),
('is',23,14,'crampon1923','Hurlez, navires de Tarsis, car votre forteresse est détruite.'),
('is',23,15,'crampon1923','Il arrivera, en ce jour-là, que Tyr sera oubliée soixante-dix ans, la durée des jours d''un roi. Et au bout de soixante dix ans, il en sera de Tyr comme dans la chanson de la courtisane:'),
('is',23,16,'crampon1923','" Prends ta harpe, fais le tour de la ville, courtisane oubliée; joue avec art, multiplie tes chants, pour qu''on se souvienne de toi. "'),
('is',23,17,'crampon1923','Et il arrivera, au bout de soixante-dix ans, que Yahweh visitera Tyr, et elle recevra de nouveau son salaire, et elle se prostituera à tous les royaumes de la terre, sur la face du monde.'),
('is',23,18,'crampon1923','Et son gain et son salaire seront consacrés à Yahweh; ils ne seront ni amassés, ni mis en réserve; car son gain appartiendra à ceux qui habitent devant Yahweh; pour qu''ils mangent, se rassasient et se parent magnifiquement.'),
('is',24,1,'crampon1923','Voici que Yahweh va dévaster la terre entière et la dépeupler; il en bouleversera la face et en dispersera les habitants.'),
('is',24,2,'crampon1923','Et il en sera du prêtre comme du peuple, du maître comme de son serviteur, de la maîtresse comme de sa servante, du vendeur comme de l''acheteur, de l''emprunteur comme du prêteur, du débiteur comme du créancier.'),
('is',24,3,'crampon1923','La terre sera dévastée et livrée au pillage, car Yahweh a prononcé cette parole.'),
('is',24,4,'crampon1923','La terre est en deuil, épuisée; le monde est languissant et épuisé; l''élite des habitants de la terre languit.'),
('is',24,5,'crampon1923','La terre a été profanée sous ses habitants; car ils ont transgressé les lois, violé le commandement, rompu l''alliance éternelle.'),
('is',24,6,'crampon1923','C''est pourquoi la malédiction dévore la terre; et ses habitants portent leur peine. C''est pourquoi les habitants de la terre sont consumés; et ce qui reste de mortels est en petit nombre.'),
('is',24,7,'crampon1923','Le jus de la vigne est en deuil, le cep languit; tous ceux qui avaient la joie au cœur gémissent.'),
('is',24,8,'crampon1923','Le son joyeux des tambourins a cessé, les fêtes bruyantes ont pris fin, le son joyeux de la harpe a cessé.'),
('is',24,9,'crampon1923','On ne boit plus de vin au bruit des chansons; la liqueur enivrante est amère au buveur.'),
('is',24,10,'crampon1923','Elle est renversée, la ville de confusion; toute maison est fermée, on ne peut y entrer.'),
('is',24,11,'crampon1923','On pousse des clameurs dans les rues, faute de vin; toute allégresse a disparu, la joie est bannie de la terre.'),
('is',24,12,'crampon1923','Il ne reste de la ville que décombres, et les portes brisées sont en ruines.'),
('is',24,13,'crampon1923','Car il en sera au milieu de la terre, parmi les peuples, comme quand on abat des olives, comme quand on grappille après la vendange.'),
('is',24,14,'crampon1923','Ceux-là élèvent leur voix, ils chantent; ils acclament de la mer la majesté de Yahweh:'),
('is',24,15,'crampon1923','" Louez Yahweh dans les régions de l''aurore, le nom de Yahweh, le Dieu d''Israël, dans les îles du couchant. " —'),
('is',24,16,'crampon1923','De l''extrémité de la terre nous entendons des cantiques: " Gloire au juste! — " Mais j''ai dit: " Je suis perdu! Je suis perdu, malheur à moi! " Les pillards pillent, les pillards pillent sans mesure!'),
('is',24,17,'crampon1923','Epouvante, fosse et filet sont sur toi, habitant de la terre.'),
('is',24,18,'crampon1923','Celui qui fuira devant le cri d''épouvante tombera dans la fosse, et celui qui remontera du milieu de la fosse sera pris au filet. Car les écluses d''en haut sont ouvertes, et les fondements de la terre sont ébranlés.'),
('is',24,19,'crampon1923','La terre se brise avec violence; la terre éclate avec fracas; la terre s''ébranle avec force.'),
('is',24,20,'crampon1923','La terre chancelle comme un homme ivre; elle vacille comme un hamac; son iniquité pèse sur elle; elle s''écroule pour ne plus se relever.'),
('is',24,21,'crampon1923','En ce jour-là, Yahweh visitera, dans les hauteurs l''armée d''en haut, et sur la terre les rois de la terre.'),
('is',24,22,'crampon1923','Et ils seront réunis captifs dans l''abîme, et ils seront emprisonnés dans la prison; après un grand nombre de jours, ils seront visités.'),
('is',24,23,'crampon1923','Et la lune rougira et le soleil pâlira, parce que Yahweh des armées régnera sur la montagne de Sion et à Jérusalem, et devant ses anciens éclatera la gloire.'),
('is',25,1,'crampon1923','Yahweh, vous êtes mon Dieu, je vous exalterai; je louerai votre nom, car vous avez fait des choses merveilleuses; vos desseins formés de loin sont fidèles et fermes.'),
('is',25,2,'crampon1923','Car vous avez fait de la ville un monceau de pierres, et de la cité fortifiée une ruine; la citadelle des barbares n''est plus une ville, elle ne sera jamais rebâtie.'),
('is',25,3,'crampon1923','C''est pourquoi un peuple puissant vous glorifiera; la cité des nations terribles vous révèrera.'),
('is',25,4,'crampon1923','Vous avez été une forteresse pour le faible, une forteresse pour le pauvre dans sa détresse, un abri contre l''orage, un ombrage contre l''ardeur du soleil. Car le souffle des tyrans est comme l''ouragan qui bat une muraille.'),
('is',25,5,'crampon1923','Comme l''ardeur du soleil sur une terre aride, vous abattez l''insolence des barbares; comme l''ardeur du soleil par l''ombrage d''un nuage, le chant de triomphe des oppresseurs est étouffé.'),
('is',25,6,'crampon1923','Et Yahweh des armées préparera, pour tous les peuples sur cette montagne, un festin de viandes grasses, un festin de vins pris sur la lie, de viandes grasses et pleines de moelle, de vins pris sur la lie et clarifiés.'),
('is',25,7,'crampon1923','Et il déchirera sur cette montagne le voile qui voilait tous les peuples, et la couverture qui couvrait toutes les nations,'),
('is',25,8,'crampon1923','Il détruira la mort pour toujours. Le Seigneur Yahweh essuiera les larmes sur tous les visages, il ôtera l''opprobre de son peuple de dessus toute la terre; car Yahweh a parlé.'),
('is',25,9,'crampon1923','On dira en ce jour-là: " Voici notre Dieu; en qui nous espérions pour être sauvés; c''est Yahweh, en qui nous avons espéré; livrons-nous à l''allégresse et réjouissons-nous en son salut.'),
('is',25,10,'crampon1923','Car la main de Yahweh reposera sur cette montagne; mais Moab sera foulé sur place, comme est foulée la paille dans la mare à fumier.'),
('is',25,11,'crampon1923','Dans cette fange, il étendra ses mains, comme le nageur les étend pour nager; mais Yahweh rabaissera son orgueil, malgré tout l''effort de ses mains;'),
('is',25,12,'crampon1923','Le rempart élevé de tes murs, il l''abattra, il le renversera, il le jettera à terre, dans la poussière. "'),
('is',26,1,'crampon1923','En ce jour-là, on chantera ce cantique dans la terre de Juda: Nous avons une ville forte! Il fait de son salut le mur et l''avant-mur,'),
('is',26,2,'crampon1923','Ouvrez les portes, laissez entrer la nation juste, qui garde la vérité.'),
('is',26,3,'crampon1923','Au cœur constant vous assurez la paix, la paix, parce qu''il se confie en vous.'),
('is',26,4,'crampon1923','Confiez-vous en Yahweh à jamais; car Yahweh est le rocher des siècles.'),
('is',26,5,'crampon1923','Il a humilié ceux qui habitaient les hauteurs; il a abaissé la ville superbe, il l''a abaissée jusqu''à terre, et lui a fait toucher la poussière.'),
('is',26,6,'crampon1923','Elle est foulée aux pieds, sous les pieds des humbles, les pas des malheureux.'),
('is',26,7,'crampon1923','Le sentier du juste est uni; elle est droite la voie que vous aplanissez au juste.'),
('is',26,8,'crampon1923','Oui, sur le sentier de vos jugements, nous vous attendions, ô Yahweh; votre nom et votre souvenir étaient le désir de nos âmes.'),
('is',26,9,'crampon1923','Mon âme vous a désiré pendant la nuit, et au dedans de moi mon esprit vous cherchait; car, lorsque vos jugements s''exercent sur la terre, les habitants du monde apprennent la justice.'),
('is',26,10,'crampon1923','Si l''on fait grâce au méchant, il n''apprend pas la justice; dans le pays de la droiture, il agit en pervers, et il ne voit pas la majesté de Yahweh.'),
('is',26,11,'crampon1923','Yahweh, votre main est levée; ils ne la voient point. Ils verront votre zèle pour votre peuple, et seront confus; le feu fait pour vos adversaires les dévorera.'),
('is',26,12,'crampon1923','Yahweh, vous nous assurerez la paix, car toute notre œuvre, c''est vous qui l''avez faite pour nous.'),
('is',26,13,'crampon1923','Yahweh, notre Dieu, d''autres maîtres que vous ont dominé sur nous; grâce à vous seul, nous pouvons célébrer votre nom.'),
('is',26,14,'crampon1923','Les morts, ne vivront plus, les ombres ne ressusciteront point. Vous les avez visités et exterminés, et vous avez anéanti d''eux tout souvenir.'),
('is',26,15,'crampon1923','Vous avez accrû la nation, Yahweh, vous avez accrû la nation et manifesté votre gloire; vous avez reculé les limites du pays.'),
('is',26,16,'crampon1923','Yahweh, dans la détresse ils vous ont recherché; ils ont exhalé leur plainte quand vous les frappiez.'),
('is',26,17,'crampon1923','Comme une femme enceinte, prête à enfanter, se tord et crie dans ses douleurs, ainsi nous étions devant votre face, Yahweh.'),
('is',26,18,'crampon1923','Nous avons conçu dans la douleur et enfanté du vent; nous n''avons pas donné le salut à la terre, et il n''est pas né d''habitants du monde.'),
('is',26,19,'crampon1923','Vos morts vivront; mes cadavres ressusciteront; Réveillez-vous et chantez, vous qui êtes couchés dans la poussière car votre rosée, Seigneur, est une rosée de lumière, et la terre rendra au jour les trépassés.'),
('is',26,20,'crampon1923','Va, mon peuple, entre dans tes chambres, et ferme tes portes sur toi; cache-toi pour quelques instants; jusqu''à ce que la colère ait passé.'),
('is',26,21,'crampon1923','Car voici que Yahweh sort de sa demeure, pour visiter l''iniquité des habitants de la terre, et la terre découvrira le sang qu''elle a bu, et ne cachera plus ses tués.'),
('is',27,1,'crampon1923','En ce jour-là, Yahweh visitera de son épée dure, grande et forte, Léviathan, le serpent agile, Léviathan, le serpent tortueux, et il tuera le monstre qui est dans la mer.'),
('is',27,2,'crampon1923','En ce jour-là on dira: " Une vigne au vin généreux, chantez-la!'),
('is',27,3,'crampon1923','C''est moi, Yahweh, qui la garde; je l''arrose en tout temps; de peur qu''on y pénètre, nuit et jour je la garde; je n''ai plus de colère.'),
('is',27,4,'crampon1923','Qui me donnera des ronces, et des épines à combattre? Je marcherai contre elles, je les brûlerai toutes.'),
('is',27,5,'crampon1923','Ou bien, qu''on s''attache à ma protection, qu''on fasse la paix avec moi, qu''avec moi on fasse la paix!'),
('is',27,6,'crampon1923','Dans les jours à venir, Jacob poussera des racines, Israël donnera des fleurs et des rejetons, et il remplira de ses fruits la face du monde.'),
('is',27,7,'crampon1923','L''a-t-il frappé comme il a frappé ceux qui le frappaient? L''a-t-il tué comme furent tués ceux qu''il avait tués?'),
('is',27,8,'crampon1923','Avec mesure, par l''exil vous le châtiez! Il l''a chassé d''un souffle impérieux, en un jour de vent d''Orient.'),
('is',27,9,'crampon1923','Ainsi donc sera expiée l''iniquité de Jacob, et voici tout le fruit du pardon de son péché: Quand il aura mis les pierres des autels en poudre, comme des pierres à chaux, les aschérahs et les images du Soleil ne se relèveront plus.'),
('is',27,10,'crampon1923','Car la ville forte est devenue une solitude, une demeure délaissée et abandonnée, comme le désert; là paissent les veaux; ils s''y couchent et broutent les rameaux.'),
('is',27,11,'crampon1923','Quand les branches sont sèches, on les brise; des femmes viennent et les brûlent. Car ce n''est pas un peuple sage; c''est pourquoi celui qui l''a fait n''en aura point pitié, et celui qui l''a formé ne lui fera pas grâce.'),
('is',27,12,'crampon1923','Et il arrivera en ce jour-là, que Yahweh secouera le blé depuis le cours du Fleuve jusqu''au torrent d''Egypte, et vous serez recueillis un à un, enfants d''Israël.'),
('is',27,13,'crampon1923','Et il arrivera, en ce jour-là, que sonnera la grande trompette, et ceux qui étaient perdus au pays d''Assur, et ceux qui étaient bannis au pays d''Egypte, reviendront et se prosterneront devant Yahweh, sur la sainte montagne, à Jérusalem.'),
('is',28,1,'crampon1923','Malheur à l''orgueilleux diadème des buveurs d''Ephraïm, à la fleur éphémère qui fait l''éclat de leur parure, sur les sommets de la fertile vallée des hommes ivres de vin.'),
('is',28,2,'crampon1923','Voici qu''un ennemi fort et puissant vient de la part du Seigneur, comme une averse de grêle, un ouragan destructeur; comme une averse de grosses eaux qui débordent, il le jettera par terre avec violence.'),
('is',28,3,'crampon1923','Il sera foulé aux pieds l''orgueilleux diadème des buveurs d''Ephraïm,'),
('is',28,4,'crampon1923','et il en sera de la fleur éphémère qui fait l''éclat de leur parure, au sommet de la fertile vallée, comme d''une figue mûrie avant l''été; celui qui l''aperçoit, l''a à peine dans la main, qu''il l''avale.'),
('is',28,5,'crampon1923','En ce jour-là, Yahweh sera un brillant diadème, et une couronne de gloire pour le reste de son peuple;'),
('is',28,6,'crampon1923','un esprit de justice pour celui qui siège pour la justice, une force pour ceux qui repoussent l''assaut à la porte.'),
('is',28,7,'crampon1923','Eux aussi sont troublés par le vin, égarés par les boissons fortes, prêtre et prophète sont égarés par les boissons fortes; ils sont noyés dans le vin, égarés par les boissons fortes; ils sont troublés en prophétisant, ils vacillent en jugeant,'),
('is',28,8,'crampon1923','toutes les tables sont couvertes d''immondes vomissements, il n''y a plus de place.'),
('is',28,9,'crampon1923','" A qui veut-il enseigner la sagesse, et à qui veut-il faire comprendre la leçon? A des enfants à peine sevrés, à peine détachés de la mamelle?'),
('is',28,10,'crampon1923','Car c''est ordre sur ordre, ordre sur ordre, règle sur règle, règle sur règle, tantôt ceci, tantôt cela. "'),
('is',28,11,'crampon1923','Eh bien, c''est par des gens qui balbutient, et dans une langue étrangère, que Yahweh parlera à ce peuple.'),
('is',28,12,'crampon1923','Il avait dit: " Voici le lieu du repos: laissez reposer celui qui est fatigué; voici le soulagement; " mais ils n''ont pas voulu entendre.'),
('is',28,13,'crampon1923','La parole de Yahweh sera donc pour eux ordre sur ordre, ordre sur ordre, règle sur règle, règle sur règle; tantôt ceci, tantôt cela, afin qu''ils aillent, et tombent à la renverse, qu''ils se brisent, qu''ils soient pris au filet.'),
('is',28,14,'crampon1923','C''est pourquoi écoutez la parole de Yahweh, hommes moqueurs, chefs de ce peuple qui est à Jérusalem.'),
('is',28,15,'crampon1923','Vous dites: " Nous avons fait un pacte avec la mort, nous avons fait une convention avec le schéol. Le fléau débordant passera et ne nous atteindra pas; car nous nous sommes fait du mensonge un refuge, et de la fraude un abri. "'),
('is',28,16,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici que j''ai mis pour fondement en Sion une pierre, une pierre éprouvée, angulaire, de prix, solidement posée: qui s''appuiera sur elle avec foi ne fuira pas.'),
('is',28,17,'crampon1923','Je prendrai le droit pour règle, et la justice pour niveau. Et la grêle balaiera le refuge de mensonge, et les eaux emporteront votre abri.'),
('is',28,18,'crampon1923','Votre pacte avec la mort sera anéanti, et votre convention avec le schéol ne subsistera pas; quand le fléau débordant passera, il vous écrasera;'),
('is',28,19,'crampon1923','aussi souvent qu''il passera, il vous saisira. Car il passera demain et demain, le jour et la nuit; la terreur seule vous fera la leçon!'),
('is',28,20,'crampon1923','Car " le lit est trop court pour s''y étendre, et la couverture trop étroite pour s''en envelopper. "'),
('is',28,21,'crampon1923','Car Yahweh se lèvera comme à la montagne de Pharasim; il frémira d''indignation comme dans la vallée de Gabaon, pour accomplir son œuvre, œuvre singulière, pour exécuter son travail, travail étrange!'),
('is',28,22,'crampon1923','Et maintenant, cessez de vous moquer, de peur que vos liens ne se resserrent; car une destruction est résolue, — je l''ai entendu, — par Yahweh des armées, contre toute la terre.'),
('is',28,23,'crampon1923','Prêtez l''oreille et entendez ma voix, soyez attentifs et entendez ma parole.'),
('is',28,24,'crampon1923','Le laboureur, pour semer, est-il toujours à labourer, à ouvrir et à herser sa terre?'),
('is',28,25,'crampon1923','Ne va-t-il pas, quand il en a aplani la surface, jetter la nigelle, semer le cumin, mettre le froment en lignes, l''orge à sa place, et l''épeautre en bordure?'),
('is',28,26,'crampon1923','C''est son Dieu qui lui enseigne ces règles, et qui l''instruit.'),
('is',28,27,'crampon1923','Car ce n''est pas avec le traîneau qu''on foule la nigelle et la roue du chariot ne passe pas sur le cumin; mais on bat la nigelle avec le bâton, et le cumin avec la verge.'),
('is',28,28,'crampon1923','On foule le froment, mais on se garde de le battre toujours; on y pousse la roue du chariot, et les chevaux, mais sans le broyer.'),
('is',28,29,'crampon1923','Cela aussi vient de Yahweh des armées; il est admirable en ses conseils et riche en ses moyens.'),
('is',29,1,'crampon1923','Malheur à Ariel, à Ariel, à la cité où David a dressé sa tente! Ajoutez année à année, que les solennités parcourent leur cycle,'),
('is',29,2,'crampon1923','et je serrerai de près Ariel, et il n''y aura que plaintes et gémissements! Mais elle sera pour moi comme Ariel'),
('is',29,3,'crampon1923','je camperai tout autour de toi, je t''environnerai de postes armés, et j''établirai contre toi des retranchements.'),
('is',29,4,'crampon1923','Tu seras abaissée; c''est de la terre que s''élèvera ta voix, et de la poussière que se feront entendre tes sourds accents; ta voix sortira de terre, comme celle d''un spectre, et ta parole montera de la poussière comme un murmure. —'),
('is',29,5,'crampon1923','Et la multitude de tes ennemis sera comme une fine poussière, et la multitude des guerriers comme la paille qui s''envole.'),
('is',29,6,'crampon1923','Et il arrivera que soudain, en un instant, tu seras visitée, par Yahweh des armées avec fracas, tonnerre et grand bruit, tourbillon, tempête et flamme de feu dévorant.'),
('is',29,7,'crampon1923','Et il en sera comme d''un songe, vision de la nuit, de la multitude de toutes les nations qui combattront contre Ariel, et de tous ceux qui combattront contre elle et sa forteresse et la serreront de près.'),
('is',29,8,'crampon1923','Comme celui qui a faim rêve qu''il mange, et, à son réveil, son âme est vide; et comme un homme qui a soif rêve qu''il boit, et, à son réveil, il est épuisé et toujours altéré; ainsi il en sera de la multitude de toutes les nations, qui marchent contre la montagne de Sion.'),
('is',29,9,'crampon1923','Etonnez-vous et soyez dans la stupeur! Aveuglez-vous et soyez aveuglés! Ils sont ivres, mais pas de vin; ils chancellent, mais pas de liqueurs fortes.'),
('is',29,10,'crampon1923','Car Yahweh a répandu sur vous un esprit de léthargie; il a fermé vos yeux — les prophètes; il a jeté un voile sur vos têtes — les voyants.'),
('is',29,11,'crampon1923','Et toute vision est devenue pour vous comme les paroles d''un livre scellé. On le présente à un homme qui sait lire, en disant: " Lis cela! " et il dit: " Je ne puis, car ce livre est scellé. "'),
('is',29,12,'crampon1923','On le présente à un homme qui ne sait pas lire, en disant: " Lis cela! " et il dit: " Je ne sais pas lire. "'),
('is',29,13,'crampon1923','Le Seigneur dit: Puisque ce peuple s''approche en paroles et m''honore des lèvres, tandis qu''il tient son cœur éloigné de moi, et que le culte qu''il me rend est un précepte appris des hommes,'),
('is',29,14,'crampon1923','à cause de cela, je continuerai à user de prodiges, avec ce peuple, de prodiges étranges. Et la sagesse de ses sages périra, et l''intelligence de ses docteurs s''obscurcira.'),
('is',29,15,'crampon1923','Malheur à ceux qui cachent profondément à Yahweh le secret de leurs desseins, dont l''œuvre s''accomplit dans les ténèbres, et qui disent: " Qui nous voit, qui nous connaît? "'),
('is',29,16,'crampon1923','Quelle folie! Le potier sera-t-il donc estimé pour de l''argile, que l''œuvre dise de l''ouvrier: " Il ne m''a point faite; " et que le vase dise du potier: " Il n''y entend rien? "'),
('is',29,17,'crampon1923','Est-ce que dans un peu de temps, le Liban ne sera pas changé en verger, et le verger ne sera pas réputé une forêt?'),
('is',29,18,'crampon1923','En ce jour-là, les sourds entendront les paroles du livre, et, sortant des ténèbres et de l''obscurité, les aveugles verront.'),
('is',29,19,'crampon1923','Les humbles se réjouiront de plus en plus en Yahweh, et les plus pauvres tressailliront dans le Saint d''Israël.'),
('is',29,20,'crampon1923','Car l''oppresseur aura disparu, et le moqueur aura péri, et tous ceux qui méditent l''iniquité seront exterminés,'),
('is',29,21,'crampon1923','ceux qui condamnent un homme pour un mot, qui tendent des pièges à celui qui les confond à la porte, et qui perdent le juste par leurs mensonges.'),
('is',29,22,'crampon1923','C''est pourquoi ainsi parle Yahweh à la maison de Jacob, lui qui a racheté Abraham: Jacob n''aura plus désormais à rougir, et son front désormais ne pâlira plus.'),
('is',29,23,'crampon1923','Car, lorsqu''il verra, lui et ses enfants, l''œuvre de mes mains au milieu d''eux, ils sanctifieront mon nom, ils sanctifieront le Saint de Jacob, et ils révéreront le Dieu d''Israël.'),
('is',29,24,'crampon1923','Ceux qui avaient l''esprit égaré apprendront la sagesse, et ceux qui murmuraient recevront l''instruction.'),
('is',30,1,'crampon1923','Malheur aux enfants rebelles, — oracle de Yahweh, qui font des projets, mais sans moi; qui contractent des pactes, mais sans mon esprit, accumulant péché sur péché.'),
('is',30,2,'crampon1923','Ils descendent sur le chemin de l''Egypte, sans avoir consulté ma bouche, pour se réfugier sous la protection de Pharaon et pour s''abriter à l''ombre de l''Egypte!'),
('is',30,3,'crampon1923','La protection de Pharaon sera pour vous une honte; et le refuge à l''ombre de l''Egypte, une confusion.'),
('is',30,4,'crampon1923','Déjà les princes de Juda sont à Tanis, et ses envoyés se sont avancés jusqu''à Hanés;'),
('is',30,5,'crampon1923','tous sont confus à cause d''un peuple qui ne leur sert de rien, qui ne leur donne ni aide ni secours, mais seulement confusion et ignominie. —'),
('is',30,6,'crampon1923','Oracle des bêtes du négéb: A travers une contrée de détresse et d''angoisse, d''où sortent le lion et la lionne, la vipère et le dragon volant, ils portent leurs richesses sur le dos des ânes, et leurs trésors sur la bosse des chameaux, à un peuple qui ne sert à rien.'),
('is',30,7,'crampon1923','Le secours de l''Egypte sera vanité et néant, c''est pourquoi je la nomme: " La superbe qui reste assise. "'),
('is',30,8,'crampon1923','Va maintenant, grave cela sur une tablette en leur présence, et écris-le dans un livre, afin que ce soit, pour les jours à venir, un témoignage à perpétuité.'),
('is',30,9,'crampon1923','Car c''est un peuple de rébellion, ce sont des enfants infidèles, des enfants qui refusent d''écouter la loi de Yahweh.'),
('is',30,10,'crampon1923','Ils disent aux voyants: " Ne voyez point; " et aux prophètes: " Ne nous prophétisez pas la vérité; dites-nous des choses agréables, prophétisez des illusions!'),
('is',30,11,'crampon1923','Ecartez-vous de la voie, détournez-vous du chemin; ôtez de devant nos yeux le Saint d''Israël! " —'),
('is',30,12,'crampon1923','C''est pourquoi ainsi parle le Saint d''Israël: Puisque vous méprisez cette parole et que vous vous confiez dans la violence et l''artifice, et que vous en faites votre appui,'),
('is',30,13,'crampon1923','à cause de cela, cette iniquité sera pour vous comme une lézarde qui menace ruine et fait saillie sur un mur élevé, dont soudain, en un instant, l''écroulement se produit.'),
('is',30,14,'crampon1923','Il se brise comme se brise un vase d''argile, que l''on fracasse sans pitié, sans que l''on trouve dans ses débris un morceau, pour prendre du feu au brasier, ou puiser de l''eau à la citerne.'),
('is',30,15,'crampon1923','Car ainsi a parlé le Seigneur Yahweh, le Saint d''Israël: Par la conversion et une paisible attente vous seriez sauvés; dans le repos et la confiance serait votre force. Mais vous ne l''avez pas voulu'),
('is',30,16,'crampon1923','et vous avez dit: " Non! Mais nous fuirons sur des chevaux! " — eh bien, vous fuirez — " Nous volerons sur des coursiers! " — eh bien, ceux qui vous poursuivront seront plus rapides!'),
('is',30,17,'crampon1923','Mille à la menace d''un seul, et à la menace de cinq, vous fuirez, jusqu''à ce que vous ne soyez plus qu''un reste, semblable à un mât sur le sommet de la montagne, à un signal sur la colline.'),
('is',30,18,'crampon1923','C''est pourquoi Yahweh attend pour vous faire grâce, c''est pourquoi il se lèvera pour vous faire miséricorde; car Yahweh est un Dieu juste. Heureux tous ceux qui espèrent en lui!'),
('is',30,19,'crampon1923','Car, ô peuple qui habite en Sion, à Jérusalem, tu ne pleureras désormais plus. A ton premier cri, il te fera grâce; dès qu''il t''aura entendu, il t''exaucera.'),
('is',30,20,'crampon1923','Le Seigneur vous donnera le pain de l''angoisse et l''eau de la détresse; et ceux qui t''instruisent ne se cacheront plus et tes yeux verront ceux qui t''instruisent;'),
('is',30,21,'crampon1923','et tes oreilles entendront derrière toi la voix qui dira: " Voici le chemin, suivez-le! " quand vous vous détournerez à droite ou à gauche.'),
('is',30,22,'crampon1923','Vous traiterez comme impurs l''argent qui recouvre vos idoles, et l''or qui revêt vos statues; vous les rejetterez comme une chose souillée: " Hors d''ici! " leur direz-vous.'),
('is',30,23,'crampon1923','Le Seigneur enverra ses ondées sur la semence que tu auras semée en terre, et le pain que donnera la terre sera délicieux et abondant; tes troupeaux en ce jour-là paîtront dans de vastes pâturages;'),
('is',30,24,'crampon1923','et les bœufs et les ânes, qui travaillent la terre, mangeront un fourrage savoureux vanné avec la pelle et le van.'),
('is',30,25,'crampon1923','Et sur toute haute montagne, et sur toute colline élevée, il y aura des ruisseaux, des courants d''eau, au jour du grand carnage quand les tours tomberont.'),
('is',30,26,'crampon1923','La lumière de la lune sera comme la lumière du soleil, et la lumière du soleil sera sept fois plus grande, comme la lumière de sept jours, au jour où Yahweh bandera la blessure de son peuple, et guérira les plaies dont il l''avait frappé.'),
('is',30,27,'crampon1923','Voici que le nom de Yahweh vient de loin, sa colère brûle, et l''ardeur en est accablante; ses lèvres respirent la fureur, et sa langue est comme un feu dévorant.'),
('is',30,28,'crampon1923','Son souffle est comme un torrent débordé, qui monte jusqu''au cou, pour cribler les nations avec le crible de la destruction, et mettre un frein d''égarement aux mâchoires des peuples.'),
('is',30,29,'crampon1923','Alors vous entonnerez des cantiques comme dans la nuit où l''on célèbre la fête, et vous aurez le cœur joyeux, comme celui qui monte au son de la flûte, pour aller à la montagne de Yahweh, vers le rocher d''Israël.'),
('is',30,30,'crampon1923','Yahweh fera éclater la majesté de sa voix, et il fera voir son bras qui s''abaisse, dans l''ardeur de sa colère, et la flamme d''un feu dévorant, dans la tempête, l''averse et les pierres de grêle.'),
('is',30,31,'crampon1923','Et Assur tremblera à la voix de Yahweh; il frappera de sa verge,'),
('is',30,32,'crampon1923','et, à chaque fois que passera la verge fatale, que Yahweh abaissera sur lui, on fera retentir les tambourins et les harpes, et il combattra contre lui à coups redoublés.'),
('is',30,33,'crampon1923','Car Topheth est dès longtemps préparé; lui aussi est prêt pour le roi; le Seigneur l''a fait large et profond; il y a sur son bûcher du feu et du bois en abondance; le souffle de Yahweh, comme un torrent de soufre, l''embrase.'),
('is',31,1,'crampon1923','Malheur à ceux qui descendent en Egypte chercher du secours, qui s''appuient sur les chevaux, mettent leur confiance dans les chars, parce qu''ils sont nombreux, et dans les cavaliers, parce qu''ils sont forts, mais ne regardent pas vers le Saint d''Israël, et ne recherchent pas Yahweh.'),
('is',31,2,'crampon1923','Cependant il est sage, il fait venir le malheur, il ne révoque pas ses paroles; il s''élèvera contre la maison des méchants, et contre le secours de ceux qui commettent l''iniquité.'),
('is',31,3,'crampon1923','L''Egyptien est un homme, et non un Dieu; ses chevaux sont chair, et non esprit; Yahweh étendra sa main, celui qui secourt trébuchera, et le secouru tombera, et ils périront tous ensemble.'),
('is',31,4,'crampon1923','Car ainsi m''a parlé Yahweh: comme le lion rugit, ainsi que le jeune lion, sur sa proie, alors que se rassemble contre lui la multitude des bergers, sans se laisser effrayer par leurs cris, ni troubler par leur nombre: ainsi Yahweh des armées descendra pour combattre, sur la montagne de Sion et sur sa colline.'),
('is',31,5,'crampon1923','Comme des oiseaux déployant leurs ailes sur leur couvée, ainsi Yahweh des armées couvrira Jérusalem; il couvrira, il sauvera, il passera, il délivrera.'),
('is',31,6,'crampon1923','Revenez donc à celui dont vous vous êtes tant éloignés, enfants d''Israël.'),
('is',31,7,'crampon1923','Car en ce jour-là chacun rejettera ses idoles d''argent et ses idoles d''or, que vous avez fabriquées de vos mains pour pécher.'),
('is',31,8,'crampon1923','Et Assur tombera par une épée qui n''est pas de l''homme; une épée qui n''est pas d''un mortel le dévorera; il fuiera devant l''épée, et ses jeunes gens seront assujettis au tribut.'),
('is',31,9,'crampon1923','Son rocher fuira d''épouvante, et ses princes tremblants déserteront l''étendard. — oracle de Yahweh, qui a son feu dans Sion, et sa fournaise dans Jérusalem.'),
('is',32,1,'crampon1923','Voici qu''un roi régnera selon la justice, et les princes gouverneront avec droiture.'),
('is',32,2,'crampon1923','Et chacun d''eux sera un abri contre le vent et un refuge contre la tempête, comme des courants d''eau dans une terre aride, comme l''ombre d''un grand rocher dans un pays désolé.'),
('is',32,3,'crampon1923','Les yeux de ceux qui voient ne seront plus aveuglés, et les oreilles de ceux qui entendent seront attentives.'),
('is',32,4,'crampon1923','Le cœur des hommes légers sera habile à comprendre, et la langue des bègues adroite à parler nettement.'),
('is',32,5,'crampon1923','L''insensé ne sera plus appelé noble, et on ne dira plus du fourbe qu''il est magnanime.'),
('is',32,6,'crampon1923','Car l''insensé parle follement, et son cœur s''adonne à l''iniquité, pour faire des choses impies, et proférer des paroles fausses contre Yahweh, pour laisser avide l''âme de celui qui a faim, et ôter le breuvage à celui qui a soif.'),
('is',32,7,'crampon1923','Les armes du fourbe sont déloyales; il ourdit des intrigues, pour perdre les humbles par des mensonges, et le pauvre alors même qu''il parle justice.'),
('is',32,8,'crampon1923','Mais le noble a de nobles desseins, et il se lèvera pour de nobles actions.'),
('is',32,9,'crampon1923','Femmes nonchalantes, levez-vous, écoutez ma voix! Filles sans souci, prêtez l''oreille à ma parole!'),
('is',32,10,'crampon1923','Dans un an et quelques jours vous tremblerez, insouciantes, car il n''y aura pas de vendange; la récolte des fruits ne se fera pas.'),
('is',32,11,'crampon1923','Soyez dans l''effroi, nonchalantes! Tremblez, insouciantes! Otez vos riches vêtements, dépouillez-vous, ceignez vos reins de sacs.'),
('is',32,12,'crampon1923','On se lamente, en se frappant le sein, sur les belles campagnes, sur les vignes fécondes.'),
('is',32,13,'crampon1923','Sur la terre de mon peuple croissent les épines et les ronces, même sur toutes les maisons de plaisir de la cité joyeuse.'),
('is',32,14,'crampon1923','Car le palais est abandonné, la ville bruyante est devenue une solitude; Ophel et la Tour de garde servent à jamais de repaires, de lieux d''ébats aux ânes sauvages, et de pâturage aux troupeaux.'),
('is',32,15,'crampon1923','Jusqu''à ce que soit répandu sur nous un esprit d''en haut, et que le désert devienne un verger, et que le verger soit réputé une forêt.'),
('is',32,16,'crampon1923','Alors la droiture habitera dans le désert, et la justice s''établira dans le verger,'),
('is',32,17,'crampon1923','Et le produit de la justice sera la paix, et le fruit de la justice le repos et la sécurité pour jamais.'),
('is',32,18,'crampon1923','Mon peuple habitera dans un séjour de paix, dans des habitations sûres, dans des demeures tranquilles.'),
('is',32,19,'crampon1923','Mais la forêt sera tombée sous la grêle, et la ville profondément abaissée.'),
('is',32,20,'crampon1923','Heureux, vous qui semez partout près des eaux et qui laissez en liberté le pied du bœuf et de l''âne!'),
('is',33,1,'crampon1923','Malheur à toi, dévastateur, qui n''es pas dévasté; pillard, que l''on n''a pas encore pillé! Quand tu auras fini de dévaster, tu seras dévasté; quand tu auras achevé de piller, on te pillera.'),
('is',33,2,'crampon1923','Yahweh, ayez pitié de nous! C''est en vous que nous espérons; soyez leur bras chaque matin, et notre délivrance au temps de la détresse.'),
('is',33,3,'crampon1923','Au bruit de votre tonnerre, les peuples fuient; quand vous vous levez, les nations se dispersent.'),
('is',33,4,'crampon1923','Votre butin est ramassé comme ramasse la sauterelle; on se précipite dessus comme un essaim de sauterelles.'),
('is',33,5,'crampon1923','Yahweh est élevé, car il habite là-haut; il remplit Sion d''équité et de justice.'),
('is',33,6,'crampon1923','Tes jours sont assurés; tu auras en abondance le salut, la sagesse et la connaissance; la crainte de Yahweh, c''est là ton trésor.'),
('is',33,7,'crampon1923','Voici que leurs héros poussent des cris dans les rues, que les messagers de paix pleurent amèrement.'),
('is',33,8,'crampon1923','Les routes sont désertes; il n''y a plus de passants sur les chemins. Il a rompu le traité et méprisé les villes, il ne respecte pas les hommes.'),
('is',33,9,'crampon1923','Le pays est en deuil et languit; le Liban est confus et flétri, Saron est devenu comme l''Arabah, Basan et le Carmel secouent leur feuillage.'),
('is',33,10,'crampon1923','Maintenant je me lèverai, dit Yahweh, maintenant je me dresserai, maintenant je m''exhausserai.'),
('is',33,11,'crampon1923','Vous avez conçu de la paille, et vous enfanterez du chaume, votre souffle est le feu qui vous dévorera.'),
('is',33,12,'crampon1923','Et les peuples seront des fournaises à chaux, des épines coupées qui brûlent dans le feu.'),
('is',33,13,'crampon1923','Vous qui êtes loin, écoutez ce que j''ai fait, et vous qui êtes près, connaissez ma puissance!'),
('is',33,14,'crampon1923','Les pécheurs ont tremblé en Sion, et l''effroi a saisi les impies: " Qui de nous séjournera dans le feu dévorant? Qui de nous séjournera dans les flammes éternelles? "'),
('is',33,15,'crampon1923','Celui qui marche dans la justice et qui parle avec droiture; qui rejette les gains extorqués, qui secoue ses mains pour ne pas prendre de présent; qui ferme son oreille aux propos sanguinaires, et se voile les yeux pour ne point voir le mal:'),
('is',33,16,'crampon1923','celui-là habitera dans des lieux élevés; la forteresse bâtie sur le rocher est sa retraite; son pain lui sera donné et ses eaux ne tariront jamais.'),
('is',33,17,'crampon1923','Tes yeux contempleront le roi dans sa beauté; ils verront une terre ouverte au loin.'),
('is',33,18,'crampon1923','Ton cœur se rappellera ses terreurs: " Où est le scribe? où l''exacteur qui tenait la balance? Où l''officier qui comptait les tours? "'),
('is',33,19,'crampon1923','Le peuple insolent, tu ne le verras plus, le peuple au langage obscur et qu''on n''entend pas, qui balbutie une langue inintelligible.'),
('is',33,20,'crampon1923','Regarde Sion, la cité de nos fêtes; que tes yeux voient Jérusalem, séjour heureux, tente qui ne sera point transportée, dont les pieux ne seront jamais arrachés, et dont aucun cordage ne sera enlevé.'),
('is',33,21,'crampon1923','Là vraiment, Yahweh dans sa majesté réside pour nous; là sont des fleuves et des larges canaux, où ne se risquera aucune barque à rames, où aucun puissant navire ne pénétrera jamais.'),
('is',33,22,'crampon1923','Car Yahweh est notre juge, Yahweh est notre législateur, Yahweh est notre roi; c''est lui qui nous sauvera.'),
('is',33,23,'crampon1923','Tes cordages sont relâchés; ils ne maintiennent plus le mât sur sa base, et ne tiennent plus le pavillon déployé. Alors on partage les dépouilles d''un riche butin; les boiteux mêmes prennent part au pillage.'),
('is',33,24,'crampon1923','Aucun habitant ne dit: " Je suis malade! " Le peuple qui demeure en Sion a reçu le pardon de son iniquité.'),
('is',34,1,'crampon1923','Approchez, nations, pour entendre; peuples, soyez attentifs! Que la terre entende, elle et ce qu''elle renferme, le monde et tout ce qu''il produit.'),
('is',34,2,'crampon1923','Car Yahweh est courroucé contre toutes les nations, et en fureur contre toute leur armée; il les a vouées, livrées au carnage.'),
('is',34,3,'crampon1923','Leurs morts seront jetés sans sépulture, leurs cadavres exhaleront l''infection, et les montagnes se fondront dans leur sang.'),
('is',34,4,'crampon1923','Toute l''armée des cieux sera réduite en poussière; les cieux seront roulés comme un livre, et toute leur armée tombera, comme tombe la feuille de la vigne, comme tombe celle du figuier.'),
('is',34,5,'crampon1923','" Car mon épée s''est enivrée dans les cieux, et voici qu''elle descend sur Edom, sur le peuple que j''ai voué à l''anathème, pour le juger.'),
('is',34,6,'crampon1923','L''épée de Yahweh est pleine de sang. ruisselante de graisse, du sang des agneaux et des boucs, de la graisse des reins des béliers. Car Yahweh fait un sacrifice à Bosra, et un grand carnage au pays d''Edom.'),
('is',34,7,'crampon1923','Avec eux tombent les buffles, et les bœufs avec les taureaux. Leur terre s''enivre de sang, et leur poussière ruisselle de graisse.'),
('is',34,8,'crampon1923','Car c''est un jour de vengeance pour Yahweh, une année de revanche pour la cause de Sion.'),
('is',34,9,'crampon1923','Ses torrents seront changés en poix, et sa poussière en soufre, et sa terre deviendra de la poix brûlante,'),
('is',34,10,'crampon1923','qui ne s''éteindra ni la nuit ni le jour, dont la fumée montera éternellement. D''âge en âge elle restera désolée; à tout jamais personne n''y passera.'),
('is',34,11,'crampon1923','Le pélican et le hérisson la posséderont; la chouette et le corbeau y habiteront. Et il étendra sur elle le cordeau du chaos et le niveau du vide.'),
('is',34,12,'crampon1923','Il n''y aura plus de grands pour proclamer un roi, et tous ses princes seront anéantis.'),
('is',34,13,'crampon1923','Les épines pousseront dans ses palais, les ronces et les chardons dans ses forteresses. Ce sera un repaire de chacals, et un parc pour les autruches.'),
('is',34,14,'crampon1923','Les chats et les chiens sauvages s''y rencontreront, et les satyres s''y appelleront les uns les autres. Là aussi le spectre des nuits fera sa demeure, et trouvera son lieu de repos.'),
('is',34,15,'crampon1923','Là le serpent fera son nid et pondra, couvera et réunira ses petits sous son ombre. Là aussi se rassembleront tous les vautours.'),
('is',34,16,'crampon1923','Cherchez dans le livre de Yahweh, et lisez: Pas un d''eux ne manque, ni l''un ni l''autre ne fait défaut. Car c''est la bouche de Yahweh qui l''a ordonné, et son souffle qui les a rassemblés.'),
('is',34,17,'crampon1923','C''est lui qui a jeté le sort pour eux, et sa main qui leur a partagé le pays au cordeau; à jamais ils le posséderont, d''âge en âge ils y habiteront.'),
('is',35,1,'crampon1923','Le désert et la terre aride se réjouiront; la steppe sera dans l''allégresse, et fleurira comme le narcisse;'),
('is',35,2,'crampon1923','il se couvrira de fleurs et tressaillira, il poussera des cris de joie. La gloire du Liban lui sera donnée, avec la magnificence du Carmel et de Saron. Ils verront la gloire de Yahweh, la magnificence de notre Dieu!'),
('is',35,3,'crampon1923','Fortifiez les mains défaillantes, et affermissez les genoux qui chancellent!'),
('is',35,4,'crampon1923','Dites à ceux qui ont le cœur troublé: " Prenez courage, ne craignez point: Voici votre Dieu; la vengeance vient, une revanche divine, il vient lui-même et vous sauvera. "'),
('is',35,5,'crampon1923','Alors s''ouvriront les yeux des aveugles, alors s''ouvriront les oreilles des sourds.'),
('is',35,6,'crampon1923','Le boiteux bondira comme un cerf, et la langue du muet éclatera de joie. Car des eaux jailliront dans le désert, et des ruisseaux dans la steppe,'),
('is',35,7,'crampon1923','Le sol brûlé se changera en un lac, et la terre altérée en sources d''eaux; le repaire où gîtaient les chacals deviendra un parc de roseaux et de joncs.'),
('is',35,8,'crampon1923','Il y aura là une route, une voie, qu''on appellera la voie sainte; nul impur n''y passera; elle n''est que pour eux seuls; ceux qui la suivront, les simples mêmes, ne s''égareront pas.'),
('is',35,9,'crampon1923','Là il n''y aura point de lion; aucune bête féroce n''y mettra le pied; on ne l''y trouvera pas. Les délivrés y marcheront,'),
('is',35,10,'crampon1923','et les rachetés de Yahweh reviendront; ils viendront en Sion avec des cris de joie; une allégresse éternelle couronnera leur tête; la joie et l''allégresse les envahiront, la douleur et le gémissement s''enfuiront.'),
('is',36,1,'crampon1923','La quatorzième année du roi Ezéchias, Sennachérib, roi d''Assyrie, monta contre toutes les villes fortes de Juda et s''en empara.'),
('is',36,2,'crampon1923','Et le roi d''Assyrie envoya de Lachis à Jérusalem, vers le roi Ezéchias, son grand échanson avec une troupe nombreuse; le grand échanson s''arrêta à l''aqueduc de l''étang supérieur, sur le chemin du champ du Foulon.'),
('is',36,3,'crampon1923','Eliacim, fils de Helcias, chef de la maison du roi, se rendit auprès de lui, avec Sobna, le secrétaire, et Joahé, fils d''Asaph, archiviste.'),
('is',36,4,'crampon1923','Le grand échanson leur dit: " Dites à Ezéchias: Ainsi dit le grand roi, le roi d''Assyrie: Quelle est cette confiance sur laquelle tu t''appuies? Je disais: Paroles en l''air que ce conseil et cette force pour la guerre!'),
('is',36,5,'crampon1923','Et maintenant, en qui te confies-tu pour te révolter contre moi?'),
('is',36,6,'crampon1923','Voici que tu te fies à l''appui de ce roseau cassé — l''Egypte — qui pénètre et perce la main de quiconque s''appuie dessus: tel est Pharaon, roi d''Egypte, pour tous ceux qui se confient en lui.'),
('is',36,7,'crampon1923','Peut-être me diras-tu: C''est en Yahweh, notre Dieu, que nous avons confiance!... Mais n''est-ce pas lui dont Ezéchias a fait disparaître les hauts lieux et les autels, en disant à Juda et à Jérusalem: Vous vous prosternerez devant cet autel?'),
('is',36,8,'crampon1923','Maintenant, fais un accord avec mon maître, le roi d''Assyrie: je te donnerai deux mille chevaux, si tu peux fournir des cavaliers pour les monter!...'),
('is',36,9,'crampon1923','Comment repousserais-tu un seul chef d''entre les moindres serviteurs de mon maître? Aussi mets-tu ta confiance dans l''Egypte pour les chars et pour les chevaux.'),
('is',36,10,'crampon1923','Maintenant, est-ce sans la volonté de Yahweh que je suis monté contre ce pays pour le détruire? Yahweh m''a dit: Monte contre ce pays, et détruis-le! "'),
('is',36,11,'crampon1923','Eliacim, Sobna et Joahé dirent au grand échanson: " Parle à tes serviteurs en araméen, car nous l''entendons; et ne nous parle pas en langue judaïque, aux oreilles du peuple qui est sur la muraille. "'),
('is',36,12,'crampon1923','Le grand échanson répondit: " Est-ce à ton maître et à toi que mon maître m''a envoyé dire ces paroles? N''est-ce pas à ces hommes assis sur la muraille, pour manger leurs excréments et boire leur urine avec vous? "'),
('is',36,13,'crampon1923','Alors le grand échanson, s''étant avancé, cria à haute voix en langue judaïque et dit: " Ecoutez les paroles du grand roi, du roi d''Assyrie:'),
('is',36,14,'crampon1923','Ainsi dit le roi: Qu''Ezéchias ne vous abuse pas, car il ne pourra vous délivrer.'),
('is',36,15,'crampon1923','Et qu''Ezéchias ne vous persuade pas de vous confier en Yahweh, en disant: Yahweh nous délivrera sûrement; cette ville ne sera pas livrée entre les mains du roi d''Assyrie.'),
('is',36,16,'crampon1923','N''écoutez point Ezéchias, car ainsi dit le roi d''Assyrie: Faites la paix avec moi, et rendez-vous à moi; et que chacun de vous mange de sa vigne et chacun de son figuier, et que chacun boive l''eau de son puits,'),
('is',36,17,'crampon1923','jusqu''à ce que je vienne et que je vous emmène dans un pays comme le vôtre, un pays de blé et de vin, un pays de pain et de vignes.'),
('is',36,18,'crampon1923','Qu''Ezéchias ne vous abuse point, en disant: Yahweh nous délivrera. Est-ce que les dieux des nations ont délivré chacun leur pays de la main du roi d''Assyrie?'),
('is',36,19,'crampon1923','Où sont les Dieux d''Emath et d''Arphad? Où sont les Dieux de Sépharvaïm? Ont-ils délivré Samarie de ma main?'),
('is',36,20,'crampon1923','Quels sont, parmi tous les dieux de ces pays, ceux qui ont délivré leur pays de ma main, pour que Yahweh puisse délivrer Jérusalem de ma main? "'),
('is',36,21,'crampon1923','Ils se turent et ne répondirent pas un mot, car le roi avait donné cet ordre: " Vous ne lui répondrez pas. "'),
('is',36,22,'crampon1923','Et Eliacim, fils de Helcias, chef de la maison du roi, Sobna le secrétaire, et Joahé, fils d''Asaph, l''archiviste, vinrent auprès d''Ezéchias, les vêtements déchirés, et lui rapportèrent les paroles du grand échanson.'),
('is',37,1,'crampon1923','Lorsque le roi Ezéchias eut entendu ce rapport, il déchira ses vêtements, se couvrit d''un sac et alla dans la maison de Yahweh.'),
('is',37,2,'crampon1923','Il envoya Eliacim, chef de sa maison, Sobna, le secrétaire, et les anciens des prêtres, couverts de sacs, vers Isaïe, fils d''Amos, le prophète.'),
('is',37,3,'crampon1923','Ils lui dirent: " Ainsi dit Ezéchias: Ce jour est un jour d''angoisse, de châtiment et d''opprobre; car les enfants sont près de sortir du sein maternel, et il n''y a pas de force pour enfanter.'),
('is',37,4,'crampon1923','Peut-être Yahweh, ton Dieu, entendra-t-il les paroles du grand échanson, que le roi d''Assyrie, son maître, a envoyé pour insulter au Dieu vivant, et le punira-t-il à cause des paroles qu''a entendues Yahweh, ton Dieu. Fais donc une prière pour le reste qui subsiste encore! "'),
('is',37,5,'crampon1923','Les serviteurs du roi Ezéchias se rendirent auprès d''Isaïe,'),
('is',37,6,'crampon1923','et Isaïe leur dit: " Voici ce que vous direz à votre maître: Ainsi dit Yahweh: Ne t''effraie point des paroles que tu as entendues, par lesquelles les serviteurs du roi d''Assyrie m''ont outragé.'),
('is',37,7,'crampon1923','Voici que je mets en lui un esprit tel que, sur une nouvelle qu''il apprendra, il retournera dans son pays, et je le ferai tomber par l''épée dans son pays. "'),
('is',37,8,'crampon1923','Le grand échanson s''en retourna et trouvas le roi d''Assyrie qui attaquait Lobna; car il avait appris que son maître était parti de Lachis.'),
('is',37,9,'crampon1923','Or le roi d''Assyrie reçut une nouvelle au sujet de Tharaca, roi d''Ethiopie; on lui dit: " Il s''est mis en marche pour te faire la guerre. " Entendant cela, il envoya des messagers à Ezéchias en disant:'),
('is',37,10,'crampon1923','" Vous parlerez ainsi à Ezéchias, roi de Juda: Que ton Dieu, en qui tu te confies, ne t''abuse point en disant: Jérusalem ne sera pas livrée entre les mains du roi d''Assyrie.'),
('is',37,11,'crampon1923','Voici que tu as appris ce qu''ont fait les rois d''Assyrie à tous les pays, les soumettant à l''anathème!... Et toi, tu serais délivré!...'),
('is',37,12,'crampon1923','Est-ce que leurs dieux les ont délivrées, ces nations que mes pères ont détruites: Gozan, Haram, Réseph et les fils d''Eden, qui étaient à Thélasar?'),
('is',37,13,'crampon1923','Où sont le roi d''Emath, le roi d''Arphad et le roi de la ville de Sépharvaïm, d''Ana et d''Ava? "'),
('is',37,14,'crampon1923','Ezéchias, ayant pris la lettre de la main des messagers, la lut; puis Ezéchias monta à la maison de Yahweh et la déploya devant Yahweh.'),
('is',37,15,'crampon1923','Et Ezéchias pria devant Yahweh, en disant:'),
('is',37,16,'crampon1923','" Yahweh des armées, Dieu d''Israël, assis sur les Chérubins, c''est vous qui êtes le seul Dieu de tous les royaumes de la terre, vous qui avez fait les cieux et la terre.'),
('is',37,17,'crampon1923','Yahweh, inclinez votre oreille et entendez! Yahweh, ouvrez les yeux et regardez! Entendez toutes les paroles de Sennachérib, qui a envoyé insulter au Dieu vivant.'),
('is',37,18,'crampon1923','Il est vrai, Yahweh, que les rois d''Assyrie ont détruit toutes les nations et dévasté leurs territoires,'),
('is',37,19,'crampon1923','et qu''ils ont jeté leurs dieux dans le feu; car ce n''étaient pas des dieux, mais des ouvrages de mains d''homme, du bois et de la pierre; et ils les ont anéantis.'),
('is',37,20,'crampon1923','Maintenant, Yahweh, notre Dieu, sauvez-nous de la main de Sennachérib, et que tous les royaumes de la terre sachent que vous seul êtes Yahweh! "'),
('is',37,21,'crampon1923','Et Isaïe, fils d''Amos, envoya dire à Ezéchias: " Ainsi dit Yahweh, Dieu d''Israël: La prière que tu m''as adressée au sujet de Sennachérib, roi d''Assyrie, je l''ai entendue.'),
('is',37,22,'crampon1923','Voici la parole que Yahweh a prononcée contre lui: Elle te méprise, elle se moque de toi, la vierge, fille de Sion; elle branle la tête derrière toi, la fille de Jérusalem!'),
('is',37,23,'crampon1923','Qui as-tu insulté et outragé? Contre qui as-tu élevé la voix et porté les yeux en haut? Contre le Saint d''Israël!'),
('is',37,24,'crampon1923','Par tes serviteurs tu as insulté le Seigneur, et tu as dit: Avec la multitude de mes chars, j''ai gravi le sommet des montagnes, les extrémités du Liban; je couperai les plus élevés de ses cèdres, les plus beaux de ses cyprès; et j''atteindrai sa dernière cime et sa forêt semblable à un verger.'),
('is',37,25,'crampon1923','J''ai creusé, et j''ai eu de l''eau à boire; avec la plante de mes pieds je dessécherai tous les fleuves de l''Egypte.'),
('is',37,26,'crampon1923','N''as-tu pas appris que depuis longtemps j''ai fait ces choses, et que je les ai formées dès les temps anciens? A présent je les fais s''accomplir, pour que tu réduises en monceaux de ruines les villes fortes,'),
('is',37,27,'crampon1923','Leurs habitants sont sans force, dans l''épouvante et le trouble; ils sont comme l''herbe des champs, et la tendre verdure comme le gazon des toits, comme le blé niellé qui sèche avant sa maturité.'),
('is',37,28,'crampon1923','Mais je sais quand tu t''assieds, quand tu sors et quand tu entres; je connais ta fureur contre moi.'),
('is',37,29,'crampon1923','Parce que tu es furieux contre moi, et que ton arrogance est montée à mes oreilles, je mettrai mon anneau dans ta narine et mon mors à tes lèvres, et je te ferai retourner par le chemin par lequel tu es venu.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('is',37,30,'crampon1923','Et ceci sera un signe pour toi: On mangera cette année le produit du grain tombé; la seconde année, on mangera ce qui croit de soi-même; mais la troisième année, vous sèmerez et moissonnerez, vous planterez des vignes et vous en mangerez le fruit.'),
('is',37,31,'crampon1923','Ce qui aura été sauvé de la maison de Juda, ce qui restera, poussera encore des racines par-dessous, et portera du fruit par dessus.'),
('is',37,32,'crampon1923','Car de Jérusalem il sortira un reste, et de la montagne de Sion des réchappés. Voilà ce que fera le zèle de Yahweh des armées.'),
('is',37,33,'crampon1923','C''est pourquoi, ainsi parle Yahweh sur le roi d''Assyrie: Il n''entrera point dans cette ville, il n''y lancera point de flèches, il ne lui présentera pas de boucliers, il n''élèvera pas de retranchements contre elle.'),
('is',37,34,'crampon1923','Il s''en retournera par le chemin par lequel il est venu, et il n''entrera point dans cette ville, — oracle de Yahweh.'),
('is',37,35,'crampon1923','Je protégerai cette ville pour la sauver, à cause de moi et à cause de David, mon serviteur. "'),
('is',37,36,'crampon1923','Et l''ange de Yahweh sortit et frappa, dans le camp des Assyriens, cent quatre-vingt-cinq mille hommes, et quand on se leva le matin, voici que c''étaient tous des cadavres.'),
('is',37,37,'crampon1923','Et Sennachérib, roi d''Assyrie, ayant levé son camp, partit et s''en retourna, et il resta à Ninive.'),
('is',37,38,'crampon1923','Comme il était prosterné dans la maison de Nesroch, son dieu, Adramélech et Sarasar, ses fils, le frappèrent avec l''épée, et s''enfuirent au pays d''Ararat. Et Asarhaddon, son fils, régna à sa place.'),
('is',38,1,'crampon1923','En ce temps-là, Ezéchias fut malade à la mort. Le prophète Isaïe, fils d''Amos, vint auprès de lui et lui dit: " Ainsi dit Yahweh: Donne tes ordres à ta maison, car tu vas mourir, et tu ne vivras plus. "'),
('is',38,2,'crampon1923','Ezéchias tourna son visage contre le mur et pria Yahweh; il dit:'),
('is',38,3,'crampon1923','" Souvenez-vous, ô Yahweh, que j''ai marché devant votre face avec fidélité et intégrité, et que j''ai fait ce qui est bien à vos yeux! " Et Ezéchias versa des larmes abondantes.'),
('is',38,4,'crampon1923','Et la parole de Yahweh fut adressée à Isaïe en ces termes:'),
('is',38,5,'crampon1923','" Va, et dis à Ezéchias: " Ainsi dit Yahweh, le Dieu de David, ton père,: J''ai entendu ta prière, j''ai vu tes larmes; voici que j''ajouterai à tes jours quinze années.'),
('is',38,6,'crampon1923','Je te délivrerai, toi et cette ville, de la main du roi d''Assyrie; je protégerai cette ville.'),
('is',38,7,'crampon1923','Et voici pour toi le signe donné par Yahweh, auquel tu connaîtras que Yahweh accomplira cette parole qu''il a dite:'),
('is',38,8,'crampon1923','Voici que je vais faire reculer l''ombre en arrière, des degrés qu''elle a descendus sur les degrés d''Achaz sous l''influence du soleil, soit de dix degrés. Et le soleil recula de dix degrés sur les degrés qu''il avait descendus.'),
('is',38,9,'crampon1923','Ecrit d''Ezéchias, roi de Juda, lorsqu''il fut malade et qu''il guérit de sa maladie:'),
('is',38,10,'crampon1923','Je disais: Dans la paix de mes jours je m''en vais aux portes du schéol; je suis privé du reste de mes ans!'),
('is',38,11,'crampon1923','Je disais: Je ne verrai plus Yahweh, Yahweh sur la terre des vivants; je ne verrai plus les hommes, parmi les habitants du silencieux séjour!'),
('is',38,12,'crampon1923','Ma demeure est enlevée, emportée loin de moi comme une tente de bergers. Comme un tisserand, j''ourdissais ma vie; il me retranche du métier! Du jour à la nuit tu en auras fini avec moi!'),
('is',38,13,'crampon1923','Je me suis tu jusqu''au matin; comme un lion, il brisait tous mes os; du jour à la nuit tu en auras fini avec moi!'),
('is',38,14,'crampon1923','Comme l''hirondelle, comme la grue, je crie; je gémis comme la colombe; mes yeux se sont lassés à regarder en haut: " Yahweh, on me fait violence; sois mon garant! "'),
('is',38,15,'crampon1923','Que dirais-je? Il m''a dit, il l''a fait. Je marcherai humblement pendant toutes mes années, me souvenant de l''amertume de mon âme.'),
('is',38,16,'crampon1923','Seigneur, c''est en cela qu''est la vie, en tout cela est la vie de mon esprit. Vous me guérissez, vous me rendez la vie:'),
('is',38,17,'crampon1923','voici que ma suprême amertume se change en paix! Vous avez retiré mon âme de la fosse de perdition; vous avez jeté derrière votre dos tous mes péchés.'),
('is',38,18,'crampon1923','Car le schéol ne vous célèbre pas, la mort ne chante pas vos louanges; ceux qui descendent dans la fosse n''espèrent plus en votre fidélité.'),
('is',38,19,'crampon1923','Le vivant, le vivant, c''est lui qui vous célèbre, comme je le fais en ce jour; père fera connaître à ses enfants votre fidélité.'),
('is',38,20,'crampon1923','Yahweh a été prompt à me sauver; nous ferons résonner les cordes de ma harpe; tous les jours de notre vie, devant la maison de Yahweh.'),
('is',38,21,'crampon1923','Isaïe dit: " Qu''on apporte une masse de figues, et qu''on l''applique sur l''ulcère et que le roi guérisse! " Et Ezéchias dit: " A quel signe connaîtrai-je que je monterai à la maison de Yahweh? "'),
('is',38,22,'crampon1923',''),
('is',39,1,'crampon1923','En ce même temps, Mérodach-Baladan fils de Baladan, roi de Babylone, envoya une lettre et des présents à Ezechias, car il avait appris qu''il avait été malade et qu''il était rétabli.'),
('is',39,2,'crampon1923','Ezéchias se réjouit de la venue des envoyés, et il leur montra la maison de son trésor, l''argent et l''or, les aromates et l''huile de prix, tout son arsenal et tout ce qui se trouvait dans ses trésors; il n''y eut rien qu''Ezéchias ne leur fit voir dans sa maison et dans tous ses domaines.'),
('is',39,3,'crampon1923','Mais Isaïe, le prophète, vint auprès du roi Ezéchias, et lui dit: " Qu''ont dit ces gens-là, et d''où sont-ils venus vers toi? " Ezéchias répondit: " Ils sont venus vers moi d''un pays éloigné, de Babylone. "'),
('is',39,4,'crampon1923','Isaïe dit: " Qu''ont-ils vu dans ta maison? " Et Ezéchias répondit: " Ils ont vu tout ce qui est dans ma maison; il n''y a rien dans mes trésors que je ne leur aie fait voir. "'),
('is',39,5,'crampon1923','Et Isaïe dit à Ezéchias: " Ecoute la parole de Yahweh des armées:'),
('is',39,6,'crampon1923','Voici que des jours viendront où l''on emportera à Babylone tout ce qui est dans ta maison et ce que tes pères ont amassé jusqu''à ce jour; il n''en restera rien, dit Yahweh.'),
('is',39,7,'crampon1923','Et l''on prendra de tes fils, qui seront sortis de toi, que tu auras engendrés, pour en faire des eunuques dans le palais du roi de Babylone. "'),
('is',39,8,'crampon1923','Ezéchias répondit à Isaïe: " La parole de Yahweh que tu as prononcée est bonne. " Et il ajouta: " Car, il y aura paix et stabilité pendant ma vie ".'),
('is',40,1,'crampon1923','Consolez, consolez mon peuple, dit votre Dieu.'),
('is',40,2,'crampon1923','Parlez au cœur de Jérusalem, et criez-lui: Que sa servitude est finie, que son iniquité est expiée, qu''elle a reçu de la main de Yahweh le double pour ses péchés.'),
('is',40,3,'crampon1923','Une voix crie: Frayez dans le désert le chemin de Yahweh, aplanissez dans la steppe une route pour notre Dieu!'),
('is',40,4,'crampon1923','Que toute vallée soit relevée, toute montagne et toute colline abaissées; que la hauteur devienne une plaine, et les roches escarpées un vallon!'),
('is',40,5,'crampon1923','Alors la gloire de Yahweh apparaîtra, et toute chair sans exception la verra; car la bouche de Yahweh a parlé.'),
('is',40,6,'crampon1923','Une voix dit: " Crie! " et on répond: " Que crierai-je? " — " Toute chair est comme l''herbe, et toute sa grâce comme la fleur des champs:'),
('is',40,7,'crampon1923','L''herbe se dessèche, la fleur se flétrit, quand le souffle de Yahweh passe sur elle. Oui, l''homme est comme l''herbe!'),
('is',40,8,'crampon1923','L''herbe se dessèche, la fleur se flétrit; mais la parole de Dieu subsiste à jamais! "'),
('is',40,9,'crampon1923','Monte sur une haute montagne, toi qui portes à Sion la bonne nouvelle; élève la voix avec force, toi qui portes à Jérusalem la bonne nouvelle; élève-la, ne crains point; dis aux villes de Juda: " Voici votre Dieu! "'),
('is',40,10,'crampon1923','Voici que le Seigneur Yahweh vient avec puissance; son bras exerce la domination; Voici que sa récompense est avec lui, et son salaire est devant lui.'),
('is',40,11,'crampon1923','Comme un berger, il fera paître son troupeau; il recueillera les agneaux dans ses bras, et les portera dans son sein; il conduira doucement celles qui allaitent.'),
('is',40,12,'crampon1923','Qui a mesuré les eaux dans le creux de sa main, estimé l''étendue des cieux à l''empan, jaugé au boisseau toute la poussière de la terre, pesé les montagnes au crochet, et les collines à la balance?'),
('is',40,13,'crampon1923','Qui a dirigé l''esprit de Yahweh, et quel a été son conseiller pour l''instruire?'),
('is',40,14,'crampon1923','Avec qui a-t-il tenu conseil, pour qu''il l''éclaire, pour qu''il lui enseigne le sentier de la justice, pour qu''il lui enseigne la sagesse, et lui montre le chemin de l''intelligence?'),
('is',40,15,'crampon1923','Voici que les nations sont comme la goutte suspendue à un seau, elles sont réputées comme la poussière dans la balance; voici que les îles sont la poudre menue qui s''envole.'),
('is',40,16,'crampon1923','Le Liban ne suffit pas pour le feu, et ses animaux ne suffisent pas pour l''holocauste.'),
('is',40,17,'crampon1923','Toutes les nations sont devant lui comme rien; il les compte pour néant et vanité.'),
('is',40,18,'crampon1923','A qui donc comparerez-vous Dieu, et quelle image lui préparerez-vous?'),
('is',40,19,'crampon1923','Quand l''ouvrier a coulé une idole, l''orfèvre la recouvre d''or, et il lui fond des chaînettes d''argent.'),
('is',40,20,'crampon1923','Le pauvre, qui ne peut offrir beaucoup, choisit un bois qui ne pourrisse point; et il va chercher un ouvrier habile, pour faire une idole qui ne branle point.'),
('is',40,21,'crampon1923','Ne savez-vous pas? N''avez-vous pas entendu dire? Ne vous a-t-on pas annoncé dès le commencement? N''avez-vous pas appris qui a posé les fondements de la terre?'),
('is',40,22,'crampon1923','Il trône par dessus la voûte de la terre, — et ses habitants sont comme des sauterelles; — il étend les cieux comme un voile, et les déploie comme une tente pour y habiter;'),
('is',40,23,'crampon1923','Il livre au néant les puissants, et réduit à rien les juges de la terre:'),
('is',40,24,'crampon1923','à peine sont-ils plantés, à peine sont-ils semés, à peine leur tronc a-t-il pris racine en terre, il souffle sur eux, et ils sèchent, et l''ouragan les emporte comme le chaume.'),
('is',40,25,'crampon1923','A qui donc me comparerez-vous, que je lui sois pareil, dit le Saint?'),
('is',40,26,'crampon1923','Levez les yeux en haut et regardez: qui a créé ces choses? Celui qui fait marcher en ordre leur armée, et qui les appelle toutes par leur nom; et, à cause de la grandeur de sa puissance et de l''énergie de sa force, pas une ne fait défaut.'),
('is',40,27,'crampon1923','Pourquoi dis-tu, ô Jacob, et parles-tu ainsi, ô Israël: " Ma voie est cachée à Yahweh, et mon droit passe inaperçu devant mon Dieu? "'),
('is',40,28,'crampon1923','Ne sais-tu pas, n''as-tu pas entendu? Yahweh est un Dieu éternel, qui a créé les extrémités de la terre, qui ne se fatigue ni ne se lasse, et dont la sagesse est insondable.'),
('is',40,29,'crampon1923','Il donne de la force à celui qui est fatigué et redouble la vigueur de celui qui est défaillant.'),
('is',40,30,'crampon1923','Les jeunes gens se fatiguent et se lassent, et les jeunes gens chancellent,'),
('is',40,31,'crampon1923','Mais ceux qui se confient en Yahweh renouvellent leurs forces; ils élèveront leur vol comme les aigles; ils courront et ne se fatigueront point; ils marcheront et ne se lasseront point.'),
('is',41,1,'crampon1923','Iles, faites silence pour m''écouter, et que les peuples raniment leurs forces; qu''ils approchent, puis qu''ils parlent! Allons ensemble au jugement!'),
('is',41,2,'crampon1923','Qui a fait lever de l''Orient celui dont la justice rencontre les pas? Qui lui a livré les nations, et lui a soumis les rois? Il fait voler leurs épées en poussière; il rend leurs arcs semblables à la paille qu''emporte le vent.'),
('is',41,3,'crampon1923','Il les poursuit et passe en paix, par un chemin que son pied n''avait jamais foulé.'),
('is',41,4,'crampon1923','Qui a fait cela? qui l''a accompli? Celui qui appelle les générations depuis le commencement, moi, Yahweh, qui suis le premier, et qui serai aussi avec les derniers!'),
('is',41,5,'crampon1923','Les îles le voient et sont saisies de crainte; les extrémités de la terre tremblent; ils approchent et viennent.'),
('is',41,6,'crampon1923','Chacun aide son compagnon, et l''un dit à l''autre: Prends courage!'),
('is',41,7,'crampon1923','Le forgeron encourage le fondeur, le polisseur au marteau celui qui frappe sur l''enclume; en disant de la soudure: " Elle est bonne! " puis il fixe le dieu avec des clous, pour qu''il ne branle pas.'),
('is',41,8,'crampon1923','Mais toi, Israël, mon serviteur, Jacob, que j''ai choisi, race d''Abraham mon ami;'),
('is',41,9,'crampon1923','Toi que j''ai été prendre aux extrémités de la terre, et que j''ai appelé de ses lointaines régions; toi à qui j''ai dit: " Tu es mon serviteur, je t''ai choisi et ne t''ai point rejeté: "'),
('is',41,10,'crampon1923','Ne crains point, car, je suis avec toi; ne regarde pas avec inquiétude, car je suis ton Dieu; je t''ai saisi fortement, et je t''aide, et je te soutiens par la droite de ma justice.'),
('is',41,11,'crampon1923','Voici qu''ils seront confondus et couverts de honte, tous ceux qui sont enflammés contre toi; ils seront semblables au néant, ils périront, ceux qui disputent contre toi!'),
('is',41,12,'crampon1923','Tu les chercheras et tu ne les trouveras plus, ceux qui te querellent; ils seront semblables au néant, réduits à rien, ceux qui te font la guerre.'),
('is',41,13,'crampon1923','Car moi, Yahweh, ton Dieu, je te prends par la main droite, je te dis: " Ne crains point, c''est moi qui viens à ton aide. "'),
('is',41,14,'crampon1923','Ne crains point, vermisseau de Jacob, faible reste d''Israël! moi, je viens à ton secours, — oracle de Yahweh; et ton Rédempteur est le Saint d''Israël.'),
('is',41,15,'crampon1923','Voici que je fais de toi un traîneau aigu, neuf, à deux tranchants; tu fouleras les montagnes et tu les broieras, et tu rendras les collines semblables à de la balle,'),
('is',41,16,'crampon1923','Tu les vanneras, et le vent les emportera, et l''ouragan les dispersera. Et toi, tu tressailliras de joie en Yahweh, tu te glorifieras dans le Saint d''Israël.'),
('is',41,17,'crampon1923','Les malheureux et les pauvres, qui cherchent des eaux et n''en trouvent point, et dont la langue est desséchée par la soif, moi, Yahweh, je les exaucerai, moi, le Dieu d''Israël, je ne les abandonnerai pas.'),
('is',41,18,'crampon1923','Je ferai jaillir des fleuves sur les sommets dénudés, et des sources au milieu des vallées; je changerai le désert en étang, et la terre aride en fontaines d''eau.'),
('is',41,19,'crampon1923','Je mettrai dans le désert le cèdre, l''acacia, le myrte et l''olivier; je mettrai dans la steppe à la fois le cyprès, le platane et le buis;'),
('is',41,20,'crampon1923','Afin qu''ils voient, qu''ils sachent, qu''ils observent et comprennent ensemble, que la main de Yahweh a fait ces choses, et que le Saint d''Israël les a créées.'),
('is',41,21,'crampon1923','Présentez votre cause, dit Yahweh; produisez vos raisons, dit le Roi de Jacob.'),
('is',41,22,'crampon1923','Qu''ils les produisent et nous déclarent ce qui doit arriver! Les choses anciennes, déclarez-nous ce qu''elles furent, et nous y appliquerons notre cœur, pour en connaître l''issue! Ou bien faites-nous entendre les choses à venir!'),
('is',41,23,'crampon1923','Annoncez les choses qui arriveront plus tard, et nous saurons que vous êtes des dieux! Faites du bien ou faites du mal, que nous voyions et que nous admirions ensemble!'),
('is',41,24,'crampon1923','Voilà, vous n''êtes rien, et votre œuvre est néant: abominable est celui qui vous choisit!'),
('is',41,25,'crampon1923','Je l''ai suscité du septentrion, et il arrive, du soleil levant, il invoque mon nom; il marche sur les satrapes comme sur la boue, comme le potier foule l''argile.'),
('is',41,26,'crampon1923','Qui l''a fait connaître dès l''origine, que nous le sachions, longtemps d''avance, que nous disions: " C''est vrai? " Non! Personne ne l''a annoncé! Non! Personne ne l''a fait entendre! Non! Personne n''a entendu vos paroles!'),
('is',41,27,'crampon1923','Le premier j''ai dit à Sion: " Voici! Les voici! " et j''envoie à Jérusalem un messager de bonne nouvelle.'),
('is',41,28,'crampon1923','Je regarde, et il n''y a personne; parmi eux, il n''y a pas un conseiller, que je puisse interroger et qui me réponde.'),
('is',41,29,'crampon1923','Voici, ils sont tous vanité; leurs œuvres sont néant; leurs idoles, un vain souffle!'),
('is',42,1,'crampon1923','Voici mon serviteur, que je soutiens, mon élu, en qui mon âme se complaît; j''ai mis mon esprit sur lui; il répandra la justice parmi les nations.'),
('is',42,2,'crampon1923','Il ne criera point, il ne parlera pas haut, il ne fera pas entendre sa voix dans les rues.'),
('is',42,3,'crampon1923','Il ne brisera pas le roseau froissé, et n''éteindra pas la mèche prête à mourir. Il annoncera la justice en vérité;'),
('is',42,4,'crampon1923','il ne faiblira point et ne se laissera point abattre, jusqu''à ce qu''il ait établi la justice sur la terre, et les îles seront dans l''attente de sa loi.'),
('is',42,5,'crampon1923','Ainsi parle le Dieu Yahweh, qui a créé les cieux et les a déployés, qui a étendu la terre et ses productions, qui donne la respiration au peuple qui l''habite; et le souffle à ceux qui la parcourent:'),
('is',42,6,'crampon1923','Moi, Yahweh, je t''ai appelé dans la justice, et je t''ai pris par la main; je te garde et je fais de toi l''alliance du peuple, la lumière des nations;'),
('is',42,7,'crampon1923','Pour ouvrir les yeux des aveugles; pour faire sortir de prison les captifs, du cachot ceux qui sont assis dans les ténèbres.'),
('is',42,8,'crampon1923','Je suis Yahweh; c''est là mon nom, et je ne donnerai pas ma gloire à un autre, ni mon honneur aux idoles,'),
('is',42,9,'crampon1923','Voici que les premières choses sont arrivées, et j''en annonce de nouvelles; avant qu''elles éclosent, je vous les fais entendre.'),
('is',42,10,'crampon1923','Chantez à Yahweh un cantique nouveau; Chantez sa louange aux extrémités de la terre, vous qui naviguez sur la mer et qui la peuplez, vous, îles, et vos habitants!'),
('is',42,11,'crampon1923','Que le désert et ses villes élèvent la voix, les campements habités par Cédar! Que les habitants de Séla tressaillent d''allégresse; que du sommet des montagnes, ils poussent des cris de joie!'),
('is',42,12,'crampon1923','Qu''ils rendent gloire à Yahweh, qu''ils publient sa louange dans les îles!'),
('is',42,13,'crampon1923','Car Yahweh sort comme un héros; comme un guerrier, il réveille son ardeur; il pousse le cri de guerre, un cri éclatant; il déploie sa force contre ses ennemis.'),
('is',42,14,'crampon1923','Longtemps je me suis tu, j''ai gardé le silence, je me suis contenu; comme la femme qui enfante, je gémis, je soupire et je suis haletant.'),
('is',42,15,'crampon1923','Je désolerai les montagnes et les collines, et je dessécherai toute leur verdure; je changerai les fleuves en îles, et je mettrai les lacs à sec.'),
('is',42,16,'crampon1923','Je conduirai les aveugles par un chemin qu''ils ne connaissent pas, je les mènerai par des sentiers qu''ils ignorent; je changerai devant eux les ténèbres en lumière, et les lieux montueux en plaine. Ces paroles, je les accomplirai; et je n''y manquerai point.'),
('is',42,17,'crampon1923','Ils reculeront, ils seront couverts de honte, ceux qui se confient dans les idoles, qui disent aux images fondues: " Vous êtes nos dieux! "'),
('is',42,18,'crampon1923','Sourds, entendez; aveugles, ouvrez les yeux pour voir!'),
('is',42,19,'crampon1923','Qui est aveugle, sinon mon serviteur, et sourd comme mon messager que j''envoie? Qui est aveugle comme celui dont j''avais fait mon ami, aveugle comme le serviteur de Yahweh?'),
('is',42,20,'crampon1923','Tu as vu beaucoup de choses, et tu n''as rien retenu; il a eu ses oreilles ouvertes, et il n''a rien entendu.'),
('is',42,21,'crampon1923','Yahweh a daigné, à cause de sa justice, donner une loi grande et magnifique.'),
('is',42,22,'crampon1923','Et voilà ce peuple pillé et dépouillé! On les a tous enchaînés dans des cavernes, ils ont été enfermés dans des cachots; ils sont au pillage, et personne qui les délivre; dépouillés, et personne qui dise: " Restitue! "'),
('is',42,23,'crampon1923','Qui de vous prêtera l''oreille à ces choses, y prendra garde et écoutera désormais?'),
('is',42,24,'crampon1923','Qui a livré Jacob au pillage, et Israël aux spoliateurs? N''est-ce pas Yahweh, lui contre qui nous avons péché, lui dont ils n''ont pas voulu suivre les voies, et dont ils n''ont pas écouté la loi?'),
('is',42,25,'crampon1923','Il a versé sur eux le feu de son courroux, et les fureurs de la guerre; elle s''est allumée tout autour de lui, et il n''a pas compris; elle l''a consumé, et il n''y a point pris garde!'),
('is',43,1,'crampon1923','Et maintenant, ainsi parle Yahweh, celui qui t''a créé, ô Jacob, celui qui t''a formé, ô Israël: Ne crains point, car je t''ai racheté; je t''ai appelé par ton nom, tu es à moi!'),
('is',43,2,'crampon1923','Quand tu passeras par les eaux, je serai avec toi; par les fleuves, ils ne t''engloutiront point; quand tu marcheras au milieu du feu, tu ne seras point brûlé et la flamme ne t''embrasera point.'),
('is',43,3,'crampon1923','Car moi, Yahweh, je suis ton Dieu; le Saint d''Israël est ton sauveur. J''ai donné l''Egypte pour ta rançon; l''Ethiopie et Saba en échange de toi.'),
('is',43,4,'crampon1923','Parce que tu es précieux à mes yeux, honorable, et que, moi, je t''aime, je donnerai des hommes en échange de toi, et des peuples en échange de ta vie.'),
('is',43,5,'crampon1923','Ne crains point, car je suis avec toi; de l''orient je ramènerai ta postérité, et de l''occident je te rassemblerai.'),
('is',43,6,'crampon1923','Je dirai au septentrion: " Donne-les! " et au midi: " Ne les retiens pas! Ramène mes fils des pays lointains et mes filles de l''extrémité de la terre,'),
('is',43,7,'crampon1923','tous ceux qui portent mon nom, que j''ai créés pour ma gloire, que j''ai formés et que j''ai faits.'),
('is',43,8,'crampon1923','Fais sortir le peuple aveugle, et qui a des yeux, et les sourds, qui ont des oreilles. "'),
('is',43,9,'crampon1923','Que les nations s''assemblent toutes, et que les peuples se réunissent! Lequel d''entre eux a annoncé ces choses, et nous a fait entendre des prédictions anciennes? Qu''ils produisent leurs témoins et qu''ils se justifient; qu''on les entende et qu''on dise: " C''est vrai! "'),
('is',43,10,'crampon1923','Vous êtes mes témoins, — oracle de Yahweh, et mon serviteur que j''ai choisi, afin que vous reconnaissiez et que vous me croyiez, et que vous compreniez que c''est moi. Avant moi aucun Dieu n''a été formé, et il n''y en aura point après moi.'),
('is',43,11,'crampon1923','C''est moi, moi qui suis Yahweh, et il n''y a point de sauveur en dehors de moi.'),
('is',43,12,'crampon1923','C''est moi qui ai annoncé, qui ai sauvé, qui ai prédit; ce n''est pas un dieu étranger parmi vous; et vous êtes mes témoins, — oracle de Yahweh! C''est moi qui suis Dieu;'),
('is',43,13,'crampon1923','désormais aussi je le suis, et il n''y a personne qui délivre de ma main; j''agirai, et qui l''empêchera?'),
('is',43,14,'crampon1923','Ainsi parle Yahweh, votre rédempteur, le Saint d''Israël: A cause de vous, j''ai envoyé contre Babylone, et je les fais tous descendre en fugitifs, les Chaldéens, sur les navires dont ils sont si fiers!'),
('is',43,15,'crampon1923','Je suis Yahweh, votre Saint, le Créateur d''Israël, votre roi!'),
('is',43,16,'crampon1923','Ainsi parle Yahweh, qui ouvrit un chemin dans la mer, un sentier dans les eaux puissantes;'),
('is',43,17,'crampon1923','qui mit en campagne chars et chevaux, armée et vaillants guerriers, — tous ensemble ils sont couchés pour ne plus se relever; ils ont été étouffés, ils se sont éteints comme une mèche: —'),
('is',43,18,'crampon1923','Ne vous souvenez plus des événements passés, et ne considérez plus les choses d''autrefois!'),
('is',43,19,'crampon1923','Voici que je vais faire une merveille nouvelle; elle est près d''éclore; ne la reconnaîtrez-vous pas? Je mettrai un chemin dans le désert, des fleuves dans la terre aride.'),
('is',43,20,'crampon1923','Les bêtes des champs me glorifieront, les chacals et les autruches. Car je mettrai des eaux dans le désert, et des fleuves dans la terre aride, pour abreuver mon peuple, mon élu,'),
('is',43,21,'crampon1923','le peuple que j''ai formé pour moi, qui publiera ma louange.'),
('is',43,22,'crampon1923','Cependant tu ne m''as pas invoqué, ô Jacob, et tu ne t''es pas mis en peine pour moi, Israël.'),
('is',43,23,'crampon1923','Tu ne m''as pas offert les brebis de tes holocaustes, et tu ne m''as pas honoré par tes sacrifices. Je ne t''ai pas été à charge pour des offrandes, et ne t''ai pas fatigué pour de l''encens.'),
('is',43,24,'crampon1923','Tu ne m''as point, à prix d''argent, acheté de roseau odoriférant, et tu ne m''as pas rassasié de la graisse de tes victimes; mais toi, tu m''as été à charge par tes péchés, tu m''as fatigué par tes iniquités.'),
('is',43,25,'crampon1923','C''est moi, c''est moi qui efface tes fautes pour l''amour de moi, et je ne me souviendrai plus de tes péchés.'),
('is',43,26,'crampon1923','Réveille mes souvenirs, plaidons ensemble, parle toi-même pour te justifier.'),
('is',43,27,'crampon1923','Ton premier père a péché, et tes interprètes m''ont été infidèles.'),
('is',43,28,'crampon1923','C''est pourquoi j''ai dégradé les princes du sanctuaire, j''ai livré Jacob à l''anathème et Israël aux outrages.'),
('is',44,1,'crampon1923','Et maintenant, écoute, Jacob, mon serviteur, et toi, Israël, que j''ai choisi.'),
('is',44,2,'crampon1923','Ainsi parle Yahweh, qui t''a fait, qui t''a formé dès le sein de ta mère, et secouru: Ne crains point, Jacob, mon serviteur, mon Israël, que j''ai choisi!'),
('is',44,3,'crampon1923','Car je répandrai des eaux sur le sol altéré, et des ruisseaux sur la terre desséchée. Je répandrai mon esprit sur ta postérité, et ma bénédiction sur tes rejetons.'),
('is',44,4,'crampon1923','Et ils croîtront parmi la verdure, comme les saules le long des eaux courantes.'),
('is',44,5,'crampon1923','Celui-ci dira: " Je suis à Yahweh! " celui-ci se réclamera du nom de Jacob; un autre écrira sur sa main: " A Yahweh! " et il prendra pour surnom le nom d''Israël.'),
('is',44,6,'crampon1923','Ainsi parle Yahweh, le roi d''Israël et son rédempteur, Yahweh des armées: Je suis le premier et je suis le dernier, et il n''y a pas de Dieu en dehors de moi!'),
('is',44,7,'crampon1923','Qui est comme moi, — qu''il parle, qu''il le déclare, qu''il me le montre! — depuis que j''ai fondé l''humanité des jours antiques? Qu''ils annoncent donc l''avenir et ce qui doit arriver!'),
('is',44,8,'crampon1923','Ne soyez point effrayés et ne craignez point! Ne te l''ai-je pas dès longtemps fait connaître et annoncé? — vous m''en êtes témoins! Y a-t-il un Dieu en dehors de moi? Il n''y a pas d''autre Rocher; je n''en connais point.'),
('is',44,9,'crampon1923','Les fabricateurs d''idoles ne sont tous que néant, et leurs chefs-d''œuvre ne servent à rien; leurs témoins, eux, ne voient rien ni ne comprennent rien, pour leur honte.'),
('is',44,10,'crampon1923','Qui a formé un dieu, qui a fondu une idole, pour n''en retirer aucune utilité?'),
('is',44,11,'crampon1923','Voici que tous ses adorateurs seront confondus; et les ouvriers ne sont que des hommes! Qu''ils s''assemblent tous, qu''ils se présentent!... Ils trembleront et seront confondus tous ensemble.'),
('is',44,12,'crampon1923','L''ouvrier en fer travaille avec le ciseau, il passe son œuvre dans les charbons embrasés, il la façonne avec le marteau; il la travaille d''un bras vigoureux. Cependant, il a faim, et le voilà sans force; il ne boit pas d''eau, et le voilà épuisé!'),
('is',44,13,'crampon1923','L''ouvrier en bois tend le cordeau, il trace la forme au crayon, la façonne avec le ciseau, la mesure au compas; il en fait une figure d''homme, la belle figure humaine, pour qu''elle loge dans une maison.'),
('is',44,14,'crampon1923','Un homme va couper des cèdres; il prend des rouvres et des chênes; il fait un choix parmi les arbres de la forêt; ou bien il plante des cèdres, et la pluie les fait croître.'),
('is',44,15,'crampon1923','Ce bois sert à l''homme pour brûler; il en prend pour se chauffer; il en allume aussi pour cuire son pain; il en fait aussi un dieu et il l''adore; il en fabrique une idole, et il se prosterne devant elle!'),
('is',44,16,'crampon1923','Il en a brûlé au feu la moitié; avec l''autre moitié, il apprête sa viande; il cuit son rôti et se rassasie. Il se chauffe aussi et il dit: " Ah! Ah! Je me réchauffe; je sens la flamme! "'),
('is',44,17,'crampon1923','De ce qui en reste, il fait son dieu, son idole, qu''il adore en se prosternant, devant laquelle il prie, en disant: " Délivre-moi, car tu es mon Dieu! "'),
('is',44,18,'crampon1923','Ils ne savent pas, ils n''entendent pas, car leurs yeux sont couverts pour ne pas voir, et leurs cœurs pour ne pas comprendre.'),
('is',44,19,'crampon1923','Et il ne rentre pas en soi-même; il n''a pas l''intelligence et le bon sens de se dire: " J''en ai brûlé la moitié au feu; j''ai aussi cuit du pain sur les braises; j''ai rôti de la viande et je l''ai mangée; et avec le reste je ferais une abomination, je me prosternerais devant un tronc d''arbre! "'),
('is',44,20,'crampon1923','Il se repaît de cendres; son cœur abusé l''égare. Il ne sauvera pas son âme et ne dira pas: " Ce qui est dans ma main n''est-il pas mensonge? "'),
('is',44,21,'crampon1923','Souviens-toi de ces choses, ô Jacob, ô Israël, car tu es mon serviteur; je t''ai formé pour mon serviteur, ô Israël, tu ne seras pas oublié de moi!'),
('is',44,22,'crampon1923','J''ai effacé tes transgressions comme un nuage; et tes péchés comme une nuée: reviens à moi, car je t''ai racheté.'),
('is',44,23,'crampon1923','Cieux, poussez des cris de joie, car Yahweh a fait cela! Retentissez, profondeurs de la terre! Eclatez de joie, montagnes, forêts, avec tous vos arbres; car Yahweh a racheté Jacob, et manifesté sa gloire en Israël!'),
('is',44,24,'crampon1923','Ainsi parle Yahweh, ton rédempteur, qui t''a formé dès le sein de ta mère: C''est moi, Yahweh, qui ai fait toutes choses, moi qui seul ai déployé les cieux, affermi la terre: qui était avec moi?'),
('is',44,25,'crampon1923','Je déjoue les présages des prophètes de mensonge, et fais délirer les devins; je fais reculer les sages, et change leur science en folie.'),
('is',44,26,'crampon1923','J''accomplis la parole de mon serviteur, et j''exécute le conseil de mes envoyés; je dis de Jérusalem: " Qu''elle soit habitée! " et des villes de Juda: " Qu''elles soient rebâties! je relèverai leurs ruines. "'),
('is',44,27,'crampon1923','Je dis à l''abîme: " Taris! je dessécherai tes fleuves. "'),
('is',44,28,'crampon1923','Je dis de Cyrus: " C''est mon berger; il accomplira toute ma volonté, en disant à Jérusalem: Sois rebâtie! et au temple: Sois fondé! "'),
('is',45,1,'crampon1923','Ainsi parle Yahweh à son oint, à Cyrus, que j''ai pris par la main droite pour terrasser devant lui les nations, et pour délier la ceinture des rois, pour ouvrir devant lui les portes, afin que les entrées ne lui soient pas fermées:'),
('is',45,2,'crampon1923','Moi, je marcherai devant toi; j''aplanirai les chemins montueux; je romprai les portes d''airain, et je briserai les verrous de fer.'),
('is',45,3,'crampon1923','Je te donnerai les trésors cachés, et les richesses enfouies, afin que tu saches que je suis Yahweh, le Dieu d''Israël, qui t''ai appelé par ton nom.'),
('is',45,4,'crampon1923','A cause de Jacob, mon serviteur, et d''Israël, mon élu, je t''ai appelé par ton nom; je t''ai désigné quand tu ne me connaissais pas.'),
('is',45,5,'crampon1923','Je suis Yahweh, et il n''y en a point d''autre; hors moi, il n''y a point de Dieu! Je t''ai ceint quand tu ne me connaissais pas,'),
('is',45,6,'crampon1923','afin que l''on sache, du levant au couchant, qu''il n''y a rien en dehors de moi! Je suis Yahweh, et il n''y en a point d''autre;'),
('is',45,7,'crampon1923','je forme la lumière et crée les ténèbres, je fais la paix et je crée le malheur: c''est moi Yahweh qui fais tout cela.'),
('is',45,8,'crampon1923','Cieux, répandez d''en haut votre rosée, et que les nuées fassent pleuvoir la justice! Que la terre s''ouvre et produise le salut, qu''elle fasse germer la justice en même temps! Moi! Yahweh, je crée ces choses.'),
('is',45,9,'crampon1923','Malheur à qui conteste avec celui qui l''a formé, vase parmi des vases de terre! L''argile dira-t-elle à celui qui la façonne: " Que fais-tu? " Ton œuvre dira-t-elle: " Il n''a pas de mains? "'),
('is',45,10,'crampon1923','Malheur à qui dit à un père: " Pourquoi engendres-tu? " Et à une femme: " Pourquoi mets-tu au monde? "'),
('is',45,11,'crampon1923','Ainsi parle Yahweh, le Saint d''Israël et celui qui l''a formé: " Oserez-vous m''interroger sur l''avenir, me commander au sujet de mes enfants et de l''œuvre de mes mains?'),
('is',45,12,'crampon1923','C''est moi qui ai fait la terre, et qui sur elle ai créé l''homme; c''est moi dont les mains ont déployé les cieux, moi qui commande à toute leur armée.'),
('is',45,13,'crampon1923','C''est moi qui l''ai suscité dans ma justice, et j''aplanis toutes ses voies. C''est lui qui rebâtira ma ville, et renverra mes captifs, sans rançon ni présents, dit Yahweh des armées.'),
('is',45,14,'crampon1923','Ainsi parle Yahweh: Les gains de l''Egypte et les profits de l''Ethiopie, et les Sabéens à la haute stature viendront à toi et seront à toi, ils marcheront à ta suite; ils passeront enchaînés, et se prosterneront devant toi; ils te diront en suppliant: " Il n''y a de Dieu que chez toi, et il n''y en a point d''autre, nul autre Dieu absolument! "'),
('is',45,15,'crampon1923','En vérité, vous êtes un Dieu caché, Dieu d''Israël, ô Sauveur!'),
('is',45,16,'crampon1923','Ils sont tous honteux et confus, ils s''en vont confus, les fabricateurs d''idoles.'),
('is',45,17,'crampon1923','Israël est sauvé par Yahweh d''un salut éternel; vous n''aurez ni honte ni confusion dans les siècles à venir.'),
('is',45,18,'crampon1923','Car ainsi parle Yahweh, qui a créé les cieux, lui, le Dieu qui a formé la terre, qui l''a achevée et affermie, qui n''en a pas fait un chaos, mais l''a formée pour être habitée: Je suis Yahweh, et il n''y en a point d''autre!'),
('is',45,19,'crampon1923','Je n''ai point parlé en cachette, dans un lieu obscur de la terre. Je n''ai point dit à la race de Jacob: " Cherchez-moi vainement! " Moi, Yahweh, je dis ce qui est juste, j''annonce la vérité.'),
('is',45,20,'crampon1923','Assemblez-vous et venez; approchez ensemble, réchappés des nations. Ils ne savent rien, ceux qui portent leur idole de bois, et invoquent un dieu qui ne sauve pas.'),
('is',45,21,'crampon1923','Appelez-les, faites-les approcher, et qu''ils se consultent ensemble! Qui a fait entendre ces choses dès le commencement, et depuis longtemps les a annoncées? N''est-ce pas moi, Yahweh? Et il n''y a pas de Dieu en dehors de moi; Moi, le Dieu juste, et il n''y a pas d''autre sauveur que moi.'),
('is',45,22,'crampon1923','Tournez-vous vers moi, et vous serez sauvés, vous tous habitants de la terre, car je suis Dieu, et il n''y en a point d''autre.'),
('is',45,23,'crampon1923','Je l''ai juré par moi-même; de ma bouche sort la vérité, une parole qui ne sera pas révoquée: Tout genou fléchira devant moi, Et toute langue me prêtera serment.'),
('is',45,24,'crampon1923','" En Yahweh seul, dira-t-on de moi, résident la justice et la force! " On viendra à lui; mais ils seront confondus, tous ceux qui étaient enflammés contre lui.'),
('is',45,25,'crampon1923','En Yahweh sera justifiée et sera glorifiée toute la race d''Israël.'),
('is',46,1,'crampon1923','Bel s''écroule, Nébo s''affaisse; on met leurs images sur des animaux, des bêtes de somme; ces idoles que vous portiez sont chargées, comme un fardeau pesant, sur les bêtes fatiguées.'),
('is',46,2,'crampon1923','Ils s''affaissent, ils s''écroulent ensemble; ils ne peuvent sauver le fardeau; ils s''en vont eux-mêmes en captivité.'),
('is',46,3,'crampon1923','Ecoutez-moi, maison de Jacob, et vous tous, reste de la maison d''Israël, vous dont je me suis chargé dès votre naissance, que j''ai portés dès le sein de votre mère.'),
('is',46,4,'crampon1923','Jusqu''à votre vieillesse je serai le même, jusqu''à vos cheveux blancs je vous soutiendrai. Je l''ai déjà fait, et je vous porterai encore; je vous soutiendrai, je vous délivrerai.'),
('is',46,5,'crampon1923','A qui me comparerez-vous, et de qui me ferez-vous l''égal? A qui m''assimilerez-vous, que nous soyons pareils?'),
('is',46,6,'crampon1923','Ils tirent l''or de leur bourse, et pèsent l''argent à la balance; ils engagent un fondeur afin qu''il en fasse un dieu, et ils se prosternent et adorent.'),
('is',46,7,'crampon1923','Ils le portent sur l''épaule, ils le soutiennent, et vont le poser en son lieu; et il s''y tient sans bouger de sa place. Même lorsqu''on crie vers lui, il ne répond pas, il ne sauve personne de la détresse.'),
('is',46,8,'crampon1923','Pensez à cela et montrez-vous hommes; rebelles, prenez-le à cœur,'),
('is',46,9,'crampon1923','rappelez-vous les choses passées des jours d''autrefois. Oui, moi, je suis Dieu, et il n''y en a point d''autre;'),
('is',46,10,'crampon1923','je suis Dieu et nul n''est semblable à moi: moi qui, dès le commencement, annonce la fin, et, longtemps à l''avance, ce qui n''est pas encore; qui dis: " Mon dessein subsistera, et je ferai toute ma volonté; "'),
('is',46,11,'crampon1923','qui de l''Orient appelle l''aigle, d''un pays éloigné l''homme de mon dessein. J''ai parlé, j''accomplirai; j''ai résolu, j''exécuterai!'),
('is',46,12,'crampon1923','Ecoutez-moi, hommes au cœur opiniâtre, qui êtes loin de la justice.'),
('is',46,13,'crampon1923','Je fais approcher ma justice; elle n''est pas loin, et mon salut ne tardera pas; je donnerai le salut à Sion, ma gloire à Israël.'),
('is',47,1,'crampon1923','Descends, assieds-toi dans la poussière, vierge, fille de Babylone; assieds-toi par terre, sans trône, fille des Chaldéens; car on ne t''appellera plus la délicate, la voluptueuse.'),
('is',47,2,'crampon1923','Prends la meule, et mouds de la farine; ôte ton voile; relève les pans de ta robe, mets à nu tes jambes, pour passer les fleuves.'),
('is',47,3,'crampon1923','Que ta nudité soit découverte, qu''on voie ta honte! Je veux me venger, je n''épargnerai personne.'),
('is',47,4,'crampon1923','— Notre Rédempteur se nomme Yahweh des armées, le Saint d''Israël! —'),
('is',47,5,'crampon1923','Assieds-toi en silence, entre dans les ténèbres, fille des Chaldéens; car on ne t''appellera plus la souveraine des royaumes.'),
('is',47,6,'crampon1923','J''étais irrité contre mon peuple; j''ai laissé profaner mon héritage et je les ai livrés entre tes mains... Tu ne leur fis point de miséricorde; sur le vieillard tu as fait peser lourdement ton joug.'),
('is',47,7,'crampon1923','Tu as dit: " Je suis souveraine à jamais! " de sorte que tu n''as pas pris garde à ces choses, tu n''as pas songé à la fin de tout cela.'),
('is',47,8,'crampon1923','Et maintenant, écoute ceci, voluptueuse, assise en sécurité, toi qui disais en ton cœur: " Moi, et rien que moi! Je ne serai jamais veuve, ni privée de mes enfants. "'),
('is',47,9,'crampon1923','Ces deux choses t''arriveront, soudain, en un même jour, et la perte de tes enfants et le veuvage; elles viendront sur toi dans leur plénitude, malgré la multitude de tes sortilèges, malgré la puissance de tes enchantements.'),
('is',47,10,'crampon1923','Tu te confiais dans ta malice; tu disais: " Nul ne me voit! " Ta sagesse et ta science, ce sont elles qui t''ont séduite, alors que tu disais en ton cœur: " Moi, et rien que moi! "'),
('is',47,11,'crampon1923','Et le malheur viendra sur toi sans que tu puisses le conjurer; la calamité fondra sur toi, sans que tu puisses la détourner; et la ruine viendra sur toi soudain, sans que tu t''en doutes.'),
('is',47,12,'crampon1923','Reste donc avec tes enchantements, et avec la multitude de tes sortilèges, auxquels tu t''es adonnée dès ta jeunesse! Peut-être en pourras-tu tirer profit, peut-être inspireras-tu la terreur!'),
('is',47,13,'crampon1923','Tu t''es fatiguée à force de consultations; qu''ils se présentent donc et qu''ils te sauvent, ceux qui mesurent le ciel, qui observent les astres, qui font connaître à chaque nouvelle lune ce qui doit t''arriver.'),
('is',47,14,'crampon1923','Voici qu''ils sont devenus comme le chaume: le feu les consumera, ils ne sauveront pas leur vie de la puissance de la flamme; ce n''est point une braise pour se chauffer, ni un feu pour s''asseoir devant.'),
('is',47,15,'crampon1923','Tels sont pour toi ceux pour qui tu t''es fatiguée; ceux avec qui tu trafiquas dès ta jeunesse: ils fuient chacun de son côté; il n''y a personne qui te sauve!'),
('is',48,1,'crampon1923','Ecoutez ceci, maison de Jacob, vous qui êtes appelés du nom d''Israël, et qui êtes sortis de la source de Juda; vous qui jurez par le nom de Yahweh, et qui célébrez le Dieu d''Israël, mais sans sincérité ni droiture.'),
('is',48,2,'crampon1923','Car ils tirent leur nom de la ville sainte, et ils s''appuient sur le Dieu d''Israël, dont le nom est Yahweh des armées.'),
('is',48,3,'crampon1923','Dès longtemps, j''ai annoncé les premières choses; elles sortirent de ma bouche; je les proclamai; soudain j''ai agi, et elles sont arrivées.'),
('is',48,4,'crampon1923','Comme je savais que tu es dur, que ton cou est une barre de fer, et que ton front est d''airain,'),
('is',48,5,'crampon1923','je t''ai annoncé ces choses il y a longtemps; je te les ai déclarées avant qu''elles n''arrivent, de peur que tu ne dises: " Mon idole les a faites; mon dieu de bois ou de fonte les a ordonnées. "'),
('is',48,6,'crampon1923','Tu l''as entendu; vois, tout s''est accompli; mais vous, ne le déclarerez-vous pas? Maintenant, je te fais entendre des choses nouvelles, cachées, que tu ne connais point.'),
('is',48,7,'crampon1923','C''est maintenant qu''elles sont créées, et non auparavant; jusqu''à ce jour, tu n''en avais point entendu parler, de peur que tu ne dises: " Voici, je le savais! "'),
('is',48,8,'crampon1923','Tu n''en as rien entendu, tu n''en as rien su; jamais ton oreille n''en a rien perçu, parce que je savais que tu es tout à fait infidèle, que ton nom est Prévaricateur dès le sein de ta mère.'),
('is',48,9,'crampon1923','A cause de mon nom, je retiens ma colère, et à cause de ma gloire, je patiente avec toi, pour ne pas t''exterminer.'),
('is',48,10,'crampon1923','Voici, je t''ai fondu, mais sans obtenir l''argent; je t''ai éprouvé au creuset de l''affliction.'),
('is',48,11,'crampon1923','C''est pour l''amour de moi, pour l''amour de moi que je le fais; car comment mon nom serait-il profané? Je ne donnerai pas ma gloire à un autre.'),
('is',48,12,'crampon1923','Ecoute-moi, Jacob, et toi, Israël, que j''ai appelé; c''est moi, moi qui suis le premier, moi aussi qui suis le dernier.'),
('is',48,13,'crampon1923','C''est aussi ma main qui a fondé la terre, et ma droite qui a étendu les cieux; c''est moi qui les appelle, et aussitôt ils se présentent.'),
('is',48,14,'crampon1923','Assemblez-vous tous et écoutez: qui d''entre eux a annoncé ces choses? — Celui qu''aime Yahweh accomplira sa volonté dans Babel, et son bras sera contre les Chaldéens. —'),
('is',48,15,'crampon1923','Moi, moi, j''ai parlé, et je l''ai appelé; je l''ai fait venir, et sa voie sera prospère.'),
('is',48,16,'crampon1923','Approchez-vous de moi, entendez ceci: Dès l''origine je n''ai point parlé en cachette; depuis que ces choses arrivent, je suis là; — Et maintenant le Seigneur Yahweh m''envoie avec son Esprit. —'),
('is',48,17,'crampon1923','Ainsi parle Yahweh, ton rédempteur, le Saint d''Israël: Moi, Yahweh, ton Dieu, je t''enseigne pour ton bien, je te conduis dans le chemin où tu dois marcher.'),
('is',48,18,'crampon1923','Oh! sois attentif à mes commandements, et ta paix sera comme un fleuve, ta justice comme les flots de la mer;'),
('is',48,19,'crampon1923','ta postérité sera comme le sable et le fruit de tes entrailles comme les grains de sable; son nom ne sera ni retranché ni effacé devant moi.'),
('is',48,20,'crampon1923','Sortez de Babylone, fuyez les Chaldéens avec des cris de joie! Publiez-le, proclamez-le, faites-le savoir jusqu''à l''extrémité de la terre! Dites: " Yahweh a racheté son serviteur Jacob!'),
('is',48,21,'crampon1923','Ils n''ont pas soif dans le désert où il les a conduits; il fait couler pour eux l''eau du rocher; il fend le rocher, et les eaux jaillissent! "'),
('is',48,22,'crampon1923','Il n''y a point de paix pour les méchants, dit Yahweh.'),
('is',49,1,'crampon1923','Iles, entendez-moi: peuples lointains, soyez attentifs! Yahweh m''a appelé dès le sein maternel, dès les entrailles de ma mère il a proclamé mon nom.'),
('is',49,2,'crampon1923','Il a fait de ma bouche une épée tranchante; il m''a abrité sous l''ombre de sa main; il a fait de moi une flèche aiguë, il m''a caché dans son carquois.'),
('is',49,3,'crampon1923','Et il m''a dit: " Tu es mon serviteur, Israël, en qui je me glorifierai. "'),
('is',49,4,'crampon1923','Et moi j''ai dit: " En vain je me suis fatigué; inutilement, pour rien, j''ai consumé ma force; mais mon droit est auprès de Yahweh, et ma récompense auprès de mon Dieu. "'),
('is',49,5,'crampon1923','Et maintenant Yahweh parle, lui qui m''a formé dès le sein de ma mère pour être son Serviteur, pour ramener à lui Jacob, et pour qu''Israël lui soit réuni. — Et je suis honoré aux yeux de Yahweh, et mon Dieu est ma force. —'),
('is',49,6,'crampon1923','Il a dit: " C''est peu que tu sois mon Serviteur, pour rétablir les tribus de Jacob et pour ramener les préservés d''Israël; je t''établirai lumière des nations, pour que mon salut arrive jusqu''aux extrémités de la terre. "'),
('is',49,7,'crampon1923','Ainsi parle Yahweh, le rédempteur et le Saint d''Israël; à celui qui est méprisé, abominable au peuple, à l''esclave des tyrans: Des rois te verront et se lèveront, des princes, et ils se prosterneront, à cause de Yahweh qui est fidèle, et du Saint d''Israël qui t''a choisi.'),
('is',49,8,'crampon1923','Ainsi parle Yahweh: Au temps de la grâce je t''exauce, et au jour du salut, je te viens en aide; je t''ai gardé et établi Alliance du peuple, pour relever le pays, pour partager les héritages dévastés;'),
('is',49,9,'crampon1923','pour dire aux captifs: " Sortez! " à ceux qui sont dans les ténèbres: " Venez à la lumière! " Ils pourront paître le long des chemins, et sur toute hauteur seront leurs pâturages;'),
('is',49,10,'crampon1923','ils n''auront pas faim, ils n''auront pas soif; ni le sable brûlant, ni le soleil ne les atteindront. Car celui qui a pitié d''eux sera leur guide, et les conduira aux eaux jaillissantes.'),
('is',49,11,'crampon1923','Je ferai de toutes mes montagnes des chemins, et mes routes seront relevées.'),
('is',49,12,'crampon1923','En voici qui viennent de loin; en voici du septentrion et du couchant; et ceux-là du pays des Sinim.'),
('is',49,13,'crampon1923','Cieux, poussez des cris de joie! Terre, tressaille! Montagnes, éclatez en cris joyeux! Car Yahweh a consolé son peuple, et il a compassion de ses affligés.'),
('is',49,14,'crampon1923','Sion disait: " Yahweh m''a abandonnée; le Seigneur m''a oubliée! "'),
('is',49,15,'crampon1923','Une femme oubliera-t-elle son nourrisson, n''aura-t-elle pas pitié du fruit de ses entrailles? Quand même les mères oublieraient, moi, je ne t''oublierai point!'),
('is',49,16,'crampon1923','Vois, je t''aie gravée sur la paume de mes mains; tes murs sont toujours devant mes yeux.'),
('is',49,17,'crampon1923','Tes fils accourent; ceux qui t''avaient détruite et dévastée s''éloignent de toi.'),
('is',49,18,'crampon1923','Lève les yeux autour de toi et regarde: ils se rassemblent tous, ils viennent à toi. Je suis vivant, — oracle de Yahweh, tu te revêtiras d''eux tous comme d''une parure, tu t''en ceindras comme d''une ceinture de fiancée.'),
('is',49,19,'crampon1923','Car tes ruines, tes déserts, ton pays dévasté, tout cela maintenant sera trop étroit pour tes habitants; et ceux qui te dévoraient se sont éloignés.'),
('is',49,20,'crampon1923','Alors ils diront à tes oreilles, tes fils, dont tu étais privée: " L''espace est trop étroit pour moi; fais-moi de la place pour que je puisse habiter. "'),
('is',49,21,'crampon1923','Et tu diras en ton cœur: " Qui m''a enfanté ceux-ci? J''étais privée d''enfants, stérile, bannie et répudiée; et ceux-ci, qui les a élevés? Voici que j''étais restée seule; ceux-ci, où étaient-ils? "'),
('is',49,22,'crampon1923','Ainsi parle le Seigneur Yahweh: Voici que je lèverai ma main vers les nations, que je dresserai mon étendard vers les peuples; et ils ramèneront tes fils entre leurs bras, et ils rapporteront tes filles sur leurs épaules.'),
('is',49,23,'crampon1923','Des rois seront tes nourriciers, et leurs princesses tes nourrices; ils se prosterneront devant toi la face contre terre, et ils lècheront la poussière de tes pieds; et tu sauras que je suis Yahweh, et que ceux qui espèrent en moi ne seront pas confondus.'),
('is',49,24,'crampon1923','Mais arrachera-t-on au puissant sa proie, et les justes qu''on a faits captifs échapperont-ils? —'),
('is',49,25,'crampon1923','Ainsi parle Yahweh: Même la proie du puissant lui sera arrachée, et la proie du violent lui échappera. Tes adversaires, moi, je les combattrai; tes fils, moi, je les sauverai.'),
('is',49,26,'crampon1923','Je ferai manger à tes oppresseurs leur propre chair, ils s''enivreront de leur sang comme d''un vin nouveau; et toute chair saura que moi, Yahweh, je suis ton Sauveur, et que ton rédempteur est le Puissant de Jacob!'),
('is',50,1,'crampon1923','Ainsi parle Yahweh: Où est la lettre de divorce de votre mère, par laquelle je l''ai répudiée? Ou bien, quel est celui de mes créanciers auquel je vous ai vendus? C''est à cause de vos iniquités que vous avez été vendus, à cause de vos péchés que votre mère a été renvoyée.'),
('is',50,2,'crampon1923','Je suis venu: pourquoi n''y avait-il personne? J''ai appelé: pourquoi personne n''a-t-il répondu? Ma main est-elle donc trop courte pour délivrer, ou bien n''ai-je pas assez de force pour sauver? Voici que, par ma menace, je dessèche la mer, je change les fleuves en désert; leurs poissons pourrissent faute d''eau, et ils périssent de soif.'),
('is',50,3,'crampon1923','Je revêts les cieux d''obscurité, et je les couvre d''un sac.'),
('is',50,4,'crampon1923','Le Seigneur Yahweh m''a donné la langue des disciples, pour que je sache fortifier par ma parole celui qui est abattu. Il éveille, chaque matin, il éveille mon oreille, pour que j''écoute en disciple.'),
('is',50,5,'crampon1923','Le Seigneur Yahweh m''a ouvert l''oreille; et moi, je n''ai pas résisté, je ne me suis pas retiré en arrière.'),
('is',50,6,'crampon1923','J''ai livré mon dos à ceux qui me frappaient, et mes joues à ceux qui m''arrachaient la barbe; je n''ai pas dérobé mon visage aux outrages et aux crachats.'),
('is',50,7,'crampon1923','Le Seigneur Yahweh m''est venu en aide; c''est pourquoi l''outrage ne m''a point abattu; c''est pourquoi j''ai rendu ma face semblable à un caillou; et je savais que je ne serais pas confondu.'),
('is',50,8,'crampon1923','Il est proche, celui qui me justifie: qui plaidera contre moi? Comparaissons ensemble! Qui est mon adversaire: qu''il s''approche de moi!'),
('is',50,9,'crampon1923','Le Seigneur Yahweh m''est venu en aide: qui est-ce qui me condamnerait? Ah! ils tomberont tous en lambeaux comme un vêtement; la teigne les dévorera!'),
('is',50,10,'crampon1923','Qui d''entre vous craint Yahweh, et écoute la voix de son Serviteur? Quiconque marche dans les ténèbres, privé de lumière, qu''il se confie dans le nom de Yahweh, et qu''il s''appuie sur son Dieu!'),
('is',50,11,'crampon1923','Mais vous tous qui allumez un feu, et qui vous armez de flèches embrasées, allez dans les flammes de votre feu, et au milieu des flèches que vous avez enflammées! C''est par ma main que ces choses vous arriveront; vous serez couchés dans la douleur!'),
('is',51,1,'crampon1923','Entendez-moi, vous qui poursuivez la justice, vous qui cherchez Yahweh; considérez le rocher d''où vous avez été taillés et la carrière d''où vous avez été tirés.'),
('is',51,2,'crampon1923','Considérez Abraham, votre père, et Sara qui vous a enfantés; car je l''appelai quand il était seul, et je l''ai béni et multiplié.'),
('is',51,3,'crampon1923','Car Yahweh a consolé Sion, et il a consolé toutes ses ruines. Il a fait de son désert un Eden, et de sa solitude un jardin de Yahweh; On y trouvera la joie et l''allégresse, les actions de grâces et le bruit des chants.'),
('is',51,4,'crampon1923','Sois attentif à ma voix, ô mon peuple; ô ma nation, prête-moi l''oreille! Car la loi sortira de moi, et j''établirai mon commandement pour être la lumière des peuples.'),
('is',51,5,'crampon1923','Ma justice est proche, mon salut va paraître, et mon bras jugera les peuples; les îles espèrent en moi et se confient dans mon bras.'),
('is',51,6,'crampon1923','Levez vos yeux vers le ciel, et abaissez vos regards sur la terre; car les cieux se dissiperont comme une fumée, et la terre tombera en lambeaux comme un vêtement, et ses habitants périront de même. Mais mon salut durera éternellement, et ma justice ne périra pas.'),
('is',51,7,'crampon1923','Entendez-moi, vous qui connaissez la justice, ô peuple qui as ma loi dans ton cœur: Ne craignez pas les injures des hommes, et ne vous effrayez pas de leurs outrages!'),
('is',51,8,'crampon1923','Car la teigne les dévorera comme un vêtement, et la gerce les rongera comme la laine. Mais ma justice subsistera à jamais, et mon salut jusqu''aux siècles des siècles.'),
('is',51,9,'crampon1923','Réveille-toi, réveille-toi, revêts-toi de force, bras de Yahweh! Réveille-toi comme aux jours anciens, comme aux âges d''autrefois. N''est-ce pas toi qui taillas en pièces Rahab, qui transperças le dragon?'),
('is',51,10,'crampon1923','N''est-ce pas toi qui desséchas la mer, les eaux du grand abîme; qui fis des profondeurs de la mer un chemin, pour faire passer les rachetés?'),
('is',51,11,'crampon1923','Ainsi les rachetés de Yahweh reviendront; ils viendront dans Sion avec des cris de joie; une allégresse éternelle couronnera leur tête, la joie et l''allégresse les envahiront; la douleur et le gémissement s''enfuiront.'),
('is',51,12,'crampon1923','C''est moi, c''est moi qui vous console. Qui es-tu pour craindre un homme mortel, un fils d''homme qui passe comme l''herbe;'),
('is',51,13,'crampon1923','pour oublier Yahweh, ton Créateur, qui a étendu les cieux et fondé la terre, et pour trembler perpétuellement, tout le jour, devant la fureur du tyran, lorsqu''il se prépare à te détruire? Et où est-elle ta fureur du tyran?'),
('is',51,14,'crampon1923','Bientôt celui qui est courbé sera délié; il ne mourra pas dans la fosse, et son pain ne lui manquera pas.'),
('is',51,15,'crampon1923','Moi, je suis Yahweh, ton Dieu, qui soulève la mer, et ses flots mugissent; Yahweh des armées est son nom.'),
('is',51,16,'crampon1923','J''ai mis mes paroles dans ta bouche, et je t''ai couvert de l''ombre de ma main, pour planter des cieux et fonder une terre, et pour dire à Sion: " Tu es mon peuple! "'),
('is',51,17,'crampon1923','Réveille-toi, réveille-toi, lève-toi, Jérusalem, qui as bu de la main de Yahweh la coupe de sa colère, qui as bu, qui as vidé le calice d''étourdissement!'),
('is',51,18,'crampon1923','Pas un qui l''ait guidée, de tous les fils qu''elle avait enfantés. Pas un qui l''ait prise par la main, de tous les fils qu''elle avait élevés.'),
('is',51,19,'crampon1923','Ces deux malheurs t''ont frappée: — qui t''adressera des paroles de pitié? — La dévastation et la ruine, la famine et l''épée — comment te consolerai-je? —'),
('is',51,20,'crampon1923','Tes fils, épuisés de force, sont gisants au coin de toutes les rues, comme une antilope dans le filet du chasseur, ivres de la fureur de Yahweh, de la menace de ton Dieu.'),
('is',51,21,'crampon1923','C''est pourquoi, entends ceci, malheureuse, enivrée, mais non de vin!'),
('is',51,22,'crampon1923','Ainsi parle ton Seigneur Yahweh, ton Dieu, qui défend son peuple: Voici que j''ai ôté de ta main la coupe d''étourdissement, le calice de ma colère; tu ne les boiras plus désormais.'),
('is',51,23,'crampon1923','Je les mettrai dans la main de tes persécuteurs, de ceux qui te disaient: " Courbe-toi, que nous passions! " Et tu faisais de ton dos comme un sol, comme une rue pour les passants!'),
('is',52,1,'crampon1923','Réveille-toi, réveille-toi, revêts ta force, Sion! Revêts tes habits de fête, Jérusalem, ville sainte! Car l''incirconcis et l''impur n''entreront plus chez toi désormais.'),
('is',52,2,'crampon1923','Secoue ta poussière, relève-toi, assieds-toi, Jérusalem; détache les chaînes de ton cou, captive, fille de Sion!'),
('is',52,3,'crampon1923','Car ainsi parle Yahweh: Vous avez été vendus pour rien, et sans argent vous serez rachetés!'),
('is',52,4,'crampon1923','Car ainsi parle le Seigneur Yahweh: Mon peuple descendit jadis en Egypte pour y séjourner puis Assur l''opprima sans cause.'),
('is',52,5,'crampon1923','Et maintenant qu''ai-je à faire ici? — oracle de Yahweh, puisque mon peuple a été enlevé sans droit? Ses tyrans poussent des hurlements, — oracle de Yahweh, et sans cesse, tout le jour, mon nom est outragé.'),
('is',52,6,'crampon1923','C''est pourquoi mon peuple connaîtra mon nom; oui, il saura en ce jour que c''est moi qui dis: " Me voici! "'),
('is',52,7,'crampon1923','Qu''ils sont beaux sur les montagnes les pieds du messager, qui publie la bonne nouvelle de la paix; de celui qui annonce le bonheur, qui publie le salut; de celui qui dit à Sion: " Ton Dieu règne! "'),
('is',52,8,'crampon1923','La voix de tes sentinelles! Elles élèvent la voix, elles poussent ensemble des cris d''allégresse, car elles voient de leurs yeux le retour de Yahweh en Sion.'),
('is',52,9,'crampon1923','Eclatez ensemble en cris de joie, ruines de Jérusalem! Car Yahweh a consolé son peuple, il a racheté Jérusalem.'),
('is',52,10,'crampon1923','Yahweh a découvert le bras de sa sainteté, aux yeux de toutes les nations; et toutes les extrémités de la terre verront le salut de notre Dieu.'),
('is',52,11,'crampon1923','Partez, partez, sortez de là; ne touchez rien d''impur! Sortez du milieu d''elle; purifiez-vous; vous qui portez les vases de Yahweh.'),
('is',52,12,'crampon1923','Car vous ne sortirez pas avec précipitation, et vous ne vous en irez pas en fuyant; car Yahweh marche devant vous, et le Dieu d''Israël est votre arrière garde!'),
('is',52,13,'crampon1923','Voici que mon Serviteur prospérera; il grandira, il sera exalté, souverainement élevé.'),
('is',52,14,'crampon1923','De même que beaucoup ont été dans la stupeur en le voyant, — tant il était défiguré, son aspect n''étant plus celui d''un homme, ni son visage celui des enfants des hommes, —'),
('is',52,15,'crampon1923','ainsi il fera tressaillir des nations nombreuses. Devant lui les rois fermeront la bouche; car ils verront ce qui ne leur avait pas été raconté, et ils apprendront ce qu''ils n''avaient pas entendu.'),
('is',53,1,'crampon1923','Qui a cru ce que nous avons entendu, et à qui le bras de Yahweh a-t-il été révélé?'),
('is',53,2,'crampon1923','Il s''est élevé devant lui comme un frêle arbrisseau; comme un rejeton qui sort d''une terre desséchée; il n''avait ni forme ni beauté pour attirer nos regards, ni apparence pour exciter notre amour.'),
('is',53,3,'crampon1923','Il était méprisé et abandonné des hommes, homme de douleurs et familier de la souffrance, comme un objet devant lequel on se voile la face; en butte au mépris, nous n''en faisions aucun cas.'),
('is',53,4,'crampon1923','Vraiment c''était nos maladies qu''il portait, et nos douleurs dont il s''était chargé; et nous, nous le regardions comme un puni, frappé de Dieu et humilié.'),
('is',53,5,'crampon1923','Mais lui, il a été transpercé à cause de nos péchés, broyé à cause de nos iniquités; le châtiment qui nous donne la paix a été sur lui, et c''est par ses meurtrissures que nous sommes guéris.'),
('is',53,6,'crampon1923','Nous étions tous errants comme des brebis, chacun de nous suivait sa propre voie; et Yahweh a fait retomber sur lui l''iniquité de nous tous.'),
('is',53,7,'crampon1923','On le maltraite, et lui se soumet et n''ouvre pas la bouche, semblable à l''agneau qu''on mène à la tuerie, et à la brebis muette devant ceux qui la tondent; il n''ouvre point la bouche.'),
('is',53,8,'crampon1923','Il a été enlevé par l''oppression et le jugement, et, parmi ses contemporains, qui a pensé qu''il était retranché de la terre des vivants, que la plaie le frappait à cause des péchés de mon peuple?'),
('is',53,9,'crampon1923','On lui a donné son sépulcre avec les méchants, et dans sa mort il est avec le riche, alors qu''il n''a pas commis d''injustice, et qu''il n''y a pas de fraude dans sa bouche.'),
('is',53,10,'crampon1923','Il a plu à Yahweh de le briser par la souffrance; mais quand son âme aura offert le sacrifice expiatoire, il verra une postérité, il prolongera ses jours, et le dessein de Yahweh prospérera dans ses mains.'),
('is',53,11,'crampon1923','A cause des souffrances de son âme, il verra et se rassasiera. Par sa connaissance le juste, mon Serviteur, justifiera beaucoup d''hommes, et lui-même se chargera de leurs iniquités.'),
('is',53,12,'crampon1923','C''est pourquoi je lui donnerai sa part parmi les grands; il partagera le butin avec les forts. Parce qu''il a livré son âme à la mort et qu''il a été compté parmi les malfaiteurs; et lui-même a porté la faute de beaucoup, et il intercédera pour les pécheurs.'),
('is',54,1,'crampon1923','Pousse des cris de joie, stérile, qui n''enfantais pas; éclate de joie et d''allégresse, toi qui n''as pas été en travail, car les fils de la délaissée sont plus nombreux que les fils de celle qui avait un époux, dit Yahweh.'),
('is',54,2,'crampon1923','Elargis l''espace de la tente; qu''on déploie les tentures de ta demeure; ne les retiens pas, allonge tes cordages, et affermis tes pieux!'),
('is',54,3,'crampon1923','Car tu te répandras à droite et à gauche, et ta postérité prendra possession des nations, et peuplera les villes désertes.'),
('is',54,4,'crampon1923','Ne crains point, car tu ne seras pas confondue; n''aie point honte, car tu n''auras pas à rougir; car tu oublieras la honte de ta jeunesse, et tu ne te souviendras plus de l''opprobre de ton veuvage.'),
('is',54,5,'crampon1923','Car ton époux, c''est ton Créateur; Yahweh des armées est son nom; et ton Rédempteur est le Saint d''Israël; il s''appelle le Dieu de toute la terre.'),
('is',54,6,'crampon1923','Car comme une femme délaissée et affligée, Yahweh te rappelle comme une épouse de la jeunesse qui a été répudiée, dit ton Dieu.'),
('is',54,7,'crampon1923','Un instant, un moment, je t''ai abandonnée, mais avec une grande miséricorde je te rassemble.'),
('is',54,8,'crampon1923','Dans une effusion de ma colère, je t''ai caché un moment mon visage, mais avec un amour éternel j''ai compassion de toi, dit ton Rédempteur, Yahweh.'),
('is',54,9,'crampon1923','Il en sera pour moi comme des eaux de Noé, lorsque je jurai que les eaux de Noé ne se répandraient plus sur la terre: ainsi j''ai juré de ne plus m''irriter contre toi, et de ne plus te menacer.'),
('is',54,10,'crampon1923','Quand les montagnes se retireraient, et que les collines seraient ébranlées, mon amour ne se retirerait pas de toi, et mon alliance de paix ne sera point ébranlée, dit celui qui a compassion de toi, Yahweh.'),
('is',54,11,'crampon1923','Malheureuse, battue de la tempête, sans consolation, voici que je coucherai tes pierres dans l''antimoine, et que je te fonderai sur des saphirs;'),
('is',54,12,'crampon1923','je ferai tes créneaux de rubis, tes portes d''escarboucles, et toute ton enceinte de pierres précieuses.'),
('is',54,13,'crampon1923','Tous tes fils seront disciples de Yahweh, tes fils jouiront d''une grande paix.'),
('is',54,14,'crampon1923','Tu seras affermie sur la justice; loin de toi l''angoisse, car tu n''as rien à redouter; la frayeur, car elle n''approchera pas de toi.'),
('is',54,15,'crampon1923','Si une ligue se forme, cela ne viendra pas de moi; qui s''est ligué contre toi? Il tombera devant toi.'),
('is',54,16,'crampon1923','Voici que moi, j''ai créé le forgeron, qui souffle sur les charbons ardents, et qui en retire l''arme qu''il doit travailler, et c''est moi qui ai créé le dévastateur pour la détruire.'),
('is',54,17,'crampon1923','Toute arme forgée contre toi sera sans effet, et toute langue qui s''élèvera pour contester avec toi, tu la condamneras. Tel est l''héritage des fils de Yahweh; telle est la justice qui leur viendra de moi — oracle de Yahweh.'),
('is',55,1,'crampon1923','O vous tous qui avez soif, venez aux eaux, vous-mêmes qui n''avez pas d''argent; venez, achetez du blé et mangez; venez, achetez sans argent, et sans rien donner en échange, du vin et du lait.'),
('is',55,2,'crampon1923','Pourquoi dépenser de l''argent pour ce qui n''est pas du pain, votre travail pour ce qui ne rassasie pas? Ecoutez-moi donc, et mangez ce qui est bon, et que votre âme se délecte de mets succulents.'),
('is',55,3,'crampon1923','Prêtez l''oreille et venez à moi; écoutez, et que votre âme vive; et je conclurai avec vous un pacte éternel, vous accordant les grâces assurées à David.'),
('is',55,4,'crampon1923','Voici que je l''ai établi témoin auprès des peuples, prince et dominateur des peuples.'),
('is',55,5,'crampon1923','Voici que tu appelleras la nation que tu ne connaissais pas, et les nations qui ne te connaissaient pas accourront à toi, à cause de Yahweh, ton Dieu, et du Saint d''Israël, parce qu''il t''a glorifié!'),
('is',55,6,'crampon1923','Cherchez Yahweh, pendant qu''on peut le trouver; invoquez-le, tandis qu''il est près.'),
('is',55,7,'crampon1923','Que le méchant abandonne sa voie, et le criminel ses pensées; qu''il revienne à Yahweh, et il lui fera grâce; à notre Dieu, car il pardonne largement.'),
('is',55,8,'crampon1923','Car mes pensées ne sont pas vos pensées, et vos voies ne sont pas mes voies, — oracle de Yahweh.'),
('is',55,9,'crampon1923','Autant les cieux sont élevés au-dessus de la terre, autant mes voies sont élevées au-dessus de vos voies et mes pensées au-dessus de vos pensées.'),
('is',55,10,'crampon1923','Comme la pluie et la neige descendent du ciel et n''y retournent pas, qu''elles n''aient abreuvé et fécondé la terre et qu''elles ne l''aient fait germer, qu''elles n''aient donné la semence au semeur, et le pain à celui qui mange;'),
('is',55,11,'crampon1923','ainsi en est-il de ma parole qui sort de ma bouche: elle ne revient pas à moi sans effet, mais elle exécute ce que j''ai voulu, et accomplit ce pour quoi je l''ai envoyée.'),
('is',55,12,'crampon1923','Car vous sortirez pleins de joie, et vous serez conduits en paix; les montagnes et les collines, à votre vue, éclateront de joie, et tous les arbres de la campagne applaudiront.'),
('is',55,13,'crampon1923','Au lieu de l''épine s''élèvera le cyprès, et au lieu de la ronce croîtra le myrte; ce sera pour Yahweh un honneur, un monument éternel qui ne sera pas détruit.'),
('is',56,1,'crampon1923','Ainsi parle Yahweh: Observez le droit et pratiquez ce qui est juste, car mon salut est près d''arriver, et ma justice va se manifester.'),
('is',56,2,'crampon1923','Heureux l''homme qui fera cela, et le fils de l''homme qui s''y attachera, gardant le sabbat sans le profaner, et gardant sa main pour ne faire aucun mal!'),
('is',56,3,'crampon1923','Que le fils de l''étranger, attaché à Yahweh, ne dise pas: " Yahweh m''exclura certainement de son peuple! " et que l''eunuque ne dise pas: " Voici que je suis un arbre sec! "'),
('is',56,4,'crampon1923','Car ainsi parle Yahweh aux eunuques: A ceux qui garderont mes sabbats, qui choisiront ce qui m''est agréable, et qui s''attacheront à mon alliance,'),
('is',56,5,'crampon1923','je donnerai dans ma maison et dans mes murs un monument et un nom, meilleurs que des fils et des filles; je leur donnerai un nom éternel, qui ne périra pas.'),
('is',56,6,'crampon1923','Et les fils de l''étranger, attachés à Yahweh, pour le servir et pour aimer son nom, pour être ses serviteurs, tous ceux qui gardent le sabbat, sans le profaner; et qui tiennent ferme à mon alliance,'),
('is',56,7,'crampon1923','je les amènerai à ma montagne sainte, et je les réjouirai dans ma maison de prière; leurs holocaustes et leurs sacrifices seront agréés sur mon autel; car ma maison sera appelée une maison de prière, pour tous tes peuples,'),
('is',56,8,'crampon1923','— oracle du Seigneur Yahweh; qui rassemble les exilés d''Israël! J''en rassemblerai encore d''autres vers lui; avec ceux qui sont déjà rassemblés.'),
('is',56,9,'crampon1923','Vous tous, animaux des champs, venez dévorer, et vous toutes aussi, bêtes de la forêt!'),
('is',56,10,'crampon1923','Les gardiens d''Israël sont tous aveugles, ils ne savent rien; ce sont tous des chiens muets, qui ne peuvent pas aboyer; ils rêvent, ils se couchent, ils aiment a dormir.'),
('is',56,11,'crampon1923','Ce sont des chiens voraces, ils ne savent pas se rassasier. Et ce sont des bergers, ils ne savent rien comprendre! Tous suivent leur propre chemin, chacun selon son profit, du premier jusqu''au dernier.'),
('is',56,12,'crampon1923','" Venez, je vais chercher du vin, et nous nous remplirons de liqueurs fortes et demain sera comme aujourd''hui, grand, très grand jour de joie! "'),
('is',57,1,'crampon1923','Cependant, le juste disparaît, et personne ne le prend à cœur; les hommes pieux sont enlevés, et nul ne prend garde que le juste a été retiré du malheur,'),
('is',57,2,'crampon1923','et qu''il entre dans la paix! Ils reposent sur leurs couches, ceux qui ont suivi le droit chemin!'),
('is',57,3,'crampon1923','Mais vous, approchez ici, fils de la magicienne, race de l''adultère et de la prostituée!'),
('is',57,4,'crampon1923','De qui vous moquez-vous? Contre qui ouvrez-vous la bouche, et tirez-vous la langue? N''êtes-vous pas des enfants de prévarication, une race de mensonge?'),
('is',57,5,'crampon1923','Vous vous échauffez près des térébinthes, sous tout arbre vert! vous égorgez les enfants dans les vallées, sous les grottes des rochers?'),
('is',57,6,'crampon1923','Ta part est dans les pierres polies du torrent; voilà, voilà ton lot! Tu as été jusqu''à leur verser des libations, à leur présenter des offrandes! Puis-je être satisfait de cela?'),
('is',57,7,'crampon1923','Sur une montagne haute et élevée tu as établi ta couche! Et c''est là que tu montes pour faire des sacrifices.'),
('is',57,8,'crampon1923','Derrière la porte et les poteaux, tu as mis ton mémorial; car, loin de moi, tu découvres ta couche, tu y montes, tu élargis ton lit, et tu leur fixes ton salaire; tu aimes leurs embrassements, tu souilles tes regards!'),
('is',57,9,'crampon1923','Tu te présentes devant le roi avec de l''huile; tu multiplies tes parfums; tu envoies au loin des messagers; tu t''abaisses jusqu''au schéol.'),
('is',57,10,'crampon1923','A force de démarches, tu te fatigues; tu ne dis pas: " C''est en vain! " tu trouves encore de la vigueur dans ta main; c''est pourquoi tu ne te sens pas malade.'),
('is',57,11,'crampon1923','Et qui donc crains-tu? De qui as-tu peur, que tu me sois infidèle, que tu ne te souviennes plus de moi, que tu ne t''en soucies pas? Ne me suis-je pas tu, et depuis longtemps, tandis que tu ne me craignais pas?'),
('is',57,12,'crampon1923','Moi, je publierai ta justice, et tes œuvres qui ne te servent de rien.'),
('is',57,13,'crampon1923','Quand tu crieras, qu''ils te délivrent, tes tas de dieux! Le vent les emportera tous, un souffle les enlèvera! Mais celui qui se confie en moi héritera le pays, et possédera ma sainte montagne.'),
('is',57,14,'crampon1923','Et l''on dira: Frayez, frayez la voie; aplanissez-la! Enlevez tout obstacle du chemin de mon peuple!'),
('is',57,15,'crampon1923','Car ainsi parle le Très-Haut, qui habite une demeure éternelle et s''appelle le Saint: J''habite dans un lieu haut et saint, et en même temps avec l''homme contrit et humble d''esprit, pour rendre la vie à l''esprit des humbles, pour rendre la vie aux cœurs contrits.'),
('is',57,16,'crampon1923','Car je ne veux pas contester à jamais, ni garder un courroux éternel; car devant moi tomberaient en défaillance l''esprit et les âmes que j''ai faites.'),
('is',57,17,'crampon1923','A cause de sa convoitise coupable, je me suis irrité, et, demeurant caché, je l''ai frappé dans mon courroux; et lui, rebelle, suivait la voie de son propre cœur! …'),
('is',57,18,'crampon1923','J''ai vu ses voies, et je le guérirai; Je serai son guide et je lui rendrai mes consolations, à lui et à ses affligés.'),
('is',57,19,'crampon1923','Celui qui crée sur les lèvres la louange, dit: " Paix, paix, à qui est loin et à qui est près, dit Yahweh, et je le guérirai! "'),
('is',57,20,'crampon1923','Mais les méchants sont comme la mer agitée, qui ne peut se calmer, et ses flots roulent de la vase et de la boue.'),
('is',57,21,'crampon1923','Il n''y a point de paix, dit mon Dieu, pour les méchants.'),
('is',58,1,'crampon1923','Crie à plein gosier, ne te retiens pas; fais retentir ta voix comme la trompette, et dénonce à mon peuple son péché, à la maison de Jacob ses iniquités.'),
('is',58,2,'crampon1923','Ils me cherchent chaque jour, et ils veulent connaître mes voies, comme une nation qui aurait pratiqué la justice, et n''aurait pas abandonné le commandement de son Dieu. Ils me demandent des jugements justes, ils veulent que Dieu s''approche:'),
('is',58,3,'crampon1923','" Que nous sert de jeûner, si vous ne le voyez pas, d''humilier notre âme, si vous n''y prenez pas garde? " — Au jour de votre jeûne, vous faites vos affaires et vous pressez au travail tous vos mercenaires.'),
('is',58,4,'crampon1923','Voici, c''est en vous disputant et vous querellant que vous jeûnez, jusqu''à frapper du poing méchamment! Vous ne jeûnez pas en ce jour, de manière à faire écouter votre voix en haut.'),
('is',58,5,'crampon1923','Est-ce à un jeûne pareil que je prends plaisir? Est-ce là un jour où l''homme humilie son âme? Courber la tête comme un jonc, se coucher sur le sac et la cendre: est-ce là ce que tu appelles un jeûne, un jour agréable à Yahweh?'),
('is',58,6,'crampon1923','Le jeûne que je choisis ne consiste-t-il pas en ceci: détacher les chaînes injustes, délier les nœuds du joug, renvoyer libres les opprimés, briser toute espèce de joug?'),
('is',58,7,'crampon1923','Ne consiste-t-il pas à rompre ton pain à celui qui a faim, à recueillir chez toi les malheureux sans asile; si tu vois un homme nu, à le couvrir, à ne point te détourner de ta propre chair?'),
('is',58,8,'crampon1923','Alors ta lumière poindra comme l''aurore, et ta guérison germera promptement; ta justice marchera devant toi; la gloire de Yahweh sera ton arrière garde.'),
('is',58,9,'crampon1923','Alors tu appelleras, et Yahweh répondra: tu crieras, et il dira: " Me voici! " Si tu bannis du milieu de toi le joug, le geste menaçant, les discours injurieux;'),
('is',58,10,'crampon1923','si tu donnes ta nourriture à l''affamé, et si tu rassasies l''âme affligée; Ta lumière se lèvera au sein de l''obscurité, et tes ténèbres brilleront comme le midi.'),
('is',58,11,'crampon1923','Et Yahweh te guidera perpétuellement, il rassasiera ton âme dans les lieux arides. Il donnera de la vigueur à tes os; tu seras comme un jardin bien arrosé, comme une source d''eau vive, qui ne tarit jamais.'),
('is',58,12,'crampon1923','Tes enfants rebâtiront tes ruines antiques; tu relèveras des fondements posés aux anciens âges; on t''appellera le réparateur des brèches, le restaurateur des chemins, pour rendre le pays habitable.'),
('is',58,13,'crampon1923','Si tu t''abstiens de fouler aux pieds le sabbat, en t''occupant de tes affaires en mon saint jour, et que tu appelles le sabbat tes délices, vénérable le saint jour de Yahweh, et que tu l''honores en ne poursuivant point tes voies, en ne te livrant pas à tes affaires et à de vains discours;'),
('is',58,14,'crampon1923','Alors tu trouveras tes délices en Yahweh, et je te transporterai comme en triomphe sur les hauteurs du pays, et je te ferai jouir de l''héritage de Jacob, ton père; car la bouche de Yahweh a parlé.'),
('is',59,1,'crampon1923','Voici que la main de Yahweh n''est pas trop courte pour sauver, ni son oreille trop dure pour entendre.'),
('is',59,2,'crampon1923','Mais vos iniquités ont mis une séparation entre vous et votre Dieu; vos péchés lui ont fait cacher sa face, pour qu''il ne vous entende pas.'),
('is',59,3,'crampon1923','Car vos mains sont souillées de sang, et vos doigts d''iniquité; vos lèvres profèrent le mensonge, votre langue tient des discours pervers.'),
('is',59,4,'crampon1923','Nul ne porte plainte avec justice; nul ne plaide selon la vérité; on s''appuie sur des faussetés et l''on invoque des mensonges, on conçoit le mal, et l''on enfante le crime.'),
('is',59,5,'crampon1923','Ils couvent des œufs de basilic, et ils tissent des toiles d''araignée; celui qui mange de leurs œufs mourra, et, si l''on en écrase un, il en sortira une vipère.'),
('is',59,6,'crampon1923','Leurs tissus ne peuvent servir de vêtement, et on ne peut se couvrir de leur ouvrage; leurs ouvrages sont des ouvrages criminels, une œuvre de violence est dans leurs mains.'),
('is',59,7,'crampon1923','Leurs pieds courent vers le mal, et se hâtent pour verser le sang innocent; leurs pensées sont des pensées de crime; le ravage et la ruine sont sur leur route.'),
('is',59,8,'crampon1923','Ils ne connaissent pas le sentier de la paix, et il n''y a pas de droiture dans leurs voies; ils se font des sentiers tortueux: quiconque y marche ne connaît point la paix.'),
('is',59,9,'crampon1923','C''est pourquoi le jugement s''est éloigné de nous; et la justice ne nous arrive pas; nous attendons la lumière, et voici l''obscurité; la clarté du jour, et nous marchons dans les ténèbres.'),
('is',59,10,'crampon1923','Nous tâtonnons comme des aveugles le long d''un mur; nous tâtonnons comme des gens qui n''ont point d''yeux; nous trébuchons en plein midi comme au crépuscule; au milieu d''hommes vigoureux, nous sommes semblables à des morts.'),
('is',59,11,'crampon1923','Nous grondons tous comme des ours; comme des colombes, nous ne cessons de gémir; nous attendons le jugement, et il ne vient pas; le salut, et il reste loin de nous.'),
('is',59,12,'crampon1923','Car nos transgressions sont nombreuses devant vous, et nos péchés témoignent contre nous; oui, nos transgressions nous sont présentes, et nous connaissons nos iniquités:'),
('is',59,13,'crampon1923','Etre infidèles et renier Yahweh, nous retirer loin de notre Dieu, proférer la violence et la révolte, concevoir et tirer de notre cœur des paroles de mensonge!...'),
('is',59,14,'crampon1923','Et le droit s''est retiré, et la justice se tient loin de nous; car la vérité trébuche sur la place publique, et la droiture ne peut y avoir accès:'),
('is',59,15,'crampon1923','la vérité a disparu, et qui s''éloigne du mal est dépouillé. Yahweh l''a vu, et il déplaît à ses yeux qu''il n''y ait plus de droiture.'),
('is',59,16,'crampon1923','Il a vu qu''il n''y avait personne, et il s''est étonné que nul n''intervint. Alors son bras lui est venu en aide, et sa justice a été son soutien.'),
('is',59,17,'crampon1923','Il a revêtu la justice comme une cuirasse, et il a mis sur sa tête le casque du salut; il a pris pour cotte d''armes la vengeance, et il s''est enveloppé de la jalousie comme d''un manteau.'),
('is',59,18,'crampon1923','Telles les œuvres, telle la rétribution: fureur pour ses adversaires, représailles pour ses ennemis; il usera de représailles contre les îles.'),
('is',59,19,'crampon1923','Et ils craindront le nom de Yahweh depuis l''occident, et sa gloire depuis le soleil levant; car il viendra comme un fleuve resserré, que précipite le souffle de Yahweh.'),
('is',59,20,'crampon1923','Il viendra en Rédempteur pour Sion, pour ceux de Jacob qui se convertiront de leurs iniquités, — oracle de Yahweh.'),
('is',59,21,'crampon1923','Et moi, voici mon alliance avec eux, dit Yahweh: Mon esprit qui est sur toi, et mes paroles que j''ai mises dans ta bouche ne cesseront point d''être dans ta bouche, et dans la bouche de tes enfants, et dans la bouche des enfants de tes enfants, dit Yahweh, dès maintenant et à jamais.'),
('is',60,1,'crampon1923','Lève-toi, et resplendis! Car ta lumière paraît, et la gloire de Yahweh s''est levée sur toi.'),
('is',60,2,'crampon1923','Voici que les ténèbres couvrent la terre, et une sombre obscurité les peuples; mais sur toi Yahweh se lève, et sa gloire se manifeste sur toi.'),
('is',60,3,'crampon1923','Les nations marchent vers ta lumière, et les rois vers la clarté de ton lever.'),
('is',60,4,'crampon1923','Lève tes regards autour de toi, et vois: Tous se rassemblent, ils viennent à toi; tes fils viennent de loin, et tes filles sont portées sur les bras.'),
('is',60,5,'crampon1923','Tu le verras alors, et tu seras radieuse; ton cœur tressaillira et se dilatera; car les richesses de la mer se dirigeront vers toi, les trésors des nations viendront à toi.'),
('is',60,6,'crampon1923','Des multitudes de chameaux te couvriront, les dromadaires de Madian et d''Epha; tous ceux de Saba viendront, ils apporteront de l''or et de l''encens, et publieront les louanges de Yahweh.'),
('is',60,7,'crampon1923','Tous les troupeaux de Cédar se rassembleront chez toi; les béliers de Nabaïoth seront à ton service; ils monteront sur mon autel comme une offrande agréable, et je glorifierai la maison de ma gloire.'),
('is',60,8,'crampon1923','Qui sont ceux-là qui volent comme des nuées, comme des colombes vers leur colombier?'),
('is',60,9,'crampon1923','Car les îles espèrent en moi, et les vaisseaux de Tarsis viendront les premiers; Pour ramener tes fils de loin, avec leur argent et leur or, pour honorer le nom de Yahweh, ton Dieu, et le Saint d''Israël, parce qu''il t''a glorifié.'),
('is',60,10,'crampon1923','Les fils de l''étranger rebâtiront tes murailles, et leurs rois seront tes serviteurs; car je t''ai frappée dans ma colère, mais, dans ma bienveillance, j''ai eu compassion de toi.'),
('is',60,11,'crampon1923','Tes portes seront toujours ouvertes; jour et nuit, elles ne seront pas fermées, afin de laisser entrer chez toi les trésors des nations et leurs rois en cortège triomphal.'),
('is',60,12,'crampon1923','Car la nation et le royaume qui ne te serviront point périront; ces nations-là seront entièrement détruites.'),
('is',60,13,'crampon1923','La gloire du Liban viendra chez toi, le cyprès, le platane et le buis tous ensemble, pour orner le lieu de mon sanctuaire, et je glorifierai le lieu où reposent mes pieds.'),
('is',60,14,'crampon1923','Les fils de tes oppresseurs viendront à toi le front courbé, et tous ceux qui te méprisaient se prosterneront à tes pieds; et l''on t''appellera la Ville de Yahweh, la Sion du Saint d''Israël.'),
('is',60,15,'crampon1923','Au lieu que tu étais délaissée, haïe et solitaire, je ferai de toi l''orgueil des siècles, la joie de toutes les générations.'),
('is',60,16,'crampon1923','Tu suceras le lait des nations, tu suceras la mamelle des rois, et tu sauras que moi, Yahweh, je suis ton Sauveur, et que le Puissant de Jacob est ton Rédempteur.'),
('is',60,17,'crampon1923','Au lieu de l''airain, je ferai venir de l''or, et au lieu du fer, je ferai venir de l''argent; et au lieu du bois, de l''airain, et au lieu des pierres, du fer; et je te donnerai pour gouverneurs, la paix, pour magistrats, la justice.'),
('is',60,18,'crampon1923','On n''entendra plus parler de violence dans ton pays, de ravage ni de ruine dans tes frontières; tu appelleras tes murailles: Salut, et tes portes: Louange.'),
('is',60,19,'crampon1923','Le soleil ne sera plus ta lumière pendant le jour, et la lueur de la lune ne t''éclairera plus; Yahweh sera pour toi une lumière éternelle, et ton Dieu sera ta gloire.'),
('is',60,20,'crampon1923','Ton soleil ne se couchera plus, et ta lune ne se retirera plus; car Yahweh sera pour toi une lumière éternelle, et les jours de ton deuil seront achevés.'),
('is',60,21,'crampon1923','Dans ton peuple, tous seront justes, et ils posséderont le pays pour toujours, eux, le rejeton que j''ai planté, l''ouvrage de mes mains, créé pour ma gloire.'),
('is',60,22,'crampon1923','Le plus petit deviendra un millier, et le moindre une nation puissante. Moi, Yahweh, en leur temps, je hâterai ces choses.'),
('is',61,1,'crampon1923','L''esprit du Seigneur Yahweh est sur moi, parce que Yahweh m''a oint; il m''a envoyé porter la bonne nouvelle aux malheureux; panser ceux qui ont le cœur brisé; Annoncer aux captifs la liberté et aux prisonniers l''élargissement;'),
('is',61,2,'crampon1923','publier une année de grâce pour Yahweh, et un jour de vengeance pour notre Dieu; consoler tous les affligés;'),
('is',61,3,'crampon1923','Apporter aux affligés de Sion et leur mettre un diadème au lieu de cendre, l''huile de joie au lieu du deuil, un manteau de fête au lieu d''un esprit abattu; on les appellera térébinthes de justice, plantations de Yahweh pour sa gloire.'),
('is',61,4,'crampon1923','Ils rebâtiront les ruines antiques; ils relèveront les décombres d''autrefois; ils restaureront les villes détruites, les décombres des âges passés.'),
('is',61,5,'crampon1923','Les étrangers seront là pour paître vos troupeaux; les fils de l''étranger seront vos laboureurs et vos vignerons.'),
('is',61,6,'crampon1923','Mais vous, on vous appellera prêtres de Yahweh; on vous nommera " ministres de notre Dieu ". Vous mangerez les richesses des nations, et vous vous parerez de leur magnificence.'),
('is',61,7,'crampon1923','Au lieu de votre honte, vous aurez double portion et au lieu de l''ignominie, ils se réjouiront de leur part; ils posséderont ainsi double part dans leur pays; il y aura pour eux une joie éternelle.'),
('is',61,8,'crampon1923','Car moi, Yahweh, j''aime la justice; je hais le pillage fait avec perfidie; je leur donnerai fidèlement leur salaire, et je ferai avec eux une alliance éternelle.'),
('is',61,9,'crampon1923','Leur race sera renommée parmi les nations; et leur postérité au milieu des peuples; tous ceux qui les verront reconnaîtront qu''ils sont une race bénie de Yahweh.'),
('is',61,10,'crampon1923','Je serai ravi d''allégresse en Yahweh, et mon cœur se réjouira en mon Dieu, parce qu''il m''a revêtu des vêtements du salut, et m''a couvert du manteau de la justice, comme le fiancé orne sa tête d''un diadème, comme la mariée se pare de ses joyaux.'),
('is',61,11,'crampon1923','Car comme la terre fait éclore ses germes, et comme un jardin fait germer ses semences, ainsi le Seigneur Yahweh fera germer la justice, et la louange devant toutes les nations.'),
('is',62,1,'crampon1923','A cause de Sion, je ne me tairai point, et à cause de Jérusalem je ne prendrai point de repos, jusqu''à ce que sa justice se lève comme l''aurore, et que son salut brille comme un flambeau.'),
('is',62,2,'crampon1923','Les nations verront ta justice, et tous les rois ta gloire, et l''on t''appellera d''un nouveau nom, que la bouche de Yahweh choisira.'),
('is',62,3,'crampon1923','Tu seras une couronne d''honneur dans la main de Yahweh, une tiare royale dans la main de notre Dieu.'),
('is',62,4,'crampon1923','On ne te nommera plus Délaissée, et on ne nommera plus ta terre Désolation. Mais on t''appellera Mon-plaisir-en-elle, et ta terre Epousée. Car Yahweh mettra son plaisir en toi, et ta terre aura un époux.'),
('is',62,5,'crampon1923','Comme un jeune homme épouse une vierge, tes fils t''épouseront; et comme la fiancée fait la joie du fiancé, ainsi tu seras la joie de ton Dieu.'),
('is',62,6,'crampon1923','Sur tes murs, Jérusalem, j''ai placé des sentinelles; jamais ni le jour ni la nuit, elles ne se tairont. O vous qui faites souvenir Yahweh, ne prenez point de repos,'),
('is',62,7,'crampon1923','et ne lui laissez point de repos, jusqu''à ce qu''il rétablisse Jérusalem, et qu''il fasse d''elle la louange de la terre.'),
('is',62,8,'crampon1923','Yahweh l''a juré par sa droite, et par son bras puissant: Je ne donnerai plus ton froment en nourriture à tes ennemis, et les fils de l''étranger ne boiront plus ton vin, fruit de tes labeurs.'),
('is',62,9,'crampon1923','Mais ceux qui auront fait la moisson la mangeront, et ils loueront Yahweh; et ceux qui auront fait la vendange la boiront, dans les parvis de mon sanctuaire.'),
('is',62,10,'crampon1923','Passez, passez par les portes; aplanissez le chemin du peuple. Frayez, frayez la route, ôtez-en les pierres; élevez un étendard sur les peuples.'),
('is',62,11,'crampon1923','Voici ce que Yahweh a publié, jusqu''aux extrémités de la terre: Dites à la fille de Sion: " Voici que ton Sauveur vient; voici que sa récompense est avec lui, et ses rétributions le précèdent. "'),
('is',62,12,'crampon1923','Et on les appellera Peuple saint, Rachetés de Yahweh; et toi, on t''appellera Recherchée, Ville-non-délaissée.'),
('is',63,1,'crampon1923','Qui est celui-là qui vient d''Edom, de Bosra en habits écarlates? Il est magnifique dans son vêtement, il se redresse dans la grandeur de sa force. — C''est moi, qui parle avec justice, et qui suis puissant pour sauver.'),
('is',63,2,'crampon1923','— Pourquoi y a-t-il du rouge à ton vêtement, et tes habits sont-ils comme ceux du pressureur? —'),
('is',63,3,'crampon1923','— Au pressoir j''ai foulé seul, et, parmi les peuples, personne n''a été avec moi. Et je les ai foulés dans ma colère, piétinés dans ma fureur; le jus en a jailli sur mes habits, et j''ai souillé tout mon vêtement.'),
('is',63,4,'crampon1923','Car un jour de vengeance était dans mon cœur, et l''année de ma rédemption était venue.'),
('is',63,5,'crampon1923','J''ai regardé, et personne pour m''aider; j''étais étonné, et personne pour me soutenir. Alors mon bras m''a sauvé, et ma fureur m''a soutenu.'),
('is',63,6,'crampon1923','J''ai écrasé les peuples dans ma colère, et je les ai enivrés de ma fureur, et j''ai fait couler leur sang à terre. "'),
('is',63,7,'crampon1923','Je célébrerai les miséricordes de Yahweh, les louanges de Yahweh, selon tout ce que Yahweh a fait pour nous, ainsi que sa grande bonté envers la maison d''Israël, qu''il lui a témoignée dans sa compassion, et son immense miséricorde.'),
('is',63,8,'crampon1923','Il a dit: " Oui, ils sont mon peuple, des fils qui ne seront pas infidèles! " et il a été pour eux un sauveur.'),
('is',63,9,'crampon1923','Dans toutes leurs angoisses, il a été en angoisse, et l''ange de sa face les a sauvés; dans son amour et son indulgence, il les a rachetés lui-même; il les a soutenus et portés, pendant tous les jours d''autrefois.'),
('is',63,10,'crampon1923','Mais eux furent rebelles et attristèrent son Esprit saint; alors il se changea pour eux en ennemi; lui-même leur fit la guerre.'),
('is',63,11,'crampon1923','Alors son peuple se souvint des anciens jours, de Moïse! Où est celui qui fit monter de la mer le berger de son troupeau? Où est celui qui mit au milieu d''eux son Esprit saint,'),
('is',63,12,'crampon1923','qui fit marcher à la droite de Moïse son bras glorieux, qui fendit les eaux devant eux, pour se faire un nom éternel;'),
('is',63,13,'crampon1923','qui les fit marcher à travers les abîmes, sans trébucher, comme un cheval dans la steppe,'),
('is',63,14,'crampon1923','comme le bétail qui descend dans la vallée? L''Esprit de Yahweh les a conduits au repos: c''est ainsi que vous avez guidé votre peuple, pour vous faire un nom glorieux.'),
('is',63,15,'crampon1923','Regardez du ciel et voyez, de votre demeure sainte et magnifique: Où sont votre zèle et votre puissance, le frémissement de vos entrailles et votre pitié? Pour moi, ils se sont arrêtés.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('is',63,16,'crampon1923','Car vous êtes notre père; car Abraham nous ignore, et Israël ne nous connaît pas. Vous, Yahweh, vous êtes notre père; notre Rédempteur: c''est votre nom dès les âges anciens.'),
('is',63,17,'crampon1923','Pourquoi, ô Yahweh, nous feriez-vous errer loin de vos voies, endurciriez-vous notre cœur contre votre crainte? Revenez, pour l''amour de vos serviteurs, et des tribus de votre héritage!'),
('is',63,18,'crampon1923','Votre peuple saint a possédé le pays bien peu de temps; nos ennemis ont foulé aux pieds votre sanctuaire.'),
('is',63,19,'crampon1923','Nous sommes depuis longtemps comme un peuple que vous ne gouvernez pas, sur lequel votre nom n''est pas invoqué. Ah! si vous déchiriez les cieux, si vous descendiez, — les montagnes seraient ébranlées devant vous! —'),
('is',64,1,'crampon1923','comme un feu qui embrase le bois sec, comme un feu qui fait bouillonner l''eau, pour manifester votre nom à vos adversaires, de sorte que les nations tremblent devant vous,'),
('is',64,2,'crampon1923','en faisant des choses terribles, inattendues, — vous descendriez, les montagnes seraient ébranlées devant vous! —'),
('is',64,3,'crampon1923','dont jamais on n''eût entendu parler! Jamais on n''a entendu, nul œil n''a vu un Dieu autre que vous agir ainsi pour qui espère en lui.'),
('is',64,4,'crampon1923','Vous venez au-devant de qui pratique avec joie la justice, de qui, marchant dans vos voies, se souvient de vous. Voici que vous étiez courroucé, et nous étions coupables; — il en est ainsi depuis longtemps: serions-nous sauvés? —'),
('is',64,5,'crampon1923','Nous étions tous semblables à un homme impur, et toutes nos justices étaient pareilles à un vêtement souillé. Nous étions tous flétris comme la feuille, et nos iniquités nous emportaient comme le vent.'),
('is',64,6,'crampon1923','Il n''y avait personne qui invoquât votre nom, qui se réveillât pour s''attacher à vous. Car vous nous aviez caché votre visage, et vous nous laissiez périr dans nos iniquités.'),
('is',64,7,'crampon1923','Et maintenant, ô Yahweh, vous êtes notre père; nous sommes l''argile, et vous celui qui nous a formés; nous sommes tous l''ouvrage de votre main.'),
('is',64,8,'crampon1923','Ne vous irritez pas à l''extrême, ô Yahweh, et ne vous souvenez pas à jamais de l''iniquité. Regardez donc: nous sommes tous votre peuple!'),
('is',64,9,'crampon1923','Vos villes saintes sont devenues un désert; Sion est devenue un désert, Jérusalem une solitude.'),
('is',64,10,'crampon1923','Notre maison sainte et glorieuse, où nos pères célébraient vos louanges, est devenue la proie des flammes, et tout ce qui nous était cher a été dévasté.'),
('is',64,11,'crampon1923','En face de ces maux, vous contiendrez-vous, ô Yahweh? Vous tairez-vous et nous affligerez-vous à l''excès?'),
('is',65,1,'crampon1923','Je me laissais rechercher de qui ne me demandait pas; je me laissais trouver de qui ne me recherchait pas; je disais: " Me voici! Me voici! " à une nation qui ne portait pas mon nom.'),
('is',65,2,'crampon1923','J''étendais mes mains tout le jour vers un peuple rebelle, vers ceux qui marchent dans la voie mauvaise, au gré de leurs pensées;'),
('is',65,3,'crampon1923','vers un peuple qui me provoquait, en face, sans arrêt, sacrifiant dans les jardins, brûlant de l''encens sur des briques,'),
('is',65,4,'crampon1923','se tenant dans les sépulcres, et passant la nuit dans des cachettes, mangeant de la chair de porc et des mets impurs dans leurs plats,'),
('is',65,5,'crampon1923','disant: " Retire-toi! Ne m''approche pas, car je suis saint pour toi! " Ceux-là sont une fumée dans mes narines, un feu qui brûle toujours.'),
('is',65,6,'crampon1923','Voici, c''est écrit devant moi: Je ne me tairai point que je n''aie rétribué, rétribué dans leur sein'),
('is',65,7,'crampon1923','vos iniquités, avec les iniquités de vos pères, dit Yahweh, qui ont brûlé l''encens sur les montagnes, et m''ont outragé sur les collines; je leur mesurerai dans le sein le salaire de leur conduite passée.'),
('is',65,8,'crampon1923','Ainsi parle Yahweh: De même que, trouvant du jus dans une grappe, on dit: " Ne la détruis pas, car il y a là une bénédiction, " ainsi agirai-je à cause de mes serviteurs, afin de ne pas tout détruire.'),
('is',65,9,'crampon1923','Je ferai sortir de Jacob une postérité, et de Juda un héritier de mes montagnes; mes élus les posséderont, et mes serviteurs y habiteront.'),
('is',65,10,'crampon1923','Et Saron servira de parc aux brebis, et la vallée d''Achor de pâturage aux bœufs, pour mon peuple qui m''aura recherché.'),
('is',65,11,'crampon1923','Mais vous qui avez abandonné Yahweh, oublié ma montagne sainte, qui dressez une table à Gad et remplissez une coupe pour Méni,'),
('is',65,12,'crampon1923','je vous destine au glaive, et vous vous courberez tous pour être égorgés. Car j''ai appelé, et vous n''avez pas répondu; j''ai parlé, et vous n''avez pas écouté; mais vous avez fait ce qui est mal à mes yeux, et vous avez choisi ce que je ne veux pas.'),
('is',65,13,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici que mes serviteurs mangeront, et vous, vous aurez faim; voici que mes serviteurs boiront, et vous, vous aurez soif; voici que mes serviteurs seront dans l''allégresse, et vous, vous serez dans la confusion;'),
('is',65,14,'crampon1923','voici que mes serviteurs chanteront dans la joie de leur cœur, et vous, vous crierez dans la douleur de votre cœur, et vous hurlerez dans le déchirement de votre esprit,'),
('is',65,15,'crampon1923','Et vous laisserez votre nom comme une imprécation à mes élus, et le Seigneur Yahweh te fera périr; mais il appellera ses serviteurs d''un autre nom.'),
('is',65,16,'crampon1923','Quiconque voudra être béni sur la terre voudra être béni par le Dieu de vérité, et quiconque jurera sur la terre jurera par le Dieu de vérité. Car les angoisses précédentes seront oubliées, et elles auront disparu à mes yeux.'),
('is',65,17,'crampon1923','Car voici que je crée de nouveaux cieux et une nouvelle terre; on ne se rappellera plus les choses passées, et elles ne reviendront plus à l''esprit.'),
('is',65,18,'crampon1923','Réjouissez-vous plutôt et soyez dans une éternelle allégresse à cause de ce que je vais créer: car voici que je crée Jérusalem pour la joie, et son peuple pour l''allégresse.'),
('is',65,19,'crampon1923','Et j''aurai de l''allégresse au sujet de Jérusalem, et de la joie au sujet de mon peuple. Et l''on n''y entendra plus désormais la voix des pleurs ni le cri de l''angoisse.'),
('is',65,20,'crampon1923','Il n''y aura plus là d''enfant né pour peu de jours, ni de vieillard qui n''accomplisse pas le nombre de ses jours; car ce sera mourir jeune que de mourir centenaire, et c''est à cent ans que la malédiction atteindra le pécheur.'),
('is',65,21,'crampon1923','Ils bâtiront des maisons et ils les habiteront; ils planteront des vignes et ils en mangeront le fruit.'),
('is',65,22,'crampon1923','Ils ne bâtiront pas pour qu''un autre habite; ils ne planteront pas pour qu''un autre mange. Car les jours de mon peuple égaleront ceux des arbres, et mes élus useront l''ouvrage de leurs mains.'),
('is',65,23,'crampon1923','Ils ne se fatigueront plus en vain, ils n''enfanteront pas pour une mort subite; car ils seront une race de bénis de Yahweh, et avec eux leurs rejetons.'),
('is',65,24,'crampon1923','Avant qu''ils appellent, je répondrai; ils parleront encore, que je les exaucerai.'),
('is',65,25,'crampon1923','Le loup et l''agneau paîtront ensemble; le serpent se nourrira de la poussière; le lion, comme le bœuf, mangera du fourrage, et le serpent se nourrira de terre. Il ne se fera ni mal ni dommage sur toute ma montagne sainte, dit Yahweh.'),
('is',66,1,'crampon1923','Ainsi parle Yahweh: Le ciel est mon trône, et la terre est l''escabeau de mes pieds: quelle est la maison que vous me bâtiriez, et quel serait le lieu de mon repos?'),
('is',66,2,'crampon1923','Toutes ces choses, ma main les a faites, et toutes ces choses sont arrivées ainsi a l''existence, — oracle de Yahweh. Voici celui que je regarde: celui qui est humble, qui a le cœur brisé et qui tremble à ma parole.'),
('is',66,3,'crampon1923','Celui qui immole un bœuf tue un homme; celui qui sacrifie une brebis égorge un chien; celui qui présente une oblation offre du sang de porc; celui qui fait brûler l''encens bénit une idole. Comme ils choisissent leurs voies, et que leur âme se complaît dans leurs abominations,'),
('is',66,4,'crampon1923','moi aussi je choisirai leur infortune, et je ferai venir sur eux ce qu''ils redoutent, parce que j''ai appelé, et personne n''a répondu; j''ai parlé, et ils n''ont pas entendu; ils ont fait ce qui est mal à mes yeux, et ils ont choisi ce qui me déplaît.'),
('is',66,5,'crampon1923','Ecoutez la parole de Yahweh, vous qui tremblez à sa parole: Ils ont dit, vos frères qui vous haïssent et vous repoussent à cause de mon nom: " Que Yahweh montre sa gloire, afin que nous voyions votre joie! " Mais ils seront confondus.'),
('is',66,6,'crampon1923','Un fracas, un tumulte monte de la ville, une clameur monte du temple! C''est la voix de Yahweh, qui paie à ses ennemis leur salaire.'),
('is',66,7,'crampon1923','Avant d''être en travail, elle a enfanté; avant que les douleurs lui vinssent, elle a mis au monde un enfant mâle.'),
('is',66,8,'crampon1923','Qui a jamais entendu rien de pareil, qui a jamais rien vu de semblable? Un pays naît-il en un jour, une nation est-elle enfantée d''un seul coup, que Sion, à peine en travail, ait mis au monde ses fils?'),
('is',66,9,'crampon1923','Ouvrirais-je le sein, et ne ferais-je pas enfanter? dit Yahweh; ou bien moi qui fais naître, fermerais-je le sein? dit ton Dieu.'),
('is',66,10,'crampon1923','Réjouissez-vous avec Jérusalem, et soyez dans l''allégresse à cause d''elle, vous tous qui l''aimez! Tressaillez de joie avec elle, vous tous qui pleuriez sur elle,'),
('is',66,11,'crampon1923','afin que vous soyez allaités et rassasiés à la mamelle de ses consolations, afin que vous savouriez avec délices la plénitude de sa gloire!'),
('is',66,12,'crampon1923','Car ainsi parle Yahweh: Je vais faire couler sur elle la paix comme un fleuve, et la gloire des nations comme un torrent qui déborde; et vous serez allaités, portés sur le sein, caressés sur les genoux.'),
('is',66,13,'crampon1923','Comme un homme que sa mère console, ainsi je vous consolerai, et vous serez consolés dans Jérusalem.'),
('is',66,14,'crampon1923','Vous le verrez, et votre cœur sera dans la joie, et vos os reprendront vigueur comme l''herbe. Et la main de Yahweh se fera connaître à ses serviteurs; et son indignation à ses ennemis.'),
('is',66,15,'crampon1923','Car voici que Yahweh vient dans le feu, et son char est semblable à l''ouragan, pour déverser sa colère en embrasement et ses menaces en flammes de feu.'),
('is',66,16,'crampon1923','Car Yahweh exerce le jugement par le feu; et par son épée, contre toute chair; et nombreux seront ceux que Yahweh aura percés.'),
('is',66,17,'crampon1923','Ceux qui se sanctifient et se purifient pour aller dans les jardins, derrière celui qui se tient au milieu, ceux qui mangent de la chair de porc, des mets abominables et des souris, périront tous ensemble, — oracle de Yahweh,'),
('is',66,18,'crampon1923','Moi, je connais leurs œuvres et leurs pensées! Le temps est venu de rassembler toutes les nations et toutes les langues. Elles viendront et verront ma gloire,'),
('is',66,19,'crampon1923','et je ferai un prodige au milieu d''eux. Et j''enverrai de leurs réchappés vers les nations, à Tarsis, à Phul et à Lud, qui tirent de l''arc, à Tubal et à Javan, vers les îles lointaines, qui n''ont jamais entendu parler de moi, et qui n''ont pas vu ma gloire; et ils publieront ma gloire parmi les nations.'),
('is',66,20,'crampon1923','Et ils ramèneront tous vos frères du milieu de toutes les nations, en offrande à Yahweh, sur des chevaux, sur des chars, en litière, sur des mulets et des dromadaires, vers ma montagne sainte, à Jérusalem, dit Yahweh, comme les enfants d''Israël apportent l''offrande dans un vase pur à la maison de Yahweh.'),
('is',66,21,'crampon1923','Et j''en prendrai même parmi eux pour prêtres et pour lévites, dit Yahweh.'),
('is',66,22,'crampon1923','Car comme les nouveaux cieux et la nouvelle terre, que je vais créer, subsisteront devant moi, — oracle de Yahweh, ainsi subsisteront votre postérité et votre nom.'),
('is',66,23,'crampon1923','De nouvelle lune en nouvelle lune, et de sabbat en sabbat, toute chair viendra se prosterner devant moi, dit Yahweh.'),
('is',66,24,'crampon1923','Et quand ils sortiront, ils verront les cadavres des hommes qui se sont révoltés contre moi; car leur ver ne mourra point, et leur feu ne s''éteindra point, et ils seront en horreur à toute chair.'),
('jr',1,1,'crampon1923','Paroles de Jérémie, fils d''Helcias, un des prêtres qui habitaient à Anathoth, au pays de Benjamin.'),
('jr',1,2,'crampon1923','La parole de Yahweh lui fut adressée aux jours de Josias, fils d''Amon, roi de Juda, la treizième année de son règne;'),
('jr',1,3,'crampon1923','et elle le fut aux jours de Joakim, fils de Josias, roi de Juda, jusqu''à la fin de la onzième année de Sédécias, fils de Josias, roi de Juda, jusqu''à la déportation de Jérusalem au cinquième mois.'),
('jr',1,4,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('jr',1,5,'crampon1923','" Avant de te former dans le ventre de ta mère, je t''ai connu, et avant que tu sortisses de son sein, je t''ai consacré; je t''ai établi prophète pour les nations. "'),
('jr',1,6,'crampon1923','Et je dis: " Ah! Seigneur Yahweh, je ne sais point parler, car je suis un enfant! "'),
('jr',1,7,'crampon1923','Et Yahweh me dit: " Ne dis pas: Je suis un enfant, car tu iras vers tous ceux à qui je t''enverrai, et tu diras tout ce que je t''ordonnerai.'),
('jr',1,8,'crampon1923','Sois sans crainte devant eux, car je suis avec toi pour te délivrer, — oracle de Yahweh. "'),
('jr',1,9,'crampon1923','Puis Yahweh étendit sa main et toucha ma bouche; et Yahweh me dit: " Voici que je mets mes paroles dans ta bouche;'),
('jr',1,10,'crampon1923','vois, je t''établis en ce jour sur les nations et sur les royaumes, pour arracher et pour abattre, et pour perdre et pour détruire, et pour planter et pour bâtir. "'),
('jr',1,11,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes: " Que vois-tu, Jérémie? " Et je dis: " Je vois une branche d''amandier. "'),
('jr',1,12,'crampon1923','Et Yahweh me dit: " Tu as bien vu, car je veille sur ma parole pour l''accomplir. "'),
('jr',1,13,'crampon1923','Et la parole de Yahweh me fut adressée une seconde fois en ces termes: " Que vois-tu? " Et je dis: " Je vois une chaudière qui bout, et elle vient du côté du septentrion. "'),
('jr',1,14,'crampon1923','Et Yahweh me dit: " C''est du septentrion que le malheur se répandra sur tous les habitants du pays.'),
('jr',1,15,'crampon1923','Car me voici qui appelle toutes les familles des royaumes du septentrion, — oracle de Yahweh. Et elles viendront, et ils placeront chacun leur trône à l''entrée des portes de Jérusalem, devant toutes ses murailles à l''entour, et devant toutes les villes de Juda.'),
('jr',1,16,'crampon1923','Et je prononcerai mes sentences contre eux, pour toute leur méchanceté, parce qu''ils m''ont abandonné, qu''ils ont offert de l''encens à d''autres dieux et adoré l''ouvrage de leurs mains.'),
('jr',1,17,'crampon1923','Et toi, ceins tes reins, lève-toi et dis-leur tout ce que je t''ordonnerai. Ne tremble pas devant eux, de peur que je ne te laisse trembler devant eux.'),
('jr',1,18,'crampon1923','Et moi, voici que je t''établis en ce jour comme une ville forte, une colonne de fer et une muraille d’airain, devant tout le pays, devant les rois de Juda, devant ses princes, devant ses prêtres et devant le peuple.'),
('jr',1,19,'crampon1923','Ils te feront la guerre, mais ils ne pourront rien sur toi, car je suis avec toi pour te délivrer, — oracle de Yahweh. "'),
('jr',2,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('jr',2,2,'crampon1923','Va et crie aux oreilles de Jérusalem en ces termes: Ainsi parle Yahweh: Je me suis souvenu de la piété de ta jeunesse, de l''amour de tes fiançailles, alors que tu me suivais au désert, au pays qu''on n''ensemence pas.'),
('jr',2,3,'crampon1923','Israël était la chose consacré à Yahweh, les prémices de son revenu; quiconque en mangeait se rendait coupable; le malheur fondait sur lui, — oracle de Yahweh.'),
('jr',2,4,'crampon1923','Ecoutez la parole de Yahweh, maison de Jacob, et vous toutes, familles de la maison d''Israël:'),
('jr',2,5,'crampon1923','Ainsi parle Yahweh: Quelle iniquité vos pères ont-ils trouvé en moi, pour s''éloigner de moi, pour suivre la vanité et devenir eux-mêmes vanité?'),
('jr',2,6,'crampon1923','Ils n''ont pas dit: " Où est Yahweh, qui nous a fait monter du pays d''Egypte, qui nous a guidés dans le désert, dans le pays aride et crevassé, dans le pays de sécheresse et d''ombre de mort, dans le pays où nul homme ne passe, et où personne n''habite? "'),
('jr',2,7,'crampon1923','Et je vous ai fait venir dans un pays semblable à un verger, pour en manger les fruits et les biens, et, une fois entrés, vous avez souillé mon pays, et fait de mon héritage une abomination.'),
('jr',2,8,'crampon1923','Les prêtres n''ont pas dit: " Où est Yahweh? " Les dépositaires de la loi ne m''ont pas connu; les pasteurs m''ont été infidèles, et les prophètes ont prophétisé par Baal; et ils ont suivi ceux qui ne sont d''aucun secours.'),
('jr',2,9,'crampon1923','Aussi je veux encore plaider contre vous, — oracle de Yahweh, et je plaiderai contre les enfants de vos enfants.'),
('jr',2,10,'crampon1923','Passez donc aux îles de Céthim et regardez; envoyez à Cédar et observez bien; et voyez s''il y a là rien de semblable.'),
('jr',2,11,'crampon1923','Une nation change-t-elle de dieux? — Et encore ce ne sont pas des dieux!... Et mon peuple a changé sa gloire contre ce qui ne sert à rien!'),
('jr',2,12,'crampon1923','Cieux, étonnez-vous-en, frémissez d''horreur et soyez stupéfaits, oracle de Yahweh!'),
('jr',2,13,'crampon1923','Car mon peuple a fait double mal: ils m''ont abandonné, moi, la source des eaux vives, pour se creuser des citernes, des citernes crevassées, qui ne retiennent pas l''eau.'),
('jr',2,14,'crampon1923','Israël est-il un esclave, est-il né d''un esclave dans la maison? Pourquoi donc est-il traité comme un butin?'),
('jr',2,15,'crampon1923','Contre lui les lionceaux rugissent, poussent leurs cris, et ils mettent son pays en dévastation. Ses villes sont incendiées, sans d''habitants.'),
('jr',2,16,'crampon1923','Même les fils de Noph et de Taphnès te tondent le crâne!'),
('jr',2,17,'crampon1923','Cela ne t''arrive-t-il pas parce que tu as abandonné Yahweh, ton Dieu, au temps où il te dirigeait dans la voie?'),
('jr',2,18,'crampon1923','Et maintenant qu''as-tu à faire sur la route de l''Egypte, pour aller boire l''eau du Nil, et qu''as-tu à faire sur la route de l''Assyrie, pour aller boire l''eau du fleuve?'),
('jr',2,19,'crampon1923','Ton impiété te châtie et tes rébellions te punissent! Sache donc et vois combien il est mauvais et amer d''avoir abandonné Yahweh, ton Dieu, et de n''avoir de moi aucune crainte, — oracle du Seigneur Yahweh des armées.'),
('jr',2,20,'crampon1923','Car depuis longtemps tu as brisé ton joug, tu as rompu tes liens et tu as dit: " Je ne servirai plus! " Car sur toute colline élevée et sous ton arbre vert tu t''es étendue, comme une courtisane.'),
('jr',2,21,'crampon1923','Et moi, je t''avais plantée comme une vigne excellente, tout entière d''une souche franche. Comment t''es-tu changée pour moi en sarments bâtards d''une vigne étrangère?'),
('jr',2,22,'crampon1923','Oui, quand tu te laverais à la soude, et que tu prodiguerais la potasse, ton iniquité ferait tache devant moi, — oracle du Seigneur Yahweh.'),
('jr',2,23,'crampon1923','Comment dis-tu: " Je ne me suis point souillée; je ne suis point allée après les Baals? " Vois les traces de tes pas dans la Vallée; reconnais ce que tu as fait! Chamelle légère, croisant ses pas en tout sens,'),
('jr',2,24,'crampon1923','onagre habituée au désert, dans l''ardeur de sa passion, elle aspire l''air: qui l''empêchera de satisfaire son désir? Nul de ceux qui la recherchent n''a à se fatiguer; ils la trouvent en son mois.'),
('jr',2,25,'crampon1923','Prends garde que ton pied ne se trouve à nu, et que ton gosier ne se dessèche! Mais tu dis: " Inutile! Non, car j''aime les étrangers et j''irai après eux! "'),
('jr',2,26,'crampon1923','Comme un voleur pris sur le fait est couvert de honte, ainsi ont été confondus la maison d''Israël, eux, leurs rois, leurs chefs, leurs prêtres et leurs prophètes,'),
('jr',2,27,'crampon1923','qui disent au bois: " Tu es mon père, " et à la pierre: " Tu m''as mis au monde. " Car ils m''ont tourné le dos, et non la face, et au temps de leur malheur ils disent: " Lève-toi et sauve-nous! "'),
('jr',2,28,'crampon1923','Où sont donc les dieux que tu t''es faits? Qu''ils se lèvent, s''ils peuvent te sauver au temps de ton malheur! Car aussi nombreux que tes villes sont tes dieux, ô Juda.'),
('jr',2,29,'crampon1923','Pourquoi plaidez-vous contre moi? Vous m''avez tous été infidèles, — oracle de Yahweh.'),
('jr',2,30,'crampon1923','C''est en vain que j''ai frappé vos fils; ils n''en ont pas retiré d''instruction; votre épée a dévoré vos prophètes, comme un lion destructeur.'),
('jr',2,31,'crampon1923','Quelle race vous êtes! Considérez la parole de Yahweh: Ai-je été pour Israël un désert, un pays d''épaisses ténèbres? Pourquoi mon peuple a-t-il dit: " Nous sommes libres, nous ne reviendrons pas à vous? "'),
('jr',2,32,'crampon1923','Une vierge oublie-t-elle sa parure, une fiancée sa ceinture? Et mon peuple m''a oublié depuis des jours sans nombre!'),
('jr',2,33,'crampon1923','Que tu sais bien disposer tes voies pour chercher l''amour! Pour cela, même avec le crime tu familiarises tes voies!'),
('jr',2,34,'crampon1923','Jusque sur les pans de tes vêtements, on trouve le sang des pauvres innocents; tu ne les avais pas surpris en délit d''effraction, mais tu les as tués pour toutes ces choses.'),
('jr',2,35,'crampon1923','Et tu dis: " Oui, je suis innocente; certainement sa colère s''est détournée de moi. " Me voici pour te faire le procès sur ce que tu dis: " Je n''ai pas péché! "'),
('jr',2,36,'crampon1923','Quelle hâte tu mets à changer ta voie! Tu seras rendue confuse par l''Egypte, comme tu l''as été par l''Assyrie.'),
('jr',2,37,'crampon1923','De là aussi tu reviendras, les mains sur la tête; car Yahweh a rejeté ceux en qui tu mets ta confiance, et tu ne réussiras pas avec eux.'),
('jr',3,1,'crampon1923','Il est dit: Lorsqu''un homme répudie sa femme, et qu''après l''avoir quittée, elle devient la femme d''un autre, cet homme retournera-t-il encore vers elle? Cette terre ne serait-elle pas vraiment profanée? Et toi, tu t''es prostituée à de nombreux amants; et tu reviendras vers moi! — oracle de Yahweh.'),
('jr',3,2,'crampon1923','Lève les yeux vers les hauteurs et regarde: où n''as-tu pas été souillée?... Tu t''asseyais pour eux sur les routes, pareille à l''Arabe dans le désert! Et tu as profané le pays par tes prostitutions et par ta méchanceté;'),
('jr',3,3,'crampon1923','les ondées de l''automne ont été retenues, les pluies du printemps ont manqué. Mais tu as eu un front de courtisane, tu n''as pas voulu rougir.'),
('jr',3,4,'crampon1923','Et maintenant, n''est-ce pas, tu me dis: " Mon père, ô vous, l''ami de ma jeunesse! Sera-t-il toujours irrité,'),
('jr',3,5,'crampon1923','gardera-t-il à jamais son courroux? " Voilà ce que tu dis, et tu commets le crime et tu le consommes.'),
('jr',3,6,'crampon1923','Yahweh me dit aux jours du roi Josias: As-tu vu ce qu''à fait Israël l''infidèle? Elle est allée sur toute montagne élevée et sous tout arbre vert, et s''y est prostituée.'),
('jr',3,7,'crampon1923','Et j''ai dit: Après avoir fait toutes ces choses, elle reviendra à moi! Mais elle n''est pas revenue. Et sa sœur, Juda la perfide, a vu cela;'),
('jr',3,8,'crampon1923','Et j''ai vu qu''à cause de tous ses adultères, j''ai répudié Israël l''infidèle, et que je lui ai donné sa lettre de divorce; et sa sœur, Juda la perfide, n''a pas été effrayée, et elle est allée se prostituer, elle aussi.'),
('jr',3,9,'crampon1923','Par sa bruyante impudicité, elle a profané le pays, et elle a commis l''adultère avec le bois et la pierre.'),
('jr',3,10,'crampon1923','Et avec tout cela sa sœur, Juda la perfide, n''est pas revenue à moi de tout son cœur, mais avec mensonge, — oracle de Yahweh.'),
('jr',3,11,'crampon1923','Et Yahweh me dit: Israël l''infidèle s''est montrée juste, en comparaison de Juda la perfide.'),
('jr',3,12,'crampon1923','Va, et crie ces paroles du côté du septentrion et dis: Reviens, infidèle Israël, — oracle de Yahweh; Je ne veux pas vous montrer un visage sévère, car je suis miséricordieux, — oracle de Yahweh, et je ne garde pas ma colère à toujours.'),
('jr',3,13,'crampon1923','Seulement reconnais ta faute, car tu as été infidèle à Yahweh, ton Dieu, et tu as prodigué tes pas vers les étrangers, sous ton arbre vert, et vous n''avez pas écouté ma voix, — oracle de Yahweh.'),
('jr',3,14,'crampon1923','Revenez, fils infidèles, — oracle de Yahweh, car je suis votre maître; et je vous prendrai, un d''une ville et deux d''une famille, et je vous amènerai dans Sion.'),
('jr',3,15,'crampon1923','Et je vous donnerai des pasteurs selon mon cœur, qui vous paîtront avec intelligence et sagesse.'),
('jr',3,16,'crampon1923','Et quand vous aurez multiplié et fructifié dans le pays, en ces jours-là, — oracle de Yahweh, alors on ne dira plus: " L''arche de l''alliance de Yahweh! " elle ne reviendra plus à la pensée, on ne s''en souviendras plus, on ne la regrettera plus, et on n''en fera plus une autre.'),
('jr',3,17,'crampon1923','En ce temps-là on appellera Jérusalem le trône de Yahweh! et toutes les nations s''y assembleront au nom de Yahweh, dans Jérusalem, et elles ne suivront plus l''obstination de leur mauvais cœur.'),
('jr',3,18,'crampon1923','En ces jours-là, la maison de Juda marchera avec la maison d''Israël, et elles viendront ensemble du pays du septentrion au pays que j''ai donné en héritage à vos pères.'),
('jr',3,19,'crampon1923','Et moi je disais: Comment te placerai-je parmi mes enfants? et te donnerai-je un pays de délices, le plus beau joyau des nations pour héritage. Et j''ai dit: Tu m''appelleras " Mon père ", et tu ne cesseras pas de me suivre.'),
('jr',3,20,'crampon1923','Mais comme une femme trahit son amant, ainsi vous m''avez été infidèle, maison d''Israël, — oracle de Yahweh.'),
('jr',3,21,'crampon1923','Une clameur se fait entendre sur les lieux élevés, les pleurs des enfants d''Israël demandant grâce; car ils ont perverti leur voie, oublié Yahweh leur Dieu:'),
('jr',3,22,'crampon1923','— Revenez, fils infidèles, et je guérirai vos infidélités. — " Nous voici, nous venons à vous, car vous êtes Yahweh notre Dieu.'),
('jr',3,23,'crampon1923','Oui, c''est en vain que retentissait sur les hauteurs, sur les montagnes le tumulte des fêtes idolâtres. Oui, c''est en Yahweh, notre Dieu, qu''est le salut d''Israël.'),
('jr',3,24,'crampon1923','La honte des idoles a dévoré dès notre jeunesse le produit du travail de nos pères, leurs brebis et leurs bœufs, leurs fils et leurs filles.'),
('jr',3,25,'crampon1923','Couchons-nous dans notre honte, et que notre opprobre nous couvre! Car c''est contre Yahweh, notre Dieu, que nous avons péché, nous et nos pères, dès notre jeunesse et jusqu''à ce jour; et nous n''avons pas écouté la voix de Yahweh notre Dieu ".'),
('jr',4,1,'crampon1923','Si tu veux revenir Israël, — oracle de Yahweh, reviens vers moi. Et si tu ôtes tes abominations de devant moi, tu ne seras plus errant!'),
('jr',4,2,'crampon1923','Et si tu jures " Yahweh est vivant! " avec vérité, avec droiture et avec justice, les nations se diront bénies en lui; et se glorifieront en lui.'),
('jr',4,3,'crampon1923','Car ainsi parle Yahweh aux hommes de Juda et de Jérusalem: Défrichez vos jachères, et ne semez pas dans les épines.'),
('jr',4,4,'crampon1923','Circoncisez-vous pour Yahweh, et enlevez les prépuces de votre cœur, hommes de Juda et habitants de Jérusalem, de peur que ma colère n''éclate comme un feu et ne consume, sans que personne éteigne, à cause de la méchanceté de vos actions.'),
('jr',4,5,'crampon1923','Publiez dans Juda et annoncez dans Jérusalem; parlez, sonnez de la trompette dans le pays; criez à pleine voix et dites: Rassemblez-vous, et allons dans les villes fortes!'),
('jr',4,6,'crampon1923','Elevez un étendard du côté de Sion, sauvez-vous, ne vous arrêtez pas! Car j''amène du septentrion une calamité et un grand désastre.'),
('jr',4,7,'crampon1923','Un lion s''élance de son fourré, et un destructeur des nations a levé sa tente, quitté son lieu, pour réduire ton pays en désert; tes villes seront désolées, sans habitants.'),
('jr',4,8,'crampon1923','C''est pourquoi ceignez-vous du cilice; pleurez et lamentez-vous; car le feu de la colère de Yahweh ne s''est pas détourné de nous.'),
('jr',4,9,'crampon1923','En ce jour-là, — oracle de Yahweh, le cœur manquera au roi et aux princes; les prêtres seront consternés, et les prophètes stupéfaits.'),
('jr',4,10,'crampon1923','Et je dis: Ah! Seigneur Yahweh, vous avez donc trompé ce peuple et Jérusalem, en disant: " Vous aurez la paix! " alors que l''épée va les frapper à mort!'),
('jr',4,11,'crampon1923','En ce temps-là, on dira à ce peuple et à Jérusalem: Un vent brûlant vient des collines du désert sur le chemin qui mène à la fille de mon peuple, non pour vanner, ni pour nettoyer;'),
('jr',4,12,'crampon1923','un vent plus fort que celui qui chasse la paille vient vers moi. Maintenant, à mon tour, je vais prononcer leur sentence.'),
('jr',4,13,'crampon1923','Voici qu''il monte comme les nuées; pareils à l''ouragan sont ses chars; plus rapides que les aigles sont ses chevaux. Malheur à nous, car nous sommes perdus!'),
('jr',4,14,'crampon1923','Purifie ton cœur de la méchanceté, Jérusalem, pour que tu sois sauvée; jusques à quand demeureront-elles dans ton cœur, tes pensées funestes?'),
('jr',4,15,'crampon1923','Car une voix partie de Dan l''annonce; elle publie le malheur depuis la montagne d''Ephraïm.'),
('jr',4,16,'crampon1923','Faites-le savoir aux nations, annoncez-leur le malheur de Jérusalem. Des assiégeants arrivent d''une terre lointaine; ils poussent leurs cris contre les villes de Juda.'),
('jr',4,17,'crampon1923','Comme les gardiens des champs, ils entourent Jérusalem; car elle s''est révoltée contre moi, — oracle de Yahweh.'),
('jr',4,18,'crampon1923','Voilà ce que t''ont valu ta conduite et tes actes criminels; voilà le fruit de ta méchanceté, et il est amer! Oui, cela atteint jusqu''au cœur!'),
('jr',4,19,'crampon1923','Mes entrailles! mes entrailles! je souffre au plus intime du cœur! Mon cœur s''agite; je ne puis me taire! Car tu entends; ô mon âme, le son de la trompette, le cri de guerre.'),
('jr',4,20,'crampon1923','On annonce ruine sur ruine; car tout le pays est ravagé. Tout d''un coup on détruit mes tentes, en un instant mes pavillons.'),
('jr',4,21,'crampon1923','Jusques à quand verrai-je l''étendard, entendrai-je le son de la trompette?...'),
('jr',4,22,'crampon1923','C''est que mon peuple est fou! Ils ne me connaissent pas; ce sont des fils insensés, qui n''ont pas d''intelligence; ils sont habiles à faire le mal, ils ne savent pas faire le bien.'),
('jr',4,23,'crampon1923','Je regarde la terre, et voici qu''elle est informe et vide; les cieux, et leur lumière a disparu.'),
('jr',4,24,'crampon1923','Je regarde les montagnes, et voici qu''elles sont ébranlées, et toutes les collines chancellent.'),
('jr',4,25,'crampon1923','Je regarde, et voici qu''il n''y a plus d''homme; et tous les oiseaux du ciel ont fui.'),
('jr',4,26,'crampon1923','Je regarde, et voici que le verger est devenu un désert; et toutes ses villes sont détruites devant Yahweh, devant le feu de sa colère.'),
('jr',4,27,'crampon1923','Car ainsi parle Yahweh: Tout le pays sera dévasté; cependant je ne le détruirai pas entièrement.'),
('jr',4,28,'crampon1923','A cause de cela, la terre est en deuil, et les cieux en haut sont obscurcis, parce que je l''ai dit et que je l''ai résolu, et je ne m''en repens pas et je n''en reviendrai pas.'),
('jr',4,29,'crampon1923','A la voix du cavalier et de l''archer, toute la ville est en fuite; on entre dans les bois, on monte sur les rochers; toutes les villes sont abandonnées, il n''y a plus d''habitant.'),
('jr',4,30,'crampon1923','Et toi, dévastée, que feras-tu? Quand tu te revêtirais de pourpre, que tu te parerais d''ornements d''or, que tu borderais tes yeux de fard, c''est en vain que tu te ferais belle: tes amants te dédaignent; c''est à ta vie qu''ils en veulent.'),
('jr',4,31,'crampon1923','Car j''entends une voix comme d''une femme en travail, des cris d''angoisse comme d''une femme qui enfante pour la première fois; voix de la fille de Sion, qui pousse des soupirs et étend les mains: " Malheur à moi! car mon âme succombe aux coups des meurtriers! "'),
('jr',5,1,'crampon1923','Parcourez les rues de Jérusalem et regardez, informez-vous; cherchez sur ses places publiques si vous y trouvez un homme, s''il en est un qui pratique la justice, et qui recherche la fidélité, et je ferai grâce à la ville.'),
('jr',5,2,'crampon1923','Même quand ils disent: " Yahweh est vivant! " c''est pour le mensonge qu''ils jurent.'),
('jr',5,3,'crampon1923','Yahweh, vos yeux ne cherchent-ils pas la fidélité? Vous les avez frappés, et ils n''ont pas eu de douleur; vous les avez exterminés, et ils n''ont pas voulu recevoir l''instruction; ils ont endurci leur face plus que le roc; ils ont refusé de revenir.'),
('jr',5,4,'crampon1923','Et moi, je disais: Ce ne sont que les petits. Ils agissent en insensés, car ils ne savent pas la voie de Yahweh, la loi de leur Dieu.'),
('jr',5,5,'crampon1923','J''irai donc vers les grands et je leur parlerai; car eux, ils savent la voie de Yahweh, La loi de leur Dieu... Mais eux aussi, ils ont tous ensemble brisé le joug, Rompu les liens!'),
('jr',5,6,'crampon1923','C''est pourquoi le lion de la forêt les a frappés, le loup du désert les ravage; la panthère est aux aguets devant leurs villes, tout homme qui en sort est déchiré; car leurs transgressions sont nombreuses, et leurs révoltes se sont accrues.'),
('jr',5,7,'crampon1923','Pour quelle raison te ferais-je grâce! Tes fils m''ont abandonné, et ils jurent par ce qui n''est pas Dieu. Je les ai rassasiés, et ils ont été adultères; ils vont par troupes dans la maison de la prostituée.'),
('jr',5,8,'crampon1923','Etalons bien repus, vagabonds, chacun d''eux hennit à la femme de son prochain.'),
('jr',5,9,'crampon1923','Et je ne les punirais pas pour ces crimes! — oracle de Yahweh; et d''une nation telle que celle-là je ne me vengerais pas!'),
('jr',5,10,'crampon1923','Escaladez ses murs et détruisez, mais non pas entièrement; enlevez ses sarments, car ils ne sont pas à Yahweh!'),
('jr',5,11,'crampon1923','Car elles m''ont été tout à fait infidèles, la maison d''Israël et la maison de Juda, — oracle de Yahweh.'),
('jr',5,12,'crampon1923','Ils ont renié Yahweh et dit: " Il n''est pas, et le malheur ne viendra pas sur nous; nous ne verrons ni l''épée, ni la famine.'),
('jr',5,13,'crampon1923','Les prophètes ne sont que du vent, et personne ne parle en eux: qu''il leur soit fait ainsi à eux-mêmes! "'),
('jr',5,14,'crampon1923','C''est pourquoi ainsi parle Yahweh, le Dieu des armées: Parce que vous dites cette parole-là, voici que je mets ma parole dans ta bouche comme un feu, et ce peuple sera comme du bois et ce feu les dévorera.'),
('jr',5,15,'crampon1923','Me voici qui amène sur vous une nation qui vient de loin, maison d''Israël, — oracle de Yahweh; c''est une nation forte, c''est une nation antique, une nation dont tu ne connais pas la langue, et tu n’entends pas ce qu''elle dit.'),
('jr',5,16,'crampon1923','Son carquois est un sépulcre ouvert; ils sont tous des héros.'),
('jr',5,17,'crampon1923','Elle dévorera ta moisson et ton pain; elle dévorera tes fils et tes filles; elle dévorera tes brebis et tes bœufs; elle dévorera ta vigne et ton figuier; elle détruira par l''épée tes villes fortes dans lesquelles tu te confies.'),
('jr',5,18,'crampon1923','Mais même en ces jours-là, — oracle du Yahweh, je ne vous détruirai pas entièrement.'),
('jr',5,19,'crampon1923','Et quand vous direz: " Pour quelle raison Yahweh, notre Dieu, nous a-t-il fait toutes ces choses? " Tu leur diras: " Comme vous m''avez abandonné pour servir dans votre pays un dieu étranger, ainsi vous servirez des étrangers dans un pays qui n''est pas à vous."'),
('jr',5,20,'crampon1923','Annoncez ceci dans la maison de Jacob; et publiez-le dans Juda, en ces termes:'),
('jr',5,21,'crampon1923','Ecoutez donc ceci, peuple insensé et sans cœur! Ils ont des yeux et ne voient point, des oreilles et ils n''entendent point!'),
('jr',5,22,'crampon1923','Ne me craindrez-vous pas, — oracle de Yahweh; ne tremblerez-vous pas devant moi, moi qui ai mis le sable pour limite à la mer, borne éternelle, qu''elle ne franchira pas? Ses flots s''agitent, et ils sont impuissants; ils mugissent, et ils ne la dépassent pas.'),
('jr',5,23,'crampon1923','Mais ce peuple a un cœur indocile et rebelle; ils se retirent et s''en vont.'),
('jr',5,24,'crampon1923','Ils ne disent pas dans leur cœur: " Craignons Yahweh notre Dieu lui qui donne la pluie, celle de la première saison, et celle de l''arrière-saison en son temps, et qui nous garde les semaines destinées à la moisson. "'),
('jr',5,25,'crampon1923','Vos iniquités ont dérangé cet ordre; vos péchés vous privent de ces biens.'),
('jr',5,26,'crampon1923','Car il se trouve des pervers dans mon peuple; ils épient comme l''oiseleur qui se baisse, ils dressent des pièges et prennent des hommes.'),
('jr',5,27,'crampon1923','Comme une cage est pleine d''oiseaux, ainsi leurs maisons sont pleines de fraude; aussi deviennent-ils puissants et riches;'),
('jr',5,28,'crampon1923','Ils s''engraissent, ils reluisent. Ils dépassent même la mesure du mal; ils ne font pas justice, justice à l''orphelin... et ils prospèrent!... Ils ne font pas droit aux malheureux.'),
('jr',5,29,'crampon1923','Et je ne punirais pas ces crimes! — oracle de Yahweh; et d''une nation telle que celle-là je ne me vengerais pas!...'),
('jr',5,30,'crampon1923','Des choses abominables, horribles, se font dans le pays.'),
('jr',5,31,'crampon1923','Les prophètes prophétisent en mentant, les prêtres gouvernent d''accord avec eux! Et mon peuple l''aime ainsi! Et que ferez-vous au terme de tout cela?'),
('jr',6,1,'crampon1923','Fuyez, enfants de Benjamin, du milieu de Jérusalem! Sonnez de la trompette à Thécua, et élevez des signaux à Béthacarem! Car un malheur s''avance du septentrion, et un grand désastre.'),
('jr',6,2,'crampon1923','La belle et la voluptueuse, je la détruis, la fille de Sion!'),
('jr',6,3,'crampon1923','Vers elle viennent des bergers avec leurs troupeaux; ils planteront leurs tentes autour d''elle; chacun pâturera son quartier.'),
('jr',6,4,'crampon1923','Inaugurez le combat contre elle: levez-vous, montons à l''assaut en plein midi! Malheur à nous, car le jour baisse, les ombres du soir s''allongent.'),
('jr',6,5,'crampon1923','Levez-vous, escaladons de nuit, et détruisons son palais!'),
('jr',6,6,'crampon1923','Car ainsi parle Yahweh des armées: Abattez ses arbres, élevez des terrasses contre Jérusalem; c''est la ville à punir, il n''y a dans son sein qu’injustice.'),
('jr',6,7,'crampon1923','Comme un puits fait sourdre ses eaux, ainsi fait-elle sourdre sa méchanceté. On n''y entend que violence et que ruine; plaies et blessures y sont constamment devant ma face.'),
('jr',6,8,'crampon1923','Amende-toi, Jérusalem, de peur que mon âme ne se détache de toi, que je ne fasse de toi un désert, un pays inhabité.'),
('jr',6,9,'crampon1923','Ainsi parle Yahweh des armées: On grappillera comme une vigne les restes d''Israël; mets et remets la main, comme fait le vendangeur aux sarments.'),
('jr',6,10,'crampon1923','A qui parler, qui adjurer pour qu''il m''entende? Voici que leurs oreilles sont incirconcises, et ils sont incapables de faire attention. Voici que la parole de Yahweh est devenue pour eux un opprobre; et ils n''y prennent aucun plaisir.'),
('jr',6,11,'crampon1923','Mais je suis rempli de la colère de Yahweh, je suis las de la contenir. Verse-la sur l''enfant dans la rue et sur la réunion des jeunes gens! Car le mari et la femme, tous seront pris, ainsi que le vieillard et l''homme chargé de jours.'),
('jr',6,12,'crampon1923','Leurs maisons passeront à d''autres, leurs champs et leurs femmes également; car j''étendrai ma main sur les habitants du pays, — oracle de Yahweh.'),
('jr',6,13,'crampon1923','Car du plus petit au plus grand, tous se livrent à la rapine, et du prophète au prêtre, tous pratiquent le mensonge.'),
('jr',6,14,'crampon1923','Ils traitent à la légère la plaie de la fille de mon peuple, en disant: Paix, paix! alors qu''il n''y a point de paix.'),
('jr',6,15,'crampon1923','Ils seront confondus, car ils ont commis des abominations; mais ils ne savent même plus rougir, et ils ne connaissent plus la honte! C''est pourquoi ils tomberont avec ceux qui tombent; ils s''affaisseront au jour où je les visiterai, dit Yahweh.'),
('jr',6,16,'crampon1923','Ainsi parle Yahweh: Tenez-vous sur les routes, et voyez; informez-vous des sentiers d''autrefois; Quelle est la voie du salut? et suivez-la, et vous trouverez du repos pour vos âmes. Mais ils ont répondu: " Nous n''y marcherons pas! "'),
('jr',6,17,'crampon1923','J’ai placé près de vous des sentinelles: " Soyez attentifs au son de la trompette! " Mais ils ont répondu: " Nous n''y ferons pas attention! "'),
('jr',6,18,'crampon1923','Aussi, écoutez, nations; sache, assemblée des peuples, ce qui leur arrivera;'),
('jr',6,19,'crampon1923','terre, écoute: Voici que je fais venir un malheur contre ce peuple, le fruit de ses pensées; car ils n''ont pas été attentifs à mes paroles; et ils ont rejeté ma loi.'),
('jr',6,20,'crampon1923','Que me fait l''encens venu de Saba et le roseau précieux d''un pays lointain? Vos holocaustes ne me plaisent point, vos sacrifices ne me sont point agréables.'),
('jr',6,21,'crampon1923','C''est pourquoi ainsi parle Yahweh: Voici que je mets devant ce peuple des pierres d''achoppement; les pères et les fils s''y heurteront ensemble, l''habitant et son voisin périront.'),
('jr',6,22,'crampon1923','Ainsi parle Yahweh: Voici qu''un peuple arrive du pays du septentrion, qu''une grande nation se lève des extrémités de la terre.'),
('jr',6,23,'crampon1923','Ils manient l''arc et le javelot; ils ont cruels et sans pitié, leur voix gronde comme la mer; ils sont montés sur des chevaux, prêts à combattre comme un seul homme, contre toi, fille de Sion.'),
('jr',6,24,'crampon1923','A la nouvelle de leur approche, nos mains ont défailli, l''angoisse nous a saisis, les douleurs d''une femme qui enfante.'),
('jr',6,25,'crampon1923','Ne sortez point aux champs, n''allez pas sur les chemins; car l''ennemi tient l''épée, et l''épouvante règne à l''entour.'),
('jr',6,26,'crampon1923','Fille de mon peuple, ceins le cilice, roule-toi dans la cendre, prends le deuil comme pour un fils unique, fais des lamentations amères; car soudain le dévastateur arrive sur nous.'),
('jr',6,27,'crampon1923','Je t''ai établi dans mon peuple comme un essayeur, une forteresse, pour que tu connaisses et éprouves leurs voies.'),
('jr',6,28,'crampon1923','Ils sont tous des rebelles entre les rebelles; ils sèment la calomnie; c''est du cuivre et du fer; tous sont corrompus.'),
('jr',6,29,'crampon1923','Le soufflet est devenu la proie du feu, le plomb est épuisé; en vain l''on épure, l''on épure; les méchants ne se détachent pas.'),
('jr',6,30,'crampon1923','" Argent de rebut! " dira-t-on; car Yahweh les a mis au rebut.'),
('jr',7,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, en ces termes:'),
('jr',7,2,'crampon1923','" Tiens-toi à la porte de la maison de Yahweh, et là prononce cette parole et dis: Ecoutez la parole de Yahweh, vous tous, hommes de Juda, qui entrez par ces portes pour adorer Yahweh.'),
('jr',7,3,'crampon1923','Ainsi parle Yahweh des armées, le Dieu d''Israël: Améliorez vos voies et vos œuvres, et je vous ferai habiter dans ce lieu.'),
('jr',7,4,'crampon1923','Ne vous fiez pas aux paroles de mensonge de ceux qui disent: " C''est ici le temple de Yahweh, le temple de Yahweh, le temple de Yahweh! "'),
('jr',7,5,'crampon1923','Mais si vous améliorez vos voies et vos œuvres, si vous rendez fidèlement la justice entre un homme et son prochain;'),
('jr',7,6,'crampon1923','Si vous n''opprimez pas l''étranger, l''orphelin et la veuve, si vous ne répandez pas en ce lieu le sang innocent, et si vous n''allez pas près d''autres dieux, pour votre malheur:'),
('jr',7,7,'crampon1923','Alors je vous ferai habiter dans ce lieu, au pays que j''ai donné à vos pères, depuis les temps anciens et pour jamais.'),
('jr',7,8,'crampon1923','Mais voici que vous vous fiez à des paroles de mensonge, qui ne vous servent de rien!'),
('jr',7,9,'crampon1923','Quoi! voler, tuer, commettre l''adultère, jurer faussement, encenser Baal et aller après d''autres dieux que, vous ne connaissez pas!...'),
('jr',7,10,'crampon1923','Et vous venez, vous vous présentez devant moi, dans cette maison sur laquelle mon nom est invoqué, et vous dites: " Nous échapperons! " Et c''est afin de commettre toutes ces abominations!'),
('jr',7,11,'crampon1923','Est-ce donc à vos yeux une caverne de brigands, que cette maison sur laquelle mon nom est invoqué? Moi aussi, je l''ai vu, — oracle de Yahweh.'),
('jr',7,12,'crampon1923','Allez donc à ma demeure qui était à Silo, où j''avais fait autrefois habiter mon nom, et voyez comment je l''ai traitée, à cause de la méchanceté de mon peuple d''Israël.'),
('jr',7,13,'crampon1923','Et maintenant, puisque vous avez fait toutes ces actions, — oracle de Yahweh, et que je vous ai parlé, vous parlant dès le matin, et vous n''avez pas écouté, et que je vous ai appelés, et vous n''avez pas répondu,'),
('jr',7,14,'crampon1923','je ferai de cette maison, sur laquelle mon nom a été invoqué, dans laquelle vous mettez votre confiance, et de ce lieu que j''ai donné à vous et à vos pères, ce que j''ai fait de Silo;'),
('jr',7,15,'crampon1923','et je vous rejetterai de devant moi, comme j''ai rejeté tous vos frères, toute la race d''Ephraïm.'),
('jr',7,16,'crampon1923','Et toi, n''intercède pas en faveur de ce peuple; n''élève pour lui ni plainte ni prière, et n''insiste pas auprès de moi, car je ne t''écouterai pas.'),
('jr',7,17,'crampon1923','Ne vois-tu pas, ce qu''ils font dans les villes de Juda, et dans les rues de Jérusalem?'),
('jr',7,18,'crampon1923','Les fils ramassent du bois, les pères allument le feu, les femmes pétrissent de la pâte pour faire des gâteaux à la reine du ciel, et répandre des libations à d''autres dieux, afin de m''offenser.'),
('jr',7,19,'crampon1923','Est-ce moi qu''ils offensent, — oracle de Yahweh, n''est-ce pas eux-mêmes, à la honte de leur visage?'),
('jr',7,20,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici que ma colère et ma fureur vont se répandre sur ce lieu, sur les hommes et sur les bêtes, sur l''arbre des champs et sur le fruit du sol; elle brûlera et ne s''éteindra point.'),
('jr',7,21,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: Ajoutez vos holocaustes à vos sacrifices, et mangez-en la chair;'),
('jr',7,22,'crampon1923','car je n''ai pas parlé à vos pères ni ne leur ai rien prescrit, le jour où je les ai fait sortir du pays d''Egypte, en matière d''holocaustes et de sacrifices.'),
('jr',7,23,'crampon1923','Mais quant au commandement que je leur ai donné, je leur ai dit: Ecoutez ma voix, et je serai votre Dieu, et vous serez mon peuple; marchez dans toutes les voies que je vous prescrirai, afin que vous soyez heureux.'),
('jr',7,24,'crampon1923','Mais ils n''ont point écouté, et ils n''ont point prêté l''oreille et ils ont marché selon leurs conseils, selon l''endurcissement de leur mauvais cœur; ils sont allés en arrière, et non en avant.'),
('jr',7,25,'crampon1923','Depuis le jour où vos pères sont sortis de la terre d''Egypte jusqu''à ce jour, je vous ai envoyé tous mes serviteurs les prophètes, les envoyant chaque jour dès le matin;'),
('jr',7,26,'crampon1923','mais ils ne m''ont pas écouté, ils n''ont pas prêté l''oreille; ils ont raidi leur cou, ils ont fait pis que leurs pères.'),
('jr',7,27,'crampon1923','Tu leur diras toutes ces choses, ils ne t''écouteront pas; tu les appelleras, ils ne te répondront pas.'),
('jr',7,28,'crampon1923','Alors tu leur diras: C''est la nation qui n''a pas écouté la voix de Yahweh, son Dieu, et qui n''a pas accepté l''instruction; la fidélité a péri; elle a disparu de sa bouche.'),
('jr',7,29,'crampon1923','Rase ta chevelure, et jette-la; et entonne sur les hauteurs un chant de deuil, car Yahweh a pris en dédain et rejeté la race objet de sa colère.'),
('jr',7,30,'crampon1923','Car les fils de Juda ont fait ce qui est mal à mes yeux, — oracle de Yahweh; ils ont placé leurs abominations dans la maison sur laquelle mon nom a été invoqué, afin de la souiller;'),
('jr',7,31,'crampon1923','et ils ont construit les hauts lieux de Topheth dans la vallée du fils de Hinnom, pour brûler au feu leurs fils et leurs filles, ce que je n''avais point commandé, et ce qui ne m''était pas venu à la pensée.'),
('jr',7,32,'crampon1923','C''est pourquoi voici que des jours viennent, — oracle de Yahweh, où l''on ne dira plus " Topheth, " ni " Vallée du fils de Hinnom ", mais " Vallée du massacre ", et où l''on enterrera à Topheth, faute de place.'),
('jr',7,33,'crampon1923','Et les cadavres de ce peuple seront la pâture des oiseaux du ciel et des bêtes de la terre, sans qu''il y ait personne pour les chasser.'),
('jr',7,34,'crampon1923','Et je ferai cesser, dans les villes de Juda et dans les rues de Jérusalem, les cris de réjouissance et les cris d''allégresse, le chant de l''époux et le chant de l''épouse, car le pays sera devenu un désert.'),
('jr',8,1,'crampon1923','En ce temps-là, — oracle de Yahweh, on tirera de leurs sépulcres les os des rois de Juda, et les os de ses princes, et les os des prêtres, et les os des prophètes, et les os des habitants de Jérusalem.'),
('jr',8,2,'crampon1923','On les étendra devant le soleil et devant la lune, et devant toute l''armée des cieux, qu''ils ont aimés et qu''ils ont servis, après lesquels ils ont marché, qu''ils ont consultés et qu''ils ont adorés; ces os ne seront ni recueillis, ni enterrés, ils deviendront un engrais sur la face de la terre.'),
('jr',8,3,'crampon1923','Et la mort sera préférée à la vie par tous ceux qui resteront de cette méchante race, dans tous les lieux où je les aurai chassés, — oracle de Yahweh des armées.'),
('jr',8,4,'crampon1923','Dis-leur: Ainsi parle Yahweh: Est-ce qu''on tombe sans se relever? Est-ce qu''on s''égare sans revenir?'),
('jr',8,5,'crampon1923','Pourquoi donc ce peuple de Jérusalem s''égare-t-il d''un égarement continuel? Ils s''attachent avec force au mensonge; ils refusent de revenir!'),
('jr',8,6,'crampon1923','J''ai fait attention et j''ai écouté: ils ne parlent pas comme il faut; nul ne se repent de sa méchanceté, en disant: " Qu''ai-je fait? " Tous reprennent leur course, comme un cheval qui s''élance dans la bataille.'),
('jr',8,7,'crampon1923','Même la cigogne dans les airs connaît sa saison; la tourterelle, l''hirondelle et la grue, observent le temps de leur retour; mais mon peuple ne connaît pas la loi de Yahweh.'),
('jr',8,8,'crampon1923','Comment pouvez-vous dire: Nous sommes sages, et la loi de Yahweh est avec nous? — Voici que le style mensonger des scribes en a fait un mensonge!'),
('jr',8,9,'crampon1923','Les sages sont confondus, consternés et pris; voici qu''ils ont rejeté la parole de Yahweh, et quelle sagesse ont-ils?...'),
('jr',8,10,'crampon1923','C''est pourquoi je donnerai leurs femmes à d’autres, et leurs champs à d''autres possesseurs; car du plus petit au plus grand, tous se livrent à la rapine; et du prophète au prêtre, tous pratiquent le mensonge.'),
('jr',8,11,'crampon1923','Ils traitent à la légère la plaie de la fille de mon peuple, en disant: " Paix, Paix! " et il n''y a point de paix.'),
('jr',8,12,'crampon1923','Ils seront confondus, car ils ont commis des abominations. Mais ils ne savent même plus rougir, et ils ne connaissent plus la honte. C''est pourquoi ils tomberont avec ceux qui tombent; ils s''affaisseront au jour où je les visiterai, dit Yahweh.'),
('jr',8,13,'crampon1923','Je vais les ramasser, les emporter, — oracle de Yahweh. Plus de raisins à la vigne, ni de figues au figuier, et la feuille même est flétrie! Et je leur ai donné des gens qui envahiront leur pays.'),
('jr',8,14,'crampon1923','Pourquoi restons-nous assis? Rassemblez-vous et allons dans les villes fortes et nous y périrons! Puisque Yahweh notre Dieu nous fait périr et nous fait boire des eaux empoisonnées, parce que nous avons péché contre Yahweh!...'),
('jr',8,15,'crampon1923','Nous attendions la paix, et il n''y a rien de bon; le temps de la guérison, et voici la terreur!'),
('jr',8,16,'crampon1923','On entend depuis Dan le ronflement de ses chevaux; au bruit du hennissement de ses coursiers, toute la terre tremble; ils arrivent, ils dévorent le pays et ce qu''il renferme, la ville et ses habitants.'),
('jr',8,17,'crampon1923','Car voici que j''envoie contre vous des serpents, des aspics, contre lesquels il n''y a pas d''enchantement; ils vous mordront, — oracle de Yahweh.'),
('jr',8,18,'crampon1923','O ma consolation dans ma douleur! Mon cœur languit au dedans de moi.'),
('jr',8,19,'crampon1923','Voici que le cri de détresse de la fille de mon peuple m''arrive d''une terre lointaine: " Yahweh n''est-il plus en Sion? Son roi n''est-il plus au milieu d''elle? " — Pourquoi m''ont-ils irrité par leurs idoles, par les vanités de l''étranger? —'),
('jr',8,20,'crampon1923','" La moisson est passée, la récolte est finie, et nous, nous ne sommes pas délivrés! " —'),
('jr',8,21,'crampon1923','Je suis meurtri de la meurtrissure de la fille de mon peuple; je suis dans le deuil; l''épouvante m''a saisi.'),
('jr',8,22,'crampon1923','N''y a-t-il plus de baume de Galaad, ne s''y trouve-t-il plus de médecin? Pourquoi donc n''a-t-on pas mis un bandage à la fille de mon peuple?'),
('jr',8,23,'crampon1923','Qui changera ma tête en eaux, et mes yeux en source de larmes, pour que je pleure nuit et jour les morts de la fille de mon peuple?'),
('jr',9,1,'crampon1923','Qui me donnera au désert un abri de voyageurs? J''abandonnerai mon peuple, je me retirerai d''avec eux! Car ils sont tous des adultères; une assemblée d''infidèles.'),
('jr',9,2,'crampon1923','Ils bandent leur langue comme leur arc, pour décocher le mensonge; ce n''est pas par la vérité qu''ils sont puissants dans le pays, car ils vont de péché en péché; et ils ne me connaissent pas, — oracle de Yahweh.'),
('jr',9,3,'crampon1923','Gardez vous chacun de votre ami, et ne vous fiez à aucun frère; car tout frère ne fait que supplanter, et tout ami s''en va répandant la calomnie.'),
('jr',9,4,'crampon1923','Ils se dupent dupent l''un l''autre; ils ne disent pas la vérité; ils exercent leur langue à mentir; ils s''étudient à mal faire.'),
('jr',9,5,'crampon1923','Tu habites au milieu de la mauvaise foi; c''est par mauvaise foi qu''ils refusent de me connaître, — oracle de Yahweh.'),
('jr',9,6,'crampon1923','C''est pourquoi ainsi parle Yahweh des armées: Je vais les fondre au creuset et les éprouver; car que faire autre chose avec la fille de mon peuple?'),
('jr',9,7,'crampon1923','C''est un dard meurtrier que leur langue; elle ne profère que mensonge; de la bouche on dit: Paix à son prochain, et dans le cœur on lui dresse des embûches.'),
('jr',9,8,'crampon1923','Et je ne les punirais pas pour tous ces crimes, — oracle de Yahweh, et d''une nation telle que celle-là je ne me vengerais pas!'),
('jr',9,9,'crampon1923','Sur les montagnes je ferai entendre une plainte et une lamentation, sur les pâturages du désert un chant de deuil! Car ils sont brûlés au point que personne n''y passe; on n''y entend plus la voix des troupeaux; depuis l''oiseau du ciel jusqu''au bétail, tous ont fui, ont disparu.'),
('jr',9,10,'crampon1923','Et je ferai de Jérusalem des tas de pierres, un repaire de chacals; et je ferai des villes de Juda une solitude, où personne n''habite.'),
('jr',9,11,'crampon1923','Quel est l''homme sage qui comprendra ces choses; celui à qui la bouche de Yahweh a parlé, pour qu''il les annonce? Pourquoi le pays est-il détruit, brûlé comme le désert où personne ne passe?'),
('jr',9,12,'crampon1923','Et Yahweh dit: C''est parce qu''ils ont abandonné ma loi, que j''avais mise devant eux, qu''ils n''ont pas écouté ma voix et ne l''ont pas suivie.'),
('jr',9,13,'crampon1923','Mais ils ont marché selon l''obstination de leur cœur, et après les Baals, que leurs pères leur ont enseignés.'),
('jr',9,14,'crampon1923','C''est pourquoi ainsi parle Yahweh, le Dieu d''Israël: " Voici que je vais les nourrir d''absinthe, — ce peuple — et je leur donnerai à boire des eaux empoisonnées.'),
('jr',9,15,'crampon1923','Je les disperserai parmi des nations que n''ont connues ni eux, ni leurs pères, et j''enverrai contre eux le glaive, jusqu''à ce que je les aie exterminés.'),
('jr',9,16,'crampon1923','Ainsi parle Yahweh des armées: Pensez à commander les pleureuses, et qu''elles viennent! Envoyez vers les plus habiles, et qu''elles viennent!'),
('jr',9,17,'crampon1923','Qu''elles se hâtent, qu''elles entonnent sur nous des lamentations; que les larmes coulent de nos yeux, et que de nos paupières les pleurs ruissellent!'),
('jr',9,18,'crampon1923','Car un bruit de lamentations a été entendu dans Sion: " Comment sommes-nous dévastés, couverts de honte, au point d''abandonner le pays, parce qu''on a jeté bas nos demeures? "'),
('jr',9,19,'crampon1923','Femmes, écoutez donc la parole de Yahweh, et que votre oreille reçoive la parole de sa bouche! Enseignez à vos filles une lamentation, et chacune à vos compagnes un chant de deuil.'),
('jr',9,20,'crampon1923','Car la mort est montée par nos fenêtres, et elle est entrée dans nos palais, pour faire disparaître l''enfant de la rue, et les jeunes gens des places publiques.'),
('jr',9,21,'crampon1923','Parle: Ainsi... — oracle de Yahweh: Le cadavre de l''homme tombera, comme du fumier sur un champ, et comme la javelle derrière le moissonneur, sans que personne la ramasse.'),
('jr',9,22,'crampon1923','Ainsi parle Yahweh: Que le sage ne se glorifie pas de sa sagesse; que le fort ne se glorifie pas de sa force; que le riche ne se glorifie pas de sa richesse.'),
('jr',9,23,'crampon1923','Mais que celui qui se glorifie se glorifie en ceci: d''avoir de l''intelligence et de me connaître. Car je suis Yahweh, qui exerce la miséricorde, le droit et la justice sur la terre; car c''est à cela que je prends plaisir, — oracle de Yahweh.'),
('jr',9,24,'crampon1923','Voici que des jours viennent, — oracle de Yahweh, où je châtierai tout circoncis avec l''incirconcis:'),
('jr',9,25,'crampon1923','L''Egypte, Juda, Edom, les fils d''Ammon, Moab, et tous ceux qui se rasent les tempes, qui habitent le désert; car toutes les nations sont incirconcises, et toute la maison d''Israël est incirconcise de cœur.'),
('jr',10,1,'crampon1923','Ecoutez la parole que Yahweh vous adresse, maison d''Israël:'),
('jr',10,2,'crampon1923','Ainsi parle Yahweh: N''apprenez pas la voie des nations, et ne soyez pas effrayés par les signes du ciel, comme les nations s''en effraient;'),
('jr',10,3,'crampon1923','Car les coutumes des nations ne sont que vanité; c''est du bois qu''on coupe dans la forêt, un ouvrage de la main du sculpteur, façonné avec le ciseau,'),
('jr',10,4,'crampon1923','que l''on décore avec l''argent et l''or. On le fixe avec des clous à coups de marteau, pour qu''il ne bouge pas.'),
('jr',10,5,'crampon1923','Ces dieux-là sont comme une colonne faite au tour; car on les porte, ils ne marchent pas. Ne les craignez point: ils ne font pas de mal; ils ne peuvent pas davantage faire du bien.'),
('jr',10,6,'crampon1923','Nul n’est semblable à vous, Yahweh; vous êtes grand, et votre nom est grand en puissance.'),
('jr',10,7,'crampon1923','Qui ne vous craindrait, Roi des nations! c''est à vous que la crainte est due. Car, parmi tous les sages des nations et dans tous leurs royaumes, nul n’est pareil à vous.'),
('jr',10,8,'crampon1923','Tous ensemble ils sont stupides et fous; enseignement de vanité; c''est du bois!'),
('jr',10,9,'crampon1923','Argent battu amené de Tharsis, et or d''Ophaz; œuvre de sculpture et de main d''orfèvre! On les revêt de pourpre violette et rouge; tous ne sont qu''ouvrage d''artistes.'),
('jr',10,10,'crampon1923','Mais Yahweh est Dieu en vérité; lui, il est un Dieu vivant et un Roi éternel; à sa colère la terre tremble, et les nations ne soutiennent pas son courroux.'),
('jr',10,11,'crampon1923','Voici comment vous leur parlerez: " Les dieux qui n''ont pas fait le ciel et la terre seront exterminés de la terre et de dessous le ciel. "'),
('jr',10,12,'crampon1923','Il a fait la terre par sa force, affermi le monde par sa sagesse, et par son intelligence il a étendu les cieux.'),
('jr',10,13,'crampon1923','A sa voix, les eaux s''amassent dans les cieux; il fait monter les nuages des extrémités de la terre; il fait briller les éclairs d''où jaillit l''averse, et fait sortir le vent de ses réservoirs.'),
('jr',10,14,'crampon1923','Tout homme est stupide, hors de sens; tout artisan a honte de son idole, car son image fondue n''est que mensonge; il n''y a point de souffle en elle.'),
('jr',10,15,'crampon1923','Elle est une vanité, une œuvre de tromperie; au jour de leur châtiment, elle périra.'),
('jr',10,16,'crampon1923','Telle n''est point la part de Jacob; car Lui, il a formé l''univers, et Israël est la tribu de son héritage; son nom est Yahweh des armées.'),
('jr',10,17,'crampon1923','Ramasse à terre ton bagage, toi qui es assiégée!'),
('jr',10,18,'crampon1923','Car ainsi parle Yahweh: Voici que cette fois, je vais lancer au loin les habitants du pays; je les serrerai de près, afin que l''ennemi les atteigne.'),
('jr',10,19,'crampon1923','Malheur à moi à cause de ma meurtrissure! Ma plaie est douloureuse; mais je le dis: " Oui, c''est là mon mal, et je le supporterai.'),
('jr',10,20,'crampon1923','Ma tente est dévastée, tous mes cordages sont rompus; mes fils m''ont quittée, ils ne sont plus; je n''ai plus personne pour redresser ma tente, relever mes pavillons. "'),
('jr',10,21,'crampon1923','Ah! les pasteurs sont stupides; ils n''ont pas cherché Yahweh; aussi n''ont-ils pas prospéré, et tout leur troupeau a été dispersé.'),
('jr',10,22,'crampon1923','Un bruit, une rumeur! Voici qu''elle vient, un grand tumulte arrive du pays du septentrion, pour faire des villes de Juda un désert, un repaire de chacals.'),
('jr',10,23,'crampon1923','Je le sais, ô Yahweh, ce n''est pas à l''homme qu''appartient sa voie, ce n''est pas à l''homme qui marche de diriger ses pas.'),
('jr',10,24,'crampon1923','Châtiez-moi, Yahweh, mais selon la justice, et non dans votre colère, pour me réduire à néant.'),
('jr',10,25,'crampon1923','Versez votre fureur sur les nations qui ne vous connaissent pas, sur les peuples qui n''invoquent pas votre nom; car ils ont dévoré Jacob, ils l''ont dévoré, ils l''achèvent, et ils dévastent sa demeure.'),
('jr',11,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, en ces termes:'),
('jr',11,2,'crampon1923','Entendez les paroles de cette alliance, et parlez aux hommes de Juda et aux habitants de Jérusalem.'),
('jr',11,3,'crampon1923','Et tu leur diras: Ainsi parle Yahweh, Dieu d''Israël: Maudit soit l''homme qui n''écoute pas les paroles de cette alliance,'),
('jr',11,4,'crampon1923','que j''ai prescrites à vos pères, au jour où je les ai fait sortir de la terre d''Egypte, de la fournaise à fer, en leur disant: Ecoutez ma voix et faites ces choses, selon tout ce que je vous commanderai, et vous serez mon peuple et moi je serai votre Dieu,'),
('jr',11,5,'crampon1923','afin que j''accomplisse le serment que j''ai fait à vos pères de leur donner un pays où coulent le lait et le miel, comme cela se voit aujourd''hui. Et je répondis: " Oui! Yahweh! "'),
('jr',11,6,'crampon1923','Et Yahweh me dit: Crie toutes ces paroles dans les villes de Juda et dans les rues de Jérusalem, en disant: Ecoutez les paroles de cette alliance et mettez-les en pratique.'),
('jr',11,7,'crampon1923','Car j''ai instamment averti vos pères depuis le jour où je les ai fait monter du pays d''Egypte jusqu''à ce jour; je les ai sans cesse avertis, en disant: Ecoutez ma voix.'),
('jr',11,8,'crampon1923','Et ils n''ont ni écouté ni prêté l''oreille; chacun d''eux a marché selon l''opiniâtreté de son mauvais cœur. Et j''ai exécuté sur eux toutes les paroles de cette alliance, que je leur avait prescrit d''observer, et qu''ils n''ont pas observée.'),
('jr',11,9,'crampon1923','Yahweh me dit: Il s''est trouvé une conjuration chez les hommes de Juda, et chez les habitants de Jérusalem.'),
('jr',11,10,'crampon1923','Ils sont retournés aux iniquités de leurs premiers pères qui ont refusé d''écouter mes paroles, et ils sont allés après d''autres dieux pour les servir. La maison d''Israël et la maison de Juda ont violé mon alliance que j''avais conclue avec leurs pères.'),
('jr',11,11,'crampon1923','C''est pourquoi ainsi parle Yahweh: Voici que je vais amener sur eux des malheurs, dont ils ne pourront sortir; et, s''ils crient vers moi, je ne les écouterai pas.'),
('jr',11,12,'crampon1923','Et les villes de Juda et les habitants de Jérusalem iront invoquer les dieux auxquels ils offrent de l''encens; mais ces dieux ne les sauveront sûrement pas, au temps de leur malheur.'),
('jr',11,13,'crampon1923','Car aussi nombreux que tes villes, sont tes dieux, ô Juda, et aussi nombreux que les rues de Jérusalem, sont les autels que vous avez dressés à une infâme idole, les autels que vous avez dressés pour encenser Baal.'),
('jr',11,14,'crampon1923','Et toi, n''intercède pas pour ce peuple, et n''élève point en leur faveur de supplication ni de prière; car je n''écouterai point lorsqu''ils m''invoqueront, au temps de leur malheur.'),
('jr',11,15,'crampon1923','Qu''est-ce que ma bien-aimée a à faire dans ma maison? Des fourberies? Est-ce que les vœux et la chair sacrée enlèveront de dessus toi tes malheurs, que tu puisses te livrer à l''allégresse?'),
('jr',11,16,'crampon1923','Olivier verdoyant, orné de beaux fruits: c''est le nom que t''avait donné Yahweh. Au bruit d''un grand fracas, il y met le feu, et ses rameaux sont brisés.'),
('jr',11,17,'crampon1923','Yahweh des armées, qui t''avait planté, a décrété le malheur contre toi, à cause du crime de la maison d''Israël et de la maison de Juda, qu''ils ont commis pour m''irriter, en encensant Baal.'),
('jr',11,18,'crampon1923','Yahweh m''en a informé, et je l''ai su;... alors vous m''avez fait connaître leurs œuvres!'),
('jr',11,19,'crampon1923','Moi, j''étais comme un agneau familier, qu''on mène à la boucherie, et je ne savais qu''ils formaient des desseins contre moi: " Détruisons l''arbre avec son fruit! Retranchons-le de la terre des vivants, et qu''on ne se souvienne plus de son nom! "'),
('jr',11,20,'crampon1923','Mais Yahweh des armées juge avec justice; il sonde les reins et les cœurs; je verrai la vengeance que vous tirerez d''eux, car c''est à vous que j''ai confié ma cause.'),
('jr',11,21,'crampon1923','C''est pourquoi ainsi parle Yahweh au sujet des hommes d''Anathoth qui en veulent à ta vie et qui disent: " Ne prophétise pas au nom de Yahweh, si tu ne veux mourir de notre main! "'),
('jr',11,22,'crampon1923','C''est pourquoi ainsi parle Yahweh des armées: Je vais les punir; les jeunes hommes mourront par l''épée; leurs fils et leurs filles mourront de faim.'),
('jr',11,23,'crampon1923','Aucun d''eux n''échappera; car j''amènerai le malheur sur les hommes d''Anathoth, l''année où je les visiterai.'),
('jr',12,1,'crampon1923','Vous êtes trop juste, ô Yahweh; pour que je dispute contre vous; je veux seulement parler justice avec vous: Pourquoi la voie des méchants est-elle prospère; pourquoi tous les perfides vivent-ils en paix?'),
('jr',12,2,'crampon1923','Vous les plantez, et ils prennent racine; ils croissent, et ils portent du fruit; vous êtes près de leur bouche; et loin de leur cœur.'),
('jr',12,3,'crampon1923','Et vous, Yahweh, vous me connaissez, vous me voyez, et vous sondez ce que mon cœur est pour vous. Enlevez-les comme des brebis, pour la boucherie; vouez-les pour le jour du massacre!'),
('jr',12,4,'crampon1923','Jusques à quand le pays sera-t-il en deuil, et l''herbe de tous les champs sera-t-elle desséchée? A cause de la méchanceté de ceux qui y habitent, bétail et oiseaux périssent; car ils disent: " Il ne verra pas notre fin! "'),
('jr',12,5,'crampon1923','Si tu cours avec des piétons et qu''ils te fatiguent, comment lutteras-tu avec des cavaliers? S''il te faut une terre de paix pour avoir confiance, que feras-tu contre les lions du Jourdain?'),
('jr',12,6,'crampon1923','Car tes frères mêmes et la maison de ton père, eux-mêmes te trahissent; eux-mêmes crient derrière toi à pleine voix; ne te fie pas à eux quand ils te disent de bonnes paroles.'),
('jr',12,7,'crampon1923','J''ai quitté ma maison, j''ai délaissé mon héritage, j''ai livré l''objet de mon amour aux mains de mes ennemis.'),
('jr',12,8,'crampon1923','Mon héritage est devenu pour moi comme un lion dans la forêt; il a élevé contre moi la voix; aussi l''ai-je pris en haine.'),
('jr',12,9,'crampon1923','Mon héritage est-il un vautour bigarré, contre lequel les vautours fondent de tous côtés? Venez, rassemblez toutes les bêtes des champs, amenez-les à la curée!'),
('jr',12,10,'crampon1923','De nombreux bergers ont détruit ma vigne, foulé aux pieds mon domaine; ils ont changé le lot qui m''était cher en désert, en dévastation.'),
('jr',12,11,'crampon1923','On en a fait une ruine; dévasté, il est en deuil devant moi; tout le pays est saccagé, car personne ne l''a pris à cœur.'),
('jr',12,12,'crampon1923','Sur toutes les collines du désert arrivent les dévastateurs; car le Yahweh a un glaive qui dévore, d''un bout à l''autre du pays; il n''y a point de salut pour toute chair.'),
('jr',12,13,'crampon1923','Ils ont semé du froment, ils moissonnent des épines; ils ont dépensé leurs forces, mais sans profit. Ayez honte de ce que vous récoltez: c''est l''effet de l''ardente colère de Yahweh.'),
('jr',12,14,'crampon1923','Ainsi parle Yahweh sur tous mes méchants voisins qui s''attaquent à l''héritage que j''ai donné à mon peuple d''Israël: Voici que je vais les arracher à leur sol, et j''arracherai du milieu d''eux la maison de Juda.'),
('jr',12,15,'crampon1923','Mais, après que je les aurai arrachés, j''aurai de nouveau compassion d''eux, et je les ramènerai chacun dans son héritage, chacun dans son pays.'),
('jr',12,16,'crampon1923','Et s''ils apprennent les voies de mon peuple, en jurant par mon nom: " Yahweh est vivant! ", comme ils ont appris à mon peuple à jurer par Baal, ils seront établis au milieu de mon peuple.'),
('jr',12,17,'crampon1923','Mais s''ils n''écoutent pas, j''arracherai cette nation; je l''arracherai et la détruirai, — oracle de Yahweh.'),
('jr',13,1,'crampon1923','Ainsi m''a parlé Yahweh: " Va t''acheter une ceinture de lin, et pose-là sur tes reins, mais ne la mets pas dans l''eau. "'),
('jr',13,2,'crampon1923','Et je m''achetai la ceinture, selon la parole de Yahweh, et je la mis sur mes reins.'),
('jr',13,3,'crampon1923','La parole de Yahweh me fut adressée une seconde fois, en ces termes:'),
('jr',13,4,'crampon1923','" Prends la ceinture que tu as achetée et qui est sur tes reins; lève-toi, va vers l''Euphrate, et là tu la cacheras dans une fente de rocher. "'),
('jr',13,5,'crampon1923','J''allai et je la cachai près de l''Euphrate, comme Yahweh me l''avait ordonné.'),
('jr',13,6,'crampon1923','Et, au bout d''un grand nombre de jours, Yahweh me dit: " Lève-toi, va vers l''Euphrate, et là reprends la ceinture que je t''ai commandé d''y cacher ".'),
('jr',13,7,'crampon1923','J''allai vers l''Euphrate, je creusai et je repris la ceinture au lieu où je l''avais cachée; et voilà que la ceinture était perdue, elle n''était plus bonne à rien.'),
('jr',13,8,'crampon1923','Et la parole de Yahweh me fut adressée, en ces termes:'),
('jr',13,9,'crampon1923','Ainsi parle Yahweh: C''est ainsi que je perdrai l''orgueil de Juda, et le grand orgueil de Jérusalem.'),
('jr',13,10,'crampon1923','Ce peuple mauvais qui refuse d''écouter mes paroles, qui suit l''opiniâtreté de son cœur et qui va après d''autres dieux pour les servir et les adorer, il sera comme cette ceinture, qui n''est plus bonne à rien.'),
('jr',13,11,'crampon1923','Car, comme la ceinture est attachée aux reins de l''homme, ainsi je m''étais attaché toute la maison d''Israël et toute la maison de Juda, — oracle de Yahweh, afin qu''elles fussent pour moi un peuple, un nom, un honneur et une gloire; mais ils n''ont pas écouté!'),
('jr',13,12,'crampon1923','Et tu leur diras cette parole: " Ainsi parle Yahweh, Dieu d''Israël: Toute cruche doit être remplie de vin. " Ils te répondront: " Ne savons-nous pas que toute cruche doit être remplie de vin? "'),
('jr',13,13,'crampon1923','Et tu leur diras: " Ainsi parle Yahweh: Je vais remplir tous les habitants de ce pays, et les rois qui sont assis sur le trône de David, les prêtres et les prophètes, et tous les habitants de Jérusalem, d''ivresse.'),
('jr',13,14,'crampon1923','Et je les briserai les uns contre les autres, les pères et les fils ensemble, — oracle de Yahweh; je n''épargnerai pas, je n''aurai pas de compassion, je n''aurai pas de pitié pour ne pas les détruire.'),
('jr',13,15,'crampon1923','Ecoutez, prêtez l''oreille, ne soyez point orgueilleux, car Yahweh a parlé.'),
('jr',13,16,'crampon1923','Rendez gloire à Yahweh, votre Dieu, avant que viennent les ténèbres, que vos pieds se heurtent aux montagnes de la nuit, qu''il change en ombre de mort la lumière que vous attendez, et qu''il en fasse une obscurité profonde.'),
('jr',13,17,'crampon1923','Si vous n''écoutez pas cela, mon âme pleurera en secret, à cause de votre orgueil; mes yeux pleureront amèrement, se fondront en larmes, car le troupeau de Jacob sera emmené captif.'),
('jr',13,18,'crampon1923','Dis au roi et à la reine: Asseyez-vous à terre, car elle tombe de votre tête, votre couronne de gloire.'),
('jr',13,19,'crampon1923','Les villes du midi sont fermées, et personne ne les ouvre; Juda tout entier est déporté; la déportation est complète.'),
('jr',13,20,'crampon1923','Lève les yeux et vois ceux qui viennent du septentrion: Où est le troupeau qui t''avait été donné, les brebis qui faisaient ta gloire?'),
('jr',13,21,'crampon1923','Que diras-tu quand Yahweh te donnera pour maîtres ceux que tu as instuits contre toi — tes familiers? Les douleurs ne te saisiront-elles pas, comme une femme qui enfante?'),
('jr',13,22,'crampon1923','Et si tu dis dans ton cœur: " Pourquoi ces malheurs m''arrivent-ils?... " C''est à cause de la multitude de tes iniquités que les pans de ta robe ont été relevés, que tes talons ont été meurtris.'),
('jr',13,23,'crampon1923','Un Ethiopien changera-t-il sa peau, un léopard ses taches? Et vous, pourriez-vous faire le bien, vous qui êtes appris à mal faire?'),
('jr',13,24,'crampon1923','Je les disperserai comme la paille qui passe, au souffle du vent du désert.'),
('jr',13,25,'crampon1923','Tel est ton sort, la part que je te mesure, — oracle de Yahweh, parce que tu m''as oublié, que tu as mis ta confiance dans le mensonge.'),
('jr',13,26,'crampon1923','Et moi aussi je relèverai les pans de ta robe sur ton visage, et l''on verra ta honte.'),
('jr',13,27,'crampon1923','Tes adultères, tes hennissements, tes criminelles prostitutions, sur les collines en pleine campagne, toutes tes abominations, je les ai vues. Malheur à toi, Jérusalem! Tu es impure jusques à quand encore?'),
('jr',14,1,'crampon1923','Parole de Yahweh qui fut adressée à Jérémie à l''occasion de la sécheresse.'),
('jr',14,2,'crampon1923','Juda est dans le deuil; ses portes languissent; elles gisent désolées sur la terre, et le cri de Jérusalem s''élève.'),
('jr',14,3,'crampon1923','Les grands envoient les petits chercher de l''eau; ceux-ci vont aux citernes, ils ne trouvent pas d''eau, ils reviennent avec leurs vases vides; ils sont confus et honteux, ils se couvrent la tête.'),
('jr',14,4,'crampon1923','A cause du sol crevassé, parce qu''il n''y a pas eu de pluie sur la terre, les laboureurs sont confondus, ils se couvrent la tête.'),
('jr',14,5,'crampon1923','Même la biche dans la campagne met bas et abandonne ses petits, parce qu''il n''y a pas d''herbe.'),
('jr',14,6,'crampon1923','Les onagres se tiennent sur les hauteurs, aspirant l''air comme des chacals; leurs yeux s''éteignent, parce qu''il n''y a pas de verdure.'),
('jr',14,7,'crampon1923','Si nos iniquités témoignent contre nous, Yahweh, agis pour l''honneur de ton nom; car nos infidélités sont nombreuses; nous avons péché contre toi.'),
('jr',14,8,'crampon1923','O toi, l''espérance d''Israël, son libérateur au temps de la détresse, pourquoi serais-tu comme un étranger dans le pays, comme un voyageur qui y dresse sa tente pour la nuit?'),
('jr',14,9,'crampon1923','Pourquoi serais-tu comme un homme éperdu, comme un héros impuissant à délivrer? Pourtant tu habites au milieu de nous, Yahweh; ton nom est invoqué sur nous, ne nous abandonne pas! —'),
('jr',14,10,'crampon1923','Ainsi parle Yahweh au sujet de ce peuple: Oui, ils aiment à courir çà et là, et ils ne savent pas retenir leurs pieds. Yahweh ne trouve plus de plaisir en eux; Il va maintenant se souvenir de leurs iniquités et châtier leurs péchés.'),
('jr',14,11,'crampon1923','Et Yahweh me dit: " N''intercède pas en faveur de ce peuple.'),
('jr',14,12,'crampon1923','Quand ils jeûneront, je n''écouterai pas leurs supplications; quand ils m''offriront des holocaustes et des offrandes, je ne les agréerai pas; car par l''épée, la famine et la peste je veux les détruire. "'),
('jr',14,13,'crampon1923','Et je répondis: " Ah! Seigneur, Yahweh, voici que les prophètes leur disent: Vous ne verrez point d''épée, et vous n''aurez point de famine; mais je vous donnerai une paix assurée dans ce lieu-ci. "'),
('jr',14,14,'crampon1923','Et Yahweh me dit: " C''est le mensonge que les prophètes prophétisent en mon nom: je ne les ai pas envoyés, je ne leur ai point donné d''ordre, et je ne leur ai point parlé; visions mensongères, vaines divinations, imposture de leur propre cœur, voilà ce qu''ils vous prophétisent. "'),
('jr',14,15,'crampon1923','C''est pourquoi ainsi parle Yahweh: Au sujet des prophètes qui prophétisent en mon nom sans que je les aie envoyés, et qui disent: " D''épée et de famine il n''y aura pas dans ce pays!... " Ils périront par l''épée et par la famine, ces prophètes-là!'),
('jr',14,16,'crampon1923','Et les gens auxquels ils prophétisent seront jetés dans les rues de Jérusalem, victimes de la famine et de l''épée, et il n''y aura personne pour les ensevelir, eux, leurs femmes, leurs fils et leurs filles et je verserai sur eux leur méchanceté.'),
('jr',14,17,'crampon1923','Et tu leur diras cette parole: Mes yeux se fondront en larmes la nuit et le jour, sans arrêt; car la vierge, fille de mon peuple, va être frappée d''un grand désastre, d''une plaie très douloureuse.'),
('jr',14,18,'crampon1923','Si je vais dans les champs, voici des hommes que le glaive a percés; si j''entre dans la ville, voilà les douleurs de la faim. Le prophète lui-même et le prêtre sont errants, vers un pays qu''ils ne connaissaient pas.'),
('jr',14,19,'crampon1923','As-tu donc entièrement rejeté Juda? Ton âme a-t-elle pris Sion en dégoût? Pourquoi nous frappes-tu sans qu''il y ait pour nous de guérison? Nous attendions la paix, et il ne vient rien de bon; le temps de la guérison, et voici l''épouvante.'),
('jr',14,20,'crampon1923','Nous reconnaissons, ô Yahweh, notre méchanceté, l''iniquité de nos pères, car nous avons péché contre toi.'),
('jr',14,21,'crampon1923','A cause de ton nom, ne dédaigne pas, ne profane pas le trône de ta gloire; souviens-toi, ne romps pas ton alliance avec nous.'),
('jr',14,22,'crampon1923','Parmi les vaines idoles des nations, en est-il qui fasse pleuvoir? Est-ce le ciel qui donnera les ondées? N''est-ce pas toi, Yahweh, notre Dieu? Nous espérons en toi, car c''est toi qui fais toutes ces choses.'),
('jr',15,1,'crampon1923','Yahweh me répondit: Quand Moïse et Samuel se tiendraient devant moi, mon âme ne se tournerait pas vers ce peuple; chasse-les de devant ma face et qu''ils partent!'),
('jr',15,2,'crampon1923','Et s''ils te disent: " Où irons-nous? " tu leur diras: Ainsi parle Yahweh: Celui qui est pour la mort, à la mort; celui qui est pour l''épée, à l''épée; celui qui est pour la famine, à la famine; et celui qui est pour la captivité, à la captivité.'),
('jr',15,3,'crampon1923','Et je susciterai contre eux quatre familles de fléaux, — oracle de Yahweh: l''épée pour tuer, les chiens pour déchirer, les oiseaux du ciel et les bêtes de la terre pour dévorer et pour détruire.'),
('jr',15,4,'crampon1923','J''en ferai un objet d''horreur pour tous les royaumes de la terre, à cause de Manassé, fils d''Ezéchias, roi de Juda, pour ce qu''il a fait dans Jérusalem.'),
('jr',15,5,'crampon1923','Qui donc aura pitié de toi, Jérusalem? qui se lamentera sur toi? Qui se détournera de sa route pour s''informer de ton état?'),
('jr',15,6,'crampon1923','Tu m''as repoussé, — oracle de Yahweh, pour te retirer en arrière; et je vais étendre ma main sur toi pour te faire périr; je suis las d''avoir pitié.'),
('jr',15,7,'crampon1923','Je les vannerai avec le van, aux portes du pays; je priverai d''enfants, je ferai périr mon peuple; ils ne reviennent pas de leurs voies.'),
('jr',15,8,'crampon1923','Ses veuves seront plus nombreuses que le sable de la mer. Je leur amènerai, sur la mère du jeune guerrier, le dévastateur en plein midi; je ferai fondre soudain sur elle l''angoisse et l''épouvante.'),
('jr',15,9,'crampon1923','La mère des sept fils se sent défaillir, elle va rendre l''âme; son soleil se couche pendant qu''il est jour encore; elle est confuse, couverte de honte. Ceux qui resteront, je les livrerai à l''épée devant leurs ennemis, oracle de Yahweh.'),
('jr',15,10,'crampon1923','Malheur à moi, ô ma mère, parce que tu m''as enfanté, pour être un homme de dispute et de querelle pour tout le pays. Je n''ai rien prêté, et ils ne m''ont rien prêté, et tous me maudissent. —'),
('jr',15,11,'crampon1923','Yahweh dit: Oui, je t''affermirai pour ton bien; certainement j''amènerai ton ennemi à te supplier, au temps du malheur et de la détresse.'),
('jr',15,12,'crampon1923','Le fer brisera-t-il le fer du nord et l''airain?'),
('jr',15,13,'crampon1923','Je livrerai tes biens et tes trésors au pillage, sans paiement, pour tous tes péchés et sur tout ton territoire;'),
('jr',15,14,'crampon1923','et je les ferai passer avec tes ennemis dans un pays que tu ne connais pas; car un feu s''est allumé dans ma colère; il brûlera sur vous.'),
('jr',15,15,'crampon1923','Tu le sais, Yahweh! Souviens-toi de moi, prends soin de moi et venge-moi de mes persécuteurs; ne m''enlève pas, dans ta patience envers eux, sache que c''est pour toi que je porte l''opprobre!'),
('jr',15,16,'crampon1923','Dès que tes paroles se sont présentées, je les ai dévorées; elles sont devenues ma joie, et l''allégresse de mon cœur; car ton nom a été invoqué sur moi, Yahweh, Dieu des armées.'),
('jr',15,17,'crampon1923','Je ne me suis point assis dans l''assemblée des rieurs, pour m''y livrer à la gaieté; sous ta main, je me suis assis solitaire, car tu m''avais rempli de courroux.'),
('jr',15,18,'crampon1923','Pourquoi ma souffrance est-elle sans fin, et ma plaie douloureuse, rebelle à la guérison? Serais-tu pour moi comme un ruisseau trompeur, comme des eaux sur lesquelles on ne peut compter?'),
('jr',15,19,'crampon1923','C''est pourquoi Yahweh parle ainsi: Si tu reviens vers moi, je te ferai revenir, pour que tu te tiennes devant ma face; et si tu sépares ce qui est précieux de ce qui est vil, tu seras comme ma bouche; ils reviendront vers toi, et ce n''est pas toi qui reviendras vers eux.'),
('jr',15,20,'crampon1923','Je ferai de toi, pour ce peuple, une forte muraille d''airain; ils te feront la guerre, mais ils ne pourront rien sur toi; car je serai avec toi pour te secourir et te délivrer, — oracle de Yahweh.'),
('jr',15,21,'crampon1923','Je te délivrerai de la main des méchants, et je te rachèterai de la main des violents.'),
('jr',16,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('jr',16,2,'crampon1923','Tu ne prendras point de femme, et tu n''auras point de fils ni de filles en ce lieu.'),
('jr',16,3,'crampon1923','Car ainsi parle Yahweh touchant les fils et les filles qui naissent en ce lieu, et touchant les mères qui les enfantent, et touchant les pères qui les engendrent, en ce pays:'),
('jr',16,4,'crampon1923','Ils mourront de maladies mortelles; on ne leur donnera ni larmes ni sépulture; ils seront comme du fumier sur le sol. Ils périront par l''épée et la famine, et leurs cadavres seront la pâture des oiseaux du ciel et des bêtes de la terre.'),
('jr',16,5,'crampon1923','Car ainsi parle Yahweh: N''entre pas dans la maison de deuil; ne va point pleurer et te lamenter avec eux; car j''ai retiré ma paix à ce peuple, — oracle de Yahweh, ma grâce et ma compassion.'),
('jr',16,6,'crampon1923','Grands et petits mourront dans ce pays; ils n''y aura pour eux ni sépulture ni larmes; on ne se fera point d''incisions, on ne se rasera point pour eux.'),
('jr',16,7,'crampon1923','On ne leur rompra point le pain du deuil, pour les consoler au sujet d''un mort, et on ne leur fera pas boire la coupe de consolation, pour un père et pour une mère.'),
('jr',16,8,'crampon1923','Ne va pas dans la maison du festin pour t''asseoir avec eux, pour manger et pour boire.'),
('jr',16,9,'crampon1923','Car ainsi parle Yahweh des armées, Dieu d''Israël: Je vais faire cesser en ce lieu, sous vos yeux et de vos jours, le cri de joie et le cri d''allégresse, le chant du fiancé et le chant de la fiancée.'),
('jr',16,10,'crampon1923','Lorsque tu annonceras à ce peuple toutes ces choses, ils te diront: " Pourquoi Yahweh nous annonce-t-il tous ces grands malheurs? Quelle est notre iniquité, et quel est notre péché que nous avons commis contre Yahweh, notre Dieu? "'),
('jr',16,11,'crampon1923','Et tu leur diras: " C''est que vos pères m''ont abandonné, — oracle de Yahweh; et qu''ils sont allés après d''autres dieux, qu''ils les ont servis, et adorés, et que moi, ils m''ont abandonné, et qu''ils n''ont pas observé ma loi.'),
('jr',16,12,'crampon1923','Et vous, vous avez fait le mal plus que vos pères, et voici que vous allez chacun après la perversité de votre mauvais cœur, pour ne point m''écouter.'),
('jr',16,13,'crampon1923','Je vous jetterai hors de ce pays dans un pays que vous n''aurez pas connu, ni vous, ni vos pères, et là vous servirez les dieux étrangers, la nuit et le jour; car je ne vous ferai point grâce. "'),
('jr',16,14,'crampon1923','C''est pourquoi voici que des jours viennent, — oracle de Yahweh, où l''on ne dira plus: " Yahweh est vivant, lui qui a fait monter les enfants d''Israël du pays d''Egypte; "'),
('jr',16,15,'crampon1923','mais: " Yahweh est vivant, lui qui a fait monter les enfants d''Israël du pays du septentrion, et de tous les pays où il les avait chassés. " Et je les ramènerai dans leur pays que j''avais donné à leurs pères.'),
('jr',16,16,'crampon1923','Voici que j''appelle en foule des pêcheurs, — oracle de Yahweh, — et ils les pêcheront. Et après cela, j''appellerai en foule des chasseurs, et ils les chasseront de toute montagne, et de toute colline, et des fentes des rochers.'),
('jr',16,17,'crampon1923','Car mes yeux sont sur toutes leurs voies; elles ne sont pas cachées devant ma face et leur iniquité ne se dérobe point à mes regards.'),
('jr',16,18,'crampon1923','Tout d''abord je leur paierai au double leur iniquité et leur péché, parce qu''ils ont profané mon pays; des cadavres de leurs idoles et de leurs abominations ils ont rempli mon héritage.'),
('jr',16,19,'crampon1923','Yahweh, ma force, mon rempart et mon refuge au jour de la détresse, les nations viendront à toi des extrémités de la terre et diront: Nos pères n''ont eu en héritage que le mensonge, des vanités qui ne servent à rien.'),
('jr',16,20,'crampon1923','Se peut-il qu''un homme se fasse des dieux? Et ce ne sont pas des dieux!'),
('jr',16,21,'crampon1923','C''est pourquoi voici que je vais leur faire connaître, cette fois-ci, je vais leur faire connaître ma main et ma puissance, et ils sauront que mon nom est Yahweh.'),
('jr',17,1,'crampon1923','Le péché de Juda est écrit avec un stylet de fer, avec une pointe de diamant, il est gravé sur la table de leurs cœurs, et aux cornes de vos autels.'),
('jr',17,2,'crampon1923','Comme ils se souviennent de leurs enfants, ainsi se souviennent-ils de leurs autels et de leurs aschérahs, près des arbres verts, sur les collines élevées.'),
('jr',17,3,'crampon1923','O ma montagne qui es dans la plaine, je livrerai au pillage tes biens, tous tes trésors, tes hauts lieux, à cause de tes péchés sur tout ton territoire.'),
('jr',17,4,'crampon1923','Tu laisseras en friche, et par ta faute, ton héritage que je t''avais donné; je te ferai servir tes ennemis, dans un pays que tu ne connais pas; car vous avez allumé le feu de ma colère, et il brûle pour jamais.'),
('jr',17,5,'crampon1923','Ainsi parle Yahweh: Maudit soit l''homme qui se confie en l’homme, qui fait de la chair son bras, et dont le cœur se retire de Yahweh!'),
('jr',17,6,'crampon1923','Il est comme une bruyère dans la lande; il ne jouit pas quand le bonheur arrive; il occupera les lieux brûlés au désert, une terre salée où personne n''habite.'),
('jr',17,7,'crampon1923','Béni soit l''homme qui se confie en Yahweh, et dont Yahweh est la confiance!'),
('jr',17,8,'crampon1923','Il est comme un arbre planté au bord des eaux, qui pousse ses racines vers le courant; il ne craint pas quand vient la chaleur, et son feuillage reste vert; il ne s''inquiète point de l''année de la sécheresse, et ne cesse pas de porter du fruit.'),
('jr',17,9,'crampon1923','Le cœur est rusé plus que toute chose et corrompu: qui le connaîtra?'),
('jr',17,10,'crampon1923','Moi, Yahweh, qui sonde les cœurs et qui éprouve les reins, et cela pour rendre à chacun selon ses voies, selon le fruit de ses œuvres.'),
('jr',17,11,'crampon1923','Une perdrix couve des œufs qu''elle n’a pas pondus; tel celui qui acquiert des richesses injustement; au milieu de ses jours il doit les quitter, et à sa fin il n''est qu''un insensé.'),
('jr',17,12,'crampon1923','Trône de gloire, hauteur éternelle, lieu de notre sanctuaire,'),
('jr',17,13,'crampon1923','espoir d''Israël, Yahweh, tous ceux qui t''abandonnent seront confondus! Ceux qui se détournent de moi seront inscrits sur la terre; car ils ont abandonné la source des eaux vives, Yahweh.'),
('jr',17,14,'crampon1923','Guéris-moi, Yahweh, et je serai guéri; sauve-moi, et je serai sauvé, car tu es ma louange.'),
('jr',17,15,'crampon1923','Voici qu''ils me disent: " Où est la parole de Yahweh? Qu''elle arrive! "'),
('jr',17,16,'crampon1923','Et moi je n''ai pas refusé d''être pasteur à ta suite; je n''ai pas désiré le jour du malheur, tu le sais; ce qui est sorti de mes lèvres était présent devant ta face.'),
('jr',17,17,'crampon1923','Ne sois pas pour moi une cause de ruine; tu es mon refuge au jour du malheur!'),
('jr',17,18,'crampon1923','Que mes persécuteurs soient confondus, et que je ne sois pas confondu moi-même! Qu''ils tremblent, eux, et que moi je ne tremble pas! Amène sur eux le jour du malheur, et brise-les d''une double brèche.'),
('jr',17,19,'crampon1923','Ainsi m''a parlé Yahweh: Va, et tiens-toi à la porte des fils du peuple, par où entrent et sortent les rois de Judas, et à toutes les portes de Jérusalem;'),
('jr',17,20,'crampon1923','et tu leur diras: Ecoutez la parole de Yahweh, vous, rois de Juda, et tout Juda, et vous tous, habitants de Jérusalem, qui entrez par ces portes.'),
('jr',17,21,'crampon1923','Ainsi parle Yahweh: Prenez garde à vos âmes, et ne portez point de fardeaux le jour du sabbat, et n''en faites point entrer par les portes de Jérusalem.'),
('jr',17,22,'crampon1923','Ne faites sortir de vos maisons aucun fardeau le jour du sabbat, et ne faites aucun ouvrage. Et sanctifiez le jour du sabbat, comme je l''ai ordonné à vos pères.'),
('jr',17,23,'crampon1923','Ils n''ont pas écouté ni prêté l''oreille; ils ont raidi leur cou pour ne pas écouter; et ne pas recevoir l''instruction.'),
('jr',17,24,'crampon1923','Si vous m''écoutez docilement, — oracle de Yahweh, en ne faisant point entrer de fardeaux par les portes de cette ville le jour du sabbat, en sanctifiant le jour du sabbat en ne faisant aucun ouvrage ce jour-là,'),
('jr',17,25,'crampon1923','alors par les portes de cette ville entreront des rois et des princes assis sur le trône de David, montés sur des chars et des chevaux, eux et leurs princes, les hommes de Juda et les habitants de Jérusalem; et cette ville sera habitée à jamais.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jr',17,26,'crampon1923','On viendra des villes de Juda et des environs de Jérusalem, du pays de Benjamin, de la Séphéla, de la montagne et du négéb, amener des holocaustes et des sacrifices, des oblations et de l''encens, et apporter des sacrifices d''actions de grâces dans la maison de Yahweh.'),
('jr',17,27,'crampon1923','Mais si vous ne m''écoutez en sanctifiant le jour du sabbat, en ne portant aucun fardeau, quand vous entrez par les portes de Jérusalem, le jour du sabbat, alors j''allumerai un feu aux portes de la ville, et il dévorera les palais de Jérusalem, et il ne s''éteindra point.'),
('jr',18,1,'crampon1923','La parole qui fut adressée à Jérémie par Yahweh, en ces termes:'),
('jr',18,2,'crampon1923','" Lève-toi et descends à la maison du potier, et là je te ferai entendre ma parole. "'),
('jr',18,3,'crampon1923','Je descendis à la maison du potier; et voici qu''il faisait son ouvrage sur les roues.'),
('jr',18,4,'crampon1923','Et le vase qu’il faisait manqua, comme il arrive à l’argile dans la main du potier; et il refit un autre vase, comme il parut bon aux yeux du potier de le faire.'),
('jr',18,5,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:'),
('jr',18,6,'crampon1923','Est-ce que je ne puis pas vous faire comme a fait ce potier, maison d''Israël; — oracle de Yahweh? Oui, comme l''argile est dans la main du potier, ainsi vous êtes dans ma main, maison d''Israël.'),
('jr',18,7,'crampon1923','Tantôt je parle, touchant une nation et touchant un royaume, d''arracher, d''abattre et de détruire.'),
('jr',18,8,'crampon1923','Mais cette nation, contre laquelle j''ai parlé, revient-elle de sa méchanceté, alors je me repens du mal que j''avais résolu de lui faire.'),
('jr',18,9,'crampon1923','Tantôt je parle, touchant une nation et touchant un royaume, de bâtir et de planter.'),
('jr',18,10,'crampon1923','Mais cette nation fait-elle ce qui est mal à mes yeux, en n''écoutant pas ma voix, alors je me repens du bien que j''avais dit que je lui ferais.'),
('jr',18,11,'crampon1923','Et maintenant parle donc aux hommes de Juda, et aux habitants de Jérusalem, en ces termes: Ainsi parle Yahweh: Voici que je façonne contre vous un malheur, et que je médite un dessein contre vous. Revenez donc chacun de votre voie mauvaise, et réformez vos voies et vos œuvres.'),
('jr',18,12,'crampon1923','Mais ils disent: " C''est en vain! Nous suivrons nos pensées, nous agirons chacun selon l''obstination de notre mauvais cœur. "'),
('jr',18,13,'crampon1923','C''est pourquoi ainsi parle Yahweh: Interrogez les nations: Qui a jamais entendu pareille chose? Elle a commis d''horribles abominations, la vierge d''Israël!'),
('jr',18,14,'crampon1923','Quitte-t-elle le rocher de la plaine, la neige du Liban? Voit-on tarir les eaux qui viennent de loin, fraîches et courantes?'),
('jr',18,15,'crampon1923','Or mon peuple m''a oublié; il offre de l''encens au néant. Les idoles les font chanceler dans leurs voies, les chemins d''autrefois, pour suivre des sentiers, une route non frayée;'),
('jr',18,16,'crampon1923','Pour faire de leur pays une désolation, un objet d''éternelle moquerie; tous ceux qui y passeront seront stupéfaits; et hocheront la tête.'),
('jr',18,17,'crampon1923','Pareil au vent d''orient, je les disperserai devant l''ennemi; je leur montrerai le dos et non la face, au jour de leur désastre.'),
('jr',18,18,'crampon1923','Et ils ont dit: " Venez, formons un complot contre Jérémie; car la loi ne périra pas chez le prêtre, ni le conseil chez le sage, ni la parole de Dieu chez le prophète! Venez, frappons-le avec la langue, et ne prêtons pas l''oreille à tous ses discours. "'),
('jr',18,19,'crampon1923','Prête moi l''oreille, Yahweh, et entends la voix de mes adversaires!'),
('jr',18,20,'crampon1923','Le mal sera-t-il rendu pour le bien, qu''ils creusent une fosse pour mon âme? souviens-toi comment je me suis tenu devant toi, pour te parler en leur faveur, pour détourner d''eux ta colère.'),
('jr',18,21,'crampon1923','C''est pourquoi, livre leurs enfants à la famine, et abandonne-les au tranchant du glaive! Que leurs femmes perdent leurs enfants et leurs époux; que leurs hommes meurent par la peste, et que leurs jeunes gens soient frappés par l''épée dans le combat!'),
('jr',18,22,'crampon1923','Qu''on entende leur cri sortir de leurs maisons, quand tu feras venir subitement sur eux des bandes armées! Car ils ont creusé une fosse pour me prendre, et ils ont caché des filets devant mes pieds.'),
('jr',18,23,'crampon1923','Et toi, Yahweh, tu connais tous leurs complots pour me faire mourir. Ne pardonne pas leur iniquité, n''efface pas leur péché de devant toi; qu''ils s''affaissent devant toi; agis contre eux au temps de ta colère!'),
('jr',19,1,'crampon1923','Ainsi a parlé Yahweh: Va, achète-toi une cruche de potier; prends avec toi des anciens du peuple et des anciens d’entre les prêtres.'),
('jr',19,2,'crampon1923','Et sors vers la vallée de Ben-Hinnom, qui est à l''entrée de la porte de la Poterie, et là tu publieras les paroles que je te dirai.'),
('jr',19,3,'crampon1923','Tu diras: Ecoutez la parole de Yahweh, rois de Juda et habitants de Jérusalem. Ainsi parle Yahweh des armées, Dieu d''Israël: Voici que je vais amener sur ce lieu un malheur, tel que les oreilles tinteront à qui en entendra parler;'),
('jr',19,4,'crampon1923','parce qu''ils m''ont abandonné, qu''ils ont aliéné ce lieu, qu''ils y ont offert de l''encens à des dieux étrangers que ne connaissaient ni eux, ni leurs pères ni les rois de Juda, et qu''ils ont rempli ce lieu du sang des innocents.'),
('jr',19,5,'crampon1923','Ils ont bâti les hauts lieux de Baal, pour consumer leurs enfants par le feu en holocauste à Baal, choses que je n''avais ni commandées, ni dites, et qui n''étaient point montées à mon cœur.'),
('jr',19,6,'crampon1923','C''est pourquoi voici que des jours viennent, — oracle de Yahweh, où ce lieu ne sera plus appelé Topheth ni vallée de Ben-Hinnom, mais vallée du massacre.'),
('jr',19,7,'crampon1923','Je rendrai vain dans ce lieu le conseil de Juda et de Jérusalem; je les ferai tomber par l''épée devant leurs ennemis et par la main de ceux qui en veulent à leur vie; et je donnerai leurs cadavres en pâture aux oiseaux du ciel et aux bêtes de la terre.'),
('jr',19,8,'crampon1923','Et je ferai de cette ville un objet de stupeur et de risée; quiconque passera près d''elle sera stupéfait et rira de toutes ses meurtrissures.'),
('jr',19,9,'crampon1923','Je leur ferai manger la chair de leurs fils et la chair de leurs filles; ils mangeront la chair les uns des autres, dans l''angoisse et la détresse où les réduiront leurs ennemis, et ceux qui en veulent à leur vie.'),
('jr',19,10,'crampon1923','Tu briseras ensuite la cruche sous les yeux des hommes venus avec toi,'),
('jr',19,11,'crampon1923','et tu leur diras: Ainsi parle Yahweh des armées: Je briserai ce peuple et cette ville, comme on brise le vase du potier, qui ne peut plus être réparé, et l''on enterrera à Topheth, faute de place pour enterrer.'),
('jr',19,12,'crampon1923','Voilà ce que je ferai à ce lieu, — oracle de Yahweh, — et à ses habitants, en rendant cette ville semblable à Topheth.'),
('jr',19,13,'crampon1923','Les maisons de Jérusalem et les maisons des rois de Juda seront telles que ce lieu de Topheth, souillées: toutes les maisons sur les toits desquelles on a offert de l''encens à toute l''armée des cieux et versé des libations à des dieux étrangers.'),
('jr',19,14,'crampon1923','Jérémie revint de Topheth où Yahweh l''avait envoyé prophétiser, et, se tenant dans le parvis de la maison de Yahweh, il dit à tout le peuple:'),
('jr',19,15,'crampon1923','" Ainsi parle Yahweh des armées, le Dieu d''Israël: Voici que je vais faire venir sur cette ville et sur toutes les villes de son ressort tous les malheurs que j''ai annoncés contre elle, parce qu''ils ont raidi leur cou pour ne point obéir à mes paroles. "'),
('jr',20,1,'crampon1923','Le prêtre Phassur, fils d’Emmer, qui était surveillant en chef dans la maison de Yahweh, entendit Jérémie prononcer ces prophéties.'),
('jr',20,2,'crampon1923','Et Phassur frappa Jérémie le prophète et le fit mettre aux ceps, à la porte Haute de Benjamin, qui est dans la maison de Yahweh.'),
('jr',20,3,'crampon1923','Le lendemain, Phassur fit sortir Jérémie des ceps, et Jérémie lui dit: " Ce n''est plus Phassur que Yahweh t''appelle, mais Magor-Missabib.'),
('jr',20,4,'crampon1923','Car ainsi parle Yahweh: Voici que je te livre à la terreur, toi et tous tes amis; ils tomberont sous l''épée de leurs ennemis, et tes yeux le verront. Et je livrerai aussi tout Juda aux mains du roi de Babylone, et il les emmènera captifs à Babylone, et les frappera de l''épée.'),
('jr',20,5,'crampon1923','Je livrerai toutes les richesses de cette ville, tous ses produits, tous ses objets précieux, et tous les trésors des rois de Juda, je les livrerai aux mains de leurs ennemis; et ils les pilleront, les enlèveront, et les emmèneront à Babylone.'),
('jr',20,6,'crampon1923','Et toi, Phassur, et tous ceux qui habitent dans ta maison, vous irez en captivité; tu iras à Babylone, et là tu mourras, là tu seras enterré, toi et tous tes amis, auxquels tu as prophétisé le mensonge.'),
('jr',20,7,'crampon1923','Tu m''as séduit, Yahweh, et j''ai été séduit; tu m''as saisi et tu as prévalu. Je suis chaque jour un objet de risée; tous se moquent de moi.'),
('jr',20,8,'crampon1923','Car chaque fois que je parle, je crie, j''annonce violence et dévastation, et la parole de Yahweh est pour moi opprobre et sujet de risée, chaque jour.'),
('jr',20,9,'crampon1923','Je disais: " Je ne ferai plus mention de lui, je ne parlerai plus en son nom... " Il y avait dans mon cœur comme un feu dévorant, enfermé dans mes os; je m’efforçais de le contenir, et je n''ai pas pu.'),
('jr',20,10,'crampon1923','Car j''entendais les propos méchants de la foule: " Terreur de toutes parts! Dénoncez, allons le dénoncer! " Tous ceux avec qui j''étais en paix épient mes pas: " S''il se laisse séduire, nous prévaudrons contre lui, et nous tirerons vengeance de lui. "'),
('jr',20,11,'crampon1923','Mais Yahweh est avec moi comme un héros puissant; c''est pourquoi mes persécuteurs s''affaisseront, et ils ne prévaudont pas. Ils seront confus pour n''avoir pas réussi, d''un opprobre éternel, qui ne sera pas oublié.'),
('jr',20,12,'crampon1923','Yahweh des armées, toi qui éprouve le juste; qui vois les reins et les cœurs, je verrai la vengeance que tu tireras d''eux, car c''est à toi que j''ai remis ma cause.'),
('jr',20,13,'crampon1923','Chantez à Yahweh, louez Yahweh, car il a tiré l''âme du malheureux de la main des méchants.'),
('jr',20,14,'crampon1923','Maudit soit le jour où je suis né! Que le jour où ma mère m''a enfanté ne soit pas béni!'),
('jr',20,15,'crampon1923','Maudit soit l''homme qui porta la nouvelle à mon père, en lui disant: " Un enfant mâle t''est né! " et qui le combla de joie!'),
('jr',20,16,'crampon1923','Que cet homme soit comme les villes que Yahweh a renversées sans s''en repentir! Qu''il entende le matin le cri des vaincus, et à midi les vociférations des vainqueurs!'),
('jr',20,17,'crampon1923','Parce qu''il ne m''a pas tué dès le sein maternel, afin que ma mère fût mon tombeau, ou que son sein me gardât éternellement!'),
('jr',20,18,'crampon1923','Pourquoi suis-je sorti de son sein, pour voir la peine et la douleur, et pour consumer mes jours dans l''ignominie?'),
('jr',21,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, lorsque le roi Sédécias envoya vers lui Phassur, fils de Melchias, et le prêtre Sophonias, fils de Maasias, pour lui dire:'),
('jr',21,2,'crampon1923','" Consulte, je t''en prie, Yahweh pour nous; car Nabuchodonosor, roi de Babylone, nous fait la guerre; peut-être Yahweh renouvellera-t-il en notre faveur tous ses grands miracles, afin qu''il s''éloigne de nous. "'),
('jr',21,3,'crampon1923','Jérémie leur répondit: Voici ce que vous direz à Sédécias:'),
('jr',21,4,'crampon1923','Ainsi parle Yahweh, Dieu d''Israël: Voici que je vais faire retourner en arrière les armes de guerre qui sont dans vos mains, avec lesquelles vous combattez hors des murs le roi de Babylone et les Chaldéens qui vous assiègent, et je les rassemblerai au milieu de la ville;'),
('jr',21,5,'crampon1923','et moi, je combattrai contre vous la main étendue et d''un bras puissant, avec colère, fureur et grande indignation.'),
('jr',21,6,'crampon1923','Je frapperai les habitants de cette ville, les hommes et les bêtes, et ils mourront d''une grande peste.'),
('jr',21,7,'crampon1923','Après cela, — oracle de Yahweh, je livrerai Sédécias, roi, de Juda, ses serviteurs, le peuple, et ceux qui, dans cette ville auront échappé à la peste, à l''épée et à la famine, je les livrerai aux mains de Nabuchodonosor, roi de Babylone, aux mains de leurs ennemis et de ceux qui en veulent à leur vie; et il les passera au fil de l''épée; il ne les épargnera pas, il n''aura ni pitié ni compassion.'),
('jr',21,8,'crampon1923','Et tu diras à ce peuple: Ainsi parle Yahweh: Voici que je mets devant vous le chemin de la vie et le chemin de la mort.'),
('jr',21,9,'crampon1923','Celui qui restera dans cette ville mourra par l''épée, par la famine où par la peste; celui qui en sortira pour se rendre aux Chaldéens qui vous assiègent vivra et aura sa vie pour butin.'),
('jr',21,10,'crampon1923','Car j''ai tourné ma face vers cette ville pour lui faire du mal, et non pas du bien, — oracle de Yahweh; elle sera livrée aux mains du roi de Babylone, et il la consumera par le feu.'),
('jr',21,11,'crampon1923','Et à la maison du roi de Juda tu diras: Ecoutez la parole de Yahweh,'),
('jr',21,12,'crampon1923','maison de David: Ainsi parle Yahweh: Rendez la justice dès le matin; arrachez l''opprimé des mains de l''oppresseur, de peur que ma colère n''éclate comme un feu et ne brûle sans qu''on puisse l''éteindre, à cause de la méchanceté de vos actions.'),
('jr',21,13,'crampon1923','Voici que j''en viens à toi, habitante de la vallée, rocher de la plaine, — oracle Yahweh, vous qui dites: " Qui descendra sur nous, et qui entrera dans nos retraites? "'),
('jr',21,14,'crampon1923','Je vous châtierai selon le fruit de vos œuvres, — oracle de Yahweh; je mettrai le feu à sa forêt, et il en dévorera tous les alentours.'),
('jr',22,1,'crampon1923','Ainsi parle Yahweh: Descends à la maison du roi de Juda, et là tu prononceras ces paroles:'),
('jr',22,2,'crampon1923','Tu diras: Ecoute la parole de Yahweh, ô roi de Juda, qui sièges sur le trône de David, toi, tes serviteurs et ton peuple, qui entrez par ces portes.'),
('jr',22,3,'crampon1923','Ainsi parle Yahweh: Faites droit et justice; arrachez l''opprimé aux mains de l''oppresseur; l''étranger, l''orphelin et la veuve, ne les maltraitez pas, ne les violentez pas, et ne versez pas le sang innocent dans ce lieu.'),
('jr',22,4,'crampon1923','Si vous accomplissez exactement cette parole, les rois assis sur le trône de David entreront par la porte de cette maison, montés sur des chars et sur des chevaux, eux, leurs serviteurs et leur peuple.'),
('jr',22,5,'crampon1923','Mais si vous n''écoutez pas ces paroles, je le jure par moi-même, — oracle de Yahweh, cette maison deviendra une ruine.'),
('jr',22,6,'crampon1923','Car ainsi parle Yahweh, touchant la maison du roi de Juda: Tu es pour moi un Galaad, le sommet du Liban; eh bien! je ferai de toi un désert, des villes inhabitées.'),
('jr',22,7,'crampon1923','Je prépare contre toi des destructeurs, chacun avec ses outils; ils couperont tes cèdres de choix, et les jetteront au feu.'),
('jr',22,8,'crampon1923','De nombreuses nations passeront par cette ville, et elles se diront l''une à l’autre: " Pourquoi Yahweh a-t-il ainsi traité cette grande ville? "'),
('jr',22,9,'crampon1923','Et l''on dira: " Parce qu''ils ont abandonné l''alliance de Yahweh, leur Dieu, qu''ils se sont prosternés devant d''autres dieux, et les ont servis. "'),
('jr',22,10,'crampon1923','Ne pleurez point celui qui est mort, et ne vous lamentez pas sur lui; pleurez, pleurez celui qui s''en est allé, car il ne reviendra plus, et ne verra pas le pays de sa naissance!'),
('jr',22,11,'crampon1923','Car ainsi parle Yahweh touchant Sellum, fils de Josias, roi de Juda, qui a régné à la place de Josias, son père, et qui est sorti de ce lieu: Il n''y reviendra plus;'),
('jr',22,12,'crampon1923','au lieu où on l''a emmené captif, il mourra, et il ne reverra plus ce pays.'),
('jr',22,13,'crampon1923','Malheur à celui qui bâtit sa maison par l’injustice, et ses étages avec l''iniquité, qui fait travailler son prochain pour rien, sans lui donner son salaire!'),
('jr',22,14,'crampon1923','Qui dit: " Je me bâtirai une maison vaste, et des chambres spacieuses; " qui y perce beaucoup de fenêtres, la couvre de cèdre, et la peint au vermillon!'),
('jr',22,15,'crampon1923','Es-tu roi parce que tu as la passion du cèdre! Ton père n''a-t-il pas mangé et bu? Il faisait droit et justice, alors tout allait bien pour lui;'),
('jr',22,16,'crampon1923','il jugeait la cause du malheureux et du pauvre, alors tout allait bien. N''est-ce pas là me connaître, — oracle de Yahweh?'),
('jr',22,17,'crampon1923','Mais tes yeux et ton cœur ne sont tournés qu''à ton intérêt, au sang innocent pour le répandre, à l''oppression et à la violence pour les commettre.'),
('jr',22,18,'crampon1923','C''est pourquoi ainsi parle Yahweh touchant Joakim, fils de Josias, roi de Juda: On ne pleurera pas sur lui, en disant: " Hélas! mon frère, hélas, ma sœur! " On ne pleurera pas sur lui, en disant: " Hélas, seigneur! hélas, majesté! "'),
('jr',22,19,'crampon1923','Il sera enterré comme on enterre un âne, il sera traîné et jeté hors des portes de Jérusalem.'),
('jr',22,20,'crampon1923','Monte au Liban et crie; élève ta voix en Basan! Crie du haut d''Abarim, car tous tes amants sont brisés.'),
('jr',22,21,'crampon1923','Je t''ai parlé au temps de ta prospérité; tu as dit: " Je n''écouterai pas! " C''est là ta conduite dès ta jeunesse; tu n''as pas écouté ma voix!'),
('jr',22,22,'crampon1923','Car le vent emmènera paître tes pasteurs, et tes amants iront en captivité; alors tu seras couverte de confusion et de honte pour toute ta méchanceté.'),
('jr',22,23,'crampon1923','Toi qui habite au Liban, qui places ton nid dans les cèdres, comme tu gémiras quand viendront sur toi les douleurs, des convulsions pareilles à celles d''une femme en travail!'),
('jr',22,24,'crampon1923','Je suis vivant! — oracle de Yahweh: Quand Jéchonias, fils de Joakim, roi de Juda serait un anneau à ma main droite, je l''arracherais de là!'),
('jr',22,25,'crampon1923','Je te livrerai aux mains de ceux qui en veulent à ta vie, aux mains de ceux devant qui tu trembles, aux mains de Nabuchodonosor, roi de Babylone, et aux mains des Chaldéens.'),
('jr',22,26,'crampon1923','Je te jetterai, toi et ta mère qui t''a mis au monde, dans un autre pays où vous n''êtes pas nés, et là vous mourrez.'),
('jr',22,27,'crampon1923','Et au pays où ils aspireront à revenir, ils ne reviendront pas.'),
('jr',22,28,'crampon1923','Est-ce donc un vase méprisé et brisé que cet homme, Jéchonias, ou bien un ustensile dont personne ne veut?... Pourquoi les a-t-on chassés, lui et sa race, et les a-t-on jetés dans un pays qu''ils ne connaissaient pas?'),
('jr',22,29,'crampon1923','Terre, terre, terre, écoute la parole de Yahweh!'),
('jr',22,30,'crampon1923','Ainsi parle Yahweh: Inscrivez cet homme comme stérile, comme un homme qui ne réussit pas dans ses jours! Car nul de sa race ne réussira à s''asseoir sur le trône de David pour régner encore sur Juda!'),
('jr',23,1,'crampon1923','Malheur aux pasteurs qui perdent et dispersent les brebis de mon pâturage, — oracle de Yahweh!'),
('jr',23,2,'crampon1923','C''est pourquoi ainsi parle Yahweh, Dieu d''Israël, touchant les pasteurs qui paissent mon peuple: Vous avez dispersé mes brebis, vous les avez chassées, vous n''en avez pas pris soin; voici que je vais prendre soin, contre vous, de la méchanceté de vos actions, — oracle de Yahweh.'),
('jr',23,3,'crampon1923','Et moi je rassemblerai le reste de mes brebis, de tous les pays où je les aurai chassées, et je les ramènerai dans leur pâturage; elles croîtront et se multiplieront.'),
('jr',23,4,'crampon1923','Et je susciterai sur elles des pasteurs qui les paîtront; elles n''auront plus ni crainte ni terreur, et il n''en manquera plus aucune, — oracle de Yahweh!'),
('jr',23,5,'crampon1923','Voici que des jours viennent, — oracle de Yahweh, où je susciterai à David un germe juste; il régnera en roi et il sera sage, et il fera droit et justice dans le pays.'),
('jr',23,6,'crampon1923','Dans ses jours, Juda sera sauvé, Israël habitera en assurance, et voici le nom dont on l''appellera: Yahweh-notre-justice.'),
('jr',23,7,'crampon1923','C''est pourquoi voici que des jours viennent, — oracle de Yahweh, où l''on ne dira plus: " Yahweh est vivant, lui qui a fait monter les enfants d''Israël du pays d''Egypte, " —'),
('jr',23,8,'crampon1923','mais " Yahweh est vivant, lui qui a fait monter et fait revenir la race de la maison d''Israël du pays du septentrion et de tous les pays où je les avais chassés; " et ils habiteront sur leur sol.'),
('jr',23,9,'crampon1923','Aux prophètes. Mon cœur est brisé au-dedans de moi, tous mes os tremblent; je suis comme un homme ivre, comme un homme pris de vin, en présence de Yahweh et en présence de sa parole sainte,'),
('jr',23,10,'crampon1923','Car le pays est rempli d''adultères; car, à cause de la malédiction, le pays est en deuil; les pâturages du désert sont desséchés. L''objet de leur course est le mal; leur force est l''injustice,'),
('jr',23,11,'crampon1923','Prophètes et prêtres eux-mêmes sont des profanes, et dans ma maison même j''ai trouvé leur méchanceté, — oracle de Yahweh.'),
('jr',23,12,'crampon1923','Aussi leur chemin sera pour eux comme des lieux glissants dans les ténébres; ils seront poussés, ils y tomberont; car j''amènerai sur eux le malheur l''année où je les visiterai, — oracle de Yahweh.'),
('jr',23,13,'crampon1923','Dans les prophètes de Samarie, j''ai vu de la sottise: ils prophétisaient par Baal, et ils égaraient mon peuple d''Israël;'),
('jr',23,14,'crampon1923','et dans les prophètes de Jérusalem, j''ai vu l''horreur: ils commettent l''adultère et marchent dans le mensonge; ils affermissent les mains des méchants, afin qu''aucun d''eux ne revienne de sa méchanceté. Ils sont tous pour moi comme Sodome, et les habitants de Jérusalem comme Gomorrhe.'),
('jr',23,15,'crampon1923','C''est pourquoi ainsi parle Yahweh des armées touchant les prophètes: Je vais leur faire manger de l''absinthe et leur faire boire des eaux empoisonnées! car c''est des prophètes de Jérusalem que la profanation est venue dans tout le pays.'),
('jr',23,16,'crampon1923','Ainsi parle Yahweh des armées: N''écoutez pas les paroles des prophètes qui vous prophétisent. Ils vous entraînent à la vanité, ils disent les visions de leur propre cœur, et non ce qui sort de la bouche de Yahweh.'),
('jr',23,17,'crampon1923','Ils disent à ceux qui me méprisent: " Yahweh a dit: Vous aurez la paix; " et à tous ceux qui marchent dans la perversersité de leur cœur ils disent: " Il ne vous arrivera aucun mal. "'),
('jr',23,18,'crampon1923','Mais qui a assisté au conseil de Yahweh pour voir et entendre sa parole? Qui a été attentif à sa parole et l''a entendue?'),
('jr',23,19,'crampon1923','Voici que la tempête de Yahweh, la fureur, va éclater; l''orage tourbillonne, il fond sur la tête des impies.'),
('jr',23,20,'crampon1923','La colère de Yahweh ne retournera pas en arrière qu''elle n''ait agi et réalisé les desseins de son cœur; à la fin des temps vous en aurez la pleine intelligence.'),
('jr',23,21,'crampon1923','Je n''ai pas envoyé ces prophètes, et ils courent! Je ne leur ai point parlé, et ils prophétisent!'),
('jr',23,22,'crampon1923','S''ils avaient assisté à mon conseil, ils auraient fait entendre mes paroles à mon peuple; ils les auraient ramenés de leur voie mauvaise, de la méchanceté de leurs actions.'),
('jr',23,23,'crampon1923','Ne suis-je un Dieu que de près, — oracle de Yahweh, et ne suis-je pas aussi un Dieu de loin?'),
('jr',23,24,'crampon1923','Un homme peut-il se cacher dans des cachettes sans que je le voie — oracle de Yahweh? Est-ce que le ciel et la terre je ne les remplis pas, moi — oracle de Yahweh?'),
('jr',23,25,'crampon1923','J''ai entendu ce que disent ces prophètes qui prophétisent en mon nom des mensonges, en disant: " J''ai eu un songe; j''ai eu un songe! "'),
('jr',23,26,'crampon1923','Jusques à quand?... Veulent-ils, ces prophètes, qui prophétisent le mensonge, ces prophètes de l''imposture de leur cœur,'),
('jr',23,27,'crampon1923','pensent-ils faire oublier mon nom à mon peuple, pour les rêves qu''ils se racontent les uns aux autres, comme leurs pères ont oublié mon nom pour Baal?'),
('jr',23,28,'crampon1923','Que le prophète qui a eu un songe raconte ce songe; que celui qui a ma parole rapporte fidèlement ma parole. Qu''a de commun la paille avec le froment, — oracle de Yahweh?'),
('jr',23,29,'crampon1923','Ma parole n''est-elle pas comme un feu, — oracle de Yahweh, comme un marteau qui brise le roc?'),
('jr',23,30,'crampon1923','C''est pourquoi, voici que je viens à ces prophètes qui se dérobent mes paroles les uns aux autres.'),
('jr',23,31,'crampon1923','Voici que je viens à ces prophètes, — oracle de Yahweh, qui agitent leur langue et qui disent: " Oracle de Yahweh! "'),
('jr',23,32,'crampon1923','Voici que je viens à ceux qui prophétisent des songes menteurs, — oracle de Yahweh, qui les racontent, qui égarent mon peuple par leurs mensonges et par leur extravagance. Je ne les ai point envoyés, et je ne leur ai rien commandé; ils ne servent de rien à ce peuple; — oracle de Yahweh.'),
('jr',23,33,'crampon1923','Quand ce peuple, ou des prophètes, ou un prêtre t''interrogent en ces termes: " Quel est le fardeau de Yahweh? " tu leur répondras: " C''est vous qui êtes le fardeau, et je vous rejetterai, " — oracle de Yahweh.'),
('jr',23,34,'crampon1923','Et le prophète, le prêtre ou l''homme du peuple qui dira: " Fardeau de Yahweh, " je visiterai cet homme et sa maison.'),
('jr',23,35,'crampon1923','Voici comment vous parlerez l''un à l''autre et chacun à son frère: " Qu''a répondu Yahweh? " et " Qu''a dit Yahweh? "'),
('jr',23,36,'crampon1923','Mais vous ne répéterez plus: " Fardeau de Yahweh! " Car le fardeau de chacun sera sa parole, parce que vous tordez les paroles du Dieu vivant, de Yahweh des armées, notre Dieu.'),
('jr',23,37,'crampon1923','Tu parleras ainsi au prophète: " Que t''a répondu Yahweh? qu''a dit Yahweh? "'),
('jr',23,38,'crampon1923','Mais si vous dites: " Fardeau de Yahweh, " alors Yahweh parle ainsi: Parce que vous dites ce mot: " Fardeau de Yahweh, " après que j''ai envoyé vers vous pour vous dire: " Ne dites plus: Fardeau de Yahweh, "'),
('jr',23,39,'crampon1923','à cause de cela, voici que je vous oublierai entièrement et que je vous rejetterai de devant ma face, vous et la ville que j''avais donnée à vous et à vos pères;'),
('jr',23,40,'crampon1923','et je ferai venir sur vous un opprobre éternel, une honte éternelle, qui ne s''oublieront jamais.'),
('jr',24,1,'crampon1923','Yahweh me fit voir, et voici deux paniers de figues posés devant le temple de Yahweh; — c''était après que Nabuchodonosor, roi de Babylone, eut emmené captif de Jérusalem à Babylone Jéchonias, fils de Joakim, roi de Juda, les chefs de Juda, les charpentiers et les serruriers; —'),
('jr',24,2,'crampon1923','l''un des paniers contenait de très bonnes figues comme le sont les figues de la première récolte; l''autre panier, des figues très mauvaises, qu''on ne pouvait manger, tant elles étaient mauvaises.'),
('jr',24,3,'crampon1923','Et Yahweh me dit: " Que vois-tu Jérémie? " Et je répondis: " Des figues; les bonnes figues sont très bonnes, les mauvaises sont très mauvaises et ne peuvent être mangées, tant elles sont mauvaises. "'),
('jr',24,4,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:'),
('jr',24,5,'crampon1923','Ainsi parle Yahweh, Dieu d''Israël: Comme on regarde ces bonnes figues, ainsi je regarderai avec faveur les captifs de Juda, que j''ai envoyés de ce lieu au pays des Chaldéens.'),
('jr',24,6,'crampon1923','Je dirigerai sur eux mes regards pour leur bien, et je les ramènerai dans ce pays; je les établirai pour ne plus les détruire; je les planterai pour ne plus les arracher.'),
('jr',24,7,'crampon1923','Je leur donnerai un cœur pour me connaître et savoir que je suis Yahweh; ils seront mon peuple et je serai leur Dieu, car ils reviendront à moi de tout leur cœur.'),
('jr',24,8,'crampon1923','Et comme on traite les mauvaises figues, qu''on ne mange pas, tant elles sont mauvaises — ainsi, parle Yahweh —, ainsi je traiterai Sédécias, roi de Juda, ses princes et le reste de Jérusalem, ceux qui sont demeurés dans ce pays, et ceux qui habitent au pays d''Egypte.'),
('jr',24,9,'crampon1923','J''en ferai un objet d''horreur, un malheur, dans tous les royaumes de la terre, un opprobre, une fable, une risée, une malédiction, dans tous les lieux où je les chasserai.'),
('jr',24,10,'crampon1923','Et j''enverrai sur eux l''épée, la famine et la peste jusqu''à ce qu''ils aient disparu du sol que j''avais donné à eux et à leurs pères.'),
('jr',25,1,'crampon1923','La parole qui fut adressée à Jérémie touchant tout le peuple de Juda, en la quatrième année de Joakim, fils de Josias, roi de Juda, — c''était la première année de Nabuchodonosor, roi de Babylone —;'),
('jr',25,2,'crampon1923','parole que Jérémie prononça sur tout le peuple de Juda et pour tous les habitants de Jérusalem, en ces termes:'),
('jr',25,3,'crampon1923','Depuis la treizième année de Josias, fils d''Amon, roi de Juda, jusqu''à ce jour, voici vingt-trois ans que la parole de Yahweh m''a été adressée et que je vous ai parlé, vous parlant dès le matin, et que vous n''avez pas écouté!'),
('jr',25,4,'crampon1923','Yahweh vous a envoyé tous ses serviteurs les prophètes, les envoyant dès le matin, et vous n''avez pas écouté, et vous n''avez pas prêté l''oreille pour entendre.'),
('jr',25,5,'crampon1923','Il disait: " Revenez-donc chacun de votre mauvaise voie et de la perversité de vos actions, et vous habiterez dans le pays que Yahweh a donné à vous et à vos pères, d''âge en âge.'),
('jr',25,6,'crampon1923','N''allez pas après d''autres dieux pour les servir et les adorer; ne m''irritez pas par l''ouvrage de vos mains, et je ne vous ferai aucun mal.'),
('jr',25,7,'crampon1923','Mais vous ne m''avez pas écouté, — oracle de Yahweh, — afin de m''irriter par l’œuvre de vos mains, pour votre malheur.'),
('jr',25,8,'crampon1923','C''est pourquoi ainsi parle Yahweh des armées: Parce que vous n''avez pas écouté mes paroles,'),
('jr',25,9,'crampon1923','voici que j''envoie prendre toutes les tribus du septentrion, — oracle de Yahweh, — et je les amène à Nabuchodonosor, roi de Babylone, mon serviteur; je les ferai venir contre ce pays et contre ses habitants, et contre toutes ces nations d''alentour, que je frapperai d''anathème, et dont je ferai une solitude, un objet de moquerie, une ruine éternelle.'),
('jr',25,10,'crampon1923','Je ferai disparaître du milieu d''eux les cris de joie et les cris d''allégresse, les chants du fiancé et les chants de la fiancée, le bruit de la meule et la lumière de la lampe.'),
('jr',25,11,'crampon1923','Tout ce pays sera une solitude, un désert, et ces nations seront asservies au roi de Babylone pendant soixante-dix ans.'),
('jr',25,12,'crampon1923','Et lorsque les soixante-dix ans seront accomplis, je ferai rendre compte de leur péché au roi de Babylone et à cette nation, — oracle de Yahweh, — et au pays des Chaldéens, et j''en ferai des solitudes éternelles.'),
('jr',25,13,'crampon1923','Et je ferai venir sur ce pays toutes les paroles que j’ai prononcées contre lui, tout ce qui est écrit dans ce livre, ce que Jérémie a prophétisé sur toutes les nations.'),
('jr',25,14,'crampon1923','Car des nations nombreuses et de grands rois les asserviront, eux aussi, et je leur rendrai selon leurs actions et selon l''œuvre de leurs mains. "'),
('jr',25,15,'crampon1923','Car ainsi m’a parlé Yahweh, Dieu d’Israël: Prends de ma main cette coupe du vin de ma colère et fais-la boire à toutes les nations vers lesquelles je t’en verrai.'),
('jr',25,16,'crampon1923','Elles en boiront, elles chancelleront, elles seront prises de folie devant l''épée que j''enverrai au milieu d''elles.'),
('jr',25,17,'crampon1923','Je pris la coupe de la main de Yahweh et je la fis boire à toutes les nations vers lesquelles Yahweh m''envoyait:'),
('jr',25,18,'crampon1923','à Jérusalem et aux villes de Juda, à ses rois, à ses princes, pour en faire une solitude, une désolation, un objet de moquerie et de malédiction, comme cela se voit aujourd''hui;'),
('jr',25,19,'crampon1923','à Pharaon; roi d''Egypte, à ses serviteurs, à ses princes, à tout son peuple;'),
('jr',25,20,'crampon1923','à tout le peuple mélangé; à tous les rois du pays de Uts; à tous les rois du pays des Philistins, à Ascalon, à Gaza, à Accaron et aux restes d''Azoth;'),
('jr',25,21,'crampon1923','à Edom, à Moab et aux fils d''Ammon;'),
('jr',25,22,'crampon1923','à tous les rois de Tyr, et à tous les rois de Sidon, et aux rois des îles qui sont au delà de la mer;'),
('jr',25,23,'crampon1923','à Dédan, à Théma, à Buz et à tous ceux qui se rasent les tempes;'),
('jr',25,24,'crampon1923','à tous les rois d''Arabie, à tous les rois des peuples mélangés qui habitent le désert;'),
('jr',25,25,'crampon1923','à tous les rois de Zambri, à tous les rois d''Elam, et à tous les rois de Médie;'),
('jr',25,26,'crampon1923','à tous les rois du septentrion, proches ou éloignés, à l''un comme à l''autre, et à tous les royaumes du monde qui sont sur la face de la terre; et le roi de Sésac boira après eux.'),
('jr',25,27,'crampon1923','Tu leur diras: Ainsi parle Yahweh des armées, Dieu d''Israël: Buvez, enivrez-vous, vomissez et tombez pour ne plus vous relever, devant l’épée que j''envoie au milieu de vous.'),
('jr',25,28,'crampon1923','Et s''ils refusent de prendre de ta main la coupe pour boire, tu leur diras: Ainsi parle Yahweh: Vous boirez!'),
('jr',25,29,'crampon1923','Car voici: c''est dans la ville sur laquelle mon nom est invoqué que je commence à faire venir le mal; et vous, vous seriez impunis? Vous ne serez pas impunis, car j''appelle l''épée sur tous les habitants de la terre, — oracle de Yahweh des armées.'),
('jr',25,30,'crampon1923','Et toi, tu leur prophétiseras toutes ces choses, et tu leur diras: Yahweh rugit du haut du ciel; de sa demeure sainte il fait retentir sa voix; il rugit violemment contre son domaine; il pousse le cri des vendangeurs, contre tous les habitants de la terre.'),
('jr',25,31,'crampon1923','Le bruit en est arrivé jusqu’au bout de la terre; car Yahweh fait le procès à toutes les nations, il entre en jugement avec toute chair; il livre les méchants au glaive, — oracle de Yahweh.'),
('jr',25,32,'crampon1923','Ainsi parle Yahweh des armées: Voici que le malheur passe de nation en nation; une grande tempête s''élève des extrémités de la terre.'),
('jr',25,33,'crampon1923','Et il y aura des tués de Yahweh, en ce jour-là, d''un bout de la terre à l''autre; ils ne seront ni pleurés, ni ramassés, ni enterrés; ils seront comme du fumier sur le sol.'),
('jr',25,34,'crampon1923','Hurlez, pasteurs, et criez; roulez-vous dans la poussière, chefs du troupeau, car vos jours sont accomplis pour le massacre; je vous disperserai et vous tomberez comme des vases de prix.'),
('jr',25,35,'crampon1923','Plus de retraite pour les pasteurs, plus de refuge pour les chefs du troupeau!'),
('jr',25,36,'crampon1923','On entend les cris des pasteurs, et les hurlements des chefs du troupeau, car Yahweh ravage leur pâturage.'),
('jr',25,37,'crampon1923','Les campagnes paisibles sont dévastées par la fureur de la colère de Yahweh.'),
('jr',25,38,'crampon1923','Il quitte sa retraite, comme le lion son fourré; leur pays va être changé en désert devant la fureur du destructeur, devant la colère de Yahweh.'),
('jr',26,1,'crampon1923','Au commencement du règne de Joakim, fils de Josias, roi de Juda, cette parole fut adressée à Jérémie de la part de Yahweh:'),
('jr',26,2,'crampon1923','Ainsi parle Yahweh: Tiens-toi dans le parvis de la maison de Yahweh, et dis à ceux de toutes les villes de Juda qui viennent adorer dans la maison de Yahweh, toutes les paroles que je t''ai commandé de leur dire; n''en retranche pas un mot.'),
('jr',26,3,'crampon1923','Peut-être écouteront-ils et reviendront-ils chacun de leur mauvaise voie; alors je me repentirai du mal que j''ai dessein de leur faire à cause de la méchanceté de leurs actions.'),
('jr',26,4,'crampon1923','Tu leur diras: Ainsi parle Yahweh: Si vous ne m’obéissez pas, en suivant la loi que j’ai mise devant vous,'),
('jr',26,5,'crampon1923','en écoutant les paroles de mes serviteurs les prophètes, que j''envoie vers vous, que j''ai envoyés dès le matin, et que vous n''avez pas écoutés,'),
('jr',26,6,'crampon1923','je traiterai cette maison comme Silo, et je ferai de cette ville un objet de malédiction pour toutes les nations de la terre.'),
('jr',26,7,'crampon1923','Les prêtres, les prophètes et tout le peuple entendirent Jérémie prononcer ces paroles dans la maison de Yahweh.'),
('jr',26,8,'crampon1923','Et quand Jérémie eut achevé de dire tout ce que Yahweh lui avait commandé de dire à tout le peuple, les prêtres, les prophètes et tout le peuple se saisirent de lui, en disant: " Tu mourras!'),
('jr',26,9,'crampon1923','Pourquoi prophétises-tu au nom de Yahweh en disant: Cette maison sera comme Silo, et cette ville sera dévastée et sans habitants? " Et tout le peuple se rassembla autour de Jérémie dans la maison de Yahweh.'),
('jr',26,10,'crampon1923','Les princes de Juda, ayant appris ces choses, montèrent de la maison du roi à la maison de Yahweh, et s''assirent à l''entrée de la porte Neuve de la maison de Yahweh.'),
('jr',26,11,'crampon1923','Alors les prêtres et les prophètes dirent aux princes et à tout le peuple: Cet homme mérite la mort, car il a prophétisé contre cette ville, comme vous l''avez entendu de vos oreilles.'),
('jr',26,12,'crampon1923','Et Jérémie parla à tous les princes et à tout le peuple en disant: " C''est Yahweh qui m''a envoyé prophétiser, contre cette maison et contre cette ville, toutes les choses que vous avez entendues.'),
('jr',26,13,'crampon1923','Maintenant, améliorez vos voies et vos œuvres, et écoutez la voix de Yahweh, votre Dieu, et Yahweh se repentira du mal qu''il a prononcé contre vous.'),
('jr',26,14,'crampon1923','Pour moi, me voici entre vos mains; faites de moi selon qu''il paraîtra bon et juste à vos yeux.'),
('jr',26,15,'crampon1923','Seulement sachez que si vous me faites mourir, c''est du sang innocent que vous mettrez sur vous, sur cette ville et ses habitants; car en vérité Yahweh m''a envoyé vers vous pour faire entendre à vos oreilles toutes ces paroles. "'),
('jr',26,16,'crampon1923','Alors les princes et tout le peuple dirent aux prêtres et aux prophètes: " Cet homme ne mérite pas la mort, car c''est au nom de Yahweh, notre Dieu, qu''il nous a parlé. "'),
('jr',26,17,'crampon1923','Et quelques-uns des anciens du pays, s''étant levés, dirent à toute l''assemblée du peuple:'),
('jr',26,18,'crampon1923','" Michée de Moréscheth prophétisait aux jours d''Ezéchias, roi de Juda, et il parla ainsi à tout le peuple de Juda en ces termes: Ainsi parle Yahweh des armées: Sion sera labourée comme un champ; Jérusalem deviendra un monceau de ruines, et la montagne du Temple une colline boisée.'),
('jr',26,19,'crampon1923','Ezéchias, roi de Juda, et tout Juda l''ont-ils donc fait mourir? N''ont-ils pas plutôt craint Yahweh? N''ont-t-ils pas imploré Yahweh? Et Yahweh s''est repenti de ce qu''il avait prononcé contre eux. Et nous, nous commettrions un grand crime au préjudice de nos âmes!... "'),
('jr',26,20,'crampon1923','Il y eut aussi un homme qui prophétisait au nom de Yahweh, Urie, fils de Séméï, de Cariathiarim; il prophétisa contre cette ville et contre ce pays exactement les mêmes choses que Jérémie.'),
('jr',26,21,'crampon1923','Le roi Joakim, tous ses hommes vaillants et tous ses princes entendirent ses paroles, et le roi chercha à le faire mourir. Urie en fut informé, il eut peur et s’enfuit en Egypte.'),
('jr',26,22,'crampon1923','Mais le roi Joakim envoya des hommes en Egypte, Elnathan, fils d''Achobor, et des hommes avec lui, en Egypte.'),
('jr',26,23,'crampon1923','Ils firent sortir Urie d’Egypte et l’emmenèrent au roi Joakim, qui le fit périr par l’épée et jeta son cadavre dans les sépulcres du commun peuple.'),
('jr',26,24,'crampon1923','Or la main d’Ahicam, fils de Saphan, soutint Jérémie, en sorte qu’on ne le livra pas au peuple pour être mis à mort.'),
('jr',27,1,'crampon1923','Au commencement du règne de Joakim, fils de Josias, roi de Juda, cette parole fut adressée à Jérémie de la part de Yahweh:'),
('jr',27,2,'crampon1923','Ainsi m''a parlé Yahweh: Fais-toi des liens et des jougs, et mets-les sur ton cou.'),
('jr',27,3,'crampon1923','Puis envoie-les au roi d''Edom, au roi de Moab, au roi des enfants d''Ammon, au roi de Tyr et au roi de Sidon, par l''intermédiaire des ambassadeurs qui sont venus à Jérusalem auprès de Sédécias, roi de Juda.'),
('jr',27,4,'crampon1923','Donne-leur un message pour leurs maîtres, en ces termes: Ainsi parle Yahweh des armées, Dieu d’Israël: Voici ce que vous direz à vos maîtres:'),
('jr',27,5,'crampon1923','C''est moi qui, par ma puissance et par mon bras étendu, ai fait la terre, l''homme et les animaux qui sont sur la face de la terre, et je la donne à qui il me plaît.'),
('jr',27,6,'crampon1923','Et maintenant, moi j''ai donné toutes ces contrées aux mains de Nabuchodonosor, roi de Babylone, mon serviteur; je lui ai donné même les animaux des champs pour qu''ils le servent.'),
('jr',27,7,'crampon1923','Toutes les nations lui seront assujetties, à lui, à son fils et au fils de son fils, jusqu’à ce que vienne le temps de son pays, à lui aussi, et que des nations nombreuses et de grands rois l''assujettissent.'),
('jr',27,8,'crampon1923','La nation et le royaume qui ne se soumettront pas à lui, Nabuchodonosor, roi de Babylone, et qui ne mettront pas leur cou sous le joug du roi de Balylonne, cette nation, je la visiterai par l''épée, par la famine et par la peste, — oracle de Yahweh, — jusqu''à ce que je l''achève par sa main.'),
('jr',27,9,'crampon1923','Et vous, n''écoutez pas vos prophètes, ni vos devins, ni vos songes, ni vos augures, ni vos magiciens, qui vous disent: " Vous ne serez pas assujettis au roi de Babylone. "'),
('jr',27,10,'crampon1923','Car c''est le mensonge qu''ils vous prophétisent, pour qu''on vous éloigne de votre pays, pour que je vous chasse et que vous périssiez.'),
('jr',27,11,'crampon1923','Mais la nation qui mettra son cou sous le joug du roi de Babylone, et le servira, je la laisserai en repos dans son pays, — oracle de Yahweh; elle le cultivera et y demeurera.'),
('jr',27,12,'crampon1923','Et à Sédécias, roi de Juda, je parlai selon toutes ces paroles, en disant: Mettez vos cous sous le joug du roi de Babylone; servez-le, lui et son peuple, et vous vivrez.'),
('jr',27,13,'crampon1923','Pourquoi mourriez-vous, toi et ton peuple, par l''épée, par la famine et par la peste, comme Yahweh l''a dit de la nation qui ne voudra pas servir le roi de Babylone?'),
('jr',27,14,'crampon1923','N''écoutez pas les paroles des prophètes qui vous disent: " Vous ne serez point assujettis au roi de Babylone. " Car c''est le mensonge qu''ils vous prophétisent.'),
('jr',27,15,'crampon1923','Car je ne les ai point envoyés, — oracle de Yahweh, — et ils prophétisent faussement en mon nom, afin que je vous chasse et que vous périssiez, vous et les prophètes qui vous prophétisent.'),
('jr',27,16,'crampon1923','Et aux prêtres et à tout ce peuple je parlerai en ces termes: Ainsi parle Yahweh: N''écoutez pas les paroles de vos prophètes qui vous prophétisent en ces termes: " Voici que les ustensiles de la maison de Yahweh seront bientôt ramenés de Babylone. " Car c''est le mensonge qu''ils vous prophétisent.'),
('jr',27,17,'crampon1923','Ne les écoutez pas; soumettez-vous au roi de Babylone, et vous vivrez. Pourquoi cette ville serait-elle réduite en solitude?'),
('jr',27,18,'crampon1923','S''ils sont prophètes, si la parole de Yahweh est avec eux, qu''ils intercèdent auprès de Yahweh des armées pour que les ustensiles qui sont restés dans la maison de Yahweh, dans celle des rois de Juda et à Jérusalem, ne s''en aillent pas à Babylone!'),
('jr',27,19,'crampon1923','Car ainsi parle Yahweh des armées au sujet des colonnes, de la mer, des bases et des autres ustensiles qui sont restés dans cette ville,'),
('jr',27,20,'crampon1923','que Nabuchodonosor, roi de Babylone, n’a pas pris, lorsqu’il a emmené captifs de Jérusalem à Babylone Jéchonias, fils de Joakim, roi de Juda, et tous les grands de Juda et de Jérusalem.'),
('jr',27,21,'crampon1923','Car ainsi parle Yahweh des armées, Dieu d’Israël, au sujet des ustensiles qui restent dans la maison de Yahweh, dans la maison du roi de Juda et à Jérusalem:'),
('jr',27,22,'crampon1923','Ils seront emportés à Babylone, et ils y resteront jusqu’au jour où je les visiterai, — oracle de Yahweh, — et je les ferai remonter et revenir dans ce lieu.'),
('jr',28,1,'crampon1923','Cette même année, au commencement du règne de Sédécias, roi de Juda, la quatrième année, le cinquième mois, le prophète Hananias, fils d''Azur, de Gabaon, me dit, dans la maison de Yahweh, en présence des prêtres et de tout le peuple:'),
('jr',28,2,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: J''ai brisé le joug du roi de Babylone.'),
('jr',28,3,'crampon1923','Encore deux ans, et je ramènerai dans ce lieu tous les ustensiles de la maison de Yahweh, que Nabuchodonosor, roi de Babylone, a enlevés de ce lieu et qu''il a emportés à Babylone.'),
('jr',28,4,'crampon1923','Et je ferai revenir dans ce lieu Jéchonias, fils de Joakim, roi de Juda, et tous les captifs de Juda qui sont allés à Babylone, — oracle de Yahweh —, car je briserai le joug du roi de Babylone.'),
('jr',28,5,'crampon1923','Et Jérémie le prophète répondit à Hananias le prophète, en présence des prêtres et en présence de tout le peuple qui se tenaient dans la maison de Yahweh.'),
('jr',28,6,'crampon1923','Jérémie le prophète dit: Amen! Ainsi fasse Yahweh! Que Yahweh accomplisse les paroles que tu viens de prophétiser, en ramenant de Babylone en ce lieu les ustensiles de la maison de Yahweh et tous les captifs!'),
('jr',28,7,'crampon1923','Toutefois entends cette parole que je prononce à tes oreilles et aux oreilles de tout le peuple:'),
('jr',28,8,'crampon1923','Les prophètes qui ont été avant moi et avant toi, dès les temps anciens, ont prophétisé à de nombreux pays et à de grands royaumes la guerre, le malheur et la peste.'),
('jr',28,9,'crampon1923','Quant au prophète qui prophétise la paix, ce sera lorsque s''accomplira la parole de ce prophète qu''il sera reconnu pour le prophète véritablement envoyé par Yahweh.'),
('jr',28,10,'crampon1923','Alors Hananias le prophète prit le joug de dessus le cou de Jérémie le prophète, et le brisa.'),
('jr',28,11,'crampon1923','Et Hananias dit en présence de tout le peuple: Ainsi parle Yahweh: C''est ainsi que dans deux ans je briserai le joug de Nabuchodonosor, roi de Babylone, de dessus le cou de toutes les nations. Et Jérémie le prophète s''en alla.'),
('jr',28,12,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie, — après que Hananias le prophète eut brisé le joug de dessus le cou de Jérémie le prophète, — en ces termes:'),
('jr',28,13,'crampon1923','Va, parle à Hananias en ces termes: Ainsi parle Yahweh: Tu as brisé un joug de bois, et tu as fait à sa place un joug de fer.'),
('jr',28,14,'crampon1923','Car ainsi parle Yahweh des armées, Dieu d''Israël: Je mets un joug de fer sur le cou de toutes ces nations, pour qu''elles soient assujetties à Nabuchodonosor, et elles lui seront assujetties; je lui ai donné même les animaux des champs.'),
('jr',28,15,'crampon1923','Puis Jérémie le prophète dit à Hananias le prophète: Ecoute, Hananias: Yahweh ne t''a pas envoyé, et tu as fait que ce peuple se confie au mensonge.'),
('jr',28,16,'crampon1923','C''est pourquoi ainsi parle Yahweh: Voici que je te renvoie de la face de la terre; cette année même tu mourras, car tu as prêché la révolte contre Yahweh.'),
('jr',28,17,'crampon1923','Et Hananias le prophète mourut cette même année, au septième mois.'),
('jr',29,1,'crampon1923','Voici le texte de la lettre que Jérémie le prophète envoya de Jérusalem au reste des anciens en captivité, aux prêtres, aux prophètes et à tout le peuple que Nabuchodonosor avait déporté de Jérusalem à Babylone,'),
('jr',29,2,'crampon1923','après que furent sortis de Jérusalem le roi Jéchonias, la reine-mère, les eunuques, les princes de Juda et de Jérusalem, les charpentiers et les serruriers:'),
('jr',29,3,'crampon1923','il l’envoya par l''intermédiaire d''Élasa, fils de Saphan, et de Gamarias, fils d’Helcias, que Sédécias, roi de Juda, avait député à Babylone auprès de Nabuchodonosor, roi de Babylone. Elle disait:'),
('jr',29,4,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël, à tous les captifs que j''ai exilés de Jérusalem à Babylone:'),
('jr',29,5,'crampon1923','Bâtissez des maisons et habitez-les; plantez des jardins et mangez-en les fruits.'),
('jr',29,6,'crampon1923','Prenez des femmes, et engendrez des fils et des filles; prenez des femmes pour vos fils, et donnez à vos filles des maris, et qu''elles enfantent des fils et des filles; multipliez-vous dans ce pays, et ne diminuez pas.'),
('jr',29,7,'crampon1923','Recherchez le bien de la ville où je vous ai menés en captivité, et priez Yahweh pour elle, car son bien sera votre bien.'),
('jr',29,8,'crampon1923','Car ainsi parle Yahweh des armées, Dieu d''Israël: Ne vous laissez pas séduire par vos prophètes qui sont au milieu de vous, ni par vos devins, et n''écoutez pas les songes que vous vous donnez.'),
('jr',29,9,'crampon1923','Car c''est faussement qu''ils vous prophétisent en mon nom; je ne les ai pas envoyés, — oracle de Yahweh.'),
('jr',29,10,'crampon1923','Car ainsi parle Yahweh: C''est lorsque soixante-dix ans se seront accomplis pour Babylone que je vous visiterai et que j''exécuterai pour vous ma bonne parole, en vous ramenant en ce lieu.'),
('jr',29,11,'crampon1923','Car moi, je connais les pensées que j''ai pour vous, — oracle de Yahweh, — pensées de paix, et non de malheur, afin de vous donner un avenir et de l''espérance.'),
('jr',29,12,'crampon1923','Vous m''appellerez, et vous viendrez, et vous me prierez, et je vous écouterai.'),
('jr',29,13,'crampon1923','Vous me chercherez et vous me trouverez, parce que vous me chercherez de tout votre cœur.'),
('jr',29,14,'crampon1923','Et je me laisserai trouver par vous, — oracle de Yahweh; je ramènerai vos captifs, et je vous rassemblerai de toutes les nations et de tous les lieux où je vous aurai chassés, — oracle de Yahweh, — et je vous ramènerai au lieu d''où je vous ai exilés.'),
('jr',29,15,'crampon1923','Mais, dites-vous, Yahweh nous a suscité des prophètes à Babylone.'),
('jr',29,16,'crampon1923','Ainsi parle Yahweh touchant le roi qui est assis sur le trône de David, tout le peuple qui habite dans cette ville et vos frères qui ne sont pas partis avec vous en exil:'),
('jr',29,17,'crampon1923','Ainsi parle Yahweh des armées: Je vais envoyer contre eux l''épée, la famine et la peste; je les traiterai comme les figues détestables dont on ne peut manger, tant elles sont mauvaises.'),
('jr',29,18,'crampon1923','Je les poursuivrai avec l''épée, la famine et la peste, et j''en ferai un objet de terreur dans tous les royaumes de la terre, un objet de malédiction, de stupeur, de moquerie, d''opprobre, parmi toutes les nations où je les aurai chassés:'),
('jr',29,19,'crampon1923','parce qu''ils n''ont pas écouté mes paroles, — oracle de Yahweh, — alors que je leur ai envoyé mes serviteurs les prophètes, les envoyant dès le matin; et vous n''avez pas écouté, — oracle de Yahweh.'),
('jr',29,20,'crampon1923','Vous donc, écoutez la parole de Yahweh, vous tous captifs que j''ai envoyés de Jérusalem à Babylone!'),
('jr',29,21,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël, au sujet d''Achab, fils de Colias, et de Sédécias, fils de Maasias, qui vous prophétisent en mon nom des mensonges: Voici que je les livre aux mains de Nabuchodonosor, roi de Babylone, et il les fera mourir sous vos yeux.'),
('jr',29,22,'crampon1923','On tirera d''eux une formule de malédiction parmi tous les captifs de Juda qui sont à Babylone, en disant: " Que Yahweh te traite comme Sédécias et Achab, que le roi de Babylone a fait rôtir au feu! "'),
('jr',29,23,'crampon1923','parce qu''ils ont fait une infamie en Israël, en commettant l''adultère avec les femmes de leur prochain et en prononçant en mon nom des mensonges, ce que je ne leur avais pas commandé; et moi je le sais, et je suis témoin, — oracle de Yahweh.'),
('jr',29,24,'crampon1923','Et à Séméias, le Néhélamite. tu diras:'),
('jr',29,25,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: Tu as envoyé en ton nom à tout le peuple qui est à Jérusalem, au prêtre Sophonie, fils de Maasias, et à tous les prêtres des lettres pour leur dire:'),
('jr',29,26,'crampon1923','Yahweh t''a établi prêtre à la place du prêtre Joïada, afin qu''il y ait des surveillants dans la maison de Yahweh pour tout homme qui fait l''inspiré et le prophète, afin que tu le mettes aux ceps ou au carcan.'),
('jr',29,27,'crampon1923','Et maintenant, pourquoi donc n''as-tu pas réprimé Jérémie d''Anathoth qui vous prophétise?'),
('jr',29,28,'crampon1923','Grâce à cela, il a pu nous envoyer dire à Babylone: " Ce sera long; bâtissez des maisons et habitez-les; plantez des jardins et mangez-en les fruits. "'),
('jr',29,29,'crampon1923','Sophonie le prêtre lu cette lettre devant Jérémie le prophète.'),
('jr',29,30,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie en ces termes:'),
('jr',29,31,'crampon1923','Envoie dire à tous les exilés: Ainsi parle Yahweh au sujet de Séméias, le Néhélamite: Parce que Séméias vous a prophétisé sans que je l''aie envoyé et qu’il vous a fait mettre votre confiance en un mensonge,'),
('jr',29,32,'crampon1923','à cause de cela, ainsi parle Yahweh: Je visiterai Séméias, le Néhélamite, et sa postérité; il n’aura personne des siens qui habite au milieu de son peuple, et il ne verra pas le bien que je ferai à mon peuple, — oracle de Yahweh — car il a prêché la révolte contre Yahweh.'),
('jr',30,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, en ces termes:'),
('jr',30,2,'crampon1923','Ainsi parle Yahweh, Dieu d’Israël: Ecris dans un livre toutes les paroles que je t’ai dites.'),
('jr',30,3,'crampon1923','Car voici que des jours viennent, — oracle de Yahweh, — où je ramènerai les captifs de mon peuple d’Israël et de Juda, dit Yahweh, et je le ferai rentrer dans le pays que j’ai donné à leurs pères, et ils le posséderont.'),
('jr',30,4,'crampon1923','Voici les paroles que Yahweh a prononcées sur Israël et sur Juda:'),
('jr',30,5,'crampon1923','Ainsi parle Yahweh: Nous avons entendu un cri de terreur: c’est l''épouvante, et il n''y a point de paix!'),
('jr',30,6,'crampon1923','Demandez et regardez si un mâle enfante. Pourquoi vois-je tous les hommes avec les mains sur leurs reins, comme une femme qui enfante, et pourquoi tous les visages sont-ils devenus livides?'),
('jr',30,7,'crampon1923','Malheur! car grande est cette journée; elle n’a pas sa pareille. C''est un temps d''angoisse pour Jacob; mais il en sera délivré.'),
('jr',30,8,'crampon1923','Et il arrivera en ce jour-là, — oracle de Yahweh des armées: Je briserai son joug de dessus ton cou, et je romprai tes liens. Des étrangers ne t''asserviront plus;'),
('jr',30,9,'crampon1923','mais ils seront assujettis à Yahweh leur Dieu, et à David leur roi, que je susciterai pour eux.'),
('jr',30,10,'crampon1923','Toi donc ne crains point, mon serviteur Jacob; — oracle de Yahweh, ne t''effraie point, Israël. Car voici que je vais te retirer de la terre lointaine, et ta postérité du pays de son exil; Jacob reviendra, il sera tranquille, en sécurité, sans que personne l’épouvante.'),
('jr',30,11,'crampon1923','Car je suis avec toi, — oracle de Yahweh, — pour te sauver; je ferai une extermination dans toutes les nations où je t''ai dispersé. Pour toi, je ne t''exterminerai pas, mais je te châtierai selon la justice, et je ne te laisserai pas impuni.'),
('jr',30,12,'crampon1923','Car ainsi parle Yahweh: Ta blessure est incurable, ta plaie est douloureuse;'),
('jr',30,13,'crampon1923','nul ne plaide ta cause pour qu''on panse ta plaie, il n’y a pas pour toi de remède qui guérisse.'),
('jr',30,14,'crampon1923','Tous tes amants t''ont oubliée, ils ne se soucient point de toi. Car je t''ai frappée comme on frappe un ennemi, d''un châtiment cruel, à cause de la multitude de tes iniquités, parce que tes péchés se sont accrus.'),
('jr',30,15,'crampon1923','Pourquoi crier à cause de ta blessure, de ce que ton mal est incurable? C''est à cause de la multitude de tes iniquités, et parce que tes péchés se sont accrus, que je t''ai fait ces choses.'),
('jr',30,16,'crampon1923','C''est pourquoi tous ceux qui te dévorent seront dévorés, tous tes oppresseurs iront en captivité, ceux qui te dépouillent seront dépouillés, et je livrerai au pillage tous ceux qui te pillent.'),
('jr',30,17,'crampon1923','Car je vais te panser, de tes plaies je vais te guérir, — oracle de Yahweh. Car on t''appelle " Repoussée ", " Sion dont nul ne prend souci. "'),
('jr',30,18,'crampon1923','Ainsi parle Yahweh: Voici que je vais rétablir les tentes de Jacob, et j''aurai compassion de leurs demeures; la ville sera rebâtie sur sa colline, et le palais rétabli à sa place.'),
('jr',30,19,'crampon1923','Il en sortira des chants de louange, et des cris d''allégresse. Je les multiplierai, et ils ne seront plus diminués; je les glorifierai, et ils ne seront plus méprisés.'),
('jr',30,20,'crampon1923','Ses fils seront comme autrefois; son assemblée sera affermie devant moi, et je châtierai tous ses oppresseurs.'),
('jr',30,21,'crampon1923','Son chef sera un des siens, et son souverain sortira de son sein; je le ferai venir et il s''approchera de moi; car quel est l''homme qui disposerait son cœur de manière à s''approcher de moi? — oracle de Yahweh.'),
('jr',30,22,'crampon1923','Et vous serez mon peuple, et je serai votre Dieu.'),
('jr',30,23,'crampon1923','Voici que la tempête de Yahweh, la fureur, va éclater; l''orage se précipite, il fond sur la tête des impies.'),
('jr',30,24,'crampon1923','Le feu de la colère de Yahweh ne retournera pas en arrière, qu''il n''ait agi et réalisé les desseins de son cœur; à la fin des temps vous le comprendrez.'),
('jr',31,1,'crampon1923','En ce temps-là, — oracle de Yahweh, — je serai le Dieu de toutes les familles d''Israël, et elles seront mon peuple.'),
('jr',31,2,'crampon1923','Ainsi parle Yahweh: Il a trouvé grâce dans le désert, le peuple échappé au glaive; je veux mettre Israël en repos.'),
('jr',31,3,'crampon1923','Yahweh m''est apparu de loin. Je t''ai aimée d''un amour éternel, aussi j''ai prolongé pour toi la miséricorde.'),
('jr',31,4,'crampon1923','Je te bâtirai encore, et tu seras rebâtie, vierge d''Israël; tu te pareras encore en main tes tambourins, et tu t''avanceras au milieu des danses joyeuses.'),
('jr',31,5,'crampon1923','Tu planteras encore tes vignes sur les montagnes de Samarie; ceux qui plantent planteront, et ils recueilleront.'),
('jr',31,6,'crampon1923','Car le jour vient où les gardes crieront sur la montagne d''Ephraïm: " Levez-vous et montons à Sion vers Yahweh notre Dieu. "'),
('jr',31,7,'crampon1923','Car ainsi parle Yahweh: Poussez des cris de joie sur Jacob, éclatez d''allégresse pour la première des nations; faites-vous, entendre, chantez des louanges et dites: " Yahweh, sauve ton peuple, le reste d’Israël! "'),
('jr',31,8,'crampon1923','Voici que je les ramène du pays du septentrion, que je les rassemble des extrémités de la terre. Parmi eux seront l''aveugle et le boiteux, la femme enceinte et celle qui enfante; ils reviendront ici en grande foule.'),
('jr',31,9,'crampon1923','Ils reviendront en pleurant; je les ramènerai au milieu de leurs supplications; je les conduirai aux eaux courantes, par un chemin uni où ils ne broncheront pas; car j''ai été un père à Israël, et Ephraïm est mon premier-né.'),
('jr',31,10,'crampon1923','Nations, écoutez la parole de Yahweh et annoncez-la aux îles lointaines; dites: " Celui qui a dispersé Israël le rassemblera, et le gardera comme un berger son troupeau.'),
('jr',31,11,'crampon1923','Car Yahweh a racheté Jacob, Il l''a délivré des mains d''un plus fort que lui. "'),
('jr',31,12,'crampon1923','Ils viendront avec des cris de joie sur la hauteur de Sion; ils afflueront vers les biens de Yahweh, vers le blé, vers le vin nouveau, vers l''huile, vers les brebis et les bœufs; leur âme sera comme un jardin arrosé, et ils ne continueront plus de languir.'),
('jr',31,13,'crampon1923','Alors la jeune fille s''égaiera à la danse, et les jeunes hommes et les vieillards ensemble; je changerai leur deuil en joie, je les consolerai, je les réjouirai après leurs douleurs.'),
('jr',31,14,'crampon1923','Je rassasierai de graisse l''âme des prêtres, et mon peuple se rassasiera de mes biens, — oracle de Yahweh.'),
('jr',31,15,'crampon1923','Ainsi parle Yahweh: Une voix a été entendue à Rama, des lamentations et des pleurs amers: Rachel pleurant ses enfants; elle refuse d''être consolée, sur ses enfants, parce qu''ils ne sont plus.'),
('jr',31,16,'crampon1923','Ainsi parle Yahweh: Retiens ta voix de gémir, et tes yeux de pleurer. Car ton œuvre aura sa récompense, — oracle de Yahweh: ils reviendront du pays de l’ennemi.'),
('jr',31,17,'crampon1923','Il y a de l''espérance pour tes derniers jours, — oracle de Yahweh, et tes enfants retourneront dans leurs frontières.'),
('jr',31,18,'crampon1923','J''ai entendu Ephraïm qui gémit: " Tu m''as châtié, et j''ai été châtié, comme un jeune taureau indompté; fais-moi revenir et je reviendrai, car tu es Yahweh mon Dieu!'),
('jr',31,19,'crampon1923','Car après m''être détourné, je me suis repenti, et après avoir compris, j''ai frappé ma cuisse; je suis honteux et confus, car je porte l’opprobre de ma jeunesse. "'),
('jr',31,20,'crampon1923','Ephraïm est-il donc pour moi un fils si cher, un enfant favori? Car chaque fois que je parle contre lui, je me ressouviens encore de lui. Aussi pour lui mes entrailles se sont émues; oui, j''aurai pitié de lui, — oracle de Yahweh.'),
('jr',31,21,'crampon1923','Dresse pour toi des signaux, pose pour toi des jalons; fais attention à la route, au chemin par lequel tu as marché. Reviens, vierge d''Israël, reviens ici, dans tes villes.'),
('jr',31,22,'crampon1923','Jusques à quand seras-tu errante, fille rebelle? Car Yahweh a créé une chose nouvelle sur la terre: une femme entourera un homme.'),
('jr',31,23,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: On dira encore cette parole sur la terre de Juda et dans ses villes, quand je ramènerai leurs captifs: " Que Yahweh te bénisse, demeure de la justice, montagne de la sainteté! "'),
('jr',31,24,'crampon1923','Là habiteront Juda et toutes ses villes, les laboureurs et ceux qui conduisent les troupeaux.'),
('jr',31,25,'crampon1923','Car j''abreuverai l''âme altérée, et je rassasierai l’âme languissante.'),
('jr',31,26,'crampon1923','Sur cela je me suis réveillé, et j''ai vu que mon sommeil avait été doux.'),
('jr',31,27,'crampon1923','Des jours viennent — oracle de Yahweh, où j''ensemencerai la maison d''Israël et la maison de Juda d''une semence d''homme et d''une semence d''animaux.'),
('jr',31,28,'crampon1923','Et il arrivera: comme j''ai veillé sur eux pour arracher et pour abattre, pour ruiner, pour détruire et pour faire du mal, ainsi je veillerai sur eux pour bâtir et pour planter, — oracle de Yahweh.'),
('jr',31,29,'crampon1923','En ces jours-là on ne dira plus: " Les pères ont mangé des raisins verts, et les dents des fils en sont agacées. "'),
('jr',31,30,'crampon1923','Mais chacun mourra pour son iniquité; tout homme qui mangera des raisins verts, ses dents en seront agacées.'),
('jr',31,31,'crampon1923','Voici que des jours viennent, — oracle de Yahweh, où je concluerai avec la maison d''Israël et avec la maison de Juda une alliance nouvelle,'),
('jr',31,32,'crampon1923','non comme l''alliance que je conclus avec leurs pères, le jour où je les pris par la main pour les faire sortir du pays d''Egypte, alliance qu''eux ont rompue, quoique je fusse leur époux.'),
('jr',31,33,'crampon1923','Car voici l''alliance que je ferai avec la maison d''Israël, après ces jours-là, — oracle de Yahweh: Je mettrai ma loi au dedans d''eux, et je l''écrirai sur leur cœur; et je serai leur Dieu, et ils seront mon peuple.'),
('jr',31,34,'crampon1923','Un homme n''enseignera plus son prochain, ni un homme son frère, en disant: " Connaissez Yahweh! " Car ils me connaîtront tous, depuis les petits jusqu''aux grands, — oracle de Yahweh. Car je pardonnerai leur iniquité, et je ne me souviendrai plus de leur péché.'),
('jr',31,35,'crampon1923','Ainsi parle Yahweh, qui donne le soleil pour éclairer pendant le jour, et trace des lois à la lune et aux étoiles pour éclairer pendant la nuit, qui soulève la mer et ses flots mugissent, — Yahweh des armées est son nom: —'),
('jr',31,36,'crampon1923','Si jamais ces lois cessent devant moi, — oracle de Yahweh, alors aussi la race d''Israël cessera pour toujours d''être une nation devant moi.'),
('jr',31,37,'crampon1923','Ainsi parle Yahweh: Si les cieux peuvent se mesurer en haut, et les fondements de la terre se sonder en bas, alors aussi je rejetterai toute la race d''Israël, à cause de tout ce qu''ils ont fait, — oracle de Yahweh.'),
('jr',31,38,'crampon1923','Voici que des jours viennent, — oracle de Yahweh, où cette ville sera rebâtie pour Yahweh, depuis la tour de Hananéel jusqu''à la porte de l''Angle.'),
('jr',31,39,'crampon1923','Le cordeau à mesurer sera tiré en droite ligne sur la colline de Gareb, et il tournera vers Goa.'),
('jr',31,40,'crampon1923','Et toute la vallée des cadavres et des cendres, et tous les champs jusqu''au torrent de Cédron, et jusqu''à l''angle de la porte des Chevaux, vers l''orient, seront des lieux saints à Yahweh, et ils ne seront jamais ni dévastés ni détruits.'),
('jr',32,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, la dixième année de Sédécias, roi de Juda. C''était la dix-huitième année de Nabuchodonosor.'),
('jr',32,2,'crampon1923','Alors l’armée du roi de Babylone assiégeait Jérusalem, et Jérémie le prophète était enfermé dans la cour de garde qui était dans la maison du roi de Juda.'),
('jr',32,3,'crampon1923','Car Sédécias, roi de Juda, l''avait fait enfermer, en lui disant: " Pourquoi prophétises-tu en ces termes: Ainsi parle Yahweh: Voici que je livre cette ville aux mains du roi de Babylone, et il la prendra;'),
('jr',32,4,'crampon1923','et Sédécias, roi de Juda n''échappera pas aux mains des Chaldéens; il sera certainement livré aux mains du roi de Babylone, et il lui parlera bouche à bouche, et ses yeux verront ses yeux.'),
('jr',32,5,'crampon1923','Et Nabuchodonosor emmènera Sédécias à Babylone, et il y restera jusqu''à ce que je le visite, — oracle de Yahweh. Si vous combattez contre les Chaldéens, vous ne réussirez point. "'),
('jr',32,6,'crampon1923','Et Jérémie dit: La parole de Yahweh m''a été adressée en ces termes:'),
('jr',32,7,'crampon1923','Voici Hanaméel, fils de Sellum, ton oncle, qui vient vers toi pour te dire: " Achète-toi mon champ qui est à Anathoth, car tu as le droit de rachat pour l''acheter. "'),
('jr',32,8,'crampon1923','Et Hanaméel, fils de mon oncle, vint vers moi selon la parole de Yahweh, dans la cour de garde, et il me dit: " Achète donc mon champ qui est à Anathoth, dans le pays de Benjamin, car tu as le droit d''héritage et le droit de rachat; achète-le donc! " Alors je connus que c''était là une parole de Yahweh.'),
('jr',32,9,'crampon1923','Et j''achetai de Hanaméel, fils de mon oncle, le champ qui est à Anathoth, et je lui pesais l''argent, dix-sept sicles d''argent.'),
('jr',32,10,'crampon1923','Puis je passai l''acte et je le scellai; je pris des témoins et je pesai l''argent dans la balance.'),
('jr',32,11,'crampon1923','Ensuite je pris l''acte d''acquisition, celui qui était scellé, renfermant les stipulations et les clauses, et celui qui était ouvert.'),
('jr',32,12,'crampon1923','Et je remis l''acte d''acquisition à Baruch, fils de Néri, fils de Maasias, en présence de Hanaméel, fils de mon oncle, et en présence des témoins qui avaient signé l''acte d''acquisition, et en présence de tous les Juifs qui étaient assis dans la cour de garde.'),
('jr',32,13,'crampon1923','Et je donnai devant eux cet ordre à Baruch:'),
('jr',32,14,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: Prends ces actes, cet acte d''acquisition qui est scellé, et cet acte qui est ouvert, et mets-les dans un vase de terre pour qu''ils se conservent longtemps.'),
('jr',32,15,'crampon1923','Car ainsi parle Yahweh des armées, Dieu d''Israël: On achètera encore des maisons, des champs et des vignes en ce pays.'),
('jr',32,16,'crampon1923','Après que j''eus remis l''acte d''acquisition à Baruch, fils de Néri, j''adressai cette prière à Yahweh:'),
('jr',32,17,'crampon1923','Ah! Seigneur Yahweh, c''est toi qui as fait le ciel et la terre par ta grande puissance et ton bras étendu; rien ne te sera impossible.'),
('jr',32,18,'crampon1923','C''est toi qui fais miséricorde à des milliers, et qui paies le salaire de l''iniquité des pères dans le sein de leurs enfants, après eux; Dieu grand et fort, dont le nom est Yahweh des armées;'),
('jr',32,19,'crampon1923','grand en conseil et puissant en action, dont les yeux sont ouverts sur toutes les voies des enfants d''Adam, pour rendre à chacun selon ses voies, et selon le fruit de ses œuvres.'),
('jr',32,20,'crampon1923','C''est toi qui as fait des signes et des prodiges dans le pays d''Egypte, et jusqu''à ce jour, en Israël et parmi les hommes, et qui t''es fait un nom tel que nous le voyons aujourd''hui;'),
('jr',32,21,'crampon1923','c''est toi qui as tiré Israël, ton peuple, du pays d''Egypte, avec des signes et des prodiges, par ta main puissante et ton bras étendu, et en répandant une grande terreur;'),
('jr',32,22,'crampon1923','et tu leur as donné ce pays, que tu avais juré à leurs pères de leur donner, un pays où coulent le lait et le miel.'),
('jr',32,23,'crampon1923','Ils y sont entrés, ils en ont pris possession; mais ils n''ont pas écouté ta voix, ils n''ont pas marché dans ta loi; et tout ce que tu leur avais commandé de faire, ils ne l''ont pas fait; et tu as amené sur eux tous ces malheurs.'),
('jr',32,24,'crampon1923','Voici que des terrasses atteignent la ville, pour la prendre; et la ville va être livrée aux mains des Chaldéens qui l''attaquent, par l''épée, la famine et la peste; ce que tu as dit arrive, et tu le vois.'),
('jr',32,25,'crampon1923','Et toi, Seigneur Yahweh, tu m''as dit: " Achète-toi ce champ à prix d''argent, et prends des témoins "; et la ville est livrée aux mains des Chaldéens!...'),
('jr',32,26,'crampon1923','La parole de Yahweh fut adressée à Jérémie en ces termes:'),
('jr',32,27,'crampon1923','Je suis Yahweh, le Dieu de toute chair; y aurait-il une chose impossible pour moi?'),
('jr',32,28,'crampon1923','C''est pourquoi ainsi parle Yahweh: Voici que je vais livrer cette ville aux mains des Chaldéens et aux mains de Nabuchodonosor, roi de Babylone, et il la prendra.'),
('jr',32,29,'crampon1923','Les Chaldéens qui attaquent cette ville y entreront; ils mettront le feu à cette ville, et ils la brûleront, ainsi que les maisons sur les toits desquelles on a offert de l''encens à Baal, et fait des libations à d''autres dieux, afin de m''irriter.'),
('jr',32,30,'crampon1923','Car les enfants d''Israël et les enfants de Juda, n''ont fait dès leur jeunesse que ce qui est mal à mes yeux; et les enfants d''Israël n’ont fait que m''irriter par l''œuvre de leurs mains, — oracle de Yahweh.'),
('jr',32,31,'crampon1923','Car cette ville n''a fait qu''exciter ma colère et ma fureur, depuis le jour où ils l''ont bâtie jusqu''à ce jour afin que je la fasse disparaître de devant ma face,'),
('jr',32,32,'crampon1923','à cause de tout le mal que les enfants d''Israël et les enfants de Juda ont fait pour m''irriter, eux, leurs rois, leurs chefs, leurs prêtres et leurs prophètes, les hommes de Juda et les habitants de Jérusalem.'),
('jr',32,33,'crampon1923','Ils m''ont tourné le dos et non pas la face, et, quand je les ai instruits, les instruisant dès le matin, ils n''ont pas écouté pour recevoir l''instruction.'),
('jr',32,34,'crampon1923','Et ils ont mis leurs abominations dans la maison sur laquelle mon nom est invoqué, pour la souiller.'),
('jr',32,35,'crampon1923','Ils ont bâti les hauts lieux de Baal dans la vallée du fils de Hinnom, faisant passer par le feu leurs fils et leurs filles pour Moloch: ce que je ne leur avais pas commandé, et ce qui ne m''était pas venu à la pensée, faisant cette abomination pour faire pêcher Juda.'),
('jr',32,36,'crampon1923','Maintenant donc, ainsi parle Yahweh, Dieu d''Israël, touchant cette ville dont vous dites: " Elle sera livrée aux mains du roi de Balylone, par l''épée, la famine et la peste: "'),
('jr',32,37,'crampon1923','Voici que je les rassemblerai de tous les pays où je les aurai chassés dans ma colère, dans mon indignation et dans mon grand courroux; je les ramènerai dans ce lieu et je les y ferai habiter en sécurité.'),
('jr',32,38,'crampon1923','Ils seront mon peuple, et moi je serai leur Dieu.'),
('jr',32,39,'crampon1923','Je leur donnerai un même cœur et je leur ferai suivre une même voie, afin qu''ils me craignent toujours, pour leur bonheur et celui de leurs enfants après eux.'),
('jr',32,40,'crampon1923','Je conclurai avec eux une alliance éternelle, pour ne pas me détourner d''eux, en cessant de leur faire du bien; et je mettrai ma crainte dans leur cœur pour qu''ils ne se détournent pas de moi.'),
('jr',32,41,'crampon1923','Je mettrai ma joie à leur faire du bien, et je les planterai fidèlement sur cette terre, de tout mon cœur et de toute mon âme.'),
('jr',32,42,'crampon1923','Car ainsi parle Yahweh: De même que j''ai fait venir sur ce peuple tous ces grands malheurs, de même je ferai venir sur eux tous ces biens dont je parle à leur sujet.'),
('jr',32,43,'crampon1923','Et on achètera des champs dans ce pays dont vous dites: " C''est un pays dévasté, où il n''y a plus ni homme ni bête; il est livré aux mains des Chaldéens. "'),
('jr',32,44,'crampon1923','On achètera des champs à prix d''argent, on en passera les actes, on les scellera et l''on prendra des témoins, dans le pays de Benjamin,et dans les environs de Jérusalem et dans les villes de Juda, dans les villes de la montagne, dans les villes de la sephélah, et dans les villes du négéb; car je ferai revenir les captifs, — oracle de Yahweh.'),
('jr',33,1,'crampon1923','La parole de Yahweh fut adressée à Jérémie une seconde fois, lorsqu’il était encore enfermé dans la cour de garde, — en ces termes:'),
('jr',33,2,'crampon1923','Ainsi parle Yahweh qui fait cela, Yahweh qui le conçoit pour l''exécuter, — Yahweh est son nom: —'),
('jr',33,3,'crampon1923','Invoque-moi et je te répondrai; je te manifesterai des choses grandes et inaccessibles, que tu ne sais pas.'),
('jr',33,4,'crampon1923','Car ainsi parle Yahweh, Dieu d''Israël, au sujet des maisons de cette ville, et des maisons du roi de Juda, abattues pour faire face aux machines de guerre et à l''épée;'),
('jr',33,5,'crampon1923','et au sujet de ceux qui vont combattre les Chaldéens, pour remplir ces maisons des cadavres des hommes, que je frappe dans ma colère et ma fureur, et à cause de la méchanceté desquels je cache ma face à cette ville:'),
('jr',33,6,'crampon1923','Voici que je lui applique un pansement, et que je la soigne pour la guérir; et je leur ferai voir une abondance de paix et de sécurité.'),
('jr',33,7,'crampon1923','Je ramènerai les exilés de Juda et les exilés d''Israël, et je les rétablirai comme ils étaient autrefois.'),
('jr',33,8,'crampon1923','Je les purifierai de toute leur iniquité, par laquelle ils ont péché contre moi; je leur pardonnerai toutes leurs iniquités, par lesquelles ils m''ont offensé, par lesquelles ils se sont révoltés contre moi.'),
('jr',33,9,'crampon1923','Et le nom de cette ville sera pour moi un nom de joie, de louange et de gloire parmi toutes les nations de la terre, qui apprendront tout le bien que je leur ferai; elles seront effrayées et frémiront, en voyant tout le bonheur et la prospérité que je leur donnerai.'),
('jr',33,10,'crampon1923','Ainsi parle Yahweh: On entendra encore — dans ce lieu dont vous dites: " C''est un désert sans homme ni bête "; dans les villes de Juda et dans les rues de Jérusalem, qui sont désolées, sans homme, sans habitant, ni bête —'),
('jr',33,11,'crampon1923','les cris de joie et les cris d''allégresse, le chant du fiancé et le chant de la fiancée, la voix de ceux qui disent: " Louez Yahweh des armées, car Yahweh est bon, et sa miséricorde dure à jamais! " de ceux qui apportent leurs sacrifices d''actions de grâces à la maison de Yahweh. Car je ferai revenir les exilés de ce pays, pour qu''ils soient comme à l''origine, dit Yahweh.'),
('jr',33,12,'crampon1923','Ainsi parle Yahweh des armées: Il y aura encore dans ce lieu, désert, sans homme, ni bête, et dans toutes ses villes, des abris, pour les pasteurs qui y feront reposer leurs troupeaux.'),
('jr',33,13,'crampon1923','Dans les villes de la montagne et dans les villes de la sephélah et dans les villes du négéb, dans le pays de Benjamin et dans les environs de Jérusalem, et dans les villes de Juda, les troupeaux passeront encore sous la main de celui qui les compte, dit Yahweh.'),
('jr',33,14,'crampon1923','Voici que des jours viennent, — oracle de Yahweh, où j''accomplirai la bonne parole que j''ai dite au sujet de la maison d''Israël et de la maison de Juda.'),
('jr',33,15,'crampon1923','En ces jours-là et en ce temps-là, je ferai germer à David un germe juste, qui exercera le droit et la justice sur la terre.'),
('jr',33,16,'crampon1923','En ces jours-là, Juda sera sauvé et Jérusalem habitera en assurance, et on l''appellera Yahweh-notre-justice.'),
('jr',33,17,'crampon1923','Car ainsi parle Yahweh: Il ne manquera jamais à David de descendant assis sur le trône de la maison d''Israël.'),
('jr',33,18,'crampon1923','Et aux prêtres lévites, il ne manquera jamais devant moi d''homme, pour offrir l''holocauste, pour faire fumer l''oblation, et faire le sacrifice tous les jours.'),
('jr',33,19,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie en ces termes:'),
('jr',33,20,'crampon1923','Ainsi parle Yahweh: Si vous pouvez rompre mon alliance avec le jour, et mon alliance avec la nuit, en sorte que le jour et la nuit ne soient plus en leur temps,'),
('jr',33,21,'crampon1923','alors aussi mon alliance sera rompue avec David mon serviteur, en sorte qu''il n''ait plus de fils qui règne sur son trône, et avec les lévites prêtres qui font mon service.'),
('jr',33,22,'crampon1923','Comme l''armée des cieux ne se compte pas, et comme le sable de la mer ne se mesure pas, ainsi je multiplierai la race de David, mon serviteur, et les lévites qui font mon service.'),
('jr',33,23,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie en ces termes:'),
('jr',33,24,'crampon1923','N''as-tu pas vu ce que ce peuple dit en ces termes: " Yahweh a rejeté les deux familles qu''il avait choisies! " Ainsi ils méprisent mon peuple, au point que, devant eux, il n''est plus une nation!'),
('jr',33,25,'crampon1923','Ainsi parle Yahweh: Si je n''ai pas établi mon alliance avec le jour et la nuit, et si je n''ai pas posé les lois du ciel et de la terre,'),
('jr',33,26,'crampon1923','je rejetterai aussi la postérité de Jacob et de David mon serviteur, au point de ne plus prendre dans sa postérité des chefs, pour la race d''Abraham, d''Isaac et de Jacob! Car je ferai revenir les captifs et j''aurai compassion d''eux.'),
('jr',34,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, lorsque Nabuchodonosor, roi de Babylone, avec toute son armée, tous les royaumes de la terre soumis à sa domination et tous les peuples, combattaient contre Jérusalem et contre toutes les villes de sa dépendance — en ces termes:'),
('jr',34,2,'crampon1923','Ainsi parle Yahweh, Dieu d''Israël: Va et parle à Sédécias, roi de Juda, et dis-lui: Ainsi parle Yahweh: Voici que je vais livrer cette ville au roi de Babylone et il la brûlera.'),
('jr',34,3,'crampon1923','Et toi, tu n''échapperas pas à sa main, car tu seras certainement pris et livré entre ses mains; tes yeux verront les yeux du roi de Babylone, il te parlera bouche à bouche, et tu iras à Babylone.'),
('jr',34,4,'crampon1923','Toutefois écoute la parole de Yahweh, Sédécias, roi de Juda! Ainsi parle Yahweh à ton sujet: Tu ne mourras point par l''épée.'),
('jr',34,5,'crampon1923','Tu mourras en paix et, comme on a brûlé des parfums pour tes pères, les anciens rois qui t''ont précédé, ainsi on en brûlera pour toi, et on se lamentera sur toi en disant: Hélas! Seigneur! Car moi, j''ai prononcé cette parole, — oracle de Yahweh.'),
('jr',34,6,'crampon1923','Jérémie le prophète dit toutes ces paroles à Sédécias, roi de Juda, à Jérusalem.'),
('jr',34,7,'crampon1923','Or l''armée du roi de Babylone combattait contre Jérusalem et contre toutes les villes de Juda qui tenaient encore, contre Lachis et contre Azéca; car des villes de Juda, des villes fortes, il ne restait plus que celles-là.'),
('jr',34,8,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, après que le roi Sédécias eut fait un accord avec tout le peuple de Jérusalem pour publier à leur adresse un affranchissement,'),
('jr',34,9,'crampon1923','afin que chacun renvoyât libre son esclave et chacun sa servante, hébreu ou hébreuse, et qu''il n''y eût personne qui retînt en servitude un Judéen son frère.'),
('jr',34,10,'crampon1923','Tous les chefs et tout le peuple, qui étaient entrés dans cet accord, consentirent à renvoyer libres chacun son esclave et chacun sa servante, pour ne plus les retenir en servitude; ils y consentirent et les renvoyèrent.'),
('jr',34,11,'crampon1923','Mais ensuite ils changèrent d''avis et firent revenir les esclaves, hommes et femmes, qu''ils avaient renvoyés libres, et les obligèrent à redevenir esclaves et servantes.'),
('jr',34,12,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie de la part de Yahweh en ces termes:'),
('jr',34,13,'crampon1923','Ainsi parle Yahweh, Dieu d''Israël: Moi j''avais fait alliance avec vos pères au jour où je les fis sortir du pays d''Egypte, de la maison de servitude, en leur disant:'),
('jr',34,14,'crampon1923','Au terme de sept ans, chacun de vous renverra libre son frère hébreu qui lui aura été vendu; il te servira six ans, puis tu le renverras libre de chez toi. Mais vos pères ne m''ont point écouté; ils n''ont point prêté l''oreille.'),
('jr',34,15,'crampon1923','Vous, aujourd''hui, vous étiez revenus, et aviez fait ce qui est droit à mes yeux, en proclamant la liberté, chacun pour son prochain; vous aviez conclu un accord en ma présence, dans la maison sur laquelle mon nom est invoqué.'),
('jr',34,16,'crampon1923','Mais vous avez changé d''avis, et vous avez profané mon nom, en faisant revenir chacun votre esclave et chacun votre servante, que vous aviez affranchis et rendus à eux-mêmes, et en les obligeant à redevenir vos esclaves et vos servantes.'),
('jr',34,17,'crampon1923','C’est pourquoi ainsi parle Yahweh: Vous ne m''avez point obéi en publiant un affranchissement chacun pour son frère, chacun pour son prochain; voici que je publie pour vous un affranchissement — oracle de Yahweh; je vous renvoie à l''épée, à la peste et à la famine, et je ferai de vous un objet de terreur parmi tous les royaumes de la terre.'),
('jr',34,18,'crampon1923','Et les hommes qui ont transgressé mon accord, qui n''ont point exécuté les termes de l''accord qu''ils ont conclu en ma présence, je les rendrai tels que le jeune taureau qu''ils ont coupé en deux pour passer entre les morceaux:'),
('jr',34,19,'crampon1923','les chefs de Juda et les chefs de Jérusalem, les eunuques, les prêtres, et tous les gens du pays qui ont passé entre les morceaux du jeune taureau.'),
('jr',34,20,'crampon1923','Je les livrerai entre les mains de leurs ennemis et entre les mains de ceux qui en veulent à leur vie; et leurs cadavres seront la pâture des oiseaux du ciel et des bêtes de la terre.'),
('jr',34,21,'crampon1923','Et Sédécias, roi de Juda, et ses princes, je les livrerai aux mains de leurs ennemis, aux mains de ceux qui en veulent à leur vie, aux mains de l''armée de Babylone, qui s''est éloignée de vous.'),
('jr',34,22,'crampon1923','Voici que je donne des ordres, — oracle de Yahweh, — et je vais les ramener contre cette ville; ils combattront contre elle, ils la prendront et la brûleront; et je ferai des villes de Juda un désert sans habitants!'),
('jr',35,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, au temps de Joakim, fils de Josias, roi de Juda, en ces termes:'),
('jr',35,2,'crampon1923','Va vers la famille des Réchabites, et parle-leur. Tu les amènera à la maison de Yahweh, dans une des chambres, et tu leur offriras du vin à boire.'),
('jr',35,3,'crampon1923','Je pris donc Jézonias, fils de Jérémie, fils de Habsanias, ses frères, tous ses fils et toute la famille des Réchabites;'),
('jr',35,4,'crampon1923','et je les fis entrer dans la maison de Yahweh, dans la chambre des fils de Hanan, fils de Jegdélias, homme de Dieu, près de la chambre des chefs, et au-dessus de la chambre de Maasias, fils de Sellum, garde du seuil.'),
('jr',35,5,'crampon1923','Je plaçai devant les fils de la famille des Réchabites des vases remplis de vin et des coupes, et je leur dis: " Buvez du vin. "'),
('jr',35,6,'crampon1923','Mais ils dirent: " Nous ne buvons point de vin; car Jonadab, fils de Réchab, notre père; nous a donné ce commandement: Vous ne boirez point de vin, ni vous, ni vos fils, à jamais;'),
('jr',35,7,'crampon1923','et vous ne bâtirez point de maisons, vous ne sémerez pas; vous ne planterez point de vignes et vous n''en posséderez point; mais vous habiterez sous des tentes pendant tous vos jours, afin que vous viviez de nombreux jours sur la terre où vous êtes comme des étrangers.'),
('jr',35,8,'crampon1923','Nous avons donc observé la parole de Jonadab, fils de Réchab, notre père, en tout ce qu''il nous a commandé, en sorte que nous ne buvons jamais de vin, nous, nos femmes, nos fils, nos filles;'),
('jr',35,9,'crampon1923','en sorte que nous ne bâtissons pas de maisons pour y demeurer, que nous n''avons ni vignes, ni champs, ni terres ensemencées.'),
('jr',35,10,'crampon1923','Nous habitons sous des tentes; nous obéissons et nous agissons selon tout ce que Jonadab, notre père, nous a commandé.'),
('jr',35,11,'crampon1923','Et quand Nabuchodonosor, roi de Babylone, est monté contre ce pays, nous avons dit: Venez et retirons-nous à Jérusalem, devant l’armée des Chaldéens et l''armée de Syrie; et nous avons demeuré dans Jérusalem. "'),
('jr',35,12,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie en ces termes:'),
('jr',35,13,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: Va, et dis aux hommes de Juda et aux habitants de Jérusalem: N''accepterez-vous pas l''instruction en écoutant mes paroles, — oracle de Yahweh?'),
('jr',35,14,'crampon1923','On a observé les paroles de Jonadab, fils de Réchab; il a ordonné à ses fils de ne pas boire de vin, et ils n''en ont pas bu jusqu''à ce jour, par obéissance à l''ordre de leur père; et moi, je vous ai parlé, parlé dès le matin, et vous ne m''avez pas écouté!'),
('jr',35,15,'crampon1923','Je vous ai envoyé tous mes serviteurs, les prophètes, les envoyant dès le matin, pour vous dire: Revenez chacun de votre mauvaise voie, amendez votre conduite, n''allez pas après d''autres dieux pour les servir; et vous habiterez le pays que je vous ai donné, à vous et à vos pères. Mais vous n''avez pas prêté l''oreille et vous ne m''avez pas écouté.'),
('jr',35,16,'crampon1923','Oui, les fils de Jonadab, fils de Réchab, ont observé le commandement que leur a donné leur père; et ce peuple ne m''écoute pas!'),
('jr',35,17,'crampon1923','C''est pourquoi ainsi parle Yahweh, Dieu des armées, Dieu d''Israël: Voici que je vais faire venir sur Juda et sur tous les habitants de Jérusalem tous les maux dont j''ai parlé à leur sujet, parce que je leur ai parlé, et ils ne m''ont pas écouté; je les ai appelés, et ils ne m''ont pas répondu.'),
('jr',35,18,'crampon1923','Et Jérémie dit à la famille des Réchabites: " Ainsi, parle Yahweh des armées, Dieu d''Israël: Parce que vous avez obéi à l''ordre de Jonadab, votre père, et que vous avez gardé tous ses commandements et agi selon tout ce qu''il vous a prescrit,'),
('jr',35,19,'crampon1923','à cause de cela, ainsi parle Yahweh des armées, Dieu d''Israël: Jamais Jonadab, fils de Réchab, ne manquera de descendants qui se tiennent en ma présence. "'),
('jr',36,1,'crampon1923','La quatrième année de Joakim, fils de Josias, roi de Juda, cette parole fut adressée à Jérémie de la part de Yahweh, en ces termes:'),
('jr',36,2,'crampon1923','" Prends un volume, et tu y écriras toutes les paroles que je t''ai dites contre Israël, contre Juda et contre toutes les nations, depuis le jour où je t''ai parlé, depuis les jours de Josias, jusqu''aujourd''hui.'),
('jr',36,3,'crampon1923','Peut-être que la maison de Juda entendra tout le mal que j''ai dessein de leur faire, afin qu''ils se détournent chacun de sa mauvaise voie, et que je pardonne leur iniquité et leur péché. "'),
('jr',36,4,'crampon1923','Jérémie appela donc Baruch, fils de Néria; et Baruch écrivit dans le volume, sous la dictée de Jérémie, toutes les paroles que Yahweh avait dites à celui-ci.'),
('jr',36,5,'crampon1923','Et Jérémie donna cet ordre à Baruch, en disant: " Je suis empêché, et ne puis aller dans la maison de Yahweh.'),
('jr',36,6,'crampon1923','Tu iras donc, toi, et tu liras, dans le volume que tu as écrit sous ma dictée, les paroles de Yahweh aux oreilles du peuple, dans la maison de Yahweh, le jour du jeûne; tu les liras aussi aux oreilles de tous ceux de Juda qui seront venus de leurs villes.'),
('jr',36,7,'crampon1923','Peut-être que leur supplication arrivera devant Yahweh, et qu''ils se détourneront chacun de sa mauvaise voie; car grande est la colère et l''indignation que Yahweh a exprimées contre ce peuple. "'),
('jr',36,8,'crampon1923','Et Baruch, fils de Néria, fit tout ce que Jérémie le prophète lui avait commandé, lisant dans le livre les paroles de Yahweh, dans la maison de Yahweh.'),
('jr',36,9,'crampon1923','La cinquième année de Joakim, fils de Josias, roi de Juda, le neuvième mois, on publia un jeûne devant Yahweh, pour tout le peuple de Jérusalem et pour tout le peuple qui viendrait des villes de Juda à Jérusalem.'),
('jr',36,10,'crampon1923','Alors Baruch lut dans le livre les paroles de Yahweh, dans la maison de Yahweh, dans la chambre de Gamarias, fils de Saphan, le secrétaire, dans le parvis supérieur, à l''entrée de la porte Neuve de la maison de Yahweh, aux oreilles de tout le peuple.'),
('jr',36,11,'crampon1923','Michée, fils de Gamarias, fils de Saphan, entendit toutes les paroles de Yahweh contenues dans le livre.'),
('jr',36,12,'crampon1923','Il descendit à la maison du roi, dans la chambre du secrétaire; et voici que là étaient assis tous les chefs, Elisama, le secrétaire, Dalaïas, fils de Séméïas, Elnathan, fils d''Achobor, Gamarias, fils de Saphan, Sédécias, fils de Hananias, et tous les chefs.'),
('jr',36,13,'crampon1923','Et Michée leur rapporta toutes les paroles qu''il avait entendues lorsque Baruch lisait dans le livre, aux oreilles du peuple.'),
('jr',36,14,'crampon1923','Alors tous les chefs envoyèrent vers Baruch Judi, fils de Nathanias, fils de Sélémias, fils de Chusi, pour lui dire: " Prends le volume dans lequel tu as lu aux oreilles du peuple, et viens! " Baruch, fils de Néria, prit le volume et se rendit auprès d''eux.'),
('jr',36,15,'crampon1923','Ils lui dirent: " Assieds-toi, et lis ce livre à nos oreilles! " Et Baruch le lut à leurs oreilles.'),
('jr',36,16,'crampon1923','Lorsqu''ils eurent entendu toutes ces paroles, ils se regardèrent avec effroi les uns les autres, et dirent à Baruch: " Il faut que nous rapportions au roi toutes ces paroles. "'),
('jr',36,17,'crampon1923','Puis ils interrogèrent Baruch en ces termes: " Déclare-nous comment tu as écrit toutes ces paroles sorties de sa bouche. "'),
('jr',36,18,'crampon1923','Baruch leur dit: " Il m''a dicté de sa bouche toutes ces paroles, et je les ai écrites sur le livre avec de l''encre. "'),
('jr',36,19,'crampon1923','Alors les chefs dirent à Baruch: " Va, cache-toi, ainsi que Jérémie, et que personne ne sache où vous êtes. "'),
('jr',36,20,'crampon1923','Ils entrèrent ensuite chez le roi dans la cour, laissant le volume dans la chambre d''Elisama, le secrétaire, et ils racontèrent aux oreilles du roi toute l''affaire.'),
('jr',36,21,'crampon1923','Le roi envoya Judi pour prendre le volume; et Judi le prit dans la chambre d''Elisama, le secrétaire, et il le lut aux oreilles du roi et aux oreilles de tous les chefs qui se tenaient debout devant le roi.'),
('jr',36,22,'crampon1923','Or le roi était assis dans l''appartement d''hiver, au neuvième mois, et le brasier était allumé devant lui.'),
('jr',36,23,'crampon1923','Dès que Judi avait lu trois ou quatre colonnes, le roi coupait le livre avec le canif du secrétaire, et le jetait dans le feu du brasier, jusqu''à ce que tout le volume fût consumé par le feu du brasier.'),
('jr',36,24,'crampon1923','Le roi et tous ses serviteurs qui entendirent toutes ces paroles, ne furent point effrayés et ne déchirèrent point leurs vêtements.'),
('jr',36,25,'crampon1923','Pourtant Elnathan, Dalaïas et Gamarias avaient fait des instances auprès du roi pour qu''il ne brûlât pas le volume; mais il ne les avait pas écoutés.'),
('jr',36,26,'crampon1923','Puis le roi ordonna à Jérémiel, fils du roi, et à Saraïas, fils d''Ezriel, et à Sélémias, fils d''Abdéel, de saisir Baruch, le secrétaire, et Jérémie, le prophète; mais Yahweh les cacha.'),
('jr',36,27,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie, après que le roi eut brûlé le volume avec les paroles que Baruch avait écrites sous la dictée de Jérémie, en ces termes:'),
('jr',36,28,'crampon1923','Va prendre un autre volume, et tu y écriras toutes les premières paroles qui étaient dans le premier volume que Joakim, roi de Juda, a brûlé.'),
('jr',36,29,'crampon1923','Et tu diras à Joakim, roi de Juda: Ainsi parle Yahweh: Toi, tu as brûlé ce volume, en disant: " Pourquoi y as-tu écrit que le roi de Babylone viendra certainement, qu''il dévastera ce pays et qu’il en fera disparaître hommes et bêtes? "'),
('jr',36,30,'crampon1923','C’est pourquoi ainsi parle Yahweh touchant Joakim, roi de Juda: Il n''aura pas un des siens assis sur le trône de David; et son cadavre sera jeté dehors, à la chaleur pendant le jour, et au froid pendant la nuit.'),
('jr',36,31,'crampon1923','Je punirai sur lui, sur sa race et sur ses serviteurs leur iniquité, et je ferai venir sur eux, sur les habitants de Jérusalem et sur les hommes de Juda, tous le mal que je leur ai annoncé sans qu''ils m''aient écouté.'),
('jr',36,32,'crampon1923','Jérémie prit donc un autre volume et le donna à Baruch, fils de Nérias, le secrétaire; et Baruch y écrivit, sous la dictée de Jérémie, toutes les paroles du livre que Joakim, roi de Juda, avait brûlé au feu; et beaucoup d''autres paroles semblables y furent ajoutées.'),
('jr',37,1,'crampon1923','Le roi Sédécias, fils de Josias, régna à la place de Jéchonias, fils de Joakim, — Nabuchodonosor, roi de Babylone, l''avait établi roi sur le pays de Juda. —'),
('jr',37,2,'crampon1923','Et il n''écouta point, ni lui, ni ses serviteurs, ni le peuple du pays, les paroles que Yahweh avait prononcées par l''intermédiaire de Jérémie, le prophète.'),
('jr',37,3,'crampon1923','Le roi Sédécias envoya Juchal, fils de Sélémias, et Sophonie, fils de Maasias, le prêtre, vers Jérémie le prophète, pour lui dire: " Intercède donc pour nous auprès de Yahweh, notre Dieu. "'),
('jr',37,4,'crampon1923','Jérémie allait et venait au milieu du peuple, et on ne l''avait pas encore mis en prison.'),
('jr',37,5,'crampon1923','Or l''armée de Pharaon était sortie d''Egypte, et les Chaldéens qui assiégeaient Jérusalem, en ayant appris la nouvelle, s''étaient éloignés de Jérusalem.'),
('jr',37,6,'crampon1923','Alors la parole de Yahweh fut adressée à Jérémie le prophète en ces termes:'),
('jr',37,7,'crampon1923','Ainsi parle Yahweh, Dieu d''Israël: Vous parlerez ainsi au roi de Juda qui vous a envoyés pour m''interroger: Voici, l’armée de Pharaon qui est sortie pour vous secourir va retourner en son pays, en Egypte.'),
('jr',37,8,'crampon1923','Et les Chaldéens reviendront, et ils combattront contre cette ville; ils la prendront et la brûleront.')
